fn conveyor_interval(kind: ChallengeKind, seed_count: usize) -> u32 {
    let base = match seed_count {
        0..=4 => 400,
        5..=6 => 425,
        7..=8 => 500,
        _ => 1_000,
    };
    match kind {
        ChallengeKind::FinalBoss => base * 7 / 8,
        ChallengeKind::PortalCombat => base * 3 / 2,
        ChallengeKind::Invisighoul => base * 2,
        ChallengeKind::Column => base * 3,
        _ => base,
    }
}

fn conveyor_curve(weight: u32, count: u32, limit: u32) -> u32 {
    if count >= limit {
        1
    } else {
        weight.saturating_sub(
            weight
                .saturating_sub(1)
                .saturating_mul(count)
                .checked_div(limit)
                .unwrap_or(0),
        )
    }
}

fn initial_challenge_state(mode: ModeKind, level: u8) -> ChallengeState {
    if mode != ModeKind::MiniGame {
        return ChallengeState::default();
    }
    let kind = challenge_kind(level);
    let (target, countdown) = match kind {
        ChallengeKind::SlotMachine => (2_000, 0),
        ChallengeKind::RainingSeeds => (0, 100),
        ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist => {
            (75, BEGHOULED_CHALLENGE_COUNTDOWN)
        }
        ChallengeKind::Zombiquarium => (1_000, 0),
        ChallengeKind::PortalCombat => (0, PORTAL_INITIAL_STATE_COUNTDOWN),
        ChallengeKind::WhackAZombie => (0, WHACK_INITIAL_COUNTDOWN),
        ChallengeKind::LastStand => (5, 0),
        _ => (0, 0),
    };
    ChallengeState {
        kind,
        score: 0,
        target,
        countdown,
        weather_counter: 0,
        weather_phase: 0,
        stage: 0,
        last_stand_onslaught: false,
        conveyor_countdown: 0,
        last_conveyor_seed: None,
        zombie_countdown: if matches!(
            kind,
            ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
        ) {
            BEGHOULED_ZOMBIE_COUNTDOWN
        } else {
            0
        },
        twist_state: BeghouledTwistState::Normal,
        twist_counter: 0,
        slot_machine_symbols: SLOT_MACHINE_START_SYMBOLS,
        slot_machine_next_symbols: SLOT_MACHINE_START_SYMBOLS,
        slot_machine_countdown: 0,
        slot_machine_roll_count: 0,
    }
}

pub fn last_stand_seed_slots(packet_upgrades: u8) -> u8 {
    (6 + packet_upgrades).min(10)
}

pub fn last_stand_seed_choices() -> Vec<PlantType> {
    (0..SOURCE_SEED_SLOTS)
        .filter_map(PlantType::from_slot)
        .filter(|plant_type| !matches!(plant_type.slot(), 1 | 8 | 9 | 24 | 41))
        .collect()
}

