    fn new_with_config(
        seed: u64,
        mode: ModeKind,
        level: u8,
        scene: SceneKind,
        adventure_configured: bool,
        first_time: bool,
        packet_upgrades: u8,
    ) -> Self {
        let mut rng = Mt19937::new(seed);
        let mut board = BoardState::new(scene, mode, level, &mut rng);
        let (total_waves, endless) = mode_wave_config(mode, level);
        board.wave.total = total_waves;
        board.wave.endless = endless;
        if mode == ModeKind::MiniGame {
            let countdown = match challenge_kind(level) {
                ChallengeKind::BobsledBonanza => 4_500,
                ChallengeKind::PogoParty => 5_500,
                ChallengeKind::PortalCombat => PORTAL_INITIAL_COUNTDOWN,
                ChallengeKind::WhackAZombie => WHACK_INITIAL_COUNTDOWN,
                _ => board.wave.countdown,
            };
            board.wave.countdown = countdown;
            board.wave.countdown_start = countdown;
        }
        if mode == ModeKind::MiniGame && challenge_kind(level) == ChallengeKind::WhackAZombie {
            for (row, column) in pick_whack_grave_cells(&board, &mut rng, WHACK_INITIAL_GRAVES) {
                board.graves.push(GraveState { row, column });
            }
        }
        if mode == ModeKind::Adventure && adventure_level_scene(level) == SceneKind::Night {
            // Board::AddGraveStones: per-column grave counts on random rows.
            let columns: &[(u8, u8)] = match level {
                11..=13 => &[(6, 1), (7, 1), (8, 2)],
                14 | 16 => &[(5, 1), (6, 1), (7, 2), (8, 3)],
                15 => &[(4, 2), (5, 2), (6, 2), (7, 2), (8, 1)],
                17..=19 => &[(4, 1), (5, 2), (6, 2), (7, 3), (8, 3)],
                20 => &[(3, 1), (4, 2), (5, 2), (6, 2), (7, 3), (8, 3)],
                _ => &[],
            };
            for (column, count) in columns {
                let mut rows: Vec<u8> = (0..board.rows).collect();
                for _ in 0..*count {
                    if rows.is_empty() {
                        break;
                    }
                    let pick = rng.range(rows.len() as u32) as usize;
                    let row = rows.remove(pick);
                    board.graves.push(GraveState {
                        row,
                        column: *column,
                    });
                }
            }
        }
        let mut challenge = initial_challenge_state(mode, level);
        if mode == ModeKind::Adventure && level == 40 {
            // Challenge::StartLevel: Stormy Night starts in flash state 1 with
            // a 400-update counter after the opening rain sound.
            challenge.weather_counter = 400;
            challenge.weather_phase = 1;
        }
        if mode == ModeKind::MiniGame
            && matches!(
                challenge.kind,
                ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
            )
        {
            board.rows = BEGHOULED_ROWS;
            board.columns = BEGHOULED_COLUMNS;
            board.mowers.clear();
        }
        if adventure_configured && mode == ModeKind::Adventure && adventure_level_is_conveyor(level)
        {
            board.set_seed_packets(adventure_conveyor_initial_seeds(level));
            challenge.conveyor_countdown = adventure_conveyor_initial_countdown(level);
        } else if mode == ModeKind::MiniGame && is_conveyor_challenge(challenge.kind) {
            board.set_seed_packets(conveyor_initial_seeds(level));
            challenge.conveyor_countdown = conveyor_initial_countdown(level);
        } else if adventure_configured && mode == ModeKind::Adventure && level == 15 {
            board.set_seed_packets(&[
                PlantType::Other(4),
                PlantType::Other(11),
                PlantType::Other(2),
            ]);
        } else if adventure_configured && mode == ModeKind::Adventure && level == 35 {
            board.set_seed_packets(&[PlantType::Other(2)]);
        } else if adventure_configured
            && mode == ModeKind::Adventure
            && !adventure_uses_seed_chooser(level, first_time)
        {
            let slots = adventure_seed_slots(level, first_time, packet_upgrades);
            let packets = (0..slots)
                .filter_map(PlantType::from_slot)
                .collect::<Vec<_>>();
            board.set_seed_packets(&packets);
        } else if (adventure_configured
            && mode == ModeKind::Adventure
            && adventure_uses_seed_chooser(level, first_time))
            || (mode == ModeKind::MiniGame && challenge.kind == ChallengeKind::LastStand)
        {
            board.set_seed_packets(&[]);
        } else if let Some(seed_bank) = fixed_seed_bank(mode, level) {
            board.set_seed_packets(seed_bank);
        }
        let garden_service =
            (mode == ModeKind::ZenGarden).then(|| GardenServiceKind::from_level(level));
        let state = GameState {
            seed,
            tick: 0,
            scene,
            level_scene: scene,
            game_lost_cutscene_time: None,
            mode,
            level,
            sun: starting_sun(
                mode,
                level,
                challenge.kind,
                if adventure_configured {
                    first_time
                } else {
                    true
                },
            ),
            coins: 0,
            unlocked_modes: 0,
            unlocked_plants: Vec::new(),
            defeated_zombies: Vec::new(),
            chocolates: 0,
            fertilizer_charges: 0,
            bug_spray_charges: 0,
            phonograph_purchased: false,
            pickup_inventory: Vec::new(),
            wave: 0,
            paused: false,
            adventure_first_time: adventure_configured && mode == ModeKind::Adventure && first_time,
            // LawnApp::HasFinishedAdventure: a configured replay is finished;
            // apply_profile derives it from the completed-round count.
            adventure_finished: adventure_configured && mode == ModeKind::Adventure && !first_time,
            packet_upgrades: if adventure_configured && mode == ModeKind::Adventure {
                packet_upgrades
            } else {
                0
            },
            // ZenGarden::HasPurchasedStinky: threaded through the Adventure
            // constructor and profile application.
            stinky_purchased: false,
            adventure_configured,
            garden_service,
            garden: garden_service.map(initial_garden_state).unwrap_or_default(),
            tree_height: 1,
            mustache_mode: false,
            future_mode: false,
            pinata_mode: false,
            daisies_mode: false,
            sukhbir_mode: false,
            typing_code_buffer: String::new(),
            challenge,
            board,
            rng: rng.snapshot(),
        };
        let mut game = Self { state, rng };
        if garden_service.is_some() {
            for plant in &mut game.state.garden.plants {
                plant.feedings_per_grow = game
                    .rng
                    .range_inclusive(GARDEN_FEEDINGS_PER_GROW_MIN, GARDEN_FEEDINGS_PER_GROW_MAX)
                    as u8;
            }
            game.state.rng = game.rng.snapshot();
        }
        if adventure_configured
            && mode == ModeKind::Adventure
            && adventure_uses_seed_chooser(level, first_time)
        {
            game.state.scene = SceneKind::SeedChooser;
        }
        if mode == ModeKind::MiniGame && game.state.challenge.kind == ChallengeKind::LastStand {
            game.state.scene = SceneKind::SeedChooser;
        }
        if mode == ModeKind::MiniGame
            && matches!(
                game.state.challenge.kind,
                ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
            )
        {
            game.initialize_beghouled_twist();
            game.state.rng = game.rng.snapshot();
        }
        if mode == ModeKind::MiniGame && game.state.challenge.kind == ChallengeKind::Column {
            // Challenge::StartLevel starts at the final sub-wave of the first
            // flag group without changing the board's initial countdown-start.
            game.state.board.wave.current = 9;
            game.state.board.wave.countdown = 2_400;
            game.state.board.wave_plan = game.pick_column_waves();
            game.state.rng = game.rng.snapshot();
        }
        if mode == ModeKind::MiniGame && game.state.challenge.kind == ChallengeKind::LastStand {
            game.state.board.wave_plan = game.pick_last_stand_waves(0);
            game.state.rng = game.rng.snapshot();
        }
        if mode == ModeKind::IZombie {
            game.initialize_izombie();
            game.state.rng = game.rng.snapshot();
        } else if mode == ModeKind::MiniGame
            && game.state.challenge.kind == ChallengeKind::Zombiquarium
        {
            game.initialize_zombiquarium();
            game.state.rng = game.rng.snapshot();
        } else if mode == ModeKind::MiniGame
            && game.state.challenge.kind == ChallengeKind::PortalCombat
        {
            game.initialize_portal_combat();
            game.state.rng = game.rng.snapshot();
        } else if mode == ModeKind::MiniGame
            && game.state.challenge.kind == ChallengeKind::FinalBoss
        {
            let mut events = Vec::new();
            game.spawn_boss_zombie(0, 0, None, &mut events);
            game.state.rng = game.rng.snapshot();
        }
        game
    }

    pub fn state(&self) -> &GameState {
        &self.state
    }

    pub fn carry_almanac_defeats_from(&mut self, previous: &Self) {
        self.state.defeated_zombies = previous.state.defeated_zombies.clone();
    }

    pub fn carry_session_state_from(&mut self, previous: &Self) {
        self.carry_almanac_defeats_from(previous);
        self.state.tree_height = previous.state.tree_height;
        self.state.mustache_mode = previous.state.mustache_mode;
        self.state.future_mode = previous.state.future_mode;
        self.state.pinata_mode = previous.state.pinata_mode;
        self.state.daisies_mode = previous.state.daisies_mode;
        self.state.sukhbir_mode = previous.state.sukhbir_mode;
    }

