    pub fn apply_profile(&mut self, profile: &SaveProfile) {
        self.state.coins = profile.inventory.coins;
        self.state.chocolates = profile.inventory.chocolates;
        self.state.fertilizer_charges = profile.inventory.fertilizer_charges;
        self.state.bug_spray_charges = profile.inventory.bug_spray_charges;
        self.state.phonograph_purchased = profile.inventory.phonograph_purchased;
        self.state.unlocked_modes = profile.unlocked_modes;
        self.state.unlocked_plants = profile.unlocked_plants.clone();
        self.state.garden = profile.garden.clone();
        self.state.tree_height = profile.tree_height;
        // LawnApp::HasFinishedAdventure (mFinishedAdventure > 0) maps to the
        // completed-round count, and HasPurchasedStinky is profile store state.
        self.state.adventure_finished = profile.adventure_rounds > 0;
        self.state.stinky_purchased = profile.stinky_purchased;
        self.state.packet_upgrades = profile.packet_upgrades;
        if self.state.mode == ModeKind::Adventure {
            self.state.adventure_first_time = profile.adventure_rounds == 0;
        }
    }

    pub fn update_profile(&self, profile: &mut SaveProfile) {
        profile.inventory.coins = self.state.coins;
        profile.inventory.chocolates = self.state.chocolates;
        profile.inventory.fertilizer_charges = self.state.fertilizer_charges;
        profile.inventory.bug_spray_charges = self.state.bug_spray_charges;
        profile.inventory.phonograph_purchased = self.state.phonograph_purchased;
        profile.unlocked_modes = self.state.unlocked_modes;
        profile.garden = self.state.garden.clone();
        profile.tree_height = self.state.tree_height;
        if self.state.mode == ModeKind::Adventure && self.state.scene == SceneKind::Complete {
            profile.adventure_level = profile
                .adventure_level
                .max(self.state.level.saturating_add(1).min(50));
            if self.state.level >= 50 {
                profile.adventure_rounds = profile.adventure_rounds.saturating_add(1);
            }
        }
        if self.state.scene == SceneKind::Complete {
            let completed_levels = u16::from(self.state.level).saturating_add(1);
            if let Some(completion) = profile
                .mode_completion
                .iter_mut()
                .find(|completion| completion.mode == self.state.mode)
            {
                completion.completed_levels = completion.completed_levels.max(completed_levels);
            } else if profile.mode_completion.len() < 6 {
                profile.mode_completion.push(ModeCompletion {
                    mode: self.state.mode,
                    completed_levels,
                    endless_unlocked: false,
                });
            }
        }
    }

    pub fn advance(&mut self, input: InputFrame) -> Vec<GameEvent> {
        let mut events = Vec::new();
        let mut restarted = false;
        for action in input.actions {
            restarted |= matches!(action, InputAction::Restart);
            self.apply_input(action, &mut events);
        }

        if !restarted && !self.state.paused && self.should_emit_ready_set_plant() {
            events.push(GameEvent::ReadySetPlant);
        }

        if !restarted && !self.state.paused {
            if self.state.scene == SceneKind::Complete {
                self.update_suns(&mut events);
                self.state.tick = self.state.tick.saturating_add(1);
                events.push(GameEvent::StateChanged);
            } else if self.state.scene == SceneKind::Garden {
                self.update_garden();
                self.state.tick = self.state.tick.saturating_add(1);
                events.push(GameEvent::StateChanged);
            } else if self.state.scene == SceneKind::GameOver {
                self.update_game_lost_cutscene(&mut events);
            } else if self.state.challenge.kind == ChallengeKind::LastStand
                && !self.state.challenge.last_stand_onslaught
            {
                // Challenge::UpdateZombieSpawning and Plant::Update both stop
                // while the Last Stand store button is waiting for input.
                self.state.tick = self.state.tick.saturating_add(1);
                events.push(GameEvent::StateChanged);
            } else if self.is_playing_scene() {
                if !matches!(
                    self.state.challenge.kind,
                    ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
                ) {
                    self.update_plants(&mut events);
                }
                let twist_plants_before = if matches!(
                    self.state.challenge.kind,
                    ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
                ) {
                    self.state
                        .board
                        .plants
                        .iter()
                        .map(|plant| (plant.id, plant.row, plant.column))
                        .collect::<Vec<_>>()
                } else {
                    Vec::new()
                };
                self.update_zombies(&mut events);
                if matches!(
                    self.state.challenge.kind,
                    ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
                ) {
                    self.mark_twist_eaten_plants(&twist_plants_before, &mut events);
                }
                self.update_mowers(&mut events);
                self.update_projectiles(&mut events);
                self.update_seed_packets(&mut events);
                // Board.cpp:1416: the sky-sun clock is only armed when the
                // stage is not a night stage.
                if self.state.mode != ModeKind::IZombie && !scene_is_night(self.state.scene) {
                    self.update_sun_spawning(&mut events);
                }
                self.update_wave_spawning(&mut events);
                self.update_challenge(&mut events);
                self.state.board.ice_counter = self.state.board.ice_counter.saturating_sub(1);
                self.update_craters();
                self.update_ice();
                self.update_suns(&mut events);
                self.update_sky_drop(&mut events);
                self.state.tick = self.state.tick.saturating_add(1);
                self.state.wave = self.state.board.wave.current;

                let scary_potter = self.state.mode == ModeKind::Adventure && self.state.level == 35;
                if scary_potter
                    && self.state.board.scary_pot_stage < 2
                    && self.state.board.vases.is_empty()
                    && self.state.board.zombies.is_empty()
                {
                    self.state.board.scary_pot_stage += 1;
                    let stage = self.state.board.scary_pot_stage;
                    let first_id = self.state.board.next_entity_id;
                    let vases = scary_pot_stage_vases(stage, first_id, &mut self.rng);
                    self.state.board.next_entity_id =
                        first_id.saturating_add(u32::try_from(vases.len()).unwrap_or(0));
                    self.state.board.vases = vases;
                }
                let won = if scary_potter {
                    self.state.board.scary_pot_stage >= 2
                        && self.state.board.vases.is_empty()
                        && self.state.board.zombies.is_empty()
                } else if self.state.mode == ModeKind::Vasebreaker {
                    self.state.board.vases.is_empty() && self.state.board.zombies.is_empty()
                } else if self.state.mode == ModeKind::IZombie {
                    self.state.board.brains.iter().all(|brain| brain.squished)
                } else if self.state.mode == ModeKind::MiniGame {
                    match self.state.challenge.kind {
                        ChallengeKind::SlotMachine => self.state.sun >= self.state.challenge.target,
                        ChallengeKind::Beghouled => {
                            self.state.challenge.score >= self.state.challenge.target
                        }
                        ChallengeKind::BeghouledTwist => {
                            self.state.challenge.score >= self.state.challenge.target
                        }
                        ChallengeKind::Zombiquarium => false,
                        ChallengeKind::WhackAZombie => {
                            self.state.board.wave.current >= self.state.board.wave.total
                                && self.state.board.zombies.is_empty()
                                && self.state.challenge.zombie_countdown == 0
                        }
                        ChallengeKind::LastStand => {
                            self.state.challenge.last_stand_onslaught
                                && self.state.board.wave.current >= self.state.board.wave.total
                                && self.state.board.zombies.is_empty()
                                && !self.state.board.wave.endless
                        }
                        ChallengeKind::SeeingStars => {
                            SEEING_STARS_STARFRUIT_CELLS.iter().all(|&(row, column)| {
                                self.state.board.plants.iter().any(|plant| {
                                    plant.row == row
                                        && plant.column == column
                                        && plant.plant_type == PlantType::Other(29)
                                })
                            })
                        }
                        _ => {
                            self.state.board.wave.current >= self.state.board.wave.total
                                && self.state.board.zombies.is_empty()
                                && !self.state.board.wave.endless
                        }
                    }
                } else if self.state.mode == ModeKind::Survival {
                    if self.state.board.wave.current >= self.state.board.wave.total
                        && self.state.board.zombies.is_empty()
                    {
                        if !self.state.board.wave.endless
                            && self.state.challenge.stage.saturating_add(1)
                                < survival_stage_limit(self.state.level)
                        {
                            self.begin_survival_repick(&mut events);
                            false
                        } else {
                            true
                        }
                    } else {
                        false
                    }
                } else {
                    self.state.board.wave.current >= self.state.board.wave.total
                        && self.state.board.zombies.is_empty()
                        && !self.state.board.wave.endless
                };
                if won {
                    if self.state.challenge.kind == ChallengeKind::LastStand
                        && self.state.challenge.stage < LAST_STAND_FINAL_STAGE
                    {
                        self.complete_last_stand_stage(&mut events);
                    } else {
                        // Endless puzzle continuation: PuzzleNextStageClear then
                        // IZombieInitLevel / ScaryPotterPopulate
                        // (Challenge.cpp:4294-4347, 4531-4545). Finite puzzle
                        // levels keep the win path; the 500-tick fade pacing and
                        // randomized award-stage rewards stay unmodeled.
                        let endless_izombie =
                            self.state.mode == ModeKind::IZombie && self.state.level == 9;
                        let endless_potter =
                            self.state.mode == ModeKind::Vasebreaker && self.state.level == 9;
                        if endless_izombie || endless_potter {
                            self.state.challenge.stage =
                                self.state.challenge.stage.saturating_add(1);
                            if endless_izombie {
                                self.state.challenge.score = 0;
                                let zombie_ids = self
                                    .state
                                    .board
                                    .zombies
                                    .iter()
                                    .map(|zombie| zombie.id)
                                    .collect::<Vec<_>>();
                                for zombie_id in zombie_ids {
                                    self.emit_zombie_died(zombie_id, &mut events);
                                }
                                self.state.board.zombies.clear();
                                self.state.board.brains = (0..DAY_ROWS)
                                    .map(|row| BrainState {
                                        row,
                                        position_x: 0,
                                        position_y: 0,
                                        age: 0,
                                        remaining: I_ZOMBIE_BRAIN_TICKS,
                                        squished: false,
                                    })
                                    .collect();
                            } else {
                                let first_id = self.state.board.next_entity_id;
                                let vases = initial_vases(self.state.level, &mut self.rng);
                                self.state.board.next_entity_id = first_id
                                    .saturating_add(u32::try_from(vases.len()).unwrap_or(0));
                                self.state.board.vases = vases;
                            }
                            events.push(GameEvent::PuzzleStageStarted {
                                stage: self.state.challenge.stage,
                            });
                        } else {
                            self.state.scene = SceneKind::Complete;
                            events.push(GameEvent::GameWon);
                            let coin_type = if self.state.mode == ModeKind::Adventure {
                                adventure_completion_award(
                                    self.state.level,
                                    self.state.adventure_first_time,
                                )
                            } else if self.state.challenge.kind == ChallengeKind::SeeingStars {
                                Some(CoinType::Trophy)
                            } else {
                                None
                            };
                            if let Some(coin_type) = coin_type {
                                events.push(GameEvent::LootDropSound {
                                    sound: LootDropSound::SpawnSun,
                                });
                                self.spawn_pickup(coin_type, grid_x(4), grid_y(2), &mut events);
                            }
                        }
                    }
                }
                events.push(GameEvent::StateChanged);
            }
        }

        self.state.rng = self.rng.snapshot();
        events
    }

    pub fn snapshot_hash(&self) -> Result<StateHash, CoreError> {
        let bytes = serde_json::to_vec(&self.state)?;
        let mut digest = Sha256::new();
        digest.update(bytes);
        Ok(StateHash(digest.finalize().into()))
    }

    fn is_playing_scene(&self) -> bool {
        matches!(
            self.state.scene,
            SceneKind::Day
                | SceneKind::Night
                | SceneKind::Pool
                | SceneKind::Fog
                | SceneKind::Roof
                | SceneKind::Boss
        )
    }

    fn update_game_lost_cutscene(&mut self, events: &mut Vec<GameEvent>) {
        let Some(previous) = self.state.game_lost_cutscene_time else {
            return;
        };
        let current = previous.saturating_add(10);
        self.state.game_lost_cutscene_time = Some(current);
        if previous < GAME_LOST_CHOMP_FIRST_TIME && current >= GAME_LOST_CHOMP_FIRST_TIME {
            events.push(GameEvent::GameLostChomp { variant: 0 });
        }
        if previous < GAME_LOST_CHOMP_SECOND_TIME && current >= GAME_LOST_CHOMP_SECOND_TIME {
            events.push(GameEvent::GameLostChomp { variant: 1 });
        }
        if previous < GAME_LOST_SCREAM_TIME && current >= GAME_LOST_SCREAM_TIME {
            events.push(GameEvent::GameLostScream);
        }
        events.push(GameEvent::StateChanged);
    }

    fn should_emit_ready_set_plant(&self) -> bool {
        self.state.tick == 0
            && self.state.board.wave.current == 0
            && self.state.mode == ModeKind::Adventure
            && self.state.adventure_configured
            && self.is_playing_scene()
            && !matches!(self.state.level, 5 | 15 | 35)
            && !(self.state.adventure_first_time && self.state.level <= 2)
    }

    fn begin_survival_repick(&mut self, events: &mut Vec<GameEvent>) {
        self.state.challenge.stage = self.state.challenge.stage.saturating_add(1);
        self.state.scene = SceneKind::SeedChooser;
        self.state.board.selected_seed = None;
        self.state.board.selected_usable_seed = None;
        self.state.board.zombies.clear();
        self.state.board.projectiles.clear();
        self.state.board.suns.clear();
        self.state.board.coins.clear();
        self.state.board.wave.current = 0;
        self.state.board.final_wave_sound_countdown = 0;
        self.state.board.final_wave_sound_wave = 0;
        self.state.board.wave.countdown = FIRST_WAVE_COUNTDOWN;
        self.state.board.wave.countdown_start = FIRST_WAVE_COUNTDOWN;
        self.state.wave = 0;
        events.push(GameEvent::SurvivalRepickStarted {
            stage: self.state.challenge.stage,
        });
    }

    fn confirm_survival_repick(&mut self, events: &mut Vec<GameEvent>) {
        let action = InputAction::ConfirmSurvivalRepick;
        if self.state.mode != ModeKind::Survival || self.state.scene != SceneKind::SeedChooser {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        self.state.scene = self.state.level_scene;
        events.push(GameEvent::SurvivalStageStarted {
            stage: self.state.challenge.stage,
        });
    }

    fn start_last_stand_onslaught(&mut self, events: &mut Vec<GameEvent>) {
        let action = InputAction::StartLastStand;
        if self.state.mode != ModeKind::MiniGame
            || self.state.challenge.kind != ChallengeKind::LastStand
            || self.state.scene != self.state.level_scene
            || self.state.challenge.last_stand_onslaught
            || self.state.challenge.stage >= LAST_STAND_STAGE_COUNT
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        self.state.challenge.last_stand_onslaught = true;
        self.state.board.wave.countdown = LAST_STAND_ONSLAUGHT_COUNTDOWN;
        self.state.board.wave.countdown_start = LAST_STAND_ONSLAUGHT_COUNTDOWN;
        events.push(GameEvent::LastStandOnslaughtStarted {
            stage: self.state.challenge.stage,
        });
    }

    fn confirm_last_stand_seeds(&mut self, seeds: Vec<PlantType>, events: &mut Vec<GameEvent>) {
        let action = InputAction::ConfirmLastStandSeeds {
            seeds: seeds.clone(),
        };
        if self.state.mode != ModeKind::MiniGame
            || self.state.challenge.kind != ChallengeKind::LastStand
            || self.state.scene != SceneKind::SeedChooser
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::SeedChooserUnavailable,
            });
            return;
        }
        let expected = usize::from(last_stand_seed_slots(self.state.packet_upgrades));
        let choices = last_stand_seed_choices();
        let duplicate = seeds
            .iter()
            .enumerate()
            .any(|(index, seed)| seeds[..index].contains(seed));
        if seeds.len() != expected || duplicate || seeds.iter().any(|seed| !choices.contains(seed))
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: if seeds.len() == expected {
                    InputRejectReason::InvalidSeedChoice
                } else {
                    InputRejectReason::WrongSeedCount
                },
            });
            return;
        }
        self.state.board.set_seed_packets(&seeds);
        self.state.board.selected_seed = None;
        self.state.board.selected_usable_seed = None;
        self.state.scene = self.state.level_scene;
        events.push(GameEvent::LastStandStageReady {
            stage: self.state.challenge.stage,
        });
    }

    fn complete_last_stand_stage(&mut self, events: &mut Vec<GameEvent>) {
        self.state.challenge.stage = self.state.challenge.stage.saturating_add(1);
        self.state.challenge.last_stand_onslaught = false;
        self.state.board.selected_seed = None;
        self.state.board.selected_usable_seed = None;
        self.state.board.zombies.clear();
        self.state.board.projectiles.clear();
        self.state.board.suns.clear();
        self.state.board.coins.clear();
        self.state.board.gold_magnet_suck_ticks.clear();
        self.state.board.gold_magnet_targets.clear();
        for packet in &mut self.state.board.seed_packets {
            packet.refresh_remaining = 0;
        }
        for plant in &mut self.state.board.plants {
            if matches!(plant.plant_type.slot(), 17 | 45 | 47) {
                plant.special_counter = plant.special_counter.min(200);
            }
        }
        self.state.board.wave.current = 0;
        self.state.board.wave.total = LAST_STAND_WAVES;
        self.state.board.wave.endless = false;
        self.state.board.wave.countdown = LAST_STAND_STAGE_COUNTDOWN;
        self.state.board.wave.countdown_start = LAST_STAND_STAGE_COUNTDOWN;
        self.state.board.wave.total_spawned_waves = 0;
        self.state.board.wave_health_threshold = -1;
        self.state.board.sky_drop_countdown = 0;
        self.state.board.final_wave_sound_countdown = 0;
        self.state.board.final_wave_sound_wave = 0;
        self.state.board.wave_plan = self.pick_last_stand_waves(self.state.challenge.stage);
        self.state.wave = 0;
        events.push(GameEvent::HugeWaveSound {
            wave: LAST_STAND_WAVES - 1,
        });
        events.push(GameEvent::LastStandStageReady {
            stage: self.state.challenge.stage,
        });
    }

    fn confirm_adventure_seeds(&mut self, seeds: Vec<PlantType>, events: &mut Vec<GameEvent>) {
        let action = InputAction::ConfirmAdventureSeeds {
            seeds: seeds.clone(),
        };
        let valid_scene = self.state.mode == ModeKind::Adventure
            && self.state.scene == SceneKind::SeedChooser
            && adventure_uses_seed_chooser(self.state.level, self.state.adventure_first_time);
        if !valid_scene {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::SeedChooserUnavailable,
            });
            return;
        }
        let expected = usize::from(adventure_seed_slots(
            self.state.level,
            self.state.adventure_first_time,
            self.state.packet_upgrades,
        ));
        if seeds.len() != expected {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::WrongSeedCount,
            });
            return;
        }
        let choices = adventure_seed_choices(self.state.level, self.state.adventure_first_time);
        let duplicate = seeds
            .iter()
            .enumerate()
            .any(|(index, seed)| seeds[..index].contains(seed));
        if duplicate || seeds.iter().any(|seed| !choices.contains(seed)) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidSeedChoice,
            });
            return;
        }
        self.state.board.set_seed_packets(&seeds);
        self.state.board.selected_seed = None;
        self.state.board.selected_usable_seed = None;
        self.state.scene = self.state.level_scene;
        events.push(GameEvent::ReadySetPlant);
        events.push(GameEvent::StateChanged);
    }

    fn has_conveyor_seed_bank(&self) -> bool {
        (self.state.mode == ModeKind::MiniGame && is_conveyor_challenge(self.state.challenge.kind))
            || (self.state.adventure_configured
                && self.state.mode == ModeKind::Adventure
                && adventure_level_is_conveyor(self.state.level))
    }

    fn add_conveyor_seed(&mut self, plant_type: PlantType) {
        if self.state.board.seed_packets.len() >= CONVEYOR_SEED_SLOTS {
            return;
        }
        let slot = u8::try_from(self.state.board.seed_packets.len())
            .expect("conveyor seed slot must fit in u8");
        self.state.board.seed_packets.push(SeedPacketState {
            slot,
            plant_type,
            refresh_remaining: 0,
        });
    }

    fn remove_conveyor_seed(&mut self, packet_index: usize) {
        self.state.board.seed_packets.remove(packet_index);
        for (slot, packet) in self.state.board.seed_packets.iter_mut().enumerate() {
            packet.slot = u8::try_from(slot).expect("conveyor seed slot must fit in u8");
        }
    }

    fn update_conveyor_belt(&mut self) {
        let kind = self.state.challenge.kind;
        self.state.challenge.conveyor_countdown =
            self.state.challenge.conveyor_countdown.saturating_sub(1);
        if self.state.challenge.conveyor_countdown != 0 {
            return;
        }

        let seed_count = self.state.board.seed_packets.len();
        self.state.challenge.conveyor_countdown = conveyor_interval(kind, seed_count);
        let pool = if self.state.mode == ModeKind::Adventure {
            adventure_conveyor_seed_pool(self.state.level)
        } else {
            conveyor_seed_pool(self.state.level)
        };
        if pool.is_empty() {
            return;
        }

        let mut weights = [0u32; 8];
        for (index, (plant_type, weight)) in pool.iter().copied().enumerate() {
            let on_conveyor = self
                .state
                .board
                .seed_packets
                .iter()
                .filter(|packet| packet.plant_type == plant_type)
                .count();
            let on_board = self
                .state
                .board
                .plants
                .iter()
                .filter(|plant| plant.plant_type == plant_type)
                .count();
            let total_count =
                u32::try_from(on_conveyor.saturating_add(on_board)).unwrap_or(u32::MAX);
            let mut adjusted = weight;
            if plant_type.is_gravebuster()
                && self.state.board.graves.len() <= on_conveyor + on_board
            {
                adjusted = 0;
            } else if plant_type.slot() == 16 {
                adjusted = conveyor_curve(adjusted, total_count, 18);
            } else if plant_type.slot() == 33 {
                let limit = if kind == ChallengeKind::Column {
                    45
                } else {
                    35
                };
                adjusted = conveyor_curve(adjusted, total_count, limit);
            }
            if pool.len() > 2 {
                if on_conveyor >= 4 {
                    adjusted = 1;
                } else if on_conveyor >= 3 {
                    adjusted = 5;
                } else if self.state.challenge.last_conveyor_seed == Some(plant_type) {
                    adjusted /= 2;
                }
            }
            weights[index] = adjusted;
        }

        let total_weight = weights[..pool.len()].iter().sum();
        let mut pick = self.rng.range(total_weight);
        let plant_type = pool
            .iter()
            .zip(weights)
            .find_map(|((plant_type, _), weight)| {
                if pick < weight {
                    Some(*plant_type)
                } else {
                    pick -= weight;
                    None
                }
            })
            .unwrap_or(pool[0].0);
        self.add_conveyor_seed(plant_type);
        self.state.challenge.last_conveyor_seed = Some(plant_type);
    }

    fn update_garden(&mut self) {
        let now = garden_wall_clock_seconds();
        for index in 0..self.state.garden.plants.len() {
            let should_refresh = {
                let plant = &self.state.garden.plants[index];
                garden_should_refresh_need(plant, now)
            };
            if should_refresh {
                let refresh_need = {
                    let plant = &self.state.garden.plants[index];
                    (plant.plant_type.is_aquatic() && plant.growth_stage >= 3).then(|| {
                        if self.rng.range(2) == 0 {
                            GardenNeed::BugSpray
                        } else {
                            GardenNeed::Phonograph
                        }
                    })
                };
                let plant = &mut self.state.garden.plants[index];
                if let Some(need) = refresh_need {
                    plant.last_watered_unix_seconds = now;
                    plant.need = need;
                } else if plant.growth_stage >= 3 {
                    plant.times_fed = 0;
                    plant.need = GardenNeed::None;
                }
            }
            let plant = &mut self.state.garden.plants[index];
            plant.age_ticks = plant.age_ticks.saturating_add(1);
            let was_on_cooldown = plant.need_cooldown_ticks > 0;
            plant.need_cooldown_ticks = plant.need_cooldown_ticks.saturating_sub(1);
            if was_on_cooldown && plant.need_cooldown_ticks == 0 {
                plant.happy = false;
            }
            plant.need = if plant.need_cooldown_ticks == 0 {
                garden_plant_need(plant, now)
            } else {
                GardenNeed::None
            };
        }
    }

    fn portal_target(&self, index: usize) -> Option<(u8, u8)> {
        let (_, _, square) = *self.state.board.portals.get(index)?;
        self.state.board.portals.iter().enumerate().find_map(
            |(other_index, (row, column, other_square))| {
                (other_index != index && *other_square == square).then_some((*row, *column))
            },
        )
    }

    fn portal_at(
        &self,
        row: u8,
        position_x: i64,
        tolerance: i64,
        last_portal_column: u32,
    ) -> Option<usize> {
        self.state
            .board
            .portals
            .iter()
            .position(|(portal_row, portal_column, _)| {
                *portal_row == row
                    && u32::from(*portal_column) + 1 != last_portal_column
                    && (position_x - grid_x(*portal_column)).abs() <= tolerance
            })
    }

    fn portal_targeting_enabled(&self, plant_type: PlantType) -> bool {
        self.state.challenge.kind == ChallengeKind::PortalCombat
            && matches!(plant_type.slot(), 0 | 7 | 26)
    }

    fn can_target_zombie_with_portals(
        &self,
        plant_row: u8,
        plant_column: u8,
        zombie: &ZombieState,
    ) -> bool {
        let mut row = plant_row;
        let mut column = plant_column;
        for _ in 0..3 {
            let portal_index = self
                .state
                .board
                .portals
                .iter()
                .enumerate()
                .filter(|(_, (portal_row, portal_column, _))| {
                    *portal_row == row && *portal_column > column
                })
                .min_by_key(|(_, (_, portal_column, _))| *portal_column)
                .map(|(index, _)| index);
            let right_column = portal_index
                .map(|index| self.state.board.portals[index].1)
                .unwrap_or(10);
            let left_x = i64::from(column) * 80 * POSITION_SCALE;
            let right_x = i64::from(right_column) * 80 * POSITION_SCALE;
            if zombie.row == row && zombie.position_x > left_x && zombie.position_x < right_x {
                return true;
            }
            let Some(portal_index) = portal_index else {
                return false;
            };
            let Some((target_row, target_column)) = self.portal_target(portal_index) else {
                return false;
            };
            row = target_row;
            column = target_column;
        }
        false
    }

    fn portal_distance_to_mower(&self, row: u8) -> u8 {
        let mut column: u8 = 10;
        let mut current_row = row;
        let mut distance: u8 = 0;
        while distance < 40 {
            let portal = self
                .state
                .board
                .portals
                .iter()
                .enumerate()
                .filter(|(_, (portal_row, portal_column, _))| {
                    *portal_row == current_row && *portal_column < column
                })
                .max_by_key(|(_, (_, portal_column, _))| *portal_column)
                .map(|(index, _)| index);
            let Some(index) = portal else {
                return distance.saturating_add(column);
            };
            let (_, portal_column, _) = self.state.board.portals[index];
            distance = distance.saturating_add(column - portal_column);
            let Some((target_row, target_column)) = self.portal_target(index) else {
                return distance;
            };
            current_row = target_row;
            column = target_column;
        }
        distance
    }

    fn portal_row_spawn_weight(&self, row: u8) -> u32 {
        if self.portal_distance_to_mower(row) < 5 {
            1
        } else if self
            .state
            .board
            .portals
            .iter()
            .any(|(portal_row, _, _)| *portal_row == row)
        {
            100
        } else {
            20
        }
    }

    fn update_portal_projectiles(&mut self) {
        let projectile_count = self.state.board.projectiles.len();
        for index in 0..projectile_count {
            let (row, position_x, motion, last_portal_column) = {
                let projectile = &self.state.board.projectiles[index];
                (
                    projectile.row,
                    projectile.position_x,
                    projectile.motion,
                    projectile.last_portal_column,
                )
            };
            if motion != ProjectileMotion::Straight {
                continue;
            }
            let Some(portal_index) =
                self.portal_at(row, position_x, 40 * POSITION_SCALE, last_portal_column)
            else {
                continue;
            };
            let Some((target_row, target_column)) = self.portal_target(portal_index) else {
                continue;
            };
            let projectile = &mut self.state.board.projectiles[index];
            projectile.row = target_row;
            projectile.position_x = grid_x(target_column) + 60 * POSITION_SCALE;
            projectile.position_y += i64::from(target_row.abs_diff(row))
                * 100
                * POSITION_SCALE
                * if target_row >= row { 1 } else { -1 };
            projectile.shadow_y = projectile_shadow_y(
                self.state.scene,
                target_row,
                projectile.position_x,
                projectile.motion,
                projectile.velocity_y,
            );
            projectile.last_portal_column = u32::from(target_column) + 1;
        }
    }

    fn update_portal_mowers(&mut self) {
        let mower_count = self.state.board.mowers.len();
        for index in 0..mower_count {
            let (row, position_x, active, last_portal_column) = {
                let mower = &self.state.board.mowers[index];
                (
                    mower.row,
                    mower.position_x,
                    mower.active,
                    mower.last_portal_column,
                )
            };
            if !active {
                continue;
            }
            let Some(portal_index) = self.portal_at(
                row,
                position_x + 45 * POSITION_SCALE,
                20 * POSITION_SCALE,
                last_portal_column,
            ) else {
                continue;
            };
            let Some((target_row, target_column)) = self.portal_target(portal_index) else {
                continue;
            };
            let mower = &mut self.state.board.mowers[index];
            mower.row = target_row;
            mower.position_x = grid_x(target_column) + 25 * POSITION_SCALE;
            mower.last_portal_column = u32::from(target_column) + 1;
        }
    }

    fn relocate_portal(&mut self, events: &mut Vec<GameEvent>) {
        if self.state.board.portals.is_empty() {
            return;
        }
        let index = self.rng.range(self.state.board.portals.len() as u32) as usize;
        let Some((other_row, other_column)) = self.portal_target(index) else {
            return;
        };
        let occupied = self
            .state
            .board
            .portals
            .iter()
            .map(|(row, column, _)| (*row, *column))
            .collect::<Vec<_>>();
        let free_cells = (0..10)
            .flat_map(|column| (0..DAY_ROWS).map(move |row| (row, column)))
            .filter(|(row, column)| {
                !occupied.contains(&(*row, *column)) && *row != other_row && *column != other_column
            })
            .collect::<Vec<_>>();
        let Some(&(row, column)) = free_cells.get(self.rng.range(free_cells.len() as u32) as usize)
        else {
            return;
        };
        let square = self.state.board.portals[index].2;
        self.state.board.portals[index] = (row, column, square);
        events.push(GameEvent::PortalOpened {
            row,
            column,
            square,
        });
    }

    fn update_portal_combat(&mut self, events: &mut Vec<GameEvent>) {
        self.update_portal_projectiles();
        self.update_portal_mowers();
        self.state.challenge.countdown = self.state.challenge.countdown.saturating_sub(1);
        if self.state.challenge.countdown == 0 {
            self.state.challenge.countdown = PORTAL_RELOCATION_COUNTDOWN;
            self.relocate_portal(events);
        }
    }

    fn update_challenge(&mut self, events: &mut Vec<GameEvent>) {
        let kind = self.state.challenge.kind;
        let stormy_night = self.state.mode == ModeKind::Adventure && self.state.level == 40;
        if stormy_night {
            if self.state.tick == 0 {
                events.push(GameEvent::WeatherSound {
                    sound: WeatherSound::Rain,
                });
            }
            self.update_stormy_night(events);
            return;
        }
        if kind == ChallengeKind::RainingSeeds && self.state.tick == 0 {
            events.push(GameEvent::WeatherSound {
                sound: WeatherSound::Rain,
            });
        }
        let adventure_conveyor = self.state.adventure_configured
            && self.state.mode == ModeKind::Adventure
            && adventure_level_is_conveyor(self.state.level);
        if self.state.mode != ModeKind::MiniGame && !adventure_conveyor {
            return;
        }
        if kind == ChallengeKind::WhackAZombie {
            return;
        }
        if kind == ChallengeKind::SlotMachine {
            if self.state.challenge.slot_machine_countdown > 0 {
                self.state.challenge.slot_machine_countdown -= 1;
                if self.state.challenge.slot_machine_countdown == 0 {
                    self.resolve_slot_machine(events);
                }
            }
            return;
        }
        if matches!(
            kind,
            ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
        ) {
            if self.state.challenge.twist_state == BeghouledTwistState::Moving {
                self.state.challenge.twist_counter =
                    self.state.challenge.twist_counter.saturating_sub(1);
                if self.state.challenge.twist_counter == 0 {
                    self.resolve_beghouled_twist(events);
                }
            } else if self.state.challenge.twist_state == BeghouledTwistState::Falling {
                self.state.challenge.twist_counter =
                    self.state.challenge.twist_counter.saturating_sub(1);
                if self.state.challenge.twist_counter == 0 {
                    self.finish_beghouled_twist_fall(events);
                }
            } else if self.state.challenge.twist_state == BeghouledTwistState::NoMoves {
                self.state.challenge.twist_counter =
                    self.state.challenge.twist_counter.saturating_sub(1);
                if self.state.challenge.twist_counter == 0 {
                    self.shuffle_beghouled_twist();
                    events.push(GameEvent::BeghouledShuffled);
                }
            }
            self.state.challenge.zombie_countdown =
                self.state.challenge.zombie_countdown.saturating_sub(1);
            if self.state.challenge.zombie_countdown == 0 {
                self.state.challenge.zombie_countdown = BEGHOULED_ZOMBIE_COUNTDOWN;
                let row = self.rng.range(u32::from(BEGHOULED_ROWS)) as u8;
                self.spawn_normal_zombie(row, 0, None, events);
            }
        }
        if is_conveyor_challenge(kind) || adventure_conveyor {
            self.update_conveyor_belt();
            if kind == ChallengeKind::PortalCombat {
                self.update_portal_combat(events);
            }
            return;
        }
        if self.state.challenge.countdown == 0 {
            return;
        }
        self.state.challenge.countdown -= 1;
        if self.state.challenge.countdown == 0 {
            let next_countdown = match kind {
                ChallengeKind::RainingSeeds => 500 + self.rng.range(500),
                ChallengeKind::WhackAZombie => 200,
                ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist => {
                    BEGHOULED_CHALLENGE_COUNTDOWN
                }
                _ => 0,
            };
            self.state.challenge.countdown = next_countdown;
            if kind == ChallengeKind::RainingSeeds {
                self.spawn_raining_seed(events);
            }
        }
    }

    fn update_stormy_night(&mut self, events: &mut Vec<GameEvent>) {
        self.state.challenge.weather_counter =
            self.state.challenge.weather_counter.saturating_sub(1);
        let counter = self.state.challenge.weather_counter;
        let phase = self.state.challenge.weather_phase;
        if (counter == 300 && matches!(phase, 1 | 2)) || (counter == 150 && matches!(phase, 1 | 3))
        {
            events.push(GameEvent::WeatherSound {
                sound: WeatherSound::Thunder,
            });
        }
        if counter > 0 {
            return;
        }
        let max_duration = if self.rng.range(2) != 0 { 400 } else { 750 };
        self.state.challenge.weather_counter = 150 + self.rng.range_inclusive(300, max_duration);
        self.state.challenge.weather_phase = 1 + self.rng.range(3) as u8;
    }

    fn spawn_raining_seed(&mut self, events: &mut Vec<GameEvent>) {
        let position_x = i64::from(self.rng.range_inclusive(100, 649)) * POSITION_SCALE;
        let target_y = i64::from(300 + self.rng.range(250)) * POSITION_SCALE;
        let Some(usable_seed_type) = self.pick_raining_seed() else {
            return;
        };
        let id = self.state.board.allocate_entity();
        self.state.board.coins.push(CoinPickupState {
            id,
            coin_type: CoinType::UsableSeedPacket,
            value: 0,
            position_x,
            position_y: 60 * POSITION_SCALE,
            plant_type: None,
            usable_seed_type: Some(usable_seed_type),
            target_y: Some(target_y),
            velocity_x: 0,
            velocity_y: 330_000,
            from_present: false,
            needs_bouncy_arrow: false,
            age: 0,
        });
        events.push(GameEvent::CoinProduced {
            entity: id,
            coin_type: CoinType::UsableSeedPacket,
            value: 0,
        });
    }

    fn pick_raining_seed(&mut self) -> Option<PlantType> {
        let candidates = (0..SOURCE_SEED_SLOTS)
            .filter_map(PlantType::from_slot)
            .filter(|plant_type| self.raining_seed_allowed(*plant_type))
            .collect::<Vec<_>>();
        let seed_type = candidates
            .get(self.rng.range(u32::try_from(candidates.len()).unwrap_or(1)) as usize)
            .copied()?;
        let lily_count = self
            .state
            .board
            .plants
            .iter()
            .filter(|plant| plant.plant_type.slot() == 16)
            .count();
        // Challenge::UpdateRainingSeeds uses TodAnimateCurve(0, 18, count, 30, 1).
        let lily_chance = u32::try_from(lily_count).unwrap_or(u32::MAX).min(18);
        let lily_chance = 30 - (lily_chance * 29 + 9) / 18;
        Some(if self.rng.range(100) < lily_chance {
            PlantType::Other(16)
        } else {
            seed_type
        })
    }

    fn raining_seed_allowed(&self, plant_type: PlantType) -> bool {
        if !plant_type.is_plant()
            || plant_type.slot() >= SOURCE_SEED_SLOTS
            || plant_type.is_upgrade()
            || (!self.state.unlocked_plants.is_empty()
                && !self.state.unlocked_plants.contains(&plant_type))
            || matches!(plant_type.slot(), 1 | 9 | 35 | 37 | 41 | 48)
        {
            return false;
        }
        if plant_type.is_nocturnal() && !scene_is_night(self.state.scene) {
            return false;
        }
        if plant_type.is_instant_coffee() && scene_is_night(self.state.scene) {
            return false;
        }
        if plant_type.is_gravebuster() && self.state.board.graves.is_empty() {
            return false;
        }
        if plant_type.slot() == 25 && self.state.scene != SceneKind::Fog {
            return false;
        }
        if plant_type.slot() == 33 && self.state.scene != SceneKind::Roof {
            return false;
        }
        if matches!(plant_type.slot(), 21 | 46) && self.state.scene == SceneKind::Roof {
            return false;
        }
        if plant_type.is_aquatic() && !scene_has_water_rows(self.state.scene) {
            return false;
        }
        true
    }

    fn initialize_zombiquarium(&mut self) {
        let mut events = Vec::new();
        for _ in 0..2 {
            self.spawn_zombiquarium_snorkel(&mut events);
        }
    }

    fn initialize_portal_combat(&mut self) {
        let mut events = Vec::new();
        for &(row, column, square) in &[(0, 2, true), (1, 9, true), (3, 9, false), (4, 2, false)] {
            self.place_portal(row, column, square, &mut events);
        }
    }

    fn spawn_zombiquarium_snorkel(&mut self, events: &mut Vec<GameEvent>) -> EntityId {
        let position_x = self.rng.fixed_range(50, 650) * POSITION_SCALE;
        let position_y = self.rng.fixed_range(100, 400) * POSITION_SCALE;
        let entity = self._spawn_zombie_inner(
            ZombieType::Snorkel,
            ZOMBIQUARIUM_START_HEALTH,
            0,
            0,
            Some(position_x),
            events,
        );
        if let Some(zombie) = self
            .state
            .board
            .zombies
            .iter_mut()
            .find(|zombie| zombie.id == entity)
        {
            zombie.position_y = position_y;
            zombie.max_health = ZOMBIQUARIUM_MAX_HEALTH;
            zombie.aquarium_velocity_x = 1_000;
            zombie.aquarium_velocity_y = 0;
            zombie.aquarium_speed = ZOMBIQUARIUM_START_SPEED;
            zombie.aquarium_counter = self.rng.range_inclusive(200, 400);
            zombie.aquarium_phase = ZOMBIQUARIUM_DRIFT_PHASE;
            zombie.aquarium_phase_counter = ZOMBIQUARIUM_BITE_TICKS;
            zombie.snorkel_phase = 0;
            zombie.in_pool = false;
        }
        entity
    }

    fn initialize_izombie(&mut self) {
        // Challenge::IZombieInitLevel in the 1.0.0.1051 source lays out enemy
        // plants separately for each numbered stage. Random picks use the same
        // game RNG stream as the rest of the board, so the layout remains a
        // deterministic function of the replay seed.
        match self.state.level {
            0 => {
                self.place_izombie_plant(PlantType::Sunflower, 2, 3);
                self.place_izombie_plant(PlantType::Sunflower, 3, 3);
                self.place_izombie_plants(PlantType::Sunflower, 7, None);
                self.place_izombie_plants(PlantType::Other(17), 3, None);
                self.place_izombie_plants(PlantType::Peashooter, 6, None);
                self.place_izombie_plants(PlantType::Other(5), 2, None);
            }
            1 => {
                self.place_izombie_plant(PlantType::Other(21), 0, 3);
                self.place_izombie_plant(PlantType::Sunflower, 0, 2);
                self.place_izombie_plant(PlantType::Sunflower, 3, 3);
                self.place_izombie_plants(PlantType::Other(21), 1, Some(0));
                self.place_izombie_plants(PlantType::Peashooter, 1, Some(0));
                self.place_izombie_plants(PlantType::Other(5), 2, Some(3));
                self.place_izombie_plants(PlantType::Sunflower, 1, Some(3));
                self.place_izombie_plants(PlantType::Sunflower, 4, None);
                self.place_izombie_plants(PlantType::Other(21), 2, None);
                self.place_izombie_plants(PlantType::Other(5), 2, None);
                self.place_izombie_plants(PlantType::Peashooter, 4, None);
            }
            2 => {
                self.place_izombie_plant(PlantType::Other(4), 0, 3);
                self.place_izombie_plant(PlantType::Sunflower, 0, 2);
                self.place_izombie_plant(PlantType::Other(4), 2, 2);
                self.place_izombie_plant(PlantType::Sunflower, 4, 2);
                self.place_izombie_plant(PlantType::Other(22), 3, 3);
                self.place_izombie_plants(PlantType::Other(22), 2, None);
                self.place_izombie_plants(PlantType::Sunflower, 5, None);
                self.place_izombie_plants(PlantType::Peashooter, 7, None);
                self.place_izombie_plants(PlantType::Other(28), 1, None);
            }
            3 => {
                for row in 0..5 {
                    self.place_izombie_plant(PlantType::Other(3), row, 3);
                }
                for (row, column) in [(0, 2), (2, 2), (4, 2)] {
                    self.place_izombie_plant(PlantType::Sunflower, row, column);
                }
                self.place_izombie_plants(PlantType::Peashooter, 1, Some(0));
                self.place_izombie_plants(PlantType::Other(5), 1, Some(1));
                self.place_izombie_plants(PlantType::Other(10), 2, Some(2));
                self.place_izombie_plants(PlantType::Other(5), 1, Some(3));
                self.place_izombie_plants(PlantType::Peashooter, 1, Some(4));
                self.place_izombie_plants(PlantType::Peashooter, 2, None);
                self.place_izombie_plants(PlantType::Sunflower, 4, None);
            }
            4 => {
                self.place_izombie_plant(PlantType::Sunflower, 2, 3);
                self.place_izombie_plant(PlantType::Sunflower, 3, 3);
                self.place_izombie_plants(PlantType::Other(26), 1, Some(1));
                self.place_izombie_plants(PlantType::Other(26), 1, Some(4));
                self.place_izombie_plants(PlantType::Other(31), 1, None);
                self.place_izombie_plants(PlantType::Sunflower, 5, None);
                self.place_izombie_plants(PlantType::Peashooter, 8, None);
                self.place_izombie_plants(PlantType::Other(5), 2, None);
            }
            5 => {
                self.place_izombie_plant(PlantType::Other(36), 1, 4);
                self.place_izombie_plant(PlantType::Other(36), 3, 4);
                self.place_izombie_plants(PlantType::Sunflower, 3, Some(1));
                self.place_izombie_plants(PlantType::Sunflower, 3, Some(3));
                self.place_izombie_plants(PlantType::Other(22), 2, None);
                self.place_izombie_plants(PlantType::Sunflower, 2, None);
                self.place_izombie_plants(PlantType::Other(21), 3, None);
                self.place_izombie_plants(PlantType::Other(5), 1, None);
                self.place_izombie_plants(PlantType::Peashooter, 5, None);
                self.place_izombie_plants(PlantType::Other(17), 2, None);
                self.place_izombie_plants(PlantType::Other(34), 2, None);
            }
            6 => {
                self.place_izombie_plant(PlantType::Sunflower, 2, 4);
                self.place_izombie_plant(PlantType::Sunflower, 4, 4);
                self.place_izombie_plants(PlantType::Sunflower, 6, None);
                self.place_izombie_plants(PlantType::Other(4), 9, None);
                self.place_izombie_plants(PlantType::Other(6), 8, None);
            }
            7 => {
                self.place_izombie_plants(PlantType::Other(3), 3, None);
                self.place_izombie_plants(PlantType::Other(31), 2, None);
                self.place_izombie_plants(PlantType::Peashooter, 8, None);
                self.place_izombie_plants(PlantType::Other(17), 2, None);
                self.place_izombie_plants(PlantType::Other(4), 2, None);
                self.place_izombie_plants(PlantType::Sunflower, 8, None);
            }
            8 => {
                self.place_izombie_plant(PlantType::Other(23), 1, 5);
                self.place_izombie_plant(PlantType::Other(22), 3, 5);
                self.place_izombie_plants(PlantType::Other(4), 4, Some(0));
                self.place_izombie_plants(PlantType::Sunflower, 2, Some(0));
                self.place_izombie_plants(PlantType::Sunflower, 2, Some(1));
                self.place_izombie_plants(PlantType::Other(18), 1, Some(1));
                self.place_izombie_plants(PlantType::Other(5), 1, Some(1));
                self.place_izombie_plants(PlantType::Other(28), 1, Some(1));
                self.place_izombie_plants(PlantType::Other(6), 3, Some(2));
                self.place_izombie_plants(PlantType::Sunflower, 2, Some(2));
                self.place_izombie_plants(PlantType::Other(17), 1, Some(2));
                self.place_izombie_plants(PlantType::Peashooter, 3, Some(3));
                self.place_izombie_plants(PlantType::Sunflower, 2, Some(3));
                self.place_izombie_plants(PlantType::Sunflower, 1, Some(4));
                self.place_izombie_plants(PlantType::Other(10), 1, Some(4));
                self.place_izombie_plants(PlantType::Other(13), 1, Some(4));
                self.place_izombie_plants(PlantType::Other(29), 1, Some(4));
                self.place_izombie_plants(PlantType::Other(28), 1, Some(4));
                self.place_izombie_plants(PlantType::Other(31), 1, Some(4));
            }
            _ => self.initialize_izombie_endless(),
        }

        for packet in &mut self.state.board.seed_packets {
            packet.refresh_remaining = 0;
        }
        self.state.sun = 150;
        self.state.board.selected_seed = None;
        self.state.board.selected_usable_seed = None;
    }

    fn initialize_izombie_endless(&mut self) {
        self.place_izombie_plants(PlantType::Sunflower, 8, None);

        // The current endless stage starts at zero, so the source skips its
        // later-stage formation branch and chooses one of these three 17-cell
        // formations after the eight initial sunflowers.
        match self.rng.range(6) {
            0..=2 => {
                self.place_izombie_plants(PlantType::Other(3), 1, None);
                self.place_izombie_plants(PlantType::Other(22), 1, None);
                self.place_izombie_plants(PlantType::Other(4), 1, None);
                self.place_izombie_plants(PlantType::Other(6), 2, None);
                self.place_izombie_plants(PlantType::Peashooter, 1, None);
                self.place_izombie_plants(PlantType::Other(28), 1, None);
                self.place_izombie_plants(PlantType::Other(34), 1, None);
                self.place_izombie_plants(PlantType::Other(18), 1, None);
                self.place_izombie_plants(PlantType::Other(5), 1, None);
                self.place_izombie_plants(PlantType::Other(17), 1, None);
                self.place_izombie_plants(PlantType::Other(10), 1, None);
                self.place_izombie_plants(PlantType::Other(37), 1, None);
                self.place_izombie_plants(PlantType::Other(29), 1, None);
                self.place_izombie_plants(PlantType::Other(31), 1, None);
                self.place_izombie_plants(PlantType::Other(21), 2, None);
            }
            3..=4 => {
                self.place_izombie_plants(PlantType::Other(22), 1, None);
                self.place_izombie_plants(PlantType::Other(28), 3, None);
                self.place_izombie_plants(PlantType::Other(7), 1, None);
                self.place_izombie_plants(PlantType::Other(34), 3, None);
                self.place_izombie_plants(PlantType::Other(18), 1, None);
                self.place_izombie_plants(PlantType::Other(5), 3, None);
                self.place_izombie_plants(PlantType::Other(37), 1, None);
                self.place_izombie_plants(PlantType::Other(31), 1, None);
                self.place_izombie_plants(PlantType::Other(21), 3, None);
            }
            _ => {
                self.place_izombie_plants(PlantType::Other(4), 4, None);
                self.place_izombie_plants(PlantType::Other(6), 3, None);
                self.place_izombie_plants(PlantType::Other(17), 3, None);
                self.place_izombie_plants(PlantType::Other(10), 4, None);
                self.place_izombie_plants(PlantType::Other(21), 3, None);
            }
        }
    }

    fn place_izombie_plant(&mut self, plant_type: PlantType, row: u8, column: u8) {
        if row >= self.state.board.rows
            || column >= self.state.board.columns
            || self
                .state
                .board
                .plants
                .iter()
                .any(|plant| plant.row == row && plant.column == column)
        {
            return;
        }
        let id = self.state.board.allocate_entity();
        let launch_rate = plant_type.launch_rate();
        self.state.board.plants.push(PlantState {
            id,
            plant_type,
            imitater_type: None,
            row,
            column,
            position_x: grid_x(column),
            position_y: grid_y(row),
            bowling_direction: 0,
            health: plant_type.max_health(),
            max_health: plant_type.max_health(),
            launch_counter: 0,
            launch_rate,
            shooting_counter: 0,
            recently_eaten_counter: 0,
            firing_directions: 0,
            kernel_pult_projectile: None,
            production_age: 0,
            production_stage: 0,
            special_counter: 0,
            special_armed: plant_type.is_potato_mine(),
            special_target: None,
            bungee_lifted: false,
            squash_target_x: None,
            cob_target: None,
            blink_counter: 0,
            asleep: false,
            wake_up_counter: 0,
        });
    }

    fn place_izombie_plants(&mut self, plant_type: PlantType, count: u8, row: Option<u8>) {
        let columns = izombie_columns(self.state.level);
        let occupied = self
            .state
            .board
            .plants
            .iter()
            .map(|plant| (plant.row, plant.column))
            .collect::<Vec<_>>();
        let mut cells = Vec::new();
        for column in 0..columns {
            for cell_row in 0..self.state.board.rows {
                if row.is_some_and(|required| required != cell_row)
                    || occupied.contains(&(cell_row, column))
                    || (matches!(plant_type.slot(), 3 | 22) && columns.saturating_sub(column) > 3)
                {
                    continue;
                }
                cells.push((cell_row, column));
            }
        }
        // ponytail: bounded 6x5 setup; remove one chosen cell per placement until
        // a larger board justifies a swap-pool helper.
        for _ in 0..count {
            if cells.is_empty() {
                break;
            }
            let cell = self.rng.range(u32::try_from(cells.len()).unwrap_or(1)) as usize;
            let (cell_row, column) = cells.remove(cell);
            self.place_izombie_plant(plant_type, cell_row, column);
        }
    }

    fn apply_input(&mut self, action: InputAction, events: &mut Vec<GameEvent>) {
        match action {
            InputAction::Pause => {
                if !self.state.paused {
                    self.state.paused = true;
                    events.push(GameEvent::Paused);
                }
            }
            InputAction::Resume => {
                if self.state.paused {
                    self.state.paused = false;
                    events.push(GameEvent::Resumed);
                }
            }
            InputAction::Restart => {
                if matches!(self.state.scene, SceneKind::GameOver | SceneKind::Complete) {
                    let seed = self.state.seed;
                    let scene = self.state.level_scene;
                    let mut restarted = if self.state.mode == ModeKind::Adventure {
                        Self::new(seed, scene)
                    } else {
                        Self::new_mode(seed, self.state.mode, self.state.level)
                    };
                    restarted.carry_session_state_from(self);
                    *self = restarted;
                    events.push(GameEvent::Restarted);
                }
            }
            InputAction::TypeCode { character } => self.type_code_character(character, events),
            InputAction::SelectSeed { slot } => self.select_seed(slot, events),
            InputAction::Plant { row, column } => self.plant(row, column, events),
            InputAction::PlantImitater {
                plant_slot,
                row,
                column,
            } => self.plant_imitater(plant_slot, row, column, events),
            InputAction::FireCobCannon {
                entity,
                row,
                column,
            } => self.fire_cob_cannon(entity, row, column, events),
            InputAction::Shovel { row, column } => self.shovel(row, column, events),
            InputAction::BreakVase { row, column } => self.break_vase(row, column, events),
            InputAction::DeployZombie {
                zombie_type,
                row,
                column,
            } => self.deploy_zombie(zombie_type, row, column, events),
            InputAction::GardenWater { plant } => self.garden_water(plant, events),
            InputAction::GardenFertilize { plant } => self.garden_fertilize(plant, false, events),
            InputAction::GardenUseTool { plant, tool } => self.garden_use_tool(plant, tool, events),
            InputAction::GardenTapGlass => self.garden_tap_glass(events),
            InputAction::GardenFulfillNeed { plant } => {
                self.garden_fulfill_need(plant, None, events)
            }
            InputAction::GardenFeedTree => self.garden_feed_tree(events),
            InputAction::GardenLeave => self.garden_leave(events),
            InputAction::StorePurchase { item } => self.store_purchase(item, events),
            InputAction::ChallengeSpin => self.challenge_spin(events),
            InputAction::ChallengeSwap {
                from_column,
                from_row,
                to_column,
                to_row,
            } => self.challenge_swap(from_column, from_row, to_column, to_row, events),
            InputAction::ChallengeTwist { column, row } => {
                self.challenge_twist(column, row, events)
            }
            InputAction::ChallengeClearCrater => self.challenge_clear_crater(events),
            InputAction::ChallengeFeed { x, y } => self.challenge_feed(x, y, events),
            InputAction::ChallengeWhack { row, column, x, y } => {
                self.challenge_whack(row, column, x, y, events)
            }
            InputAction::CollectSun { entity } => self.collect_sun(entity, events),
            InputAction::CollectCoin { entity } => self.collect_coin(entity, events),
            InputAction::StartLastStand => self.start_last_stand_onslaught(events),
            InputAction::ConfirmLastStandSeeds { seeds } => {
                self.confirm_last_stand_seeds(seeds, events)
            }
            InputAction::ConfirmSurvivalRepick => self.confirm_survival_repick(events),
            InputAction::ConfirmAdventureSeeds { seeds } => {
                self.confirm_adventure_seeds(seeds, events)
            }
        }
    }

    fn type_code_character(&mut self, character: char, events: &mut Vec<GameEvent>) {
        if !character.is_ascii_alphabetic() {
            self.state.typing_code_buffer.clear();
            return;
        }
        self.state
            .typing_code_buffer
            .push(character.to_ascii_lowercase());
        if self.state.typing_code_buffer.len() > TYPING_CODE_BUFFER_CAPACITY {
            self.state.typing_code_buffer.remove(0);
        }
        let code = if self.state.typing_code_buffer.ends_with("mustache")
            || self.state.typing_code_buffer.ends_with("moustache")
        {
            Some(HiddenCode::Mustache)
        } else if self.state.typing_code_buffer.ends_with("future") {
            Some(HiddenCode::Future)
        } else if self.state.typing_code_buffer.ends_with("pinata") {
            Some(HiddenCode::Pinata)
        } else if self.state.typing_code_buffer.ends_with("daisies") {
            Some(HiddenCode::Daisies)
        } else if self.state.typing_code_buffer.ends_with("sukhbir") {
            Some(HiddenCode::Sukhbir)
        } else {
            None
        };
        if let Some(code) = code {
            self.toggle_hidden_code(code, events);
        }
    }

    fn toggle_hidden_code(&mut self, code: HiddenCode, events: &mut Vec<GameEvent>) {
        let minimum_height = match code {
            HiddenCode::Pinata => 1_000,
            HiddenCode::Daisies => 100,
            HiddenCode::Mustache | HiddenCode::Future | HiddenCode::Sukhbir => 0,
        };
        if self.state.tree_height < minimum_height {
            events.push(GameEvent::HiddenCodeRejected { code });
            return;
        }
        let enabled = match code {
            HiddenCode::Mustache => {
                self.state.mustache_mode = !self.state.mustache_mode;
                self.state.mustache_mode
            }
            HiddenCode::Future => {
                self.state.future_mode = !self.state.future_mode;
                self.state.future_mode
            }
            HiddenCode::Pinata => {
                self.state.pinata_mode = !self.state.pinata_mode;
                self.state.pinata_mode
            }
            HiddenCode::Daisies => {
                self.state.daisies_mode = !self.state.daisies_mode;
                self.state.daisies_mode
            }
            HiddenCode::Sukhbir => {
                self.state.sukhbir_mode = !self.state.sukhbir_mode;
                self.state.sukhbir_mode
            }
        };
        if code == HiddenCode::Mustache && enabled {
            for zombie in &mut self.state.board.zombies {
                if zombie.has_head && zombie_uses_plain_reanimation(zombie.zombie_type) {
                    zombie.mustache_variant = self.rng.range(3) as u8 + 1;
                }
            }
        }
        events.push(GameEvent::HiddenCodeToggled { code, enabled });
    }

    fn store_purchase(&mut self, item: StoreItem, events: &mut Vec<GameEvent>) {
        let action = InputAction::StorePurchase { item };
        if self.state.scene != SceneKind::AdventureSelect {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::StoreUnavailable,
            });
            return;
        }
        let sold_out = match item {
            StoreItem::PacketUpgrade => self.state.packet_upgrades >= 4,
            StoreItem::Fertilizer => self.state.fertilizer_charges > 15,
            StoreItem::BugSpray => self.state.bug_spray_charges > 15,
            StoreItem::Phonograph => self.state.phonograph_purchased,
            StoreItem::Stinky => self.state.stinky_purchased,
        };
        if sold_out {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::StoreItemUnavailable,
            });
            return;
        }
        let cost = store_item_cost(item, self.state.packet_upgrades);
        if self.state.coins < cost {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NotEnoughCoins,
            });
            return;
        }
        self.state.coins -= cost;
        match item {
            StoreItem::PacketUpgrade => self.state.packet_upgrades += 1,
            StoreItem::Fertilizer => self.state.fertilizer_charges += 5,
            StoreItem::BugSpray => self.state.bug_spray_charges += 5,
            StoreItem::Phonograph => self.state.phonograph_purchased = true,
            StoreItem::Stinky => self.state.stinky_purchased = true,
        }
        events.push(GameEvent::StorePurchased {
            item,
            cost,
            coins_remaining: self.state.coins,
        });
    }

    fn garden_tool_available(&self, tool: GardenTool) -> bool {
        match tool {
            GardenTool::WateringCan => true,
            GardenTool::Fertilizer => self.state.fertilizer_charges > 0,
            GardenTool::BugSpray => self.state.bug_spray_charges > 0,
            GardenTool::Phonograph => self.state.phonograph_purchased,
        }
    }

    fn consume_garden_tool(&mut self, tool: GardenTool) {
        match tool {
            GardenTool::Fertilizer => {
                self.state.fertilizer_charges = self.state.fertilizer_charges.saturating_sub(1);
            }
            GardenTool::BugSpray => {
                self.state.bug_spray_charges = self.state.bug_spray_charges.saturating_sub(1);
            }
            GardenTool::WateringCan | GardenTool::Phonograph => {}
        }
    }

    fn garden_use_tool(&mut self, plant: u8, tool: GardenTool, events: &mut Vec<GameEvent>) {
        let action = InputAction::GardenUseTool { plant, tool };
        if self.state.scene != SceneKind::Garden || self.state.garden_service.is_none() {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        if !self.garden_tool_available(tool) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::GardenToolUnavailable,
            });
            return;
        }
        let Some(target) = self.state.garden.plants.get(usize::from(plant)) else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        };
        if garden_plant_need(target, garden_wall_clock_seconds()) != garden_need_for_tool(tool) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        events.push(GameEvent::GardenToolUsed { plant, tool });
        match tool {
            GardenTool::WateringCan => self.garden_water(plant, events),
            GardenTool::Fertilizer => self.garden_fertilize(plant, true, events),
            GardenTool::BugSpray | GardenTool::Phonograph => {
                self.garden_fulfill_need(plant, Some(tool), events)
            }
        }
    }

    fn garden_water(&mut self, plant: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::GardenWater { plant };
        if self.state.scene != SceneKind::Garden
            || self.state.garden_service.is_none()
            || self.state.garden.plants.get(usize::from(plant)).is_none()
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        let delay = self.rng.range_inclusive(
            GARDEN_WATER_NEED_DELAY_MIN_TICKS,
            GARDEN_WATER_NEED_DELAY_MAX_TICKS,
        );
        let should_pick_special = {
            let target = &self.state.garden.plants[usize::from(plant)];
            target.growth_stage >= 3 && target.need == GardenNeed::None
        };
        let special_need = should_pick_special.then(|| {
            if self.rng.range(2) == 0 {
                GardenNeed::BugSpray
            } else {
                GardenNeed::Phonograph
            }
        });
        let now = garden_wall_clock_seconds();
        let target = &mut self.state.garden.plants[usize::from(plant)];
        target.watered = true;
        target.times_fed = target.times_fed.saturating_add(1);
        target.need_cooldown_ticks = delay;
        target.last_watered_unix_seconds = now.saturating_sub(i64::from(self.rng.range(9)));
        target.need = special_need.unwrap_or(GardenNeed::None);
        events.push(GameEvent::GardenWatered {
            plant,
            age_ticks: target.age_ticks,
        });
    }

    fn garden_fertilize(&mut self, plant: u8, consume_tool: bool, events: &mut Vec<GameEvent>) {
        let action = InputAction::GardenFertilize { plant };
        if self.state.scene != SceneKind::Garden
            || self.state.garden_service.is_none()
            || self.state.garden.plants.get(usize::from(plant)).is_none()
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        let age_ticks = {
            let target = &mut self.state.garden.plants[usize::from(plant)];
            target.age_ticks = target.age_ticks.saturating_add(100);
            target.watered = true;
            target.growth_stage = target.growth_stage.saturating_add(1).min(3);
            target.times_fed = 0;
            target.need = GardenNeed::None;
            target.need_cooldown_ticks = GARDEN_CARE_COOLDOWN_TICKS;
            target.last_fertilized_unix_seconds = garden_wall_clock_seconds();
            target.age_ticks
        };
        if consume_tool {
            self.consume_garden_tool(GardenTool::Fertilizer);
        }
        events.push(GameEvent::GardenFertilized { plant, age_ticks });
    }

    fn garden_tap_glass(&mut self, events: &mut Vec<GameEvent>) {
        if self.state.scene != SceneKind::Garden
            || self.state.garden_service != Some(GardenServiceKind::Aquarium)
        {
            events.push(GameEvent::InputRejected {
                action: InputAction::GardenTapGlass,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        events.push(GameEvent::GardenTapGlass);
    }

    fn garden_fulfill_need(
        &mut self,
        plant: u8,
        tool: Option<GardenTool>,
        events: &mut Vec<GameEvent>,
    ) {
        let action = tool
            .map(|tool| InputAction::GardenUseTool { plant, tool })
            .unwrap_or(InputAction::GardenFulfillNeed { plant });
        if self.state.scene != SceneKind::Garden
            || self.state.garden_service.is_none()
            || self.state.garden.plants.get(usize::from(plant)).is_none()
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        if tool.is_some_and(|tool| !self.garden_tool_available(tool)) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::GardenToolUnavailable,
            });
            return;
        }

        let target = &mut self.state.garden.plants[usize::from(plant)];
        if target.happy {
            return;
        }
        target.happy = true;
        target.need = GardenNeed::None;
        target.times_fed = 0;
        target.need_cooldown_ticks = GARDEN_CARE_COOLDOWN_TICKS;
        target.last_need_fulfilled_unix_seconds = garden_wall_clock_seconds();
        let aquatic = target.plant_type.is_aquatic();
        if let Some(tool) = tool {
            self.consume_garden_tool(tool);
        }
        events.push(GameEvent::GardenBecameHappy { plant, aquatic });
    }

    fn garden_feed_tree(&mut self, events: &mut Vec<GameEvent>) {
        if self.state.scene != SceneKind::Garden
            || self.state.garden_service != Some(GardenServiceKind::TreeOfWisdom)
        {
            events.push(GameEvent::InputRejected {
                action: InputAction::GardenFeedTree,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        self.state.tree_height = self.state.tree_height.saturating_add(1);
        events.push(GameEvent::GardenTreeGrew {
            height: self.state.tree_height,
        });
    }

    fn garden_leave(&mut self, events: &mut Vec<GameEvent>) {
        if self.state.scene != SceneKind::Garden {
            events.push(GameEvent::InputRejected {
                action: InputAction::GardenLeave,
                reason: InputRejectReason::InvalidGardenTarget,
            });
            return;
        }
        self.state.scene = SceneKind::AdventureSelect;
        events.push(GameEvent::GardenLeft);
    }

    fn challenge_spin(&mut self, events: &mut Vec<GameEvent>) {
        if self.state.challenge.kind != ChallengeKind::SlotMachine
            || self.state.challenge.slot_machine_countdown != 0
            || self.state.sun < 25
        {
            events.push(GameEvent::InputRejected {
                action: InputAction::ChallengeSpin,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        self.state.sun -= 25;
        for index in 0..self.state.challenge.slot_machine_next_symbols.len() {
            self.state.challenge.slot_machine_next_symbols[index] =
                self.pick_slot_machine_symbol(index);
        }
        self.state.challenge.slot_machine_countdown = 300;
        self.state.challenge.slot_machine_roll_count = self
            .state
            .challenge
            .slot_machine_roll_count
            .saturating_add(1);
        events.push(GameEvent::ChallengeAction {
            kind: ChallengeKind::SlotMachine,
            value: self.state.challenge.slot_machine_roll_count,
        });
    }

    fn pick_slot_machine_symbol(&mut self, index: usize) -> SlotMachineSymbol {
        let pea_count = self
            .state
            .board
            .plants
            .iter()
            .filter(|plant| plant.plant_type == PlantType::Peashooter)
            .count()
            .min(5) as u32;
        let pea_weight = 200 - pea_count * 20;
        let mut weights = [
            (SlotMachineSymbol::Sunflower, 100),
            (SlotMachineSymbol::Peashooter, pea_weight),
            (SlotMachineSymbol::SnowPea, 100),
            (SlotMachineSymbol::Wallnut, 100),
            (SlotMachineSymbol::Sun, 100),
            (SlotMachineSymbol::Diamond, 30),
        ];
        if index == 2 {
            for (symbol, weight) in &mut weights {
                if *symbol != SlotMachineSymbol::Diamond
                    && (self.state.challenge.slot_machine_next_symbols[0] == *symbol
                        || self.state.challenge.slot_machine_next_symbols[1] == *symbol)
                {
                    *weight += *weight / 2;
                }
            }
        }
        let total_weight = weights.iter().map(|(_, weight)| *weight).sum();
        let mut pick = self.rng.range(total_weight);
        for (symbol, weight) in weights {
            if pick < weight {
                return symbol;
            }
            pick -= weight;
        }
        SlotMachineSymbol::Sunflower
    }

    fn resolve_slot_machine(&mut self, events: &mut Vec<GameEvent>) {
        self.state.challenge.slot_machine_symbols = self.state.challenge.slot_machine_next_symbols;
        let symbols = self.state.challenge.slot_machine_symbols;
        let matching = if symbols[0] == symbols[1] && symbols[1] == symbols[2] {
            Some((symbols[0], 3))
        } else if symbols[0] == symbols[1] || symbols[0] == symbols[2] {
            Some((symbols[0], 2))
        } else if symbols[1] == symbols[2] {
            Some((symbols[1], 2))
        } else {
            None
        };
        let Some((symbol, count)) = matching else {
            return;
        };
        let offsets: &[i64] = match (symbol, count) {
            (SlotMachineSymbol::Diamond, 2) => &[40],
            (SlotMachineSymbol::Sun, 2) => &[0, 15, 30, 45],
            (_, 2) => &[40],
            (SlotMachineSymbol::Diamond, 3) => &[0, 12, 24, 36, 48],
            (SlotMachineSymbol::Sun, 3) => &[
                0, 3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36, 39, 42, 45, 48, 51, 54, 57,
            ],
            (_, 3) => &[
                0, 20, 40, 60, 80, 100, 120, 140, 160, 180, 200, 220, 240, 260, 280, 300, 320, 340,
                360, 380,
            ],
            _ => &[],
        };
        for offset in offsets {
            let position_x = (320 + *offset) * POSITION_SCALE;
            match symbol {
                SlotMachineSymbol::Diamond => {
                    self.spawn_coin(CoinType::Diamond, position_x, 85 * POSITION_SCALE, events)
                }
                SlotMachineSymbol::Sun => {
                    self.spawn_coin(CoinType::Sun, position_x, 85 * POSITION_SCALE, events)
                }
                _ => {
                    let Some(plant_type) = slot_machine_plant(symbol) else {
                        continue;
                    };
                    self.spawn_coin_with_payload(
                        CoinType::UsableSeedPacket,
                        position_x,
                        85 * POSITION_SCALE,
                        Some(plant_type),
                        events,
                    );
                }
            }
        }
    }

    fn challenge_swap(
        &mut self,
        from_column: u8,
        from_row: u8,
        to_column: u8,
        to_row: u8,
        events: &mut Vec<GameEvent>,
    ) {
        let action = InputAction::ChallengeSwap {
            from_column,
            from_row,
            to_column,
            to_row,
        };
        let adjacent =
            u16::from(from_column.abs_diff(to_column)) + u16::from(from_row.abs_diff(to_row)) == 1;
        if self.state.challenge.kind != ChallengeKind::Beghouled
            || self.state.challenge.twist_state != BeghouledTwistState::Normal
            || from_column >= BEGHOULED_COLUMNS
            || to_column >= BEGHOULED_COLUMNS
            || from_row >= BEGHOULED_ROWS
            || to_row >= BEGHOULED_ROWS
            || !adjacent
            || self.twist_seed_at(from_row, from_column).is_none()
            || self.twist_seed_at(to_row, to_column).is_none()
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        if !self.swap_move_causes_match(from_column, from_row, to_column, to_row) {
            events.push(GameEvent::ChallengeAction {
                kind: ChallengeKind::Beghouled,
                value: 0,
            });
            return;
        }
        self.swap_beghouled_plants(from_column, from_row, to_column, to_row);
        self.state.challenge.twist_state = BeghouledTwistState::Moving;
        self.state.challenge.twist_counter = BEGHOULED_MOVE_TICKS;
        self.state.challenge.countdown = BEGHOULED_CHALLENGE_COUNTDOWN;
    }

    fn initialize_beghouled_twist(&mut self) {
        self.state.board.plants.clear();
        let board = [
            [3, 3, 0, 2, 4, 3, 3, 2],
            [3, 2, 4, 1, 4, 1, 2, 1],
            [0, 4, 2, 4, 5, 4, 1, 2],
            [0, 5, 0, 5, 2, 3, 4, 0],
            [2, 3, 2, 4, 5, 1, 4, 3],
        ];
        for (row, values) in board.into_iter().enumerate() {
            for (column, seed) in values.into_iter().enumerate() {
                self.place_beghouled_plant(BEGHOULED_SEED_TYPES[seed], row as u8, column as u8);
            }
        }
        debug_assert!(!self.twist_has_match());
        debug_assert!(self.has_standard_move());
        debug_assert!(self.has_twist_move());
    }

    fn place_beghouled_plant(&mut self, plant_type: PlantType, row: u8, column: u8) {
        let id = self.state.board.allocate_entity();
        let max_health = plant_type.max_health();
        self.state.board.plants.push(PlantState {
            id,
            plant_type,
            imitater_type: None,
            row,
            column,
            position_x: grid_x(column),
            position_y: grid_y(row),
            bowling_direction: 0,
            health: max_health,
            max_health,
            launch_counter: 0,
            launch_rate: 0,
            shooting_counter: 0,
            recently_eaten_counter: 0,
            firing_directions: 0,
            kernel_pult_projectile: None,
            production_age: 0,
            production_stage: 0,
            special_counter: 0,
            special_armed: false,
            special_target: None,
            bungee_lifted: false,
            squash_target_x: None,
            cob_target: None,
            blink_counter: 0,
            asleep: false,
            wake_up_counter: 0,
        });
    }

    fn twist_seed_at(&self, row: u8, column: u8) -> Option<PlantType> {
        if self
            .state
            .board
            .craters
            .iter()
            .any(|crater| crater.row == row && crater.column == column)
        {
            return None;
        }
        self.state
            .board
            .plants
            .iter()
            .find(|plant| plant.row == row && plant.column == column && plant.health > 0)
            .map(|plant| plant.plant_type)
    }

    fn twist_has_match(&self) -> bool {
        (0..BEGHOULED_ROWS).any(|row| {
            (0..BEGHOULED_COLUMNS.saturating_sub(2)).any(|column| {
                let Some(seed) = self.twist_seed_at(row, column) else {
                    return false;
                };
                self.twist_seed_at(row, column + 1) == Some(seed)
                    && self.twist_seed_at(row, column + 2) == Some(seed)
            })
        }) || (0..BEGHOULED_COLUMNS).any(|column| {
            (0..BEGHOULED_ROWS.saturating_sub(2)).any(|row| {
                let Some(seed) = self.twist_seed_at(row, column) else {
                    return false;
                };
                self.twist_seed_at(row + 1, column) == Some(seed)
                    && self.twist_seed_at(row + 2, column) == Some(seed)
            })
        })
    }

    fn twist_valid_square(&self, column: u8, row: u8) -> bool {
        column < BEGHOULED_COLUMNS - 1
            && row < BEGHOULED_ROWS - 1
            && self.twist_seed_at(row, column).is_some()
            && self.twist_seed_at(row, column + 1).is_some()
            && self.twist_seed_at(row + 1, column).is_some()
            && self.twist_seed_at(row + 1, column + 1).is_some()
    }

    fn twist_square_ids(&self, column: u8, row: u8) -> Option<[EntityId; 4]> {
        if !self.twist_valid_square(column, row) {
            return None;
        }
        let positions = [
            (row, column),
            (row, column + 1),
            (row + 1, column),
            (row + 1, column + 1),
        ];
        positions
            .map(|(row, column)| {
                self.state
                    .board
                    .plants
                    .iter()
                    .find(|plant| plant.row == row && plant.column == column)
                    .map(|plant| plant.id)
            })
            .into_iter()
            .collect::<Option<Vec<_>>>()?
            .try_into()
            .ok()
    }

    fn rotate_twist_square(&mut self, ids: [EntityId; 4]) {
        let positions = [
            (ids[2], 0_u8, 0_u8),
            (ids[0], 0, 1),
            (ids[3], 1, 0),
            (ids[1], 1, 1),
        ];
        let Some(top_left) = self
            .state
            .board
            .plants
            .iter()
            .find(|plant| plant.id == ids[0])
            .map(|plant| (plant.row, plant.column))
        else {
            return;
        };
        for (id, row_offset, column_offset) in positions {
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == id)
            {
                plant.row = top_left.0 + row_offset;
                plant.column = top_left.1 + column_offset;
            }
        }
    }

    fn beghouled_plant_ids(
        &self,
        from_column: u8,
        from_row: u8,
        to_column: u8,
        to_row: u8,
    ) -> Option<[EntityId; 2]> {
        [(from_row, from_column), (to_row, to_column)]
            .map(|(row, column)| {
                self.state
                    .board
                    .plants
                    .iter()
                    .find(|plant| plant.row == row && plant.column == column)
                    .map(|plant| plant.id)
            })
            .into_iter()
            .collect::<Option<Vec<_>>>()?
            .try_into()
            .ok()
    }

    fn swap_beghouled_plants(&mut self, from_column: u8, from_row: u8, to_column: u8, to_row: u8) {
        let Some(ids) = self.beghouled_plant_ids(from_column, from_row, to_column, to_row) else {
            return;
        };
        for (id, row, column) in [(ids[0], to_row, to_column), (ids[1], from_row, from_column)] {
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == id)
            {
                plant.row = row;
                plant.column = column;
            }
        }
    }

    fn swap_move_causes_match(
        &mut self,
        from_column: u8,
        from_row: u8,
        to_column: u8,
        to_row: u8,
    ) -> bool {
        let Some(ids) = self.beghouled_plant_ids(from_column, from_row, to_column, to_row) else {
            return false;
        };
        self.swap_beghouled_plants(from_column, from_row, to_column, to_row);
        let has_match = self.twist_has_match();
        self.swap_beghouled_plants(from_column, from_row, to_column, to_row);
        debug_assert!(
            self.beghouled_plant_ids(from_column, from_row, to_column, to_row)
                .is_some_and(|restored| restored == ids)
        );
        has_match
    }

    fn twist_move_causes_match(&mut self, column: u8, row: u8) -> bool {
        let Some(ids) = self.twist_square_ids(column, row) else {
            return false;
        };
        let original = ids.map(|id| {
            self.state
                .board
                .plants
                .iter()
                .find(|plant| plant.id == id)
                .map(|plant| (plant.row, plant.column))
                .expect("validated Twist plant")
        });
        self.rotate_twist_square(ids);
        let has_match = self.twist_has_match();
        for (id, (row, column)) in ids.into_iter().zip(original) {
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == id)
            {
                plant.row = row;
                plant.column = column;
            }
        }
        has_match
    }

    fn challenge_twist(&mut self, column: u8, row: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::ChallengeTwist { column, row };
        if self.state.challenge.kind != ChallengeKind::BeghouledTwist
            || self.state.challenge.twist_state != BeghouledTwistState::Normal
            || !self.twist_valid_square(column, row)
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        if !self.twist_move_causes_match(column, row) {
            events.push(GameEvent::ChallengeAction {
                kind: ChallengeKind::BeghouledTwist,
                value: 0,
            });
            return;
        }
        let ids = self
            .twist_square_ids(column, row)
            .expect("validated Twist square");
        self.rotate_twist_square(ids);
        self.state.challenge.twist_state = BeghouledTwistState::Moving;
        self.state.challenge.twist_counter = BEGHOULED_MOVE_TICKS;
        self.state.challenge.countdown = BEGHOULED_CHALLENGE_COUNTDOWN;
    }

    fn challenge_clear_crater(&mut self, events: &mut Vec<GameEvent>) {
        if !matches!(
            self.state.challenge.kind,
            ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
        ) || matches!(
            self.state.challenge.twist_state,
            BeghouledTwistState::Moving | BeghouledTwistState::Falling
        ) || self.state.sun < BEGHOULED_CRATER_COST
        {
            events.push(GameEvent::InputRejected {
                action: InputAction::ChallengeClearCrater,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        let Some(index) = self
            .state
            .board
            .craters
            .iter()
            .position(|crater| crater.remaining == u32::MAX)
        else {
            events.push(GameEvent::InputRejected {
                action: InputAction::ChallengeClearCrater,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        };
        self.state.sun -= BEGHOULED_CRATER_COST;
        self.state.board.craters.remove(index);
        self.refill_beghouled_twist();
        self.state.challenge.twist_state = BeghouledTwistState::Falling;
        self.state.challenge.twist_counter = BEGHOULED_MOVE_TICKS;
        self.state.challenge.countdown = BEGHOULED_CHALLENGE_COUNTDOWN;
        events.push(GameEvent::ChallengeAction {
            kind: self.state.challenge.kind,
            value: BEGHOULED_CRATER_COST,
        });
    }

    fn resolve_beghouled_twist(&mut self, events: &mut Vec<GameEvent>) {
        let mut removed = Vec::new();
        let mut rewards = Vec::new();
        let mut score_lines = 0_u32;
        for row in 0..BEGHOULED_ROWS {
            for column in 0..BEGHOULED_COLUMNS {
                let Some(seed) = self.twist_seed_at(row, column) else {
                    continue;
                };
                let horizontal = column == 0 || self.twist_seed_at(row, column - 1) != Some(seed);
                let horizontal_len = (column..BEGHOULED_COLUMNS)
                    .take_while(|&c| self.twist_seed_at(row, c) == Some(seed))
                    .count();
                let vertical = row == 0 || self.twist_seed_at(row - 1, column) != Some(seed);
                let vertical_len = (row..BEGHOULED_ROWS)
                    .take_while(|&r| self.twist_seed_at(r, column) == Some(seed))
                    .count();
                if horizontal && horizontal_len >= 3 {
                    score_lines += 1;
                    rewards.push((row, column, horizontal_len));
                    for offset in 0..horizontal_len {
                        if !removed.contains(&(row, column + offset as u8)) {
                            removed.push((row, column + offset as u8));
                        }
                    }
                }
                if vertical && vertical_len >= 3 {
                    score_lines += 1;
                    rewards.push((row, column, vertical_len));
                    for offset in 0..vertical_len {
                        if !removed.contains(&(row + offset as u8, column)) {
                            removed.push((row + offset as u8, column));
                        }
                    }
                }
            }
        }
        if removed.is_empty() {
            self.state.challenge.twist_state = BeghouledTwistState::Normal;
            return;
        }
        for (row, column) in removed {
            if let Some(index) = self
                .state
                .board
                .plants
                .iter()
                .position(|plant| plant.row == row && plant.column == column)
            {
                let entity = self.state.board.plants.remove(index).id;
                events.push(GameEvent::PlantDied { entity });
            }
        }
        self.state.challenge.score = self
            .state
            .challenge
            .score
            .saturating_add(score_lines)
            .min(self.state.challenge.target);
        if self.state.challenge.score < self.state.challenge.target {
            for (match_index, (row, column, length)) in rewards.into_iter().enumerate() {
                let mut sun_count = u32::try_from(length.saturating_sub(2)).unwrap_or(u32::MAX);
                sun_count =
                    sun_count.saturating_add(u32::try_from(match_index).unwrap_or(u32::MAX));
                if length >= 5 {
                    sun_count = sun_count.saturating_add(2);
                }
                for offset in 0..sun_count.clamp(1, 5) {
                    self.spawn_coin(
                        CoinType::Sun,
                        grid_x(column) + (i64::from(offset) * 20 - 10) * POSITION_SCALE,
                        grid_y(row),
                        events,
                    );
                }
            }
        }
        self.refill_beghouled_twist();
        self.state.challenge.twist_state = BeghouledTwistState::Falling;
        self.state.challenge.twist_counter = BEGHOULED_MOVE_TICKS;
        events.push(GameEvent::ChallengeAction {
            kind: self.state.challenge.kind,
            value: score_lines,
        });
    }

    fn finish_beghouled_twist_fall(&mut self, events: &mut Vec<GameEvent>) {
        self.state.challenge.countdown = BEGHOULED_CHALLENGE_COUNTDOWN;
        if self.twist_has_match() {
            self.resolve_beghouled_twist(events);
        } else {
            let has_move = if self.state.challenge.kind == ChallengeKind::Beghouled {
                self.has_standard_move()
            } else {
                self.has_twist_move()
            };
            if has_move {
                self.state.challenge.twist_state = BeghouledTwistState::Normal;
            } else {
                self.state.challenge.twist_state = BeghouledTwistState::NoMoves;
                self.state.challenge.twist_counter = BEGHOULED_NO_MOVES_TICKS;
            }
        }
    }

    fn shuffle_beghouled_twist(&mut self) {
        // ponytail: 100 bounded random fills cover the pathological no-move shuffle case.
        for _ in 0..100 {
            self.state
                .board
                .plants
                .retain(|plant| plant.column >= BEGHOULED_COLUMNS);
            self.refill_beghouled_twist();
            let has_move = if self.state.challenge.kind == ChallengeKind::Beghouled {
                self.has_standard_move()
            } else {
                self.has_twist_move()
            };
            if has_move {
                break;
            }
        }
        self.state.challenge.twist_state = BeghouledTwistState::Falling;
        self.state.challenge.twist_counter = BEGHOULED_MOVE_TICKS;
        self.state.challenge.countdown = BEGHOULED_CHALLENGE_COUNTDOWN;
    }

    fn beghouled_cell_has_match(&self, row: u8, column: u8) -> bool {
        let Some(seed) = self.twist_seed_at(row, column) else {
            return false;
        };
        let mut horizontal = 1;
        let mut left = column;
        while left > 0 && self.twist_seed_at(row, left - 1) == Some(seed) {
            left -= 1;
            horizontal += 1;
        }
        let mut right = column;
        while right + 1 < BEGHOULED_COLUMNS && self.twist_seed_at(row, right + 1) == Some(seed) {
            right += 1;
            horizontal += 1;
        }
        let mut vertical = 1;
        let mut top = row;
        while top > 0 && self.twist_seed_at(top - 1, column) == Some(seed) {
            top -= 1;
            vertical += 1;
        }
        let mut bottom = row;
        while bottom + 1 < BEGHOULED_ROWS && self.twist_seed_at(bottom + 1, column) == Some(seed) {
            bottom += 1;
            vertical += 1;
        }
        horizontal >= 3 || vertical >= 3
    }

    fn place_beghouled_refill_seed(&mut self, row: u8, column: u8) {
        let start = self.rng.range(BEGHOULED_SEED_TYPES.len() as u32) as usize;
        for offset in 0..BEGHOULED_SEED_TYPES.len() {
            let seed = BEGHOULED_SEED_TYPES[(start + offset) % BEGHOULED_SEED_TYPES.len()];
            self.place_beghouled_plant(seed, row, column);
            if !self.beghouled_cell_has_match(row, column) {
                return;
            }
            self.state.board.plants.pop();
        }
        let seed = BEGHOULED_SEED_TYPES[start];
        self.place_beghouled_plant(seed, row, column);
    }

    fn refill_beghouled_twist(&mut self) {
        let old_plants = std::mem::take(&mut self.state.board.plants);
        let mut columns = (0..BEGHOULED_COLUMNS)
            .map(|_| Vec::new())
            .collect::<Vec<Vec<PlantState>>>();
        let mut other_plants = Vec::new();
        for plant in old_plants {
            if plant.column < BEGHOULED_COLUMNS {
                columns[usize::from(plant.column)].push(plant);
            } else {
                other_plants.push(plant);
            }
        }
        self.state.board.plants = other_plants;
        for column in 0..BEGHOULED_COLUMNS {
            let column_plants = &mut columns[usize::from(column)];
            column_plants.sort_by_key(|plant| plant.row);
            let destinations = (0..BEGHOULED_ROWS)
                .rev()
                .filter(|row| {
                    !self
                        .state
                        .board
                        .craters
                        .iter()
                        .any(|crater| crater.row == *row && crater.column == column)
                })
                .collect::<Vec<_>>();
            for row in destinations.iter().copied() {
                if let Some(mut plant) = column_plants.pop() {
                    plant.row = row;
                    plant.column = column;
                    self.state.board.plants.push(plant);
                } else {
                    self.place_beghouled_refill_seed(row, column);
                }
            }
        }
    }

    fn mark_twist_eaten_plants(
        &mut self,
        before: &[(EntityId, u8, u8)],
        events: &mut Vec<GameEvent>,
    ) {
        if !matches!(
            self.state.challenge.kind,
            ChallengeKind::Beghouled | ChallengeKind::BeghouledTwist
        ) {
            return;
        }
        let missing = before
            .iter()
            .filter(|(id, _, _)| !self.state.board.plants.iter().any(|plant| plant.id == *id));
        for (_, row, column) in missing {
            if !self
                .state
                .board
                .craters
                .iter()
                .any(|crater| crater.row == *row && crater.column == *column)
            {
                self.state.board.craters.push(CraterState {
                    row: *row,
                    column: *column,
                    remaining: u32::MAX,
                    persistent: true,
                });
                events.push(GameEvent::CraterCreated {
                    row: *row,
                    column: *column,
                    duration: u32::MAX,
                });
            }
        }
    }

    fn has_twist_move(&mut self) -> bool {
        (0..BEGHOULED_ROWS - 1).any(|row| {
            (0..BEGHOULED_COLUMNS - 1).any(|column| self.twist_move_causes_match(column, row))
        })
    }

    fn has_standard_move(&mut self) -> bool {
        (0..BEGHOULED_ROWS).any(|row| {
            (0..BEGHOULED_COLUMNS).any(|column| {
                (column + 1 < BEGHOULED_COLUMNS
                    && self.swap_move_causes_match(column, row, column + 1, row))
                    || (row + 1 < BEGHOULED_ROWS
                        && self.swap_move_causes_match(column, row, column, row + 1))
            })
        })
    }

    fn challenge_feed(&mut self, x: u16, y: u16, events: &mut Vec<GameEvent>) {
        if self.state.challenge.kind != ChallengeKind::Zombiquarium
            || !(80..=720).contains(&x)
            || !(90..=430).contains(&y)
            || self.state.sun < ZOMBIQUARIUM_BRAIN_COST
            || self
                .state
                .board
                .brains
                .iter()
                .filter(|brain| !brain.squished && brain.position_x != 0)
                .count()
                >= ZOMBIQUARIUM_MAX_BRAINS
        {
            events.push(GameEvent::InputRejected {
                action: InputAction::ChallengeFeed { x, y },
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        self.state.sun -= ZOMBIQUARIUM_BRAIN_COST;
        self.state.board.brains.push(BrainState {
            row: 0,
            position_x: i64::from(x) * POSITION_SCALE,
            position_y: i64::from(y) * POSITION_SCALE,
            age: 0,
            remaining: 0,
            squished: false,
        });
        events.push(GameEvent::ChallengeAction {
            kind: ChallengeKind::Zombiquarium,
            value: ZOMBIQUARIUM_BRAIN_COST,
        });
    }

    fn challenge_whack(
        &mut self,
        row: u8,
        column: u8,
        x: u16,
        y: u16,
        events: &mut Vec<GameEvent>,
    ) {
        let action = InputAction::ChallengeWhack { row, column, x, y };
        if self.state.challenge.kind != ChallengeKind::WhackAZombie
            || row >= self.state.board.rows
            || column >= self.state.board.columns
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        events.push(GameEvent::WhackHammerSwung);
        let center = grid_x(column);
        let Some(index) = self.state.board.zombies.iter().position(|zombie| {
            zombie.health > 0
                && zombie.row == row
                && (zombie.position_x - center).abs() <= 80 * POSITION_SCALE
        }) else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::MissingEntity,
            });
            return;
        };
        let entity = self.state.board.zombies[index].id;
        let (sound, variant) = match self.state.board.zombies[index].zombie_type {
            ZombieType::Buckethead if self.state.board.zombies[index].armor_intact => {
                (WhackHitSound::Shield, self.rng.range(2) as u8)
            }
            ZombieType::Conehead if self.state.board.zombies[index].armor_intact => {
                (WhackHitSound::Plastic, self.rng.range(2) as u8)
            }
            _ => (WhackHitSound::Bonk, 0),
        };
        events.push(GameEvent::WhackHit {
            x,
            y,
            sound,
            variant,
        });
        if sound == WhackHitSound::Bonk {
            self.state.board.zombies[index].health = 0;
            self.emit_zombie_died_with_loot(entity, events);
            self.state.board.zombies.remove(index);
        } else {
            let zombie = &mut self.state.board.zombies[index];
            zombie.health = (zombie.health - WHACK_HELM_DAMAGE).max(WHACK_BODY_HEALTH);
            if zombie.health == WHACK_BODY_HEALTH {
                zombie.armor_intact = false;
                events.push(GameEvent::ZombieArmorLost { entity });
            }
        }
        events.push(GameEvent::ChallengeAction {
            kind: ChallengeKind::WhackAZombie,
            value: 1,
        });
    }

    fn select_seed(&mut self, slot: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::SelectSeed { slot };
        let Some(packet) = self
            .state
            .board
            .seed_packets
            .iter()
            .find(|packet| packet.slot == slot)
        else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidSlot,
            });
            return;
        };
        if self.state.challenge.kind == ChallengeKind::SlotMachine {
            self.challenge_spin(events);
            return;
        }
        let packet_type = packet.plant_type;
        if self.state.challenge.kind == ChallengeKind::Zombiquarium {
            self.challenge_zombiquarium_packet(packet_type, events);
            return;
        }
        if packet.refresh_remaining != 0 {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::SeedRefreshing,
            });
            return;
        }
        if !packet.plant_type.is_plant() {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidSlot,
            });
            return;
        }

        self.state.board.selected_usable_seed = None;
        self.state.board.selected_seed = Some(slot);
        events.push(GameEvent::SeedSelected {
            slot,
            plant_type: packet.plant_type,
        });
    }

    fn challenge_zombiquarium_packet(
        &mut self,
        packet_type: PlantType,
        events: &mut Vec<GameEvent>,
    ) {
        let cost = match packet_type {
            PlantType::ZombiquariumSnorkel => ZOMBIQUARIUM_SNORKEL_COST,
            PlantType::ZombiquariumTrophy => ZOMBIQUARIUM_TROPHY_COST,
            _ => {
                events.push(GameEvent::InputRejected {
                    action: InputAction::SelectSeed {
                        slot: packet_type.slot(),
                    },
                    reason: InputRejectReason::InvalidSlot,
                });
                return;
            }
        };
        if self.state.sun < cost {
            events.push(GameEvent::InputRejected {
                action: InputAction::SelectSeed {
                    slot: packet_type.slot(),
                },
                reason: InputRejectReason::NotEnoughSun,
            });
            return;
        }
        if packet_type == PlantType::ZombiquariumSnorkel
            && self.state.board.zombies.len() > ZOMBIQUARIUM_MAX_ZOMBIES
        {
            events.push(GameEvent::InputRejected {
                action: InputAction::SelectSeed {
                    slot: packet_type.slot(),
                },
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }

        self.state.sun -= cost;
        match packet_type {
            PlantType::ZombiquariumSnorkel => {
                self.spawn_zombiquarium_snorkel(events);
                events.push(GameEvent::ZombiquariumSnorkelPurchased {
                    variant: self.rng.range(2) as u8,
                });
            }
            PlantType::ZombiquariumTrophy => {
                self.spawn_pickup(CoinType::Trophy, grid_x(2), grid_y(0), events);
                let trophy = self.state.board.coins.last().map(|coin| coin.id);
                if let Some(trophy) = trophy {
                    self.collect_coin(trophy, events);
                }
                self.state.scene = SceneKind::Complete;
                events.push(GameEvent::GameWon);
            }
            _ => unreachable!(),
        }
        events.push(GameEvent::ChallengeAction {
            kind: ChallengeKind::Zombiquarium,
            value: cost,
        });
    }

    fn deploy_zombie(
        &mut self,
        zombie_type: ZombieType,
        row: u8,
        column: u8,
        events: &mut Vec<GameEvent>,
    ) {
        let action = InputAction::DeployZombie {
            zombie_type,
            row,
            column,
        };
        if self.state.mode != ModeKind::IZombie
            || row >= self.state.board.rows
            || column >= izombie_columns(self.state.level)
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidTerrain,
            });
            return;
        }
        if !self.state.board.zombie_packets.contains(&zombie_type) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidSlot,
            });
            return;
        }
        // Plant::GetCost in 1.0.0.1051 prices the I, Zombie seed cards;
        // types without a source card keep their previous fallback values.
        let cost = match zombie_type {
            ZombieType::Normal | ZombieType::Flag | ZombieType::Imp => 50,
            ZombieType::Conehead | ZombieType::PoleVaulter => 75,
            ZombieType::ScreenDoor => 100,
            ZombieType::Buckethead
            | ZombieType::Newspaper
            | ZombieType::Digger
            | ZombieType::Bungee => 125,
            ZombieType::Ladder | ZombieType::Balloon | ZombieType::Jackbox => 150,
            ZombieType::Bobsled => 150,
            ZombieType::Football | ZombieType::Zamboni => 175,
            ZombieType::Pogo => 200,
            ZombieType::Dancer => 350,
            ZombieType::Gargantuar | ZombieType::Gigagargantuar => 300,
            _ => 100,
        };
        if self.state.sun < cost {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NotEnoughSun,
            });
            return;
        }
        self.state.sun -= cost;
        let health = match zombie_type {
            // I, Zombie imps use the source 70-HP override; everywhere else imps are 270.
            ZombieType::Imp => 70,
            ZombieType::Conehead => 640,
            ZombieType::Buckethead => 1_370,
            ZombieType::ScreenDoor => 270,
            ZombieType::Football => 1_670,
            ZombieType::Digger => 370,
            ZombieType::Bungee => 450,
            ZombieType::PoleVaulter | ZombieType::Pogo | ZombieType::Dancer => 500,
            ZombieType::Ladder => LADDER_HEALTH,
            ZombieType::Bobsled => BOBSLED_HEALTH,
            ZombieType::Gargantuar => 3_000,
            ZombieType::Gigagargantuar => GIGAGARGANTUAR_HEALTH,
            ZombieType::JalapenoHead => ZOMBOTANY_JALAPENO_HEALTH,
            ZombieType::Boss => {
                if self.state.mode == ModeKind::Adventure {
                    BOSS_ADVENTURE_HEALTH
                } else {
                    BOSS_CHALLENGE_HEALTH
                }
            }
            _ => 270,
        };
        let position = Some(grid_x(column) - 30 * POSITION_SCALE);
        let entity = if zombie_type == ZombieType::Bobsled {
            self.spawn_bobsled_zombie(row, 0, position, events)
        } else if zombie_type == ZombieType::Bungee {
            self.spawn_bungee_zombie_at(row, 0, column, events)
        } else {
            self._spawn_zombie_inner(zombie_type, health, row, 0, position, events)
        };
        events.push(GameEvent::ZombieDeployed {
            entity,
            zombie_type,
            row,
            column,
            sun_remaining: self.state.sun,
            variant: self.rng.range(2) as u8,
        });
    }

    fn plant(&mut self, row: u8, column: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::Plant { row, column };
        let plant_type = if let Some(plant_type) = self.state.board.selected_usable_seed {
            plant_type
        } else {
            let Some(slot) = self.state.board.selected_seed else {
                events.push(GameEvent::InputRejected {
                    action,
                    reason: InputRejectReason::NoSeedSelected,
                });
                return;
            };
            let Some(packet) = self
                .state
                .board
                .seed_packets
                .iter()
                .find(|packet| packet.slot == slot)
            else {
                events.push(GameEvent::InputRejected {
                    action,
                    reason: InputRejectReason::InvalidSlot,
                });
                return;
            };
            packet.plant_type
        };
        if !plant_type.is_plant() {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidSlot,
            });
            return;
        }
        if plant_type.is_cob_cannon() {
            self.plant_cob_cannon(row, column, events);
            return;
        }
        if plant_type.is_imitater() {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidSlot,
            });
            return;
        }
        self.plant_selected(action, row, column, plant_type, None, events);
    }

    fn plant_cob_cannon(&mut self, row: u8, column: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::Plant { row, column };
        if self.state.challenge.kind == ChallengeKind::SeeingStars && seeing_stars_cell(row, column)
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NotOnArt,
            });
            return;
        }
        let Some(right_column) = column.checked_add(1) else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::OutsideBoard,
            });
            return;
        };
        if row >= self.state.board.rows || right_column >= self.state.board.columns {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::OutsideBoard,
            });
            return;
        }

        let kernel_slot = 34;
        let left_index = self.state.board.plants.iter().position(|plant| {
            plant.row == row && plant.column == column && plant.plant_type.slot() == kernel_slot
        });
        let right_index = self.state.board.plants.iter().position(|plant| {
            plant.row == row
                && plant.column == right_column
                && plant.plant_type.slot() == kernel_slot
        });
        let (Some(left_index), Some(right_index)) = (left_index, right_index) else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::Occupied,
            });
            return;
        };
        let has_support = |column: u8, slot: u8| {
            self.state.board.plants.iter().any(|plant| {
                plant.row == row && plant.column == column && plant.plant_type.slot() == slot
            })
        };
        let left_lilypad = has_support(column, 16);
        let right_lilypad = has_support(right_column, 16);
        let left_flowerpot = has_support(column, 33);
        let right_flowerpot = has_support(right_column, 33);
        let valid_support = match self.state.scene {
            SceneKind::Pool => left_lilypad && right_lilypad,
            SceneKind::Roof => left_flowerpot && right_flowerpot,
            _ => left_lilypad == right_lilypad && left_flowerpot == right_flowerpot,
        };
        let has_pumpkin = self.state.board.plants.iter().any(|plant| {
            plant.row == row
                && (plant.column == column || plant.column == right_column)
                && plant.plant_type.slot() == 30
        });
        if !valid_support || has_pumpkin {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidTerrain,
            });
            return;
        }

        let cannon_type = PlantType::Other(47);
        if self.state.sun < cannon_type.cost() {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NotEnoughSun,
            });
            return;
        }
        let packet_index = self
            .state
            .board
            .seed_packets
            .iter()
            .position(|packet| packet.slot == cannon_type.slot())
            .expect("selected CobCannon packet must exist");
        self.state.sun -= cannon_type.cost();
        self.state.board.selected_seed = None;
        self.state.board.selected_usable_seed = None;
        self.state.board.seed_packets[packet_index].refresh_remaining =
            cannon_type.refresh_time() + 1;

        let consumed = self.state.board.plants[right_index].id;
        self.state.board.plants.remove(right_index);
        let left_index = if left_index > right_index {
            left_index - 1
        } else {
            left_index
        };
        let cannon_id = self.state.board.plants[left_index].id;
        let cannon_health = cannon_type.max_health();
        let blink_counter = 400 + self.rng.range(400);
        let cannon = &mut self.state.board.plants[left_index];
        cannon.plant_type = cannon_type;
        cannon.imitater_type = None;
        cannon.health = cannon_health;
        cannon.max_health = cannon_health;
        cannon.launch_counter = 0;
        cannon.launch_rate = 0;
        cannon.shooting_counter = 0;
        cannon.firing_directions = 0;
        cannon.production_age = 0;
        cannon.production_stage = 0;
        cannon.special_counter = COB_ARM_TICKS;
        cannon.special_armed = false;
        cannon.special_target = None;
        cannon.blink_counter = blink_counter;
        cannon.asleep = false;
        cannon.wake_up_counter = 0;
        events.push(GameEvent::PlantCombined {
            entity: cannon_id,
            consumed,
            plant_type: cannon_type,
        });
        events.push(GameEvent::PlantPlaced {
            entity: cannon_id,
            plant_type: cannon_type,
            row,
            column,
            sun_remaining: self.state.sun,
            variant: self.rng.range(2) as u8,
        });
    }

    fn plant_imitater(&mut self, plant_slot: u8, row: u8, column: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::PlantImitater {
            plant_slot,
            row,
            column,
        };
        if self.state.board.selected_seed != Some(48) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NoSeedSelected,
            });
            return;
        }
        let Some(target) = PlantType::from_slot(plant_slot).filter(|target| !target.is_imitater())
        else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidSlot,
            });
            return;
        };
        self.plant_selected(
            action,
            row,
            column,
            PlantType::Other(48),
            Some(target),
            events,
        );
    }

    fn fire_cob_cannon(
        &mut self,
        entity: EntityId,
        target_row: u8,
        target_column: u8,
        events: &mut Vec<GameEvent>,
    ) {
        let action = InputAction::FireCobCannon {
            entity,
            row: target_row,
            column: target_column,
        };
        if target_row >= self.state.board.rows || target_column >= self.state.board.columns {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::OutsideBoard,
            });
            return;
        }
        let Some(index) = self
            .state
            .board
            .plants
            .iter()
            .position(|plant| plant.id == entity && plant.plant_type.is_cob_cannon())
        else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::MissingEntity,
            });
            return;
        };
        if !self.state.board.plants[index].special_armed {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NotReady,
            });
            return;
        }
        self.state.board.plants[index].special_armed = false;
        // Source CobCannonFire (Plant.cpp:4502-4516) stores the target and the
        // 206-tick firing counter; the Cob projectile is created only at the
        // UpdateShooting launch boundary.
        self.state.board.plants[index].special_counter = COB_RELOAD_TICKS;
        self.state.board.plants[index].cob_target = Some((target_row, target_column));
        events.push(GameEvent::CobCannonFired {
            entity,
            target_row,
            target_column,
        });
    }

    fn plant_selected(
        &mut self,
        action: InputAction,
        row: u8,
        column: u8,
        plant_type: PlantType,
        imitater_type: Option<PlantType>,
        events: &mut Vec<GameEvent>,
    ) {
        let effective_type = imitater_type.unwrap_or(plant_type);
        if row >= self.state.board.rows || column >= self.state.board.columns {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::OutsideBoard,
            });
            return;
        }
        if self.state.challenge.kind == ChallengeKind::SeeingStars
            && seeing_stars_cell(row, column)
            && !matches!(plant_type.slot(), 16 | 29 | 30)
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NotOnArt,
            });
            return;
        }
        if self.state.mode == ModeKind::Adventure && !adventure_row_is_sodded(self.state.level, row)
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidTerrain,
            });
            return;
        }
        let has_lilypad = self.state.board.plants.iter().any(|plant| {
            plant.row == row && plant.column == column && plant.plant_type.slot() == 16
        });
        let has_flowerpot = self.state.board.plants.iter().any(|plant| {
            plant.row == row && plant.column == column && plant.plant_type.slot() == 33
        });
        let aquatic = matches!(effective_type.slot(), 16 | 19 | 24);
        let valid_terrain = if scene_row_is_water(self.state.scene, row) {
            aquatic || effective_type.slot() == 43 || has_lilypad
        } else if self.state.scene == SceneKind::Roof {
            effective_type.slot() == 33 || has_flowerpot
        } else {
            !aquatic && effective_type.slot() != 33
        };
        if !valid_terrain {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidTerrain,
            });
            return;
        }
        let has_grave = self
            .state
            .board
            .graves
            .iter()
            .any(|grave| grave.row == row && grave.column == column);
        if effective_type.slot() == 11 && !has_grave {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::InvalidTerrain,
            });
            return;
        }
        let occupied = self
            .state
            .board
            .plants
            .iter()
            .any(|plant| plant.row == row && plant.column == column);
        let has_top_plant = self.state.board.plants.iter().any(|plant| {
            plant.row == row
                && plant.column == column
                && !matches!(plant.plant_type.slot(), 16 | 33)
        });
        // Source Board::GetTopPlantAt resolves Coffee through the normal plant
        // layer only: support (Lily Pad/Flower Pot), Pumpkin, and another
        // flying Coffee are separate slots and never reject a valid overlay.
        let coffee_target = self.state.board.plants.iter().any(|plant| {
            plant.row == row
                && plant.column == column
                && !matches!(plant.plant_type.slot(), 16 | 30 | 33 | 35)
                && plant.plant_type.is_nocturnal()
                && plant.asleep
                && plant.wake_up_counter == 0
        });
        let coffee_already_present = self.state.board.plants.iter().any(|plant| {
            plant.row == row && plant.column == column && plant.plant_type.slot() == 35
        });
        let pumpkin_already_present = self.state.board.plants.iter().any(|plant| {
            plant.row == row && plant.column == column && plant.plant_type.slot() == 30
        });
        let has_magnet_shroom = self.state.board.plants.iter().any(|plant| {
            plant.row == row && plant.column == column && plant.plant_type.slot() == 31
        });
        let gold_magnet_already_present = self.state.board.plants.iter().any(|plant| {
            plant.row == row && plant.column == column && plant.plant_type.slot() == 45
        });
        if effective_type.slot() == 45 && !has_magnet_shroom {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::Occupied,
            });
            return;
        }
        if effective_type.slot() == 35 && (coffee_already_present || !coffee_target) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::Occupied,
            });
            return;
        }
        let can_layer_on_support = ((has_lilypad || has_flowerpot)
            && !has_top_plant
            && !matches!(effective_type.slot(), 16 | 19 | 24 | 33))
            || (effective_type.slot() == 45 && has_magnet_shroom && !gold_magnet_already_present)
            || (effective_type.slot() == 35 && coffee_target);
        if occupied
            && ((effective_type.slot() == 30 && pumpkin_already_present)
                || (effective_type.slot() != 30 && !can_layer_on_support))
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::Occupied,
            });
            return;
        }
        if self
            .state
            .board
            .craters
            .iter()
            .any(|crater| crater.row == row && crater.column == column)
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::Crater,
            });
            return;
        }
        if self.is_ice_at(row, column) {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::Ice,
            });
            return;
        }

        let usable_seed = self.state.board.selected_usable_seed.is_some();
        let packet_index = if usable_seed {
            None
        } else {
            let packet_slot = self
                .state
                .board
                .selected_seed
                .expect("planting requires a selected seed packet");
            Some(
                self.state
                    .board
                    .seed_packets
                    .iter()
                    .position(|packet| packet.slot == packet_slot)
                    .expect("selected seed packet must exist"),
            )
        };
        let conveyor = self.has_conveyor_seed_bank();
        if !usable_seed && !conveyor && self.state.sun < effective_type.cost() {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NotEnoughSun,
            });
            return;
        }

        if !usable_seed && !conveyor {
            self.state.sun -= effective_type.cost();
        }
        self.state.board.selected_seed = None;
        self.state.board.selected_usable_seed = None;
        if let Some(packet_index) = packet_index {
            if conveyor {
                self.remove_conveyor_seed(packet_index);
            } else {
                self.state.board.seed_packets[packet_index].refresh_remaining =
                    effective_type.refresh_time() + 1;
            }
        }
        let id = self.state.board.allocate_entity();

        // Preserve the original gameplay RNG stream even before render state consumes these values.
        let _frame_length = self.rng.range_inclusive(12, 18);
        let _body_animation_rate = self.rng.next();
        let blink_counter = 400 + self.rng.range(400);
        if effective_type == PlantType::Peashooter {
            let _head_animation_rate = self.rng.next();
        }
        let launch_rate = effective_type.launch_rate();
        let launch_counter = if launch_rate == 0 {
            0
        } else if effective_type.is_producer() {
            self.rng.range_inclusive(300, launch_rate / 2)
        } else {
            self.rng.range_inclusive(0, launch_rate)
        };
        let max_health = effective_type.max_health();
        let asleep = effective_type.is_nocturnal() && !scene_is_night(self.state.scene);
        let (special_counter, special_armed) = if imitater_type.is_some() {
            (IMITATER_MORPH_TICKS, false)
        } else if effective_type.is_instant_coffee() {
            (COFFEE_WAKE_TICKS, false)
        } else if effective_type.is_gravebuster() {
            (GRAVEBUSTER_EAT_TICKS, false)
        } else if effective_type.is_blover() {
            (BLOVER_SPECIAL_COUNTDOWN, false)
        } else if effective_type.is_cherry_bomb()
            || effective_type.is_jalapeno()
            || effective_type.is_ice_shroom()
            || effective_type.is_doom_shroom()
        {
            (INSTANT_PLANT_COUNTDOWN, false)
        } else if effective_type.is_potato_mine() {
            (POTATO_ARM_TICKS, false)
        } else {
            (0, false)
        };
        self.state.board.plants.push(PlantState {
            id,
            plant_type,
            imitater_type,
            row,
            column,
            position_x: grid_x(column),
            position_y: grid_y(row),
            bowling_direction: 0,
            health: max_health,
            max_health,
            launch_counter,
            launch_rate,
            shooting_counter: 0,
            recently_eaten_counter: 0,
            firing_directions: 0,
            kernel_pult_projectile: None,
            production_age: 0,
            production_stage: 0,
            special_counter,
            special_armed,
            special_target: None,
            bungee_lifted: false,
            squash_target_x: None,
            cob_target: None,
            blink_counter,
            asleep,
            wake_up_counter: 0,
        });
        events.push(GameEvent::PlantPlaced {
            entity: id,
            plant_type,
            row,
            column,
            sun_remaining: self.state.sun,
            variant: self.rng.range(2) as u8,
        });
    }

    fn morph_imitater(&mut self, index: usize, target: PlantType, events: &mut Vec<GameEvent>) {
        let entity = self.state.board.plants[index].id;
        let _frame_length = self.rng.range_inclusive(12, 18);
        let _body_animation_rate = self.rng.next();
        let blink_counter = 400 + self.rng.range(400);
        if target == PlantType::Peashooter {
            let _head_animation_rate = self.rng.next();
        }
        let launch_rate = target.launch_rate();
        let launch_counter = if launch_rate == 0 {
            0
        } else if target.is_producer() {
            self.rng.range_inclusive(300, launch_rate / 2)
        } else {
            self.rng.range_inclusive(0, launch_rate)
        };
        let asleep = target.is_nocturnal() && !scene_is_night(self.state.scene);
        let (special_counter, special_armed) = if target.is_cob_cannon() {
            (COB_ARM_TICKS, false)
        } else if target.is_instant_coffee() {
            (COFFEE_WAKE_TICKS, false)
        } else if target.is_gravebuster() {
            (GRAVEBUSTER_EAT_TICKS, false)
        } else if target.is_blover() {
            (BLOVER_SPECIAL_COUNTDOWN, false)
        } else if target.is_cherry_bomb()
            || target.is_jalapeno()
            || target.is_ice_shroom()
            || target.is_doom_shroom()
        {
            (INSTANT_PLANT_COUNTDOWN, false)
        } else if target.is_potato_mine() {
            (POTATO_ARM_TICKS, false)
        } else {
            (0, false)
        };
        let plant = &mut self.state.board.plants[index];
        plant.plant_type = target;
        plant.health = target.max_health();
        plant.max_health = target.max_health();
        plant.launch_counter = launch_counter;
        plant.launch_rate = launch_rate;
        plant.shooting_counter = 0;
        plant.firing_directions = 0;
        plant.kernel_pult_projectile = None;
        plant.production_age = 0;
        plant.production_stage = 0;
        plant.special_counter = special_counter;
        plant.special_armed = special_armed;
        plant.special_target = None;
        plant.blink_counter = blink_counter;
        plant.asleep = asleep;
        plant.wake_up_counter = 0;
        events.push(GameEvent::ImitaterMorphed {
            entity,
            plant_type: target,
        });
    }

    fn shovel(&mut self, row: u8, column: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::Shovel { row, column };
        if self.state.challenge.kind == ChallengeKind::BeghouledTwist {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::ChallengeUnavailable,
            });
            return;
        }
        let Some(index) = self
            .state
            .board
            .plants
            .iter()
            .rposition(|plant| plant.row == row && plant.column == column)
        else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::MissingEntity,
            });
            return;
        };
        let entity = self.state.board.plants.remove(index).id;
        self.state
            .board
            .ladders
            .retain(|ladder| ladder.row != row || ladder.column != column);
        events.push(GameEvent::PlantShoveled { entity });
    }

    fn break_vase(&mut self, row: u8, column: u8, events: &mut Vec<GameEvent>) {
        let action = InputAction::BreakVase { row, column };
        let Some(index) = self
            .state
            .board
            .vases
            .iter()
            .position(|vase| vase.row == row && vase.column == column)
        else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::NoVase,
            });
            return;
        };
        let vase = self.state.board.vases.remove(index);
        events.push(GameEvent::VaseBroken {
            entity: vase.id,
            row: vase.row,
            column: vase.column,
        });
        events.push(GameEvent::VaseRevealed {
            entity: vase.id,
            row: vase.row,
            column: vase.column,
            contents: vase.contents,
            leaf: vase.leaf,
        });
        match vase.contents {
            VaseContents::Plant(_) => {}
            VaseContents::Zombie(zombie_type) => {
                self.spawn_vase_zombie(zombie_type, vase.row, vase.column, events);
            }
            VaseContents::Sun(value) => {
                self.spawn_sun_value(
                    SunSource::Plant(vase.id),
                    u32::from(value) * SMALL_SUN_VALUE,
                    grid_x(vase.column),
                    grid_y(vase.row),
                    events,
                );
            }
        }
    }

    fn collect_sun(&mut self, entity: EntityId, events: &mut Vec<GameEvent>) {
        let action = InputAction::CollectSun { entity };
        let Some(index) = self
            .state
            .board
            .suns
            .iter()
            .position(|sun| sun.id == entity)
        else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::MissingEntity,
            });
            return;
        };
        let sun = self.state.board.suns.remove(index);
        self.state.sun = self.state.sun.saturating_add(sun.value).min(MAX_SUN);
        events.push(GameEvent::SunCollected {
            entity,
            value: sun.value,
            sun_total: self.state.sun,
        });
    }

    fn collect_coin(&mut self, entity: EntityId, events: &mut Vec<GameEvent>) {
        let action = InputAction::CollectCoin { entity };
        if self
            .state
            .board
            .gold_magnet_targets
            .iter()
            .any(|(coin_id, _)| *coin_id == entity)
        {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::MissingEntity,
            });
            return;
        }
        let Some(index) = self
            .state
            .board
            .coins
            .iter()
            .position(|coin| coin.id == entity)
        else {
            events.push(GameEvent::InputRejected {
                action,
                reason: InputRejectReason::MissingEntity,
            });
            return;
        };
        let coin = self.state.board.coins.remove(index);
        let mut value = coin.value;
        if coin.coin_type.is_sun() {
            value = coin.coin_type.sun_value();
            self.state.sun = self.state.sun.saturating_add(value).min(MAX_SUN);
        } else if coin.coin_type.is_money() {
            self.state.coins = self.state.coins.saturating_add(value);
        } else if coin.coin_type.unlock_mask() != 0 {
            self.state.unlocked_modes |= coin.coin_type.unlock_mask();
        } else if matches!(
            coin.coin_type,
            CoinType::Chocolate | CoinType::AwardChocolate
        ) {
            self.state.chocolates = self.state.chocolates.saturating_add(1);
            value = 1;
        } else if matches!(
            coin.coin_type,
            CoinType::PresentPlant | CoinType::AwardPresent
        ) {
            // ZenGarden::IsZenGardenFull(false) rejects the plant while still
            // consuming the pickup (Coin.cpp:1053-1067); only the Zen garden
            // counts toward the 8 x 4 capacity.
            if !self.is_zen_garden_full(false) {
                self.state.garden.plants.push(GardenPlant {
                    plant_type: coin.plant_type.unwrap_or(PlantType::Peashooter),
                    age_ticks: 0,
                    watered: false,
                    happy: false,
                    growth_stage: 0,
                    times_fed: 0,
                    feedings_per_grow: 4,
                    need_cooldown_ticks: 0,
                    last_watered_unix_seconds: 0,
                    last_fertilized_unix_seconds: 0,
                    last_need_fulfilled_unix_seconds: 0,
                    need: GardenNeed::Water,
                    which_garden: GardenServiceKind::Zen,
                });
            }
            value = 1;
        } else if coin.coin_type == CoinType::UsableSeedPacket {
            if let Some(plant_type) = coin.usable_seed_type {
                self.state.board.selected_usable_seed = Some(plant_type);
                self.state.board.selected_seed = Some(plant_type.slot());
            } else {
                self.state.pickup_inventory.push(coin.coin_type);
            }
            value = 1;
        } else {
            self.state.pickup_inventory.push(coin.coin_type);
            value = if coin.coin_type.is_level_award() {
                1
            } else {
                coin.value.max(1)
            };
        }
        if coin.coin_type.is_level_award()
            && !matches!(
                coin.coin_type,
                CoinType::AwardPresent | CoinType::AwardChocolate
            )
        {
            let endless_award =
                matches!(self.state.mode, ModeKind::IZombie | ModeKind::Vasebreaker)
                    && self.state.level == 9;
            let scary_potter = (self.state.mode == ModeKind::Vasebreaker && self.state.level < 9)
                || (self.state.mode == ModeKind::Adventure && self.state.level == 35);
            if endless_award {
                match coin.coin_type {
                    CoinType::AwardBagDiamond => events.push(GameEvent::AwardCollectionSound {
                        sound: AwardCollectionSound::Diamond,
                    }),
                    CoinType::AwardMoneyBag => events.push(GameEvent::AwardCollectionSound {
                        sound: AwardCollectionSound::Coin,
                    }),
                    _ => {}
                }
            } else if scary_potter {
                if matches!(coin.coin_type, CoinType::Trophy | CoinType::AwardMoneyBag) {
                    events.push(GameEvent::AwardCollectionSound {
                        sound: AwardCollectionSound::Coin,
                    });
                }
            } else if (self.state.mode == ModeKind::Adventure && self.state.level == 50)
                || coin.coin_type == CoinType::AwardGoldSunflower
            {
            } else if self.state.mode == ModeKind::Adventure
                && self.state.adventure_first_time
                && self.state.level == 4
            {
                events.push(GameEvent::AwardCollectionSound {
                    sound: AwardCollectionSound::Shovel,
                });
            } else if self.state.mode == ModeKind::Adventure
                && self.state.adventure_first_time
                && matches!(self.state.level, 24 | 34 | 44)
            {
                events.push(GameEvent::AwardCollectionSound {
                    sound: AwardCollectionSound::Tap2,
                });
            } else if coin.coin_type == CoinType::Trophy {
                events.push(GameEvent::AwardCollectionSound {
                    sound: AwardCollectionSound::Diamond,
                });
            } else if coin.coin_type == CoinType::AwardMoneyBag {
                events.push(GameEvent::AwardCollectionSound {
                    sound: AwardCollectionSound::Coin,
                });
            } else {
                events.push(GameEvent::AwardCollectionSound {
                    sound: AwardCollectionSound::Seedlift,
                });
                events.push(GameEvent::AwardCollectionSound {
                    sound: AwardCollectionSound::Tap2,
                });
            }
        }
        if let Some((fanout_type, count)) = self.award_fanout(coin.coin_type) {
            self.spawn_coins_from_present(
                fanout_type,
                coin.position_x + 20 * POSITION_SCALE,
                coin.position_y,
                count,
            );
        }
        events.push(GameEvent::PickupCollected {
            entity,
            coin_type: coin.coin_type,
            value,
            coins_total: self.state.coins,
            sun_total: self.state.sun,
        });
        if coin.coin_type.is_money() {
            events.push(GameEvent::CoinCollected {
                entity,
                coin_type: coin.coin_type,
                value: coin.value,
                coin_total: self.state.coins,
            });
        }
    }

    fn award_fanout(&self, coin_type: CoinType) -> Option<(CoinType, usize)> {
        if coin_type.is_level_award()
            && self.state.mode == ModeKind::Adventure
            && self.state.level == 50
        {
            return Some((CoinType::Diamond, 3));
        }
        if self.state.mode == ModeKind::Adventure && self.state.level == 35 {
            return matches!(coin_type, CoinType::Trophy | CoinType::AwardMoneyBag)
                .then_some((CoinType::Gold, 5));
        }
        if matches!(self.state.mode, ModeKind::IZombie | ModeKind::Vasebreaker)
            && self.state.level == 9
        {
            return match coin_type {
                CoinType::AwardBagDiamond => Some((CoinType::Diamond, 1)),
                CoinType::AwardMoneyBag => Some((CoinType::Gold, 5)),
                _ => None,
            };
        }
        match coin_type {
            CoinType::Trophy => Some((CoinType::Diamond, 1)),
            CoinType::AwardMoneyBag => Some((CoinType::Gold, 5)),
            CoinType::AwardGoldSunflower => Some((CoinType::Diamond, 5)),
            _ => None,
        }
    }

    fn tick_gold_magnet_suck(&mut self, plant_id: EntityId) -> bool {
        let Some(index) = self
            .state
            .board
            .gold_magnet_suck_ticks
            .iter()
            .position(|(id, _)| *id == plant_id)
        else {
            return false;
        };
        let ticks = &mut self.state.board.gold_magnet_suck_ticks[index].1;
        *ticks = ticks.saturating_sub(1);
        *ticks == 0
    }

    fn gold_magnet_about_to_suck(&self, plant_id: EntityId) -> bool {
        let early_ticks = (GOLD_MAGNET_SUCK_TICKS / 2).max(1);
        self.state
            .board
            .gold_magnet_suck_ticks
            .iter()
            .any(|(id, ticks)| *id != plant_id && *ticks >= early_ticks)
    }

    fn find_gold_magnet_target(
        &self,
        row: u8,
        column: u8,
        excluded: &[EntityId],
    ) -> Option<EntityId> {
        let plant_x = grid_x(column) + 40 * POSITION_SCALE;
        let plant_y = grid_y(row) + 40 * POSITION_SCALE;
        self.state
            .board
            .coins
            .iter()
            .filter(|coin| {
                coin.coin_type.is_money()
                    && !coin.from_present
                    && coin.age >= 50
                    && !excluded.contains(&coin.id)
                    && !self
                        .state
                        .board
                        .gold_magnet_targets
                        .iter()
                        .any(|(coin_id, _)| *coin_id == coin.id)
            })
            .min_by_key(|coin| {
                let dx = coin.position_x + 30 * POSITION_SCALE - plant_x;
                let dy = coin.position_y + 30 * POSITION_SCALE - plant_y;
                dx * dx + dy * dy
            })
            .map(|coin| coin.id)
    }

    fn capture_gold_magnet_targets(&mut self, plant_id: EntityId, row: u8, column: u8) {
        let mut selected = Vec::with_capacity(GOLD_MAGNET_MAX_ITEMS);
        while selected.len() < GOLD_MAGNET_MAX_ITEMS {
            let Some(coin_id) = self.find_gold_magnet_target(row, column, &selected) else {
                break;
            };
            selected.push(coin_id);
            self.state
                .board
                .gold_magnet_targets
                .push((coin_id, plant_id));
        }
        self.state
            .board
            .gold_magnet_suck_ticks
            .retain(|(id, _)| *id != plant_id);
        if selected.is_empty()
            && let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
        {
            plant.special_counter = self
                .rng
                .range_inclusive(GOLD_MAGNET_RECHARGE_MIN, GOLD_MAGNET_RECHARGE_MAX);
        }
    }

    fn update_plants(&mut self, events: &mut Vec<GameEvent>) {
        self.state
            .board
            .gold_magnet_suck_ticks
            .retain(|(plant_id, _)| {
                self.state
                    .board
                    .plants
                    .iter()
                    .any(|plant| plant.id == *plant_id && plant.plant_type.is_gold_magnet())
            });
        let plant_count = self.state.board.plants.len();
        for index in 0..plant_count {
            if index >= self.state.board.plants.len() {
                break;
            }
            if self.state.board.plants[index].bungee_lifted {
                continue;
            }
            let (asleep, recently_eaten) = {
                let plant = &mut self.state.board.plants[index];
                if plant.wake_up_counter > 0 {
                    plant.wake_up_counter -= 1;
                    if plant.wake_up_counter == 0 {
                        plant.asleep = false;
                    }
                }
                let recently_eaten = plant.recently_eaten_counter > 0;
                plant.recently_eaten_counter = plant.recently_eaten_counter.saturating_sub(1);
                (plant.asleep, recently_eaten)
            };
            if asleep {
                continue;
            }
            let (id, plant_type, row, column, imitater_type) = {
                let plant = &self.state.board.plants[index];
                (
                    plant.id,
                    plant.plant_type,
                    plant.row,
                    plant.column,
                    plant.imitater_type,
                )
            };
            let gold_magnet_capture = plant_type.is_gold_magnet() && self.tick_gold_magnet_suck(id);
            if self.state.challenge.kind == ChallengeKind::WallnutBowling
                && plant_type.is_bowling_plant()
            {
                self.update_bowling_plant(index, id, plant_type, events);
                continue;
            }
            if plant_type.slot() == 31 {
                self.update_magnet_shroom(index, id, row, column, events);
                continue;
            }
            if plant_type.is_imitater() {
                let Some(target) = imitater_type else {
                    continue;
                };
                let morph = {
                    let plant = &mut self.state.board.plants[index];
                    plant.special_counter = plant.special_counter.saturating_sub(1);
                    plant.special_counter == 0
                };
                if morph {
                    self.morph_imitater(index, target, events);
                }
                continue;
            }
            let threepeater_target_rows = if plant_type.firing_pattern() == FiringPattern::ThreeRow
            {
                [
                    row.checked_sub(1),
                    Some(row),
                    row.checked_add(1)
                        .filter(|target_row| *target_row < self.state.board.rows),
                ]
                .into_iter()
                .flatten()
                .filter(|target_row| {
                    *target_row < self.state.board.rows
                        && (self.state.mode != ModeKind::Adventure
                            || adventure_row_is_sodded(self.state.level, *target_row))
                })
                .collect::<Vec<_>>()
            } else {
                Vec::new()
            };
            let threepeater_attack_left = plant_attack_start(column);
            let threepeater_attack_right =
                threepeater_attack_left + i64::from(LOGICAL_WIDTH) * POSITION_SCALE;
            let firing_directions = if matches!(
                plant_type.firing_pattern(),
                FiringPattern::Split | FiringPattern::Backward
            ) {
                self.state
                    .board
                    .zombies
                    .iter()
                    .fold(0, |directions, zombie| {
                        directions | directional_target_directions(plant_type, row, column, zombie)
                    })
            } else {
                0
            };
            let scaredy_threat = plant_type.is_scaredy_shroom()
                && self.state.board.zombies.iter().any(|zombie| {
                    scaredy_shroom_sees_threat(self.state.scene, row, column, zombie)
                });
            let has_target = self.state.board.zombies.iter().any(|zombie| {
                if !plant_damage_can_hit_zombie(zombie) || zombie_rejects_ground_damage(zombie) {
                    return false;
                }
                // Only Cactus (slot 26) and homing Cattail spikes target fliers.
                let targets_fliers =
                    plant_type.slot() == 26 || plant_type.firing_pattern() == FiringPattern::Homing;
                if zombie.imp_flight_ticks > 0 && !targets_fliers {
                    return false;
                }
                if balloon_is_airborne(zombie) && (!balloon_is_flying(zombie) || !targets_fliers) {
                    return false;
                }
                if self.portal_targeting_enabled(plant_type) {
                    return self.can_target_zombie_with_portals(row, column, zombie);
                }
                let row_distance = zombie.row.abs_diff(row);
                let target_row = if zombie.zombie_type == ZombieType::Boss {
                    row
                } else {
                    zombie.row
                };
                let (zombie_left, zombie_right) = zombie_horizontal_rect(zombie);
                match plant_type.firing_pattern() {
                    FiringPattern::ThreeRow => {
                        threepeater_target_rows.contains(&target_row)
                            && zombie_right > threepeater_attack_left
                            && zombie_left < threepeater_attack_right
                    }
                    FiringPattern::Star => {
                        starfruit_can_target(self.state.scene, row, column, zombie)
                    }
                    FiringPattern::Split => false,
                    FiringPattern::Homing => cattail_can_target_zombie(self.state.scene, zombie),
                    FiringPattern::Backward => false,
                    _ if plant_type.is_scaredy_shroom() => {
                        !scaredy_threat
                            && row_distance == 0
                            && zombie.position_x > plant_attack_start(column)
                    }
                    _ if plant_type.is_gloom_shroom() => {
                        row_distance <= GLOOM_ROW_RADIUS
                            && zombie.position_x > grid_x(column) - 80 * POSITION_SCALE
                            && zombie.position_x
                                < grid_x(column) + (GLOOM_ATTACK_RANGE - 80) * POSITION_SCALE
                    }
                    _ if plant_type.is_fume_shroom() => {
                        row_distance == 0
                            && zombie.position_x > plant_attack_start(column)
                            && zombie.position_x
                                < plant_attack_start(column) + FUME_ATTACK_RANGE * POSITION_SCALE
                    }
                    _ if plant_type.is_puff_range_shooter() => {
                        row_distance == 0
                            && zombie.position_x > plant_attack_start(column)
                            && zombie.position_x
                                < plant_attack_start(column) + PUFF_ATTACK_RANGE * POSITION_SCALE
                    }
                    _ => {
                        zombie.zombie_type == ZombieType::Boss
                            || (row_distance == 0 && zombie.position_x > plant_attack_start(column))
                    }
                }
            });
            let has_target = has_target
                || firing_directions != 0
                || (plant_type.firing_pattern() == FiringPattern::Star && recently_eaten);
            let chomper_target = if plant_type.is_chomper() {
                self.find_chomper_target(row, column)
            } else {
                None
            };
            let squash_target = if plant_type.is_squash() {
                self.find_squash_target(row, column).and_then(|target| {
                    self.state
                        .board
                        .zombies
                        .iter()
                        .find(|zombie| zombie.id == target)
                        .map(|zombie| (target, squash_target_x(zombie, 0)))
                })
            } else {
                None
            };
            let squash_prelaunch_target_x = if plant_type.is_squash() {
                self.state.board.plants[index]
                    .special_target
                    .and_then(|target| {
                        self.state
                            .board
                            .zombies
                            .iter()
                            .find(|zombie| zombie.id == target)
                    })
                    .map(|zombie| squash_target_x(zombie, SQUASH_TARGET_LEAD_TICKS))
            } else {
                None
            };
            let tangle_target = if plant_type.is_tangle_kelp() {
                self.find_tangle_kelp_target(row, column)
            } else {
                None
            };
            let potato_trigger = plant_type.is_potato_mine()
                && self.state.board.zombies.iter().any(|zombie| {
                    plant_damage_can_hit_zombie(zombie)
                        && !zombie_rejects_ground_damage(zombie)
                        && !balloon_is_airborne(zombie)
                        && zombie.row == row
                        // Source FindTargetZombie PotatoMine branch: a Pogo
                        // carrying its object or a Pole Vaulter in vault cannot
                        // be selected; a Bungee is only a target in its locked
                        // target column.
                        && !(zombie.zombie_type == ZombieType::Pogo
                            && (zombie.pogo_counter > 0 || zombie.pogo_phase != 0))
                        && !(zombie.zombie_type == ZombieType::PoleVaulter
                            && zombie.special_phase == POLE_VAULT_IN_VAULT_PHASE)
                        && (zombie.zombie_type != ZombieType::Bungee
                            || zombie.bungee_target_column == Some(column))
                        && (zombie.position_x - grid_x(column)).abs() <= 60 * POSITION_SCALE
                });
            let spikeweed_target = plant_type.is_spikeweed()
                && self.state.board.zombies.iter().any(|zombie| {
                    plant_damage_can_hit_zombie(zombie)
                        && !zombie_rejects_ground_damage(zombie)
                        && zombie.row == row
                        && !balloon_is_airborne(zombie)
                        && spikeweed_hits(zombie.position_x, column)
                });
            let gold_magnet_target = if plant_type.is_gold_magnet() {
                self.find_gold_magnet_target(row, column, &[])
            } else {
                None
            };
            let gold_magnet_about_to_suck =
                plant_type.is_gold_magnet() && self.gold_magnet_about_to_suck(id);

            let mut fire = false;
            let mut produce_suns = 0;
            let mut produce_value = 25;
            let mut produce_coin = false;
            let mut special = false;
            let mut spikeweed_hit = false;
            let mut spikeweed_started = false;
            let mut chomper_bite_target = None;
            let mut squash_hit_x = None;
            let mut squash_landed = false;
            let mut squash_finished = false;
            let mut tangle_grab_target = None;
            let mut tangle_started = false;
            let mut tangle_water_entry = false;
            let mut gold_magnet_start = false;
            let mut potato_armed_now = false;
            let mut squash_hum_started = false;
            let mut firing_projectile = None;
            let mut fired_directions = 0;
            let mut cob_launch = None;
            let mut plant_particle = false;
            {
                let plant = &mut self.state.board.plants[index];
                if plant_type.is_cob_cannon() {
                    plant.special_counter = plant.special_counter.saturating_sub(1);
                    if plant.special_counter == 1
                        && let Some((target_row, target_column)) = plant.cob_target
                    {
                        // Source UpdateShooting creates the Cob projectile only
                        // at the launch boundary (Plant.cpp:3234-3340).
                        plant.cob_target = None;
                        cob_launch =
                            Some((plant.id, plant.row, plant.column, target_row, target_column));
                    } else if plant.special_counter == 0 {
                        plant.special_armed = true;
                    }
                } else if plant_type.is_gold_magnet() {
                    if gold_magnet_capture {
                        // GoldMagnetFindTargets runs at the attract animation event.
                    } else if plant.special_counter > 0 {
                        plant.special_counter -= 1;
                    } else if !self
                        .state
                        .board
                        .gold_magnet_targets
                        .iter()
                        .any(|(_, plant_id)| *plant_id == id)
                        && !self
                            .state
                            .board
                            .gold_magnet_suck_ticks
                            .iter()
                            .any(|(plant_id, _)| *plant_id == id)
                        && gold_magnet_target.is_some()
                        && !gold_magnet_about_to_suck
                        && self.rng.range(50) == 0
                    {
                        gold_magnet_start = true;
                    }
                } else if plant_type.is_instant_coffee() || plant_type.is_gravebuster() {
                    plant.special_counter = plant.special_counter.saturating_sub(1);
                    special = plant.special_counter == 0;
                } else if plant_type.is_blover() {
                    if !plant.special_armed {
                        plant.special_counter = plant.special_counter.saturating_sub(1);
                        if plant.special_counter == 0 {
                            plant.special_armed = true;
                            special = true;
                        }
                    }
                } else if plant_type.is_chomper() {
                    if plant.special_armed {
                        plant.special_counter = plant.special_counter.saturating_sub(1);
                        if plant.special_counter == 0 {
                            chomper_bite_target = plant.special_target.take();
                            plant.special_armed = false;
                            plant.special_counter = CHOMPER_CHEW_TICKS;
                        }
                    } else if plant.special_counter > 0 {
                        plant.special_counter -= 1;
                    } else if let Some(target) = chomper_target {
                        plant.special_armed = true;
                        plant.special_target = Some(target);
                        plant.special_counter = CHOMPER_BITE_WINDUP_TICKS;
                    }
                } else if plant_type.is_cherry_bomb()
                    || plant_type.is_jalapeno()
                    || plant_type.is_ice_shroom()
                    || plant_type.is_doom_shroom()
                {
                    plant.special_counter = plant.special_counter.saturating_sub(1);
                    special = plant.special_counter == 0;
                } else if plant_type.is_potato_mine() {
                    if plant.special_armed {
                        special = potato_trigger;
                    } else {
                        plant.special_counter = plant.special_counter.saturating_sub(1);
                        if plant.special_counter == 0 {
                            plant.special_armed = true;
                            // PARTICLE_POTATO_MINE_RISE anchor.
                            potato_armed_now = true;
                        }
                    }
                } else if plant_type.is_squash() {
                    if plant.special_armed {
                        plant.special_counter = plant.special_counter.saturating_sub(1);
                        if plant.special_counter == 0 {
                            if plant.special_target.take().is_some()
                                || plant.squash_target_x.is_some()
                            {
                                squash_hit_x =
                                    plant.squash_target_x.take().or(squash_prelaunch_target_x);
                                plant.special_counter = SQUASH_LANDING_HIT_TICKS;
                            } else if matches!(self.state.scene, SceneKind::Pool | SceneKind::Fog)
                                && matches!(row, 2 | 3)
                            {
                                plant.health = 0;
                                squash_finished = true;
                            } else {
                                plant.special_armed = false;
                                plant.special_counter = SQUASH_DONE_FALLING_TICKS;
                                squash_landed = true;
                            }
                        }
                    } else if plant.special_target.is_some() {
                        plant.special_counter = plant.special_counter.saturating_sub(1);
                        if plant.special_counter == 0 {
                            if let Some(target_x) = squash_prelaunch_target_x {
                                plant.squash_target_x = Some(target_x);
                            }
                            plant.special_armed = true;
                            plant.special_counter = SQUASH_HIT_DELAY_TICKS;
                        }
                    } else if plant.special_counter > 0 {
                        // A target-less, unarmed Squash is STATE_SQUASH_DONE_FALLING.
                        plant.special_counter -= 1;
                        if plant.special_counter == 0 {
                            plant.health = 0;
                            squash_finished = true;
                        }
                    } else if let Some((target, target_x)) = squash_target {
                        plant.special_target = Some(target);
                        plant.squash_target_x = Some(target_x);
                        plant.special_counter = SQUASH_LOOK_TICKS;
                        squash_hum_started = true;
                    }
                } else if plant_type.is_tangle_kelp() {
                    if plant.special_armed {
                        tangle_water_entry = plant.special_counter == 20;
                        plant.special_counter = plant.special_counter.saturating_sub(1);
                        if plant.special_counter == 0 {
                            tangle_grab_target = plant.special_target.take();
                            plant.health = 0;
                        }
                    } else if let Some(target) = tangle_target {
                        plant.special_armed = true;
                        plant.special_counter = TANGLE_KELP_GRAB_TICKS;
                        plant.special_target = Some(target);
                        tangle_started = true;
                    }
                } else if plant_type.slot() == 37 && plant.special_armed {
                    plant.special_counter = plant.special_counter.saturating_sub(1);
                    if plant.special_counter == 0 {
                        plant.special_armed = false;
                    }
                } else if plant_type.is_spikeweed() {
                    if plant.special_armed {
                        plant.special_counter = plant.special_counter.saturating_sub(1);
                        let damage_countdown = if plant_type.slot() == 46 {
                            matches!(plant.special_counter, 69 | 33)
                        } else {
                            plant.special_counter == SPIKEWEED_DAMAGE_COUNTDOWN
                        };
                        if damage_countdown {
                            spikeweed_hit = true;
                        } else if plant.special_counter == 0 {
                            plant.special_armed = false;
                        }
                    } else if spikeweed_target {
                        plant.special_armed = true;
                        plant.special_counter = SPIKEWEED_ATTACK_TICKS;
                        spikeweed_started = true;
                    }
                }
                if plant_type.is_sunshroom() {
                    plant.production_age = plant.production_age.saturating_add(1);
                    if plant.production_age >= SUNSHROOM_GROWTH_TICKS {
                        plant.production_stage = 1;
                    }
                }
                if plant.shooting_counter > 0 {
                    plant.shooting_counter -= 1;
                    plant_particle = matches!(
                        (plant_type.slot(), plant.shooting_counter),
                        (10, 15) | (42, 136 | 108 | 80 | 52)
                    );
                    fire = plant_type.fires_at_shooting_counter(plant.shooting_counter)
                        && (plant_type.firing_pattern() != FiringPattern::Homing || has_target);
                    if fire {
                        fired_directions = std::mem::take(&mut plant.firing_directions);
                        firing_projectile = plant.kernel_pult_projectile.take();
                    }
                }

                let mut attack_directions = None;
                if plant.launch_rate != 0 {
                    if plant.launch_counter <= 1 {
                        if plant_type.is_producer() {
                            plant.launch_counter = self
                                .rng
                                .range_inclusive(plant.launch_rate - 150, plant.launch_rate);
                            if plant_type.is_marigold() {
                                produce_coin = true;
                            } else {
                                produce_suns = if plant_type.is_twin_sunflower() { 2 } else { 1 };
                                if plant_type.is_sunshroom() && plant.production_stage == 0 {
                                    produce_value = SMALL_SUN_VALUE;
                                }
                            }
                        } else if plant_type.is_shooter() {
                            plant.launch_counter = plant.launch_rate - self.rng.range(15);
                            attack_directions =
                                Some(if plant_type.firing_pattern() == FiringPattern::Split {
                                    firing_directions & FIRING_BACKWARD
                                } else {
                                    firing_directions
                                });
                        }
                    } else {
                        plant.launch_counter -= 1;
                        // Plant::UpdateShooter checks these boundaries after decrementing.
                        if (plant_type.firing_pattern() == FiringPattern::Homing
                            && plant.launch_counter == 50)
                            || (matches!(plant_type.slot(), 7 | 28 | 52)
                                && plant.launch_counter == 25)
                        {
                            attack_directions = Some(firing_directions);
                        }
                    }

                    if let Some(directions) = attack_directions {
                        let attack_has_target = match plant_type.firing_pattern() {
                            FiringPattern::Split | FiringPattern::Backward => directions != 0,
                            _ => has_target,
                        };
                        if attack_has_target {
                            plant.firing_directions = directions;
                            if plant_type.is_kernel_pult() {
                                plant.kernel_pult_projectile = Some(if self.rng.range(4) == 0 {
                                    ProjectileType::Butter
                                } else {
                                    ProjectileType::Kernel
                                });
                            }
                            plant.shooting_counter = plant_type.shooting_counter_start();
                        }
                    }
                }
            }

            if squash_hum_started {
                events.push(GameEvent::SquashHumStarted {
                    entity: id,
                    variant: self.rng.range(3) as u8,
                });
            }
            if let Some((source, source_row, source_column, target_row, target_column)) = cob_launch
            {
                self.fire_cob_projectile(
                    source,
                    source_row,
                    source_column,
                    target_row,
                    target_column,
                    events,
                );
            }
            if plant_particle {
                events.push(GameEvent::PlantParticleTriggered {
                    entity: id,
                    plant_type,
                });
            }
            if fire {
                self.fire_projectiles(
                    id,
                    plant_type,
                    firing_projectile.unwrap_or_else(|| plant_type.projectile_type()),
                    (row, column),
                    fired_directions,
                    events,
                );
            }
            if gold_magnet_start {
                self.state
                    .board
                    .gold_magnet_suck_ticks
                    .push((id, GOLD_MAGNET_SUCK_TICKS));
            }
            if gold_magnet_capture {
                self.capture_gold_magnet_targets(id, row, column);
            }
            if let Some(zombie_id) = chomper_bite_target
                && let Some(zombie_index) = self.state.board.zombies.iter().position(|zombie| {
                    zombie.id == zombie_id && plant_damage_can_hit_zombie(zombie)
                })
            {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
                events.push(GameEvent::PlantSpecialTriggered {
                    entity: id,
                    plant_type,
                });
            }
            if let Some(target_x) = squash_hit_x {
                let mut zombie_index = 0;
                while zombie_index < self.state.board.zombies.len() {
                    if !squash_hits_zombie(&self.state.board.zombies[zombie_index], row, target_x) {
                        zombie_index += 1;
                        continue;
                    }
                    let zombie_id = self.state.board.zombies[zombie_index].id;
                    self.damage_zombie(zombie_index, PLANT_SPECIAL_DAMAGE, events);
                    let health_remaining = self.state.board.zombies[zombie_index].health;
                    events.push(GameEvent::PlantSpecialHit {
                        plant: id,
                        zombie: zombie_id,
                        damage: PLANT_SPECIAL_DAMAGE,
                        health_remaining,
                    });
                    if health_remaining <= 0 {
                        self.emit_zombie_died_with_loot(zombie_id, events);
                        self.state.board.zombies.remove(zombie_index);
                    } else {
                        zombie_index += 1;
                    }
                }
                continue;
            }
            if squash_landed {
                events.push(GameEvent::PlantSpecialTriggered {
                    entity: id,
                    plant_type,
                });
            }
            if squash_finished {
                events.push(GameEvent::PlantDied { entity: id });
                continue;
            }
            if let Some(zombie_id) = tangle_grab_target {
                events.push(GameEvent::PlantSpecialTriggered {
                    entity: id,
                    plant_type,
                });
                if let Some(zombie_index) = self.state.board.zombies.iter().position(|zombie| {
                    zombie.id == zombie_id && plant_damage_can_hit_zombie(zombie)
                }) {
                    self.emit_zombie_died_with_loot(zombie_id, events);
                    self.state.board.zombies.remove(zombie_index);
                }
                events.push(GameEvent::PlantDied { entity: id });
                continue;
            }
            if tangle_started {
                events.push(GameEvent::TangleKelpGrabStarted { entity: id });
            }
            if tangle_water_entry {
                events.push(GameEvent::TangleKelpWaterEntry { entity: id });
            }
            if spikeweed_started {
                events.push(GameEvent::PlantSpecialTriggered {
                    entity: id,
                    plant_type,
                });
            }
            if potato_armed_now {
                events.push(GameEvent::PotatoMineArmed { entity: id });
            }
            if spikeweed_hit {
                let vehicle_hit = self.apply_spikeweed_damage(id, row, column, events);
                if vehicle_hit && self.pop_spiky_plant(id, events) {
                    continue;
                }
            }
            if special {
                self.trigger_plant_special(id, plant_type, row, column, events);
                continue;
            }
            for _ in 0..produce_suns {
                self.spawn_sun_value(
                    SunSource::Plant(id),
                    produce_value,
                    grid_x(column),
                    grid_y(row),
                    events,
                );
                let vertical_motion = self.rng.next();
                let horizontal_motion = self.rng.next();
                let ground_offset = self.rng.range(20);
                if let Some(sun) = self.state.board.suns.last_mut() {
                    // COIN_MOTION_COIN: plant suns pop up in the -1.7..-3.4
                    // launch band with a small lateral drift and fall back to
                    // a ground stop near the plant under 0.09 gravity.
                    sun.velocity_y = -1_700_000 - (i64::from(vertical_motion) % 1_700_001);
                    sun.velocity_x = (i64::from(horizontal_motion) % 2_000_001) - 1_000_000;
                    sun.target_y = Some(sun.position_y + i64::from(ground_offset) * POSITION_SCALE);
                }
            }
            if produce_coin {
                let coin_type = if self.rng.range(100) < 10 {
                    CoinType::Gold
                } else {
                    CoinType::Silver
                };
                self.spawn_coin(coin_type, grid_x(column), grid_y(row), events);
            }

            let plant = &mut self.state.board.plants[index];
            if plant.blink_counter <= 1 {
                plant.blink_counter = 400 + self.rng.range(400);
            } else {
                plant.blink_counter -= 1;
            }
        }
        self.state.board.plants.retain(|plant| plant.health > 0);
    }

    fn update_bowling_plant(
        &mut self,
        plant_index: usize,
        plant_id: EntityId,
        plant_type: PlantType,
        events: &mut Vec<GameEvent>,
    ) {
        let (position_x, position_y, row, direction) = {
            let plant = &mut self.state.board.plants[plant_index];
            plant.position_x = plant
                .position_x
                .saturating_add(if plant_type.is_giant_wallnut() {
                    BOWLING_GIANT_ROLL_SPEED
                } else {
                    BOWLING_ROLL_SPEED
                });
            if plant.bowling_direction < 0 {
                plant.position_y = plant.position_y.saturating_sub(2 * POSITION_SCALE);
            } else if plant.bowling_direction > 0 {
                plant.position_y = plant.position_y.saturating_add(2 * POSITION_SCALE);
            }
            (
                plant.position_x,
                plant.position_y,
                plant.row,
                plant.bowling_direction,
            )
        };

        if position_x > BOWLING_EDGE_X {
            self.state.board.plants[plant_index].health = 0;
            events.push(GameEvent::PlantDied { entity: plant_id });
            return;
        }
        if (position_y - grid_y(row)).abs() > BOWLING_GRID_EPSILON {
            return;
        }

        let attack_left = position_x;
        let attack_right = position_x + 60 * POSITION_SCALE;
        let zombie_index = self
            .state
            .board
            .zombies
            .iter()
            .enumerate()
            .filter(|(_, zombie)| {
                (zombie.zombie_type == ZombieType::Boss || zombie.row == row)
                    && plant_damage_can_hit_zombie(zombie)
                    && !zombie_rejects_ground_damage(zombie)
                    && !balloon_is_airborne(zombie)
                    && {
                        let (zombie_left, zombie_right) = zombie_horizontal_rect(zombie);
                        zombie_right > attack_left && zombie_left < attack_right
                    }
            })
            .min_by_key(|(_, zombie)| zombie_horizontal_rect(zombie).0)
            .map(|(index, _)| index);

        let mut next_direction = direction;
        if direction < 0 && row == 0 {
            next_direction = 1;
        } else if direction > 0 && row + 1 >= self.state.board.rows {
            next_direction = -1;
        }

        if let Some(zombie_index) = zombie_index {
            let zombie_id = self.state.board.zombies[zombie_index].id;
            if plant_type.is_explode_o_nut() {
                events.push(GameEvent::PlantSpecialTriggered {
                    entity: plant_id,
                    plant_type,
                });
                let center_x = position_x + 40 * POSITION_SCALE;
                let center_y = position_y + 40 * POSITION_SCALE;
                let target_ids = self
                    .state
                    .board
                    .zombies
                    .iter()
                    .filter(|zombie| {
                        plant_damage_can_hit_zombie(zombie)
                            && !zombie_rejects_ground_damage(zombie)
                            && zombie.row.abs_diff(row) <= 1
                            && (zombie.position_x + 40 * POSITION_SCALE - center_x).abs()
                                <= 90 * POSITION_SCALE
                            && (grid_y(zombie.row) + 40 * POSITION_SCALE - center_y).abs()
                                <= 90 * POSITION_SCALE
                    })
                    .map(|zombie| zombie.id)
                    .collect::<Vec<_>>();
                for target_id in target_ids {
                    let Some(target_index) = self
                        .state
                        .board
                        .zombies
                        .iter()
                        .position(|zombie| zombie.id == target_id)
                    else {
                        continue;
                    };
                    self.damage_zombie(target_index, PLANT_SPECIAL_DAMAGE, events);
                    if self.state.board.zombies[target_index].health <= 0 {
                        self.emit_zombie_died_with_loot(target_id, events);
                        self.state.board.zombies.remove(target_index);
                    }
                }
                self.state.board.plants[plant_index].health = 0;
                events.push(GameEvent::PlantDied { entity: plant_id });
                return;
            }

            events.push(GameEvent::BowlingImpact {
                plant: plant_id,
                zombie: zombie_id,
            });
            self.damage_zombie(zombie_index, PLANT_SPECIAL_DAMAGE, events);
            let health_remaining = self.state.board.zombies[zombie_index].health;
            if health_remaining <= 0 {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
            }

            if plant_type.slot() == 3 && (!self.state.adventure_first_time || self.state.level > 10)
            {
                let plant = &mut self.state.board.plants[plant_index];
                plant.launch_counter = plant.launch_counter.saturating_add(1);
                let reward_count = match plant.launch_counter {
                    2 => 1,
                    3 => 2,
                    4 => 3,
                    _ if plant.launch_counter >= 5 => 1,
                    _ => 0,
                };
                let reward_type = if plant.launch_counter >= 5 {
                    CoinType::Gold
                } else {
                    CoinType::Silver
                };
                if reward_count > 0 {
                    events.push(GameEvent::LootDropSound {
                        sound: LootDropSound::SpawnSun,
                    });
                }
                for offset in 0..reward_count {
                    self.spawn_coin(
                        reward_type,
                        position_x
                            + (i64::from(offset) * 10 - i64::from(reward_count - 1) * 5)
                                * POSITION_SCALE,
                        position_y + 40 * POSITION_SCALE,
                        events,
                    );
                }
            }

            if !plant_type.is_giant_wallnut() {
                next_direction = if row + 1 >= self.state.board.rows || direction > 0 {
                    -1
                } else if row == 0 || direction < 0 {
                    1
                } else if self.rng.range(2) == 0 {
                    -1
                } else {
                    1
                };
            }
        }

        if next_direction != 0 {
            let next_row = if next_direction < 0 {
                row.saturating_sub(1)
            } else {
                row.saturating_add(1)
                    .min(self.state.board.rows.saturating_sub(1))
            };
            let plant = &mut self.state.board.plants[plant_index];
            plant.bowling_direction = next_direction;
            plant.row = next_row;
        }
    }

    fn trigger_plant_special(
        &mut self,
        plant_id: EntityId,
        plant_type: PlantType,
        row: u8,
        column: u8,
        events: &mut Vec<GameEvent>,
    ) {
        events.push(GameEvent::PlantSpecialTriggered {
            entity: plant_id,
            plant_type,
        });

        if plant_type.is_instant_coffee() {
            let target_id = self
                .state
                .board
                .plants
                .iter()
                .find(|plant| {
                    plant.id != plant_id
                        && plant.row == row
                        && plant.column == column
                        && !matches!(plant.plant_type.slot(), 16 | 30 | 33 | 35)
                        && plant.plant_type.is_nocturnal()
                        && plant.asleep
                        && plant.wake_up_counter == 0
                })
                .map(|plant| plant.id);
            if let Some(target_id) = target_id
                && let Some(target) = self
                    .state
                    .board
                    .plants
                    .iter_mut()
                    .find(|plant| plant.id == target_id)
            {
                target.wake_up_counter = COFFEE_WAKE_TICKS;
            }
            if let Some(coffee) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
            {
                coffee.health = 0;
            }
            events.push(GameEvent::PlantDied { entity: plant_id });
            return;
        }

        if plant_type.is_blover() {
            self.blow_away_fliers();
            events.push(GameEvent::BloverTriggered {
                entity: plant_id,
                row,
            });
            return;
        }

        if plant_type.is_gravebuster() {
            if let Some(grave_index) = self
                .state
                .board
                .graves
                .iter()
                .position(|grave| grave.row == row && grave.column == column)
            {
                self.state.board.graves.remove(grave_index);
                events.push(GameEvent::GraveCleared {
                    entity: plant_id,
                    row,
                    column,
                });
            }
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
            {
                plant.health = 0;
            }
            events.push(GameEvent::PlantDied { entity: plant_id });
            // Plant::UpdateGraveBuster (Plant.cpp:1118): DropLootPiece factor
            // 12 at mX + 40, mY once the grave is cleared.
            self.drop_loot_piece(
                grid_x(column) + 40 * POSITION_SCALE,
                grid_y(row),
                12,
                events,
            );
            return;
        }

        if plant_type.is_doom_shroom() {
            let center_x = grid_x(column);
            let radius = DOOM_SHROOM_RADIUS * POSITION_SCALE;
            let target_ids = self
                .state
                .board
                .zombies
                .iter()
                .filter(|zombie| {
                    plant_damage_can_hit_zombie(zombie)
                        && zombie.row.abs_diff(row) <= DOOM_SHROOM_ROW_RADIUS
                        && (zombie.position_x - center_x).abs() <= radius
                })
                .map(|zombie| zombie.id)
                .collect::<Vec<_>>();

            for zombie_id in target_ids {
                let Some(zombie_index) = self
                    .state
                    .board
                    .zombies
                    .iter()
                    .position(|zombie| zombie.id == zombie_id)
                else {
                    continue;
                };
                self.damage_zombie(zombie_index, PLANT_SPECIAL_DAMAGE, events);
                let health_remaining = self.state.board.zombies[zombie_index].health;
                events.push(GameEvent::PlantSpecialHit {
                    plant: plant_id,
                    zombie: zombie_id,
                    damage: PLANT_SPECIAL_DAMAGE,
                    health_remaining,
                });
                if health_remaining <= 0 {
                    self.emit_zombie_died_with_loot(zombie_id, events);
                    self.state.board.zombies.remove(zombie_index);
                }
            }

            self.state.board.craters.push(CraterState {
                row,
                column,
                remaining: DOOM_CRATER_TICKS,
                persistent: false,
            });
            events.push(GameEvent::CraterCreated {
                row,
                column,
                duration: DOOM_CRATER_TICKS,
            });
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
            {
                plant.health = 0;
            }
            events.push(GameEvent::PlantDied { entity: plant_id });
            return;
        }

        if plant_type.is_ice_shroom() {
            self.state.board.ice_counter = BOARD_ICE_TICKS;
            self.destroy_boss_ball(true, None, events);
            let target_ids = self
                .state
                .board
                .zombies
                .iter()
                .map(|zombie| zombie.id)
                .collect::<Vec<_>>();

            for zombie_id in target_ids {
                let Some(zombie_index) = self
                    .state
                    .board
                    .zombies
                    .iter()
                    .position(|zombie| zombie.id == zombie_id)
                else {
                    continue;
                };

                // Source HitIceTrap: fully excluded states get no chill, no
                // freeze, and no Ice-shroom damage.
                if !zombie_can_be_chilled(&self.state.board.zombies[zombie_index]) {
                    continue;
                }

                // Read the pre-chill debuff state and freeze eligibility before
                // applying the chill.
                let (cold, can_freeze) = {
                    let zombie = &self.state.board.zombies[zombie_index];
                    (
                        zombie.frozen_counter != 0 || zombie.chilled_counter != 0,
                        zombie_can_be_frozen(zombie),
                    )
                };
                let duration = if can_freeze {
                    if self.state.board.zombies[zombie_index].in_pool {
                        ICE_SHROOM_POOL_FREEZE_TICKS
                    } else if cold {
                        self.rng
                            .range_inclusive(ICE_SHROOM_COLD_FREEZE_MIN, ICE_SHROOM_COLD_FREEZE_MAX)
                    } else {
                        self.rng.range_inclusive(
                            ICE_SHROOM_FRESH_FREEZE_MIN,
                            ICE_SHROOM_FRESH_FREEZE_MAX,
                        )
                    }
                } else {
                    0
                };

                self.state.board.zombies[zombie_index].chilled_counter = self.state.board.zombies
                    [zombie_index]
                    .chilled_counter
                    .max(ICE_SHROOM_CHILL_TICKS);
                events.push(GameEvent::ZombieChilled {
                    entity: zombie_id,
                    duration: ICE_SHROOM_CHILL_TICKS,
                });

                if can_freeze {
                    let frozen_counter = self.state.board.zombies[zombie_index].frozen_counter;
                    self.state.board.zombies[zombie_index].frozen_counter =
                        frozen_counter.max(duration);
                    events.push(GameEvent::ZombieFrozen {
                        entity: zombie_id,
                        duration,
                    });

                    self.damage_zombie(zombie_index, ICE_SHROOM_DAMAGE, events);
                    let health_remaining = self.state.board.zombies[zombie_index].health;
                    events.push(GameEvent::PlantSpecialHit {
                        plant: plant_id,
                        zombie: zombie_id,
                        damage: ICE_SHROOM_DAMAGE,
                        health_remaining,
                    });
                    if health_remaining <= 0 {
                        self.emit_zombie_died_with_loot(zombie_id, events);
                        self.state.board.zombies.remove(zombie_index);
                    }
                }
            }

            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
            {
                plant.health = 0;
            }
            events.push(GameEvent::PlantDied { entity: plant_id });
            return;
        }

        let (radius, row_radius, row_wide) = if plant_type.is_potato_mine() {
            (60 * POSITION_SCALE, 0, false)
        } else if plant_type.is_jalapeno() {
            (0, 0, true)
        } else {
            (115 * POSITION_SCALE, 1, false)
        };
        if plant_type.is_jalapeno() {
            let row_index = usize::from(row);
            if row_index < self.state.board.ice_timer.len()
                && self.state.board.ice_timer[row_index] > 0
            {
                self.state.board.ice_timer[row_index] = JALAPENO_ICE_MELT_TICKS;
            }
            self.destroy_boss_ball(false, Some(row), events);
        }
        let center_x = grid_x(column);
        let target_ids = self
            .state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                plant_damage_can_hit_zombie(zombie)
                    && (!plant_type.is_potato_mine() || !zombie_rejects_ground_damage(zombie))
                    && zombie.row.abs_diff(row) <= row_radius
                    && (row_wide || (zombie.position_x - center_x).abs() <= radius)
            })
            .map(|zombie| zombie.id)
            .collect::<Vec<_>>();
        for zombie_id in target_ids {
            let Some(zombie_index) = self
                .state
                .board
                .zombies
                .iter()
                .position(|zombie| zombie.id == zombie_id)
            else {
                continue;
            };
            self.damage_zombie(zombie_index, PLANT_SPECIAL_DAMAGE, events);
            let health_remaining = self.state.board.zombies[zombie_index].health;
            events.push(GameEvent::PlantSpecialHit {
                plant: plant_id,
                zombie: zombie_id,
                damage: PLANT_SPECIAL_DAMAGE,
                health_remaining,
            });
            if health_remaining <= 0 {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
            }
        }
        if let Some(plant) = self
            .state
            .board
            .plants
            .iter_mut()
            .find(|plant| plant.id == plant_id)
        {
            plant.health = 0;
        }
        events.push(GameEvent::PlantDied { entity: plant_id });
    }

    fn advance_garlic_state(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) -> bool {
        let counter = self.state.board.zombies[zombie_index].garlic_counter;
        if counter == 0 {
            return false;
        }

        let next_counter = counter.saturating_add(1);
        let zombie_id = self.state.board.zombies[zombie_index].id;
        let (zombie_type, has_head) = {
            let zombie = &self.state.board.zombies[zombie_index];
            (zombie.zombie_type, zombie.has_head)
        };
        let zombie_count_on_screen = self
            .state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                zombie.health > 0 && !zombie.departed && zombie.has_head && !zombie.hypnotized
            })
            .count();
        let has_yucky_face_image = matches!(
            zombie_type,
            ZombieType::Normal
                | ZombieType::Flag
                | ZombieType::Conehead
                | ZombieType::Buckethead
                | ZombieType::ScreenDoor
                | ZombieType::DuckyTube
                | ZombieType::Dancer
                | ZombieType::BackupDancer
                | ZombieType::Newspaper
                | ZombieType::PoleVaulter
        );
        let yuck_boundary = if has_yucky_face_image {
            next_counter == GARLIC_EAT_TICKS
        } else {
            next_counter == GARLIC_YUCK_EARLY_TICKS
        };
        let yuck_gate = yuck_boundary
            && (zombie_count_on_screen <= 5
                || (zombie_count_on_screen <= 10 && self.rng.range(2) == 0));
        if has_head && yuck_gate {
            events.push(GameEvent::ZombieYuckSound {
                entity: zombie_id,
                variant: self.rng.range(3) as u8,
            });
        }
        if next_counter == GARLIC_EAT_TICKS {
            let garlic_id = self.state.board.zombies[zombie_index].garlic_target;
            if let Some(plant_index) = self
                .state
                .board
                .plants
                .iter()
                .position(|plant| Some(plant.id) == garlic_id)
            {
                let plant_id = self.state.board.plants.remove(plant_index).id;
                events.push(GameEvent::PlantDied { entity: plant_id });
            }
        }
        let yuck_early_boundary = !has_yucky_face_image && yuck_boundary;
        if (next_counter == GARLIC_ROW_CHANGE_TICKS || yuck_early_boundary)
            && self.state.board.rows > 1
        {
            let from = self.state.board.zombies[zombie_index].row;
            let choice = self.rng.range(u32::from(self.state.board.rows - 1)) as u8;
            let to = if choice >= from { choice + 1 } else { choice };
            self.state.board.zombies[zombie_index].row = to;
            events.push(GameEvent::ZombieRowChanged {
                entity: zombie_id,
                from,
                to,
            });
        }
        if next_counter >= GARLIC_RESET_TICKS {
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.garlic_counter = 0;
            zombie.garlic_target = None;
            zombie.eating = false;
            return false;
        }

        let zombie = &mut self.state.board.zombies[zombie_index];
        zombie.garlic_counter = if yuck_early_boundary {
            GARLIC_ROW_CHANGE_TICKS
        } else {
            next_counter
        };
        zombie.eating = true;
        true
    }

    fn trigger_mower(&mut self, row: u8, events: &mut Vec<GameEvent>) -> bool {
        let pool = scene_row_is_water(self.state.scene, row);
        let Some(mower) = self
            .state
            .board
            .mowers
            .iter_mut()
            .find(|mower| mower.row == row && !mower.active && !mower.spent)
        else {
            return false;
        };
        mower.active = true;
        events.push(GameEvent::MowerTriggered { row, pool });
        let mut dead_ids = Vec::new();
        for zombie in &mut self.state.board.zombies {
            if zombie.row == row && zombie.health > 0 {
                zombie.health = 0;
                zombie.eating = false;
                events.push(GameEvent::MowerZombieHit {
                    entity: zombie.id,
                    pool,
                    variant: if pool { 0 } else { self.rng.range(3) as u8 },
                });
                dead_ids.push(zombie.id);
            }
        }
        for entity in dead_ids {
            self.emit_zombie_died_with_loot(entity, events);
        }
        true
    }

    fn update_mowers(&mut self, events: &mut Vec<GameEvent>) {
        let mut dead_ids = Vec::new();
        for mower in &mut self.state.board.mowers {
            if !mower.active {
                continue;
            }
            let previous_x = mower.position_x;
            mower.position_x = mower.position_x.saturating_add(MOWER_SPEED);
            if mower.position_x > i64::from(LOGICAL_WIDTH) * POSITION_SCALE {
                mower.active = false;
                mower.spent = true;
                continue;
            }
            let row = mower.row;
            let pool = scene_row_is_water(self.state.scene, row);
            let mower_x = mower.position_x;
            if pool && previous_x <= 26 * POSITION_SCALE && mower_x > 26 * POSITION_SCALE {
                events.push(GameEvent::MowerEnteredPool {
                    row,
                    variant: self.rng.range(2) as u8,
                });
            }
            if pool && previous_x <= 660 * POSITION_SCALE && mower_x > 660 * POSITION_SCALE {
                events.push(GameEvent::MowerExitedPool { row });
            }
            for zombie in &mut self.state.board.zombies {
                if zombie.row == row
                    && zombie.health > 0
                    && zombie.position_x + 70 * POSITION_SCALE > previous_x
                    && zombie.position_x < mower_x + 80 * POSITION_SCALE
                {
                    zombie.health = 0;
                    zombie.eating = false;
                    events.push(GameEvent::MowerZombieHit {
                        entity: zombie.id,
                        pool,
                        variant: if pool { 0 } else { self.rng.range(3) as u8 },
                    });
                    dead_ids.push(zombie.id);
                }
            }
        }
        for entity in dead_ids {
            self.emit_zombie_died_with_loot(entity, events);
        }
        self.state.board.zombies.retain(|zombie| zombie.health > 0);
    }

    fn apply_jackbox_explosion(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let zx;
        let zrow;
        let zombie_id;
        {
            let zombie = &self.state.board.zombies[zombie_index];
            zx = zombie.position_x;
            zrow = zombie.row;
            zombie_id = zombie.id;
        }

        let explosion_radius = 115 * POSITION_SCALE;

        // KillAllPlantsInRadius uses the smaller 90-unit plant radius, ±1 row.
        let plant_radius = JACKBOX_PLANT_RADIUS * POSITION_SCALE;
        let mut plant_targets = Vec::new();
        for (i, plant) in self.state.board.plants.iter().enumerate() {
            if plant.health <= 0 {
                continue;
            }
            let row_diff = (i16::from(plant.row) - i16::from(zrow)).unsigned_abs();
            if row_diff > 1 {
                continue;
            }
            let px = grid_x(plant.column);
            let dx = (px - zx).unsigned_abs();
            if dx > plant_radius as u64 {
                continue;
            }
            plant_targets.push(i);
        }
        for i in plant_targets {
            self.state.board.plants[i].health = 0;
            events.push(GameEvent::PlantDied {
                entity: self.state.board.plants[i].id,
            });
        }

        // Also damage nearby zombies (friendly fire).
        let mut zombie_targets = Vec::new();
        for (other_idx, other) in self.state.board.zombies.iter().enumerate() {
            if other_idx == zombie_index {
                continue;
            }
            if other.health <= 0 {
                continue;
            }
            let row_diff = (i16::from(other.row) - i16::from(zrow)).unsigned_abs();
            if row_diff > 1 {
                continue;
            }
            let dx = (other.position_x - zx).unsigned_abs();
            if dx > explosion_radius as u64 {
                continue;
            }
            zombie_targets.push(other.id);
        }
        for target in zombie_targets {
            if let Some(target_index) = self
                .state
                .board
                .zombies
                .iter()
                .position(|zombie| zombie.id == target)
            {
                self.damage_zombie(target_index, PLANT_SPECIAL_DAMAGE, events);
                if self.state.board.zombies[target_index].health <= 0 {
                    self.emit_zombie_died_with_loot(target, events);
                }
            }
        }

        let zombie_column = ((zx - 40 * POSITION_SCALE) / (80 * POSITION_SCALE))
            .clamp(0, i64::from(self.state.board.columns.saturating_sub(1)))
            as u8;
        events.push(GameEvent::JackboxExploded {
            entity: zombie_id,
            row: zrow,
            column: zombie_column,
        });
        self.emit_zombie_died(zombie_id, events);
    }

    fn eat_brain(&mut self, zombie_index: usize, row: u8, events: &mut Vec<GameEvent>) -> bool {
        let chew = self
            .state
            .board
            .zombies
            .get(zombie_index)
            .map(|zombie| (zombie.id, zombie.variant));
        let Some(brain_index) = self
            .state
            .board
            .brains
            .iter()
            .position(|brain| brain.row == row && !brain.squished)
        else {
            return false;
        };
        if let Some((entity, variant)) = chew {
            events.push(GameEvent::ZombieChew {
                entity,
                target: None,
                soft: false,
                variant,
            });
        }
        let remaining = self.state.board.brains[brain_index]
            .remaining
            .saturating_sub(1);
        self.state.board.brains[brain_index].remaining = remaining;
        let finished = remaining == 0;
        if finished {
            self.state.board.brains[brain_index].squished = true;
        }
        let brains_remaining = self
            .state
            .board
            .brains
            .iter()
            .filter(|brain| !brain.squished)
            .count()
            .try_into()
            .unwrap_or(u8::MAX);
        events.push(GameEvent::BrainEaten {
            zombie: self.state.board.zombies[zombie_index].id,
            row,
            brains_remaining,
        });
        if finished {
            events.push(GameEvent::BrainFinished {
                zombie: self.state.board.zombies[zombie_index].id,
                row,
                brains_remaining,
            });
        }
        if finished {
            // Challenge::IZombieScoreBrain (Challenge.cpp:4907-4927): each
            // finished brain scores once and drops ordinary loot (factor 12)
            // except the award-stage terminal brain; PuzzleIsAwardStage is
            // stage % 3 for endless I, Zombie and always true for finite
            // levels (Challenge.cpp:4179-4186).
            self.state.challenge.score = self.state.challenge.score.saturating_add(1);
            let award_stage = if self.state.level == 9 {
                self.state.challenge.stage.is_multiple_of(3)
            } else {
                true
            };
            if self.state.challenge.score < 5 || !award_stage {
                // Brains sit at grid(0) - 40 / gridY + 40
                // (Challenge.cpp:4542-4543), so mPosX + 40 / mPosY - 50 is
                // grid_x(0), grid_y(row) - 10.
                self.drop_loot_piece(
                    grid_x(0),
                    grid_y(row).saturating_sub(10 * POSITION_SCALE),
                    12,
                    events,
                );
            }
        }
        if finished {
            self.state.board.zombies[zombie_index].health = 0;
            self.state.board.zombies[zombie_index].eating = false;
        } else {
            self.state.board.zombies[zombie_index].eating = true;
        }
        true
    }

    fn update_zombiquarium_brains(&mut self) {
        for brain in &mut self.state.board.brains {
            if brain.position_x != 0 && !brain.squished {
                brain.age = brain.age.saturating_add(1);
                brain.position_y += 150_000;
                if brain.position_y >= 515 * POSITION_SCALE {
                    brain.squished = true;
                }
            }
        }
    }

    fn update_zombiquarium_zombie(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let (entity, mut health, position_x, position_y, age, phase, phase_counter) = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.age = zombie.age.saturating_add(1);
            (
                zombie.id,
                zombie.health,
                zombie.position_x,
                zombie.position_y,
                zombie.age,
                zombie.aquarium_phase,
                zombie.aquarium_phase_counter,
            )
        };

        if age % ZOMBIQUARIUM_DAMAGE_TICKS == 0 {
            let health_remaining = self.state.board.zombies[zombie_index]
                .health
                .saturating_sub(ZOMBIQUARIUM_DAMAGE);
            self.state.board.zombies[zombie_index].health = health_remaining;
            health = health_remaining;
            events.push(GameEvent::ZombieDamaged {
                entity,
                damage: ZOMBIQUARIUM_DAMAGE,
                health_remaining,
                attacker: None,
            });
            if health_remaining <= 0 {
                events.push(GameEvent::ZombiquariumZombieDied { entity });
                self.emit_zombie_died_with_loot(entity, events);
                self.state.board.zombies[zombie_index].departed = true;
                if self
                    .state
                    .board
                    .zombies
                    .iter()
                    .all(|zombie| zombie.id == entity || zombie.departed || zombie.health <= 0)
                {
                    self.state.scene = SceneKind::GameOver;
                    self.state.game_lost_cutscene_time = Some(0);
                    events.push(GameEvent::GameLost { zombie: entity });
                }
                return;
            }
        }

        let mut spawn_sun = false;
        {
            let zombie = &mut self.state.board.zombies[zombie_index];
            if zombie.aquarium_counter > 0 {
                zombie.aquarium_counter -= 1;
            } else {
                zombie.aquarium_counter = self.rng.range_inclusive(1_000, 1_500);
                spawn_sun = true;
            }
        }
        if spawn_sun {
            self.spawn_sun_value(
                SunSource::Plant(entity),
                NORMAL_SUN_VALUE,
                position_x + 50 * POSITION_SCALE,
                position_y + 40 * POSITION_SCALE,
                events,
            );
        }

        if phase == ZOMBIQUARIUM_BITE_PHASE {
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.aquarium_phase_counter = phase_counter.saturating_sub(1);
            if zombie.aquarium_phase_counter == 0 {
                zombie.aquarium_phase = ZOMBIQUARIUM_DRIFT_PHASE;
                zombie.aquarium_speed = ZOMBIQUARIUM_DRIFT_SPEED;
            }
            return;
        }

        let zombie_center_x = position_x + 50 * POSITION_SCALE;
        let zombie_center_y = position_y + 40 * POSITION_SCALE;
        let target = if health <= 150 {
            self.state
                .board
                .brains
                .iter()
                .enumerate()
                .filter(|(_, brain)| {
                    brain.position_x != 0
                        && !brain.squished
                        && brain.age >= ZOMBIQUARIUM_BRAIN_ARM_TICKS
                })
                .map(|(index, brain)| {
                    let dx = brain.position_x - zombie_center_x;
                    let dy = brain.position_y - zombie_center_y;
                    (index, brain.position_x, brain.position_y, dx * dx + dy * dy)
                })
                .min_by_key(|(_, _, _, distance)| *distance)
        } else {
            None
        };

        if let Some((brain_index, target_x, target_y, distance)) = target {
            if distance <= (50 * POSITION_SCALE) * (50 * POSITION_SCALE) {
                let brain_row = self.state.board.brains[brain_index].row;
                self.state.board.brains[brain_index].squished = true;
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.health = (zombie.health + ZOMBIQUARIUM_HEAL).min(zombie.max_health);
                zombie.aquarium_phase = ZOMBIQUARIUM_BITE_PHASE;
                zombie.aquarium_phase_counter = ZOMBIQUARIUM_BITE_TICKS;
                zombie.aquarium_speed = 0;
                zombie.aquarium_velocity_x = 0;
                zombie.aquarium_velocity_y = 0;
                let brains_remaining = self
                    .state
                    .board
                    .brains
                    .iter()
                    .filter(|brain| brain.position_x != 0 && !brain.squished)
                    .count()
                    .try_into()
                    .unwrap_or(u8::MAX);
                events.push(GameEvent::ZombiquariumBrainSlurped {
                    zombie: entity,
                    row: brain_row,
                });
                events.push(GameEvent::BrainEaten {
                    zombie: entity,
                    row: brain_row,
                    brains_remaining,
                });
                return;
            }

            let dx = target_x - zombie_center_x;
            let dy = target_y - zombie_center_y;
            let distance = dx.abs().max(dy.abs());
            let speed = {
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.aquarium_phase = ZOMBIQUARIUM_ACCEL_PHASE;
                zombie.aquarium_speed = (zombie.aquarium_speed + ZOMBIQUARIUM_ACCELERATION)
                    .min(ZOMBIQUARIUM_BRAIN_SPEED);
                zombie.aquarium_speed
            };
            if distance > 0 {
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.position_x += dx * speed / distance;
                zombie.position_y += dy * speed / distance;
            }
            self.clamp_zombiquarium_position(zombie_index);
            return;
        }

        let choose_direction = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            if zombie.aquarium_phase_counter == 0 {
                zombie.aquarium_phase_counter = 300 + self.rng.range(701);
                zombie.aquarium_phase = if self.rng.range(2) == 0 {
                    ZOMBIQUARIUM_ACCEL_PHASE
                } else {
                    ZOMBIQUARIUM_BACK_AND_FORTH_PHASE
                };
                true
            } else {
                false
            }
        };
        if choose_direction {
            let directions = [
                (1_000, 0),
                (-1_000, 0),
                (0, 1_000),
                (0, -1_000),
                (1_000, 1_000),
                (-1_000, 1_000),
                (1_000, -1_000),
                (-1_000, -1_000),
            ];
            let (velocity_x, velocity_y) = directions[self.rng.range(8) as usize];
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.aquarium_velocity_x = velocity_x;
            zombie.aquarium_velocity_y = velocity_y;
        } else {
            self.state.board.zombies[zombie_index].aquarium_phase_counter =
                phase_counter.saturating_sub(1);
        }

        let (velocity_x, velocity_y, speed_cap) = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            let speed_cap = match zombie.aquarium_phase {
                ZOMBIQUARIUM_DRIFT_PHASE => ZOMBIQUARIUM_DRIFT_SPEED,
                ZOMBIQUARIUM_BACK_AND_FORTH_PHASE => 300_000,
                _ => ZOMBIQUARIUM_MAX_SPEED,
            };
            zombie.aquarium_speed =
                (zombie.aquarium_speed + ZOMBIQUARIUM_ACCELERATION).min(speed_cap);
            (
                zombie.aquarium_velocity_x,
                zombie.aquarium_velocity_y,
                zombie.aquarium_speed,
            )
        };
        let zombie = &mut self.state.board.zombies[zombie_index];
        zombie.position_x += velocity_x * speed_cap / 1_000;
        zombie.position_y += velocity_y * speed_cap / 1_000;
        self.clamp_zombiquarium_position(zombie_index);
    }

    fn clamp_zombiquarium_position(&mut self, zombie_index: usize) {
        let zombie = &mut self.state.board.zombies[zombie_index];
        if zombie.position_x <= ZOMBIQUARIUM_MIN_X || zombie.position_x >= ZOMBIQUARIUM_MAX_X {
            zombie.aquarium_velocity_x = -zombie.aquarium_velocity_x;
            zombie.aquarium_phase_counter = zombie.aquarium_phase_counter.min(100);
        }
        if zombie.position_y <= ZOMBIQUARIUM_MIN_Y || zombie.position_y >= ZOMBIQUARIUM_MAX_Y {
            zombie.aquarium_velocity_y = -zombie.aquarium_velocity_y;
            zombie.aquarium_phase_counter = zombie.aquarium_phase_counter.min(100);
        }
        zombie.position_x = zombie
            .position_x
            .clamp(ZOMBIQUARIUM_MIN_X, ZOMBIQUARIUM_MAX_X);
        zombie.position_y = zombie
            .position_y
            .clamp(ZOMBIQUARIUM_MIN_Y, ZOMBIQUARIUM_MAX_Y);
    }

    fn emit_zombie_died(&mut self, entity: EntityId, events: &mut Vec<GameEvent>) {
        let daisies_mode = self.state.daisies_mode;
        let scene = self.state.scene;
        let zombie = self
            .state
            .board
            .zombies
            .iter_mut()
            .find(|zombie| zombie.id == entity)
            .map(|zombie| {
                let zombie_type = zombie.zombie_type;
                let vehicle_disabled = zombie.vehicle_disabled;
                let falling_sound = !zombie.in_pool
                    && self.state.challenge.kind != ChallengeKind::Zombiquarium
                    && !zombie.falling_sound_played
                    && zombie_falling_sound_supported(zombie_type);
                if falling_sound {
                    zombie.falling_sound_played = true;
                }
                let daisies =
                    falling_sound && daisies_mode && zombie_can_drop_daisies(zombie, scene);
                (zombie_type, vehicle_disabled, falling_sound, daisies)
            });
        if let Some((zombie_type, vehicle_disabled, falling_sound, daisies)) = zombie {
            if !self.state.defeated_zombies.contains(&zombie_type) {
                self.state.defeated_zombies.push(zombie_type);
            }
            if falling_sound {
                events.push(GameEvent::ZombieFallingSound {
                    entity,
                    zombie_type,
                    variant: self.rng.range(2) as u8,
                });
            }
            if daisies {
                events.push(GameEvent::ZombieDaisiesDropped { entity });
            }
            if matches!(zombie_type, ZombieType::Zamboni | ZombieType::Catapult)
                && !vehicle_disabled
            {
                events.push(GameEvent::VehicleExploded { entity });
            }
            events.push(GameEvent::ZombieDeathSound {
                entity,
                zombie_type,
            });
        }
        events.push(GameEvent::ZombieDied { entity });
        self.try_spawn_final_level_award(entity);
    }

    fn emit_zombie_died_with_loot(&mut self, entity: EntityId, events: &mut Vec<GameEvent>) {
        self.emit_zombie_died(entity, events);
        self.drop_zombie_loot(entity, events);
    }

    fn final_wave_award_suppresses_loot(&self, entity: EntityId) -> bool {
        if self.state.scene == SceneKind::Complete
            || self
                .state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == entity)
                .is_none_or(|zombie| zombie.departed)
        {
            return false;
        }
        let wave = &self.state.board.wave;
        if wave.total == 0 || wave.current < wave.total || wave.endless {
            return false;
        }

        // TrySpawnLevelAward: final-boss levels only accept a Boss death.
        if self.state.mode == ModeKind::Adventure
            && self.state.level == 50
            && self
                .state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == entity)
                .is_none_or(|zombie| zombie.zombie_type != ZombieType::Boss)
        {
            return false;
        }
        let completion_branch = match self.state.mode {
            ModeKind::Adventure => {
                self.state.level != 35
                    && adventure_completion_award(self.state.level, self.state.adventure_first_time)
                        .is_some()
            }
            ModeKind::Survival => {
                !wave.endless
                    && self.state.challenge.stage.saturating_add(1)
                        >= survival_stage_limit(self.state.level)
            }
            ModeKind::MiniGame => {
                !(matches!(self.state.challenge.kind, ChallengeKind::Zombiquarium)
                    || is_continuous_challenge(self.state.challenge.kind)
                    || (self.state.challenge.kind == ChallengeKind::LastStand
                        && self.state.challenge.stage < LAST_STAND_FINAL_STAGE)
                    || (self.state.challenge.kind == ChallengeKind::WhackAZombie
                        && self.state.challenge.countdown > 0))
            }
            _ => false,
        };
        if !completion_branch {
            return false;
        }

        !self.state.board.zombies.iter().any(|zombie| {
            zombie.id != entity
                && zombie.health > 0
                && !zombie.departed
                && !zombie.hypnotized
                && zombie.has_head
        })
    }

    fn try_spawn_final_level_award(&mut self, entity: EntityId) -> bool {
        if !self.final_wave_award_suppresses_loot(entity) {
            return false;
        }
        for zombie in &mut self.state.board.zombies {
            zombie.health = 0;
            zombie.eating = false;
            zombie.departed = true;
        }
        true
    }

    fn drop_zombie_loot(&mut self, entity: EntityId, events: &mut Vec<GameEvent>) {
        // Zombie::TrySpawnLevelAward runs before DropLoot and excludes the
        // dying zombie from AreEnemyZombiesOnScreen.
        if self.try_spawn_final_level_award(entity)
            || self
                .state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == entity)
                .is_some_and(|zombie| zombie.departed)
        {
            return;
        }

        let already_dropped = self
            .state
            .board
            .zombies
            .iter()
            .find(|zombie| zombie.id == entity)
            .is_none_or(|zombie| {
                zombie.loot_dropped
                    || (zombie.zombie_type == ZombieType::Yeti && zombie.yeti_loot_dropped)
            });
        if already_dropped {
            if let Some(zombie) = self
                .state
                .board
                .zombies
                .iter_mut()
                .find(|zombie| zombie.id == entity && zombie.zombie_type == ZombieType::Yeti)
            {
                zombie.loot_dropped = true;
                zombie.yeti_loot_dropped = true;
            }
            return;
        }

        // Board::CanDropLoot: first-run Adventure levels below 11 suppress
        // DropLoot. Upsell cutscenes are not modeled separately.
        if self.state.mode == ModeKind::Adventure
            && self.state.adventure_first_time
            && self.state.level < 11
        {
            return;
        }

        let (zombie_type, row) = {
            let Some(zombie) = self
                .state
                .board
                .zombies
                .iter_mut()
                .find(|zombie| zombie.id == entity)
            else {
                return;
            };
            zombie.loot_dropped = true;
            if zombie.zombie_type == ZombieType::Yeti {
                zombie.yeti_loot_dropped = true;
            }
            (zombie.zombie_type, zombie.row)
        };

        // Zombie::DropLoot marks mDroppedLoot before these mode-specific
        // ordinary-piece suppressions.
        if self.state.challenge.kind == ChallengeKind::LittleTrouble && self.rng.range(4) != 0 {
            return;
        }
        if self.state.mode == ModeKind::IZombie
            || self.state.challenge.kind == ChallengeKind::Zombiquarium
        {
            return;
        }

        let (position_x, position_y) = self
            .state
            .board
            .zombies
            .iter()
            .find(|zombie| zombie.id == entity)
            .map(|zombie| zombie_loot_position(self.state.scene, zombie))
            .unwrap_or((0, 0));
        if zombie_type == ZombieType::Yeti {
            events.push(GameEvent::LootDropSound {
                sound: LootDropSound::SpawnSun,
            });
            for offset in [20, 30, 40, 50].into_iter().take(YETI_DIAMOND_COUNT) {
                self.spawn_coin(
                    CoinType::Diamond,
                    position_x - offset * POSITION_SCALE,
                    grid_y(row),
                    events,
                );
            }
        } else {
            // Zombie::DropLoot passes GetZombieDefinition(...).mZombieValue as
            // the ordinary-drop factor (Zombie.cpp:7225-7248).
            self.drop_loot_piece(
                position_x,
                position_y,
                zombie_drop_value(zombie_type),
                events,
            );
        }
    }

    fn try_drop_adventure_mode_present(
        &mut self,
        position_x: i64,
        position_y: i64,
        events: &mut Vec<GameEvent>,
    ) -> bool {
        if self.state.mode != ModeKind::Adventure
            || !self.state.adventure_first_time
            || self.state.board.wave.current <= 5
        {
            return false;
        }
        let coin_type = match self.state.level {
            22 => CoinType::PresentMinigames,
            36 => CoinType::PresentPuzzleMode,
            _ => return false,
        };
        let unlock_mask = coin_type.unlock_mask();
        if self.state.unlocked_modes & unlock_mask != 0
            || self
                .state
                .board
                .coins
                .iter()
                .any(|coin| coin.coin_type == coin_type)
        {
            return false;
        }
        events.push(GameEvent::LootDropSound {
            sound: LootDropSound::ArtChallenge,
        });
        self.spawn_coin(coin_type, position_x, position_y, events);
        true
    }

    /// Board::DropLootPiece (Board.cpp:9447-9562), shared by Zombie::DropLoot,
    /// I, Zombie brain scoring, and Grave Buster with their distinct factors.
    fn drop_loot_piece(
        &mut self,
        position_x: i64,
        position_y: i64,
        drop_factor: u32,
        events: &mut Vec<GameEvent>,
    ) {
        // Adventure level-22/36 mode-unlock presents return first.
        if self.try_drop_adventure_mode_present(position_x, position_y, events) {
            return;
        }
        let mut drop_hit = self.rng.range(30_000);
        if self.state.mode == ModeKind::Adventure
            && self.state.adventure_first_time
            && self.state.level == 11
            && !self.state.board.dropped_first_coin
            && self.state.board.wave.current > 5
        {
            drop_hit = 1000;
        }
        if self.state.challenge.kind == ChallengeKind::Column {
            drop_hit *= 5;
        }
        if self.state.challenge.kind == ChallengeKind::WhackAZombie {
            // Board.cpp:9475-9487: Whack-a-Zombie sun drops shrink as the
            // board money (mSunMoney, modeled as state.sun) grows.
            let sun_max = if self.state.sun > 500 {
                2800
            } else if self.state.sun > 350 {
                3100
            } else if self.state.sun > 200 {
                3700
            } else {
                5000
            };
            if drop_hit >= 2500 * drop_factor && drop_hit <= sun_max * drop_factor {
                events.push(GameEvent::LootDropSound {
                    sound: LootDropSound::SpawnSun,
                });
                for offset in [20, 40, 60] {
                    self.spawn_sun(
                        SunSource::Sky,
                        position_x - offset * POSITION_SCALE,
                        position_y,
                        events,
                    );
                }
                return;
            }
        }
        // Board.cpp:9489-9490: no ordinary loot after 70 spawned waves.
        if self.state.board.wave.total_spawned_waves > 70 {
            return;
        }
        let potted_plant_chance = if !self.can_drop_potted_plant_loot() {
            0
        } else if self.state.mode == ModeKind::Adventure && !self.state.adventure_first_time {
            24
        } else if self.state.mode == ModeKind::Survival && self.state.board.wave.endless {
            3
        } else {
            12
        };
        let mut chocolate_chance = potted_plant_chance;
        if self.can_drop_chocolate() {
            chocolate_chance = potted_plant_chance
                + if self.state.mode == ModeKind::Adventure && !self.state.adventure_first_time {
                    72
                } else if self.state.mode == ModeKind::Survival && self.state.board.wave.endless {
                    9
                } else {
                    36
                };
        }
        let diamond_chance = chocolate_chance + 14;
        let gold_chance = chocolate_chance + 250;
        let silver_chance = chocolate_chance + 2500;
        let coin_type = if drop_hit < potted_plant_chance * drop_factor {
            CoinType::PresentPlant
        } else if drop_hit < chocolate_chance * drop_factor {
            CoinType::Chocolate
        } else if drop_hit < diamond_chance * drop_factor {
            if self.state.packet_upgrades < 1 {
                CoinType::Gold
            } else {
                CoinType::Diamond
            }
        } else if drop_hit < gold_chance * drop_factor {
            CoinType::Gold
        } else if drop_hit < silver_chance * drop_factor {
            CoinType::Silver
        } else {
            return;
        };
        if self.state.challenge.kind == ChallengeKind::WallnutBowling && coin_type.is_money() {
            return;
        }
        if self.state.mode == ModeKind::Adventure
            && self.state.adventure_first_time
            && self.state.level == 11
        {
            // Board.cpp:9549-9558: suppress while the packet upgrade stays
            // affordable; CountCoinsBeingCollected is zero under Rust's
            // immediate-collection model.
            let money = CoinType::Gold.value()
                * u32::try_from(self.state.board.mowers.len()).unwrap_or(0)
                + self.state.coins
                + coin_type.value();
            if money >= self.packet_upgrade_cost() {
                return;
            }
        }
        events.push(GameEvent::LootDropSound {
            sound: LootDropSound::SpawnSun,
        });
        self.spawn_coin(
            coin_type,
            position_x - 40 * POSITION_SCALE,
            position_y,
            events,
        );
        self.state.board.dropped_first_coin = true;
    }

    /// ZenGarden::IsZenGardenFull (ZenGarden.cpp:295-320): dropped
    /// `AwardPresent`/`PresentPlant` pickups count only when included, plus
    /// Zen-tagged potted plants, against the 8 x 4 capacity.
    fn is_zen_garden_full(&self, include_dropped_presents: bool) -> bool {
        let presents = if include_dropped_presents {
            self.state
                .board
                .coins
                .iter()
                .filter(|coin| {
                    matches!(
                        coin.coin_type,
                        CoinType::AwardPresent | CoinType::PresentPlant
                    )
                })
                .count()
        } else {
            0
        };
        presents + zen_garden_plant_count(&self.state.garden) >= ZEN_GARDEN_CAPACITY
    }

    /// ZenGarden::CanDropPottedPlantLoot (ZenGarden.cpp:317-320): finished
    /// Adventure plus spare Zen capacity including dropped presents.
    fn can_drop_potted_plant_loot(&self) -> bool {
        self.state.adventure_finished && !self.is_zen_garden_full(true)
    }

    /// ZenGarden::CanDropChocolate (ZenGarden.cpp:289-292): Stinky purchased
    /// and fewer than ten usable charges.
    fn can_drop_chocolate(&self) -> bool {
        self.state.stinky_purchased && self.state.chocolates < 10
    }

    /// StoreScreen::GetItemCost(STORE_ITEM_PACKET_UPGRADE)
    /// (StoreScreen.cpp:887-891): 75/500/2000 then 8000.
    fn packet_upgrade_cost(&self) -> u32 {
        match self.state.packet_upgrades {
            0 => 75,
            1 => 500,
            2 => 2000,
            _ => 8000,
        }
    }

    fn dolphin_is_tangle_target(&self, entity: EntityId) -> bool {
        self.state.board.plants.iter().any(|plant| {
            plant.plant_type.is_tangle_kelp()
                && plant.special_armed
                && plant.special_target == Some(entity)
        })
    }

    fn update_dolphin_state(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) -> bool {
        let (entity, row, position_x, phase, counter, backwards) = {
            let zombie = &self.state.board.zombies[zombie_index];
            if zombie.zombie_type != ZombieType::DolphinRider {
                return false;
            }
            (
                zombie.id,
                zombie.row,
                zombie.position_x,
                zombie.dolphin_phase,
                zombie.dolphin_counter,
                zombie.hypnotized,
            )
        };
        if self.state.scene != SceneKind::Pool || !matches!(row, 2 | 3) {
            return false;
        }
        if self.dolphin_is_tangle_target(entity) {
            return false;
        }

        let next_counter = counter.saturating_sub(1);
        let ride_target = phase == DOLPHIN_RIDING_PHASE
            && self
                .find_plant_for_dolphin(row, position_x, false)
                .is_some();
        let jump_target = if phase == DOLPHIN_IN_JUMP_PHASE
            && next_counter == DOLPHIN_JUMP_BONK_COUNTER
        {
            self.find_plant_for_dolphin(row, position_x, true)
                .filter(|&plant_index| self.state.board.plants[plant_index].plant_type.slot() == 23)
                .map(|plant_index| {
                    (
                        grid_x(self.state.board.plants[plant_index].column) + 25 * POSITION_SCALE,
                        self.state.board.plants[plant_index].id,
                    )
                })
        } else {
            None
        };

        let mut pool_splash = false;
        let mut jump_started = false;
        let mut suppress_attack = false;
        let mut jump_blocked = None;
        let mut reset_walk_speed = false;
        {
            let zombie = &mut self.state.board.zombies[zombie_index];
            if matches!(
                zombie.dolphin_phase,
                DOLPHIN_WALKING_PHASE | DOLPHIN_WALKING_WITHOUT_DOLPHIN_PHASE
            ) && zombie.in_pool
                && zombie.dolphin_counter > 0
            {
                zombie.dolphin_counter = zombie.dolphin_counter.saturating_sub(1);
                if zombie.dolphin_counter == 0 {
                    zombie.in_pool = false;
                }
            }

            match zombie.dolphin_phase {
                DOLPHIN_WALKING_PHASE
                    if !backwards
                        && zombie.position_x > 700 * POSITION_SCALE
                        && zombie.position_x <= 720 * POSITION_SCALE =>
                {
                    zombie.dolphin_phase = DOLPHIN_INTO_POOL_PHASE;
                    zombie.dolphin_counter = DOLPHIN_ENTRY_TICKS;
                }
                DOLPHIN_INTO_POOL_PHASE => {
                    zombie.dolphin_counter = next_counter;
                    if zombie.dolphin_counter == DOLPHIN_ENTRY_TICKS - DOLPHIN_SPLASH_TICKS {
                        pool_splash = true;
                    }
                    if zombie.dolphin_counter == 0 {
                        zombie.position_x -= 70 * POSITION_SCALE;
                        zombie.dolphin_phase = DOLPHIN_RIDING_PHASE;
                        zombie.in_pool = true;
                        suppress_attack = true;
                    }
                }
                DOLPHIN_RIDING_PHASE => {
                    if zombie.position_x <= 10 * POSITION_SCALE {
                        zombie.dolphin_phase = DOLPHIN_WALKING_PHASE;
                        zombie.dolphin_counter = DOLPHIN_EXIT_TICKS;
                        reset_walk_speed = true;
                    } else if ride_target {
                        zombie.dolphin_phase = DOLPHIN_IN_JUMP_PHASE;
                        zombie.dolphin_counter = DOLPHIN_JUMP_TIME;
                        zombie.speed = DOLPHIN_RIDE_SPEED;
                        zombie.dolphin_target_x = None;
                        zombie.eating = false;
                        jump_started = true;
                    }
                }
                DOLPHIN_IN_JUMP_PHASE => {
                    zombie.dolphin_counter = next_counter;
                    if let Some((target_x, plant)) = jump_target {
                        zombie.position_x = target_x;
                        zombie.dolphin_phase = DOLPHIN_WALKING_IN_POOL_PHASE;
                        zombie.dolphin_counter = 0;
                        zombie.speed = DOLPHIN_POOL_SPEED;
                        suppress_attack = true;
                        jump_blocked = Some(plant);
                    } else if zombie.dolphin_counter == DOLPHIN_JUMP_SPLASH_COUNTER {
                        zombie.speed = 0;
                    } else if zombie.dolphin_counter == 0 {
                        zombie.position_x -= 94 * POSITION_SCALE;
                        zombie.dolphin_phase = DOLPHIN_WALKING_IN_POOL_PHASE;
                        zombie.speed = DOLPHIN_POOL_SPEED;
                        suppress_attack = true;
                    }
                }
                DOLPHIN_WALKING_IN_POOL_PHASE
                    if (!backwards && zombie.position_x <= 10 * POSITION_SCALE)
                        || (backwards && zombie.position_x > 680 * POSITION_SCALE) =>
                {
                    zombie.dolphin_phase = DOLPHIN_WALKING_WITHOUT_DOLPHIN_PHASE;
                    zombie.dolphin_counter = DOLPHIN_EXIT_TICKS;
                    reset_walk_speed = true;
                }
                _ => {}
            }
        }

        if reset_walk_speed {
            self.state.board.zombies[zombie_index].speed = self.rng.fixed_range(890_000, 910_000);
        }
        if pool_splash {
            events.push(GameEvent::ZombieEnteredPool {
                entity,
                variant: self.rng.range(2) as u8,
            });
        }
        if jump_started {
            events.push(GameEvent::DolphinJumpStarted { entity });
        }
        if let Some(plant) = jump_blocked {
            events.push(GameEvent::JumpBlocked {
                zombie: entity,
                plant,
            });
        }
        suppress_attack
    }

    fn update_snorkel_state(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let (entity, row, backwards) = {
            let zombie = &self.state.board.zombies[zombie_index];
            if zombie.zombie_type != ZombieType::Snorkel {
                return;
            }
            (zombie.id, zombie.row, zombie.hypnotized)
        };
        if self.state.scene != SceneKind::Pool || !matches!(row, 2 | 3) {
            return;
        }

        let mut pool_splash = false;
        {
            let zombie = &mut self.state.board.zombies[zombie_index];
            match zombie.snorkel_phase {
                SNORKEL_WALKING_PHASE
                    if !backwards
                        && zombie.position_x > 700 * POSITION_SCALE
                        && zombie.position_x <= 720 * POSITION_SCALE =>
                {
                    zombie.snorkel_phase = SNORKEL_INTO_POOL_PHASE;
                    zombie.snorkel_counter = SNORKEL_ENTRY_TICKS;
                    zombie.speed = SNORKEL_ENTRY_SPEED;
                }
                SNORKEL_INTO_POOL_PHASE => {
                    zombie.snorkel_counter = zombie.snorkel_counter.saturating_sub(1);
                    if zombie.snorkel_counter == SNORKEL_ENTRY_TICKS - SNORKEL_SPLASH_TICKS {
                        pool_splash = true;
                    }
                    if zombie.snorkel_counter == 0 {
                        zombie.snorkel_phase = SNORKEL_WALKING_IN_POOL_PHASE;
                        zombie.in_pool = true;
                    }
                }
                SNORKEL_WALKING_IN_POOL_PHASE => {
                    if (!backwards && zombie.position_x <= 25 * POSITION_SCALE)
                        || (backwards && zombie.position_x > 640 * POSITION_SCALE)
                    {
                        zombie.snorkel_phase = SNORKEL_OUT_OF_POOL_PHASE;
                        zombie.snorkel_counter = SNORKEL_EXIT_TICKS;
                        zombie.position_x += if backwards {
                            15 * POSITION_SCALE
                        } else {
                            -15 * POSITION_SCALE
                        };
                        // Source StartWalkAnim -> PickRandomSpeed re-picks 0.66..0.68
                        // and the zombie keeps walking while it rises out of the pool.
                        zombie.speed = self.rng.fixed_range(660_000, 680_000);
                        zombie.eating = false;
                    } else if zombie.eating {
                        zombie.snorkel_phase = SNORKEL_UP_TO_EAT_PHASE;
                        zombie.snorkel_counter = SNORKEL_EAT_TRANSITION_TICKS;
                        zombie.speed = 0;
                    }
                }
                SNORKEL_UP_TO_EAT_PHASE => {
                    zombie.speed = 0;
                    if !zombie.eating {
                        zombie.snorkel_phase = SNORKEL_DOWN_FROM_EAT_PHASE;
                        zombie.snorkel_counter = SNORKEL_EAT_TRANSITION_TICKS;
                    } else {
                        zombie.snorkel_counter = zombie.snorkel_counter.saturating_sub(1);
                        if zombie.snorkel_counter == 0 {
                            zombie.snorkel_phase = SNORKEL_EATING_IN_POOL_PHASE;
                        }
                    }
                }
                SNORKEL_EATING_IN_POOL_PHASE => {
                    zombie.speed = 0;
                    if !zombie.eating {
                        zombie.snorkel_phase = SNORKEL_DOWN_FROM_EAT_PHASE;
                        zombie.snorkel_counter = SNORKEL_EAT_TRANSITION_TICKS;
                    }
                }
                SNORKEL_DOWN_FROM_EAT_PHASE => {
                    zombie.speed = 0;
                    zombie.snorkel_counter = zombie.snorkel_counter.saturating_sub(1);
                    if zombie.snorkel_counter == 0 {
                        zombie.snorkel_phase = SNORKEL_WALKING_IN_POOL_PHASE;
                        // Source PickRandomSpeed re-picks 0.66..0.68 for every Snorkel.
                        zombie.speed = self.rng.fixed_range(660_000, 680_000);
                    }
                }
                SNORKEL_OUT_OF_POOL_PHASE => {
                    zombie.snorkel_counter = zombie.snorkel_counter.saturating_sub(1);
                    if zombie.snorkel_counter == 0 {
                        zombie.snorkel_phase = SNORKEL_WALKING_PHASE;
                        zombie.in_pool = false;
                    }
                }
                _ => {}
            }
        }

        if pool_splash {
            events.push(GameEvent::ZombieEnteredPool {
                entity,
                variant: self.rng.range(2) as u8,
            });
        }
    }

    fn update_zamboni_state(&mut self, zombie_index: usize) {
        let (row, position_x) = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            if zombie.zombie_type != ZombieType::Zamboni {
                return;
            }
            zombie.speed = zamboni_speed(zombie.position_x);
            (zombie.row, zombie.position_x)
        };
        let lay_min = if self.state.scene == SceneKind::Roof {
            ICE_LAY_MIN_X_ROOF
        } else {
            ICE_LAY_MIN_X
        };
        let ice_x = (position_x + ICE_LAY_OFFSET).max(lay_min);
        let row_index = usize::from(row);
        if row_index >= self.state.board.ice_timer.len() {
            return;
        }
        if ice_x < self.state.board.ice_min_x[row_index] {
            self.state.board.ice_min_x[row_index] = ice_x;
        }
        if ice_x < ICE_START_X {
            self.state.board.ice_timer[row_index] =
                if self.state.challenge.kind == ChallengeKind::BobsledBonanza {
                    u32::MAX
                } else {
                    ICE_TIMER_TICKS
                };
        }
    }

    fn update_ice(&mut self) {
        for row in 0..self.state.board.ice_timer.len() {
            if self.state.board.ice_timer[row] > 0 {
                self.state.board.ice_timer[row] -= 1;
                if self.state.board.ice_timer[row] == 0 {
                    self.state.board.ice_min_x[row] = ICE_START_X;
                }
            }
        }
    }

    fn is_ice_at(&self, row: u8, column: u8) -> bool {
        let row_index = usize::from(row);
        let timer = self
            .state
            .board
            .ice_timer
            .get(row_index)
            .copied()
            .unwrap_or(0);
        let min_x = self
            .state
            .board
            .ice_min_x
            .get(row_index)
            .copied()
            .unwrap_or(ICE_START_X);
        if timer == 0 || min_x > 750 * POSITION_SCALE {
            return false;
        }
        let ice_column =
            ((min_x + 12 * POSITION_SCALE - 40 * POSITION_SCALE) / (80 * POSITION_SCALE))
                .clamp(0, i64::from(self.state.board.columns.saturating_sub(1))) as u8;
        column >= ice_column
    }

    fn update_balloon_state(&mut self, zombie_index: usize) {
        let zombie = &mut self.state.board.zombies[zombie_index];
        if zombie.zombie_type == ZombieType::Balloon
            && zombie.balloon_phase == BALLOON_POPPING_PHASE
        {
            zombie.balloon_counter = zombie.balloon_counter.saturating_sub(1);
            if zombie.balloon_counter == 0 {
                zombie.balloon_phase = BALLOON_WALKING_PHASE;
            }
        }
    }

    fn update_special_zombie_state(
        &mut self,
        zombie_index: usize,
        events: &mut Vec<GameEvent>,
    ) -> bool {
        match self.state.board.zombies[zombie_index].zombie_type {
            ZombieType::Boss => {
                self.update_boss_state(zombie_index, events);
                true
            }
            ZombieType::JalapenoHead => self.update_jalapeno_head(zombie_index, events),
            ZombieType::GatlingHead => {
                self.update_gatling_head(zombie_index, events);
                false
            }
            ZombieType::SquashHead => self.update_squash_head(zombie_index, events),
            _ => false,
        }
    }

    fn start_boss_rv(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let max_row = self.state.board.rows.saturating_sub(2);
        let target_row = self.rng.range(u32::from(max_row) + 1) as u8;
        let target_column = self.rng.range(3) as u8;
        let entity = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.special_phase = BOSS_RV_PHASE_DROP;
            zombie.special_counter = BOSS_RV_LANDING_TICKS;
            zombie.boss_target_row = target_row;
            zombie.boss_target_column = target_column;
            zombie.id
        };
        events.push(GameEvent::BossRVStarted {
            entity,
            row: target_row,
            column: target_column,
        });
    }

    fn update_boss_rv_landing(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let (entity, target_row, target_column) = {
            let zombie = &self.state.board.zombies[zombie_index];
            (zombie.id, zombie.boss_target_row, zombie.boss_target_column)
        };
        let target_ids = self
            .state
            .board
            .plants
            .iter()
            .filter(|plant| {
                plant.health > 0
                    && plant.row >= target_row
                    && plant.row <= target_row.saturating_add(1)
                    && plant.column >= target_column
                    && plant.column <= target_column.saturating_add(2)
            })
            .map(|plant| plant.id)
            .collect::<Vec<_>>();
        for plant_id in target_ids {
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
            {
                plant.health = 0;
                events.push(GameEvent::PlantDied { entity: plant_id });
            }
        }
        events.push(GameEvent::BossRVLanded {
            entity,
            row: target_row,
            column: target_column,
        });
        let boss = &mut self.state.board.zombies[zombie_index];
        boss.special_phase = 0;
        boss.special_counter = BOSS_ATTACK_TICKS;
    }

    fn update_boss_state(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let rv_active = self.state.board.zombies[zombie_index].special_phase == BOSS_RV_PHASE_DROP;
        if rv_active {
            let landed = {
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.special_counter = zombie.special_counter.saturating_sub(1);
                zombie.special_counter == 0
            };
            if landed {
                self.update_boss_rv_landing(zombie_index, events);
            }
            return;
        }
        self.update_boss_head(zombie_index, events);
        let should_stomp = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.special_counter = zombie.special_counter.saturating_sub(1);
            zombie.special_counter == 0
        };
        if !should_stomp {
            return;
        }

        let max_row = self.state.board.rows.saturating_sub(2);
        let target_row = self.rng.range(u32::from(max_row) + 1) as u8;
        let target_ids = self
            .state
            .board
            .plants
            .iter()
            .filter(|plant| {
                plant.health > 0
                    && plant.row >= target_row
                    && plant.row <= target_row.saturating_add(1)
                    && plant.column >= 5
            })
            .map(|plant| plant.id)
            .collect::<Vec<_>>();
        let has_target = !target_ids.is_empty();
        for plant_id in target_ids {
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
            {
                plant.health = 0;
                events.push(GameEvent::PlantDied { entity: plant_id });
            }
        }
        if has_target {
            events.push(GameEvent::BossStomp {
                entity: self.state.board.zombies[zombie_index].id,
                row: target_row,
            });
        }
        self.state.board.zombies[zombie_index].special_counter = BOSS_ATTACK_TICKS;
    }

    /// Zombie.cpp:9977-10202: the boss head cycle spits a fire or ice ball
    /// down a random row; the ball drives over plants in its cell, squishes
    /// mowers it passes, and leaves the lawn at x < -180.
    fn update_boss_head(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let (ball_active, ball_row, ball_x) = {
            let zombie = &self.state.board.zombies[zombie_index];
            (
                zombie.boss_ball_active,
                zombie.boss_ball_row,
                zombie.boss_ball_x,
            )
        };
        if ball_active {
            if ball_x == BOSS_BALL_START_X {
                let boss = &self.state.board.zombies[zombie_index];
                events.push(GameEvent::BossProjectileStarted {
                    entity: boss.id,
                    row: boss.boss_ball_row,
                    fire: boss.boss_ball_fire,
                });
            }
            let ball_x = ball_x - BOSS_BALL_SPEED;
            if ball_x < BOSS_BALL_END_X {
                self.state.board.zombies[zombie_index].boss_ball_active = false;
            } else {
                self.state.board.zombies[zombie_index].boss_ball_x = ball_x;
                // Zombie.cpp:10156: drive-over squish at the ball center +75.
                let column = ((ball_x + 75 * POSITION_SCALE - 40 * POSITION_SCALE)
                    / (80 * POSITION_SCALE))
                    .clamp(0, i64::from(self.state.board.columns.saturating_sub(1)))
                    as u8;
                let plant_ids = self
                    .state
                    .board
                    .plants
                    .iter()
                    .filter(|plant| {
                        plant.health > 0 && plant.row == ball_row && plant.column == column
                    })
                    .map(|plant| plant.id)
                    .collect::<Vec<_>>();
                for plant_id in plant_ids {
                    if let Some(plant) = self
                        .state
                        .board
                        .plants
                        .iter_mut()
                        .find(|plant| plant.id == plant_id)
                    {
                        plant.health = 0;
                        events.push(GameEvent::PlantDied { entity: plant_id });
                    }
                }
                // Zombie.cpp:10158-10166: the ball squishes mowers it passes
                // instead of triggering them.
                let mut squished_rows = Vec::new();
                self.state.board.mowers.retain(|mower| {
                    let squished = mower.row == ball_row
                        && mower.position_x > ball_x
                        && mower.position_x < ball_x + BOSS_BALL_MOWER_REACH;
                    if squished {
                        squished_rows.push(mower.row);
                    }
                    !squished
                });
                for row in squished_rows {
                    events.push(GameEvent::MowerSquished {
                        row,
                        variant: self.rng.range(2) as u8,
                    });
                }
            }
        }
        let counter = self.state.board.zombies[zombie_index].boss_head_counter;
        if counter > 1 {
            self.state.board.zombies[zombie_index].boss_head_counter = counter - 1;
        } else if counter == 1 {
            // BossHeadSpit (Zombie.cpp:9987-10002): row 0-4, 50/50 fire.
            let row = self.rng.range(u32::from(DAY_ROWS)) as u8;
            let fire = self.rng.range(2) == 0;
            let next = BOSS_HEAD_SPIT_DELAY + self.rng.range_inclusive(4_000, 5_000);
            let entity = {
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.boss_head_counter = next;
                zombie.boss_ball_active = true;
                zombie.boss_ball_fire = fire;
                zombie.boss_ball_row = row;
                zombie.boss_ball_x = BOSS_BALL_START_X;
                zombie.id
            };
            // Zombie.cpp:10385-10395: the simplified fixed-step head-entry
            // boundary retains the source hydraulic Foley before the spit.
            events.push(GameEvent::BossHeadHydraulic { entity });
            events.push(GameEvent::BossAttackWindup { entity, row, fire });
        }
    }

    /// Plant.cpp:4261-4265 (Ice-shroom kills the fire ball) and
    /// Zombie.cpp:2345-2349 (a row burn kills the ice ball in its row).
    fn destroy_boss_ball(&mut self, fire: bool, row: Option<u8>, events: &mut Vec<GameEvent>) {
        for zombie in &mut self.state.board.zombies {
            if zombie.zombie_type == ZombieType::Boss
                && zombie.boss_ball_active
                && zombie.boss_ball_fire == fire
                && (row.is_none() || row == Some(zombie.boss_ball_row))
            {
                zombie.boss_ball_active = false;
                events.push(GameEvent::BossProjectileDestroyed {
                    entity: zombie.id,
                    fire,
                });
            }
        }
    }

    fn update_jalapeno_head(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) -> bool {
        let should_burn = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            if zombie.special_counter == 0 {
                true
            } else {
                zombie.special_counter -= 1;
                zombie.special_counter == 0
            }
        };
        if !should_burn {
            return false;
        }

        let row = self.state.board.zombies[zombie_index].row;
        let plant_ids = self
            .state
            .board
            .plants
            .iter()
            .filter(|plant| plant.health > 0 && plant.row == row)
            .map(|plant| plant.id)
            .collect::<Vec<_>>();
        for plant_id in plant_ids {
            if let Some(plant) = self
                .state
                .board
                .plants
                .iter_mut()
                .find(|plant| plant.id == plant_id)
            {
                plant.health = 0;
                events.push(GameEvent::PlantDied { entity: plant_id });
            }
        }
        let zombie_id = self.state.board.zombies[zombie_index].id;
        self.state.board.zombies[zombie_index].health = 0;
        self.state.board.zombies[zombie_index].eating = false;
        self.emit_zombie_died(zombie_id, events);
        true
    }

    fn update_gatling_head(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let should_fire = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.special_counter = zombie.special_counter.saturating_sub(1);
            if zombie.special_counter == 0 {
                zombie.special_counter = ZOMBOTANY_HEAD_RELOAD_TICKS;
                true
            } else {
                false
            }
        };
        if !should_fire {
            return;
        }

        let (source, row, position_x) = {
            let zombie = &self.state.board.zombies[zombie_index];
            (zombie.id, zombie.row, zombie.position_x)
        };
        for _ in 0..4 {
            self.fire_projectile(
                source,
                ProjectileType::ZombiePea,
                row,
                ProjectileTrajectory {
                    motion: ProjectileMotion::Backwards,
                    position_x: position_x + 20 * POSITION_SCALE,
                    position_y: grid_y(row),
                    velocity_x: -3_330_000,
                    velocity_y: 0,
                },
                events,
            );
        }
    }

    fn update_squash_head(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) -> bool {
        let phase = self.state.board.zombies[zombie_index].special_phase;
        if phase == 0 {
            return false;
        }

        match phase {
            1 => {
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.special_counter = zombie.special_counter.saturating_sub(1);
                if zombie.special_counter == 0 {
                    zombie.special_phase = 2;
                    zombie.special_counter = ZOMBOTANY_SQUASH_FALL_TICKS;
                }
            }
            2 => {
                let (counter, target_id) = {
                    let zombie = &mut self.state.board.zombies[zombie_index];
                    let counter = zombie.special_counter;
                    zombie.special_counter = counter.saturating_sub(1);
                    (counter, zombie.special_target.take())
                };
                if counter <= 3
                    && let Some(target_id) = target_id
                    && let Some(plant) = self
                        .state
                        .board
                        .plants
                        .iter_mut()
                        .find(|plant| plant.id == target_id && plant.health > 0)
                {
                    plant.health = 0;
                    events.push(GameEvent::PlantDied { entity: target_id });
                }
                if self.state.board.zombies[zombie_index].special_counter == 0 {
                    self.state.board.zombies[zombie_index].special_phase = 3;
                    self.state.board.zombies[zombie_index].special_counter =
                        ZOMBOTANY_SQUASH_DONE_TICKS;
                } else if target_id.is_some() {
                    self.state.board.zombies[zombie_index].special_target = target_id;
                }
            }
            3 => {
                let zombie_id = {
                    let zombie = &mut self.state.board.zombies[zombie_index];
                    zombie.special_counter = zombie.special_counter.saturating_sub(1);
                    if zombie.special_counter == 0 {
                        Some(zombie.id)
                    } else {
                        None
                    }
                };
                if let Some(zombie_id) = zombie_id {
                    self.damage_zombie(zombie_index, ZOMBOTANY_SQUASH_DAMAGE, events);
                    self.emit_zombie_died_with_loot(zombie_id, events);
                }
            }
            _ => {}
        }
        true
    }

    fn blow_away_fliers(&mut self) {
        for zombie in &mut self.state.board.zombies {
            if balloon_is_airborne(zombie) {
                zombie.blowing_away = true;
            }
        }
    }

    fn damage_zombie(&mut self, zombie_index: usize, damage: i32, events: &mut Vec<GameEvent>) {
        self.damage_zombie_with_mode(
            zombie_index,
            damage,
            ShieldDamageMode::Consume,
            false,
            events,
        );
    }

    fn damage_zombie_with_mode(
        &mut self,
        zombie_index: usize,
        damage: i32,
        mode: ShieldDamageMode,
        spike: bool,
        events: &mut Vec<GameEvent>,
    ) {
        let pool_lane = self.state.scene == SceneKind::Pool
            && matches!(self.state.board.zombies[zombie_index].row, 2 | 3);
        let (
            entity,
            shield_damage,
            shield_type,
            newspaper_ripped,
            boss_damage_explosion,
            balloon_popped,
        ) = {
            let mut remaining = damage.max(0);
            let zombie = &mut self.state.board.zombies[zombie_index];
            let health_before = zombie.health;
            let mut balloon_popped = false;
            if zombie.zombie_type == ZombieType::Balloon
                && zombie.balloon_phase == BALLOON_FLYING_PHASE
            {
                let absorbed = remaining.min(zombie.balloon_flying_health);
                zombie.balloon_flying_health -= absorbed;
                remaining -= absorbed;
                if zombie.balloon_flying_health == 0 {
                    balloon_popped = absorbed > 0;
                    if pool_lane {
                        zombie.health = 0;
                        zombie.balloon_phase = 0;
                    } else {
                        zombie.balloon_phase = BALLOON_POPPING_PHASE;
                        zombie.balloon_counter = BALLOON_POP_TICKS;
                    }
                }
            }
            let shield_damage = if mode == ShieldDamageMode::Bypass {
                0
            } else {
                remaining.min(zombie.shield_health)
            };
            zombie.shield_health -= shield_damage;
            zombie.health -= if mode == ShieldDamageMode::HitShieldAndBody {
                damage.max(0)
            } else {
                remaining - shield_damage
            };
            let newspaper_ripped = zombie.zombie_type == ZombieType::Newspaper
                && shield_damage > 0
                && zombie.shield_health == 0
                && zombie.health > 0;
            let boss_damage_explosion = zombie.zombie_type == ZombieType::Boss
                && health_before >= zombie.max_health / BOSS_HEALTH_FLASH_FRACTION
                && zombie.health < zombie.max_health / BOSS_HEALTH_FLASH_FRACTION;
            if newspaper_ripped {
                zombie.newspaper_mad_pending = true;
            }
            (
                zombie.id,
                shield_damage,
                zombie.zombie_type,
                newspaper_ripped,
                boss_damage_explosion,
                balloon_popped,
            )
        };
        if balloon_popped {
            events.push(GameEvent::BalloonPopped { entity });
        }
        if newspaper_ripped {
            events.push(GameEvent::ZombieNewspaperRipped { entity });
        }
        if shield_damage > 0 && matches!(shield_type, ZombieType::ScreenDoor | ZombieType::Ladder) {
            events.push(GameEvent::ZombieShieldHit {
                entity,
                variant: self.rng.range(2) as u8,
            });
        }
        if boss_damage_explosion {
            events.push(GameEvent::BossDamageExplosion { entity });
        }
        self.update_damage_tier(zombie_index, spike, events);
    }

    /// Fume, gloom, and spike damage carry DAMAGE_BYPASSES_SHIELD: doors,
    /// paper, and ladders are skipped, but the Bobsled sled is a helm in the
    /// source and still absorbs first.
    fn damage_zombie_bypassing_shield(
        &mut self,
        zombie_index: usize,
        damage: i32,
        spike: bool,
        events: &mut Vec<GameEvent>,
    ) {
        if balloon_is_airborne(&self.state.board.zombies[zombie_index]) {
            return;
        }
        if self.state.board.zombies[zombie_index].zombie_type == ZombieType::Bobsled {
            self.damage_zombie(zombie_index, damage, events);
            return;
        }
        self.damage_zombie_with_mode(
            zombie_index,
            damage,
            ShieldDamageMode::Bypass,
            spike,
            events,
        );
    }

    fn damage_zombie_from_projectile(
        &mut self,
        zombie_index: usize,
        projectile: &ProjectileState,
        damage: i32,
        events: &mut Vec<GameEvent>,
    ) {
        if projectile.projectile_type.is_splash() {
            self.damage_zombie_with_mode(
                zombie_index,
                damage,
                ShieldDamageMode::HitShieldAndBody,
                false,
                events,
            );
        } else if matches!(
            projectile.motion,
            ProjectileMotion::Lobbed | ProjectileMotion::Backwards
        ) || (projectile.motion == ProjectileMotion::Star && projectile.velocity_x < 0)
        {
            self.damage_zombie_bypassing_shield(zombie_index, damage, false, events);
        } else {
            self.damage_zombie(zombie_index, damage, events);
        }
    }

    fn update_damage_tier(
        &mut self,
        zombie_index: usize,
        spike: bool,
        events: &mut Vec<GameEvent>,
    ) {
        let challenge = self.state.challenge.kind;
        let mustache_mode = self.state.mustache_mode;
        let future_mode = self.state.future_mode;
        let pinata_mode = self.state.pinata_mode;
        let (entity, drop_arm, drop_head, start_boss_rv, mustache_variant, future_frame) = {
            let zombie = &mut self.state.board.zombies[zombie_index];
            let tier = damage_tier(zombie.health, zombie.max_health);
            let entity = zombie.id;
            let start_boss_rv = zombie.zombie_type == ZombieType::Boss
                && zombie.health > 0
                && tier == 2
                && tier > zombie.damage_tier;
            if tier > zombie.damage_tier {
                zombie.damage_tier = tier;
                events.push(GameEvent::ZombieDamageTierChanged { entity, tier });
            }
            let drop_head = zombie.has_head
                && zombie.health < zombie.max_health / 3
                && zombie_can_lose_body_parts(zombie, challenge);
            let drop_arm = zombie.has_arm
                && zombie.health < zombie.max_health * 2 / 3
                && zombie.health > 0
                && zombie_can_lose_body_parts(zombie, challenge)
                && !matches!(
                    zombie.zombie_type,
                    ZombieType::ScreenDoor | ZombieType::Newspaper
                )
                && !(zombie.zombie_type == ZombieType::Snorkel
                    && zombie.snorkel_phase == SNORKEL_INTO_POOL_PHASE)
                && !(zombie.zombie_type == ZombieType::DolphinRider
                    && matches!(
                        zombie.dolphin_phase,
                        DOLPHIN_WALKING_PHASE
                            | DOLPHIN_INTO_POOL_PHASE
                            | DOLPHIN_RIDING_PHASE
                            | DOLPHIN_IN_JUMP_PHASE
                    ));
            if drop_arm {
                zombie.has_arm = false;
            }
            if drop_head {
                zombie.has_head = false;
            }
            if spike
                && matches!(
                    zombie.zombie_type,
                    ZombieType::Zamboni | ZombieType::Catapult
                )
                && !zombie.vehicle_disabled
            {
                zombie.vehicle_disabled = true;
                zombie.speed = 0;
                zombie.catapult_armed = false;
                events.push(GameEvent::VehicleDisabled { entity });
            }
            let plain = zombie_uses_plain_reanimation(zombie.zombie_type);
            (
                entity,
                drop_arm,
                drop_head,
                start_boss_rv,
                (drop_head && mustache_mode && plain && zombie.mustache_variant > 0)
                    .then_some(zombie.mustache_variant),
                (drop_head && future_mode && plain).then_some((entity & 3) as u8),
            )
        };
        if drop_arm {
            events.push(GameEvent::ZombieBodyPartLost {
                entity,
                head: false,
            });
        }
        if drop_head {
            events.push(GameEvent::ZombieBodyPartLost { entity, head: true });
            if let Some(variant) = mustache_variant {
                events.push(GameEvent::ZombieMustacheDropped { entity, variant });
            }
            if let Some(frame) = future_frame {
                events.push(GameEvent::ZombieFutureGlassesDropped { entity, frame });
            }
            if pinata_mode {
                events.push(GameEvent::ZombiePinataDropped { entity });
            }
            self.drop_zombie_loot(entity, events);
        }
        if start_boss_rv {
            self.start_boss_rv(zombie_index, events);
        }
    }

    fn update_gargantuar_throw(
        &mut self,
        zombie_index: usize,
        events: &mut Vec<GameEvent>,
    ) -> bool {
        let mut throw = None;
        {
            let zombie = &mut self.state.board.zombies[zombie_index];
            if !is_gargantuar(zombie.zombie_type) {
                return false;
            }

            if zombie.special_phase != 0 {
                if zombie.frozen_counter == 0 {
                    let step = if zombie.chilled_counter == 0 { 2 } else { 1 };
                    zombie.special_counter = zombie.special_counter.saturating_sub(step);
                    if zombie.special_counter == 0 {
                        if zombie.special_phase == 1 {
                            zombie.special_phase = 2;
                            zombie.special_counter = GARGANTUAR_THROW_RECOVERY_STEPS;
                            zombie.imp_thrown = true;
                            throw =
                                Some((zombie.id, zombie.row, zombie.position_x, zombie.from_wave));
                        } else {
                            zombie.special_phase = 0;
                        }
                    }
                }
            } else if !zombie.imp_thrown
                && zombie.frozen_counter == 0
                && zombie.health < zombie.max_health / 2
                && zombie.position_x - GARGANTUAR_THROW_BASE_X > GARGANTUAR_THROW_MIN_DISTANCE
            {
                zombie.special_phase = 1;
                zombie.special_counter = GARGANTUAR_THROW_EVENT_STEPS;
                zombie.eating = false;
            }
        }

        if let Some((gargantuar, row, position_x, wave)) = throw {
            self.throw_imp(gargantuar, row, position_x, wave, events);
        }
        self.state.board.zombies[zombie_index].special_phase != 0
    }

    fn update_pole_vault(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) -> bool {
        let (entity, row, position_x, phase, elapsed, has_vaulted, frozen, chilled) = {
            let zombie = &self.state.board.zombies[zombie_index];
            if zombie.zombie_type != ZombieType::PoleVaulter {
                return false;
            }
            (
                zombie.id,
                zombie.row,
                zombie.position_x,
                zombie.special_phase,
                zombie.special_counter,
                zombie.has_vaulted,
                zombie.frozen_counter > 1,
                zombie.chilled_counter > 1,
            )
        };

        if matches!(phase, POLE_VAULT_UP_LADDER_PHASE | POLE_VAULT_FALLING_PHASE) {
            if frozen {
                return true;
            }
            let ladder_present = self.state.board.zombies[zombie_index]
                .ladder_column
                .is_some_and(|column| {
                    self.state
                        .board
                        .ladders
                        .iter()
                        .any(|ladder| ladder.row == row && ladder.column == column)
                });
            let zombie = &mut self.state.board.zombies[zombie_index];
            let speed = if chilled {
                zombie.speed * 2 / 5
            } else {
                zombie.speed
            };
            zombie.position_x -= speed;

            if phase == POLE_VAULT_UP_LADDER_PHASE {
                let rise_steps = if ladder_present {
                    elapsed.saturating_add(1).min(POLE_VAULT_LADDER_RISE_STEPS)
                } else {
                    elapsed
                };
                if !ladder_present || rise_steps == POLE_VAULT_LADDER_RISE_STEPS {
                    let fall_steps = rise_steps
                        .saturating_mul(2)
                        .div_ceil(5)
                        .min(POLE_VAULT_LADDER_FALL_STEPS)
                        .saturating_sub(1);
                    zombie.special_phase = if fall_steps == 0 {
                        0
                    } else {
                        POLE_VAULT_FALLING_PHASE
                    };
                    zombie.special_counter = fall_steps;
                } else {
                    zombie.special_counter = rise_steps;
                }
            } else {
                zombie.special_counter = elapsed.saturating_sub(1);
                if zombie.special_counter == 0 {
                    zombie.special_phase = 0;
                }
            }
            return true;
        }

        if phase == 0 {
            if has_vaulted || frozen {
                return false;
            }
            if let Some(plant_index) = self.find_plant_for_pole_vault(row, position_x, false) {
                let plant = &self.state.board.plants[plant_index];
                let target_x = grid_x(plant.column);
                if self
                    .state
                    .board
                    .ladders
                    .iter()
                    .any(|ladder| ladder.row == plant.row && ladder.column == plant.column)
                {
                    let zombie = &mut self.state.board.zombies[zombie_index];
                    if target_x + 40 * POSITION_SCALE > position_x
                        && zombie.ladder_column != Some(plant.column)
                    {
                        zombie.eating = false;
                        zombie.ladder_column = Some(plant.column);
                        zombie.special_phase = POLE_VAULT_UP_LADDER_PHASE;
                        zombie.special_counter = 0;
                        let speed = if chilled {
                            zombie.speed * 2 / 5
                        } else {
                            zombie.speed
                        };
                        zombie.position_x -= speed;
                        return true;
                    }
                    return false;
                }

                let anim_rate = if chilled { 12 } else { 24 };
                let vault_speed = if self.state.challenge.kind == ChallengeKind::WallnutBowling {
                    0
                } else {
                    (position_x - target_x - POLE_VAULT_JUMP_OFFSET) * anim_rate / (43 * 100)
                };
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.has_vaulted = true;
                zombie.eating = false;
                zombie.special_phase = POLE_VAULT_IN_VAULT_PHASE;
                zombie.special_counter = 0;
                zombie.speed = vault_speed;
                zombie.position_x -= vault_speed;
                return true;
            }

            if self.state.mode == ModeKind::IZombie
                && position_x <= POLE_VAULT_BRAIN_TARGET_X
                && self
                    .state
                    .board
                    .brains
                    .iter()
                    .any(|brain| brain.row == row && !brain.squished)
            {
                let walk_speed = self.rng.fixed_range(230_000, 320_000);
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.has_vaulted = true;
                zombie.eating = false;
                zombie.speed = walk_speed;
            }
            return false;
        }

        if frozen {
            return true;
        }

        let step = if chilled { 1 } else { 2 };
        let next = elapsed.saturating_add(step).min(POLE_VAULT_COMPLETE_STEPS);
        self.state.board.zombies[zombie_index].special_counter = next;
        if elapsed < POLE_VAULT_GRASS_STEPS && next >= POLE_VAULT_GRASS_STEPS {
            events.push(GameEvent::PoleVaultGrassStep { entity });
        }
        if elapsed < POLE_VAULT_SOUND_STEPS && next >= POLE_VAULT_SOUND_STEPS {
            events.push(GameEvent::PoleVaultSound { entity });
        }

        if (POLE_VAULT_BLOCK_START_STEPS..=POLE_VAULT_BLOCK_END_STEPS).contains(&next)
            && let Some(plant_index) = self
                .find_plant_for_pole_vault(row, position_x, true)
                .filter(|plant_index| self.state.board.plants[*plant_index].plant_type.slot() == 23)
        {
            let plant = self.state.board.plants[plant_index].id;
            let plant_x = grid_x(self.state.board.plants[plant_index].column);
            let walk_speed = self.rng.fixed_range(230_000, 320_000);
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.position_x = plant_x;
            zombie.speed = walk_speed;
            zombie.special_phase = 0;
            zombie.special_counter = 0;
            events.push(GameEvent::JumpBlocked {
                zombie: entity,
                plant,
            });
            return false;
        }

        if next == POLE_VAULT_COMPLETE_STEPS {
            let walk_speed = self.rng.fixed_range(230_000, 320_000);
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.position_x -= POLE_VAULT_LANDING_SHIFT;
            zombie.speed = walk_speed;
            zombie.special_phase = 0;
            zombie.special_counter = 0;
            events.push(GameEvent::ZombieVaulted { entity });
            return false;
        }

        let zombie = &mut self.state.board.zombies[zombie_index];
        zombie.position_x -= zombie.speed;
        true
    }

    fn update_pogo_state(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let (entity, row, position_x, phase, counter, frozen, chilled, hypnotized, has_stick) = {
            let zombie = &self.state.board.zombies[zombie_index];
            if zombie.zombie_type != ZombieType::Pogo {
                return;
            }
            (
                zombie.id,
                zombie.row,
                zombie.position_x,
                zombie.pogo_phase,
                zombie.pogo_counter,
                zombie.frozen_counter != 0,
                zombie.chilled_counter != 0,
                zombie.hypnotized,
                zombie.special_phase == 0,
            )
        };
        if !has_stick || counter == 0 || frozen {
            return;
        }

        let next_counter = counter - 1;
        if next_counter == 5 {
            events.push(GameEvent::PogoBounceSound { entity });
        }
        if phase == POGO_FORWARD_BOUNCE_PHASE
            && next_counter == 70
            && let Some(plant_index) = self
                .find_plant_for_pole_vault(row, position_x, true)
                .filter(|&plant_index| self.state.board.plants[plant_index].plant_type.slot() == 23)
        {
            let plant = self.state.board.plants[plant_index].id;
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.special_phase = 1;
            zombie.pogo_counter = 0;
            zombie.pogo_phase = 0;
            zombie.pogo_target_x = None;
            zombie.pogo_velocity_x = 0;
            zombie.eating = false;
            events.push(GameEvent::JumpBlocked {
                zombie: entity,
                plant,
            });
            events.push(GameEvent::PogoStickLost { entity });
            return;
        }

        if next_counter == 0 {
            let (next_phase, target_x, velocity_x) =
                if let Some(plant_index) = self.find_plant_for_pole_vault(row, position_x, false) {
                    if phase == POGO_HIGH_BOUNCE_PHASE {
                        let plant_x = grid_x(self.state.board.plants[plant_index].column);
                        let target_x = plant_x - 60 * POSITION_SCALE;
                        (
                            POGO_FORWARD_BOUNCE_PHASE,
                            Some(target_x),
                            (target_x - position_x) / i64::from(POGO_BOUNCE_TICKS),
                        )
                    } else {
                        (POGO_HIGH_BOUNCE_PHASE, None, 0)
                    }
                } else {
                    (0, None, 0)
                };
            let zombie = &mut self.state.board.zombies[zombie_index];
            zombie.pogo_counter = POGO_BOUNCE_TICKS;
            zombie.pogo_phase = next_phase;
            zombie.pogo_target_x = target_x;
            zombie.pogo_velocity_x = velocity_x;
        } else {
            self.state.board.zombies[zombie_index].pogo_counter = next_counter;
        }

        let zombie = &mut self.state.board.zombies[zombie_index];
        let speed = if chilled {
            zombie.speed * 2 / 5
        } else {
            zombie.speed
        };
        let movement = match zombie.pogo_phase {
            POGO_HIGH_BOUNCE_PHASE => 0,
            POGO_FORWARD_BOUNCE_PHASE => {
                if chilled {
                    zombie.pogo_velocity_x * 2 / 5
                } else {
                    zombie.pogo_velocity_x
                }
            }
            _ if hypnotized => speed,
            _ => -speed,
        };
        zombie.position_x += movement;
    }

    fn dancer_group_blocked(&self, zombie_index: usize) -> bool {
        let zombie = &self.state.board.zombies[zombie_index];
        let leader_id = match zombie.zombie_type {
            ZombieType::Dancer => Some(zombie.id),
            ZombieType::BackupDancer => zombie.dancer_leader,
            _ => return false,
        };
        let Some(leader_id) = leader_id else {
            return false;
        };
        self.state.board.zombies.iter().any(|member| {
            (member.id == leader_id || member.dancer_leader == Some(leader_id))
                && (member.frozen_counter > 0 || member.eating)
        })
    }

    fn dancer_has_follower(&self, leader: EntityId, slot: u8) -> bool {
        self.state.board.zombies.iter().any(|zombie| {
            zombie.zombie_type == ZombieType::BackupDancer
                && zombie.health > 0
                && !zombie.departed
                && zombie.dancer_leader == Some(leader)
                && zombie.dancer_slot == slot
        })
    }

    fn dancer_slot_position(&self, row: u8, position_x: i64, slot: u8) -> Option<(u8, i64)> {
        let target_row = match slot {
            0 => row.checked_sub(1),
            1 => row.checked_add(1),
            2 | 3 => Some(row),
            _ => return None,
        }?;
        let target_x = match slot {
            0 | 1 => position_x,
            2 => position_x - 100 * POSITION_SCALE,
            3 => position_x + 100 * POSITION_SCALE,
            _ => return None,
        };
        (target_row < self.state.board.rows).then_some((target_row, target_x))
    }

    fn dancer_needs_follower(&self, zombie_index: usize) -> bool {
        let zombie = &self.state.board.zombies[zombie_index];
        (0..BACKUP_DANCER_COUNT as u8).any(|slot| {
            self.dancer_slot_position(zombie.row, zombie.position_x, slot)
                .is_some()
                && !self.dancer_has_follower(zombie.id, slot)
        })
    }

    fn summon_missing_dancers(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let (leader, row, position_x, wave, hypnotized) = {
            let zombie = &self.state.board.zombies[zombie_index];
            (
                zombie.id,
                zombie.row,
                zombie.position_x,
                zombie.from_wave,
                zombie.hypnotized,
            )
        };
        for slot in 0..BACKUP_DANCER_COUNT as u8 {
            if self.dancer_has_follower(leader, slot) {
                continue;
            }
            let Some((target_row, target_x)) = self.dancer_slot_position(row, position_x, slot)
            else {
                continue;
            };
            let backup = self.spawn_backup_dancer(target_row, wave, Some(target_x), events);
            if let Some(zombie) = self.state.board.zombies.iter_mut().find(|z| z.id == backup) {
                zombie.dancer_leader = Some(leader);
                zombie.dancer_slot = slot;
                zombie.dancer_phase = DANCER_RISE_PHASE;
                zombie.dancer_counter = DANCER_RISE_TICKS;
                zombie.hypnotized = hypnotized;
            }
        }
    }

    fn update_dancer_state(&mut self, zombie_index: usize, events: &mut Vec<GameEvent>) {
        let (zombie_type, phase, counter, frozen, eating) = {
            let zombie = &self.state.board.zombies[zombie_index];
            (
                zombie.zombie_type,
                zombie.dancer_phase,
                zombie.dancer_counter,
                zombie.frozen_counter != 0,
                zombie.eating,
            )
        };
        match zombie_type {
            ZombieType::Dancer => {
                if frozen {
                    return;
                }
                match phase {
                    DANCER_ENTRANCE_PHASE => {
                        let next = counter.saturating_sub(1);
                        let zombie = &mut self.state.board.zombies[zombie_index];
                        zombie.dancer_counter = next;
                        if next == 0 {
                            zombie.dancer_phase = DANCER_SNAP_PHASE;
                            zombie.dancer_counter = DANCER_SNAP_TICKS;
                        }
                    }
                    DANCER_SNAP_PHASE => {
                        let next = counter.saturating_sub(1);
                        if next == 0 {
                            let zombie_count_on_screen = self
                                .state
                                .board
                                .zombies
                                .iter()
                                .filter(|zombie| {
                                    zombie.health > 0
                                        && !zombie.departed
                                        && zombie.has_head
                                        && !zombie.hypnotized
                                })
                                .count();
                            if zombie_count_on_screen <= 15 {
                                events.push(GameEvent::DancerRumble {
                                    entity: self.state.board.zombies[zombie_index].id,
                                });
                            }
                            self.summon_missing_dancers(zombie_index, events);
                            let zombie = &mut self.state.board.zombies[zombie_index];
                            zombie.dancer_summoned = true;
                            zombie.dancer_phase = DANCER_HOLD_PHASE;
                            zombie.dancer_counter = DANCER_HOLD_TICKS;
                        } else {
                            self.state.board.zombies[zombie_index].dancer_counter = next;
                        }
                    }
                    DANCER_HOLD_PHASE => {
                        let next = counter.saturating_sub(1);
                        let zombie = &mut self.state.board.zombies[zombie_index];
                        zombie.dancer_counter = next;
                        if next == 0 {
                            zombie.dancer_phase = DANCER_DANCE_PHASE;
                            zombie.speed = 450_000;
                        }
                    }
                    DANCER_DANCE_PHASE => {
                        if counter > 0 {
                            let next = counter - 1;
                            self.state.board.zombies[zombie_index].dancer_counter = next;
                            if next == 0 {
                                self.summon_missing_dancers(zombie_index, events);
                            }
                        } else {
                            if self.dancer_needs_follower(zombie_index) {
                                self.state.board.zombies[zombie_index].dancer_counter =
                                    DANCER_RESUMMON_TICKS;
                            }
                        }
                    }
                    _ => {
                        let zombie = &mut self.state.board.zombies[zombie_index];
                        zombie.dancer_phase = DANCER_ENTRANCE_PHASE;
                        zombie.dancer_counter = DANCER_ENTRANCE_TICKS;
                    }
                }
            }
            ZombieType::BackupDancer if phase == DANCER_RISE_PHASE && !frozen && !eating => {
                let next = counter.saturating_sub(1);
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.dancer_counter = next;
                if next == 0 {
                    zombie.dancer_phase = DANCER_DANCE_PHASE;
                }
            }
            _ => {}
        }
    }

    fn update_zombies(&mut self, events: &mut Vec<GameEvent>) {
        let zombiquarium = self.state.challenge.kind == ChallengeKind::Zombiquarium;
        if zombiquarium {
            self.update_zombiquarium_brains();
        }
        let zombie_count = self.state.board.zombies.len() as u32;
        let sukhbir_mode = self.state.sukhbir_mode;
        for zombie_index in 0..self.state.board.zombies.len() {
            if self.state.board.zombies[zombie_index].departed {
                continue;
            }
            if self.state.board.zombies[zombie_index].health <= 0 {
                // Zombie_UpdateJack only detonates when the pop phase finishes;
                // a Jack killed by damage never explodes.
                continue;
            }
            if zombiquarium {
                self.update_zombiquarium_zombie(zombie_index, events);
                continue;
            }
            self.update_balloon_state(zombie_index);
            let bobsled_finished = {
                let zombie = &mut self.state.board.zombies[zombie_index];
                if zombie.zombie_type == ZombieType::Bobsled && zombie.bobsled_sliding {
                    zombie.bobsled_counter = zombie.bobsled_counter.saturating_sub(1);
                    if zombie.bobsled_counter == 0 {
                        zombie.bobsled_sliding = false;
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            };
            if bobsled_finished {
                self.state.board.zombies[zombie_index].speed =
                    self.rng.fixed_range(230_000, 320_000);
            }
            {
                let (sliding, sled_row, is_leader, leader_x) = {
                    let zombie = &self.state.board.zombies[zombie_index];
                    (
                        zombie.zombie_type == ZombieType::Bobsled && zombie.bobsled_sliding,
                        zombie.row,
                        zombie.bobsled_leader,
                        zombie.position_x,
                    )
                };
                if sliding {
                    let row_index = usize::from(sled_row);
                    if row_index < self.state.board.ice_timer.len() {
                        let timer = self.state.board.ice_timer[row_index];
                        self.state.board.ice_timer[row_index] =
                            timer.max(BOBSLED_ICE_KEEPALIVE_TICKS);
                    }
                    let ice_min = self
                        .state
                        .board
                        .ice_min_x
                        .get(row_index)
                        .copied()
                        .unwrap_or(ICE_START_X);
                    if is_leader && leader_x + 10 * POSITION_SCALE < ice_min {
                        self.damage_zombie(zombie_index, BOBSLED_ICE_END_DAMAGE, events);
                        if self.state.board.zombies[zombie_index].shield_health == 0 {
                            let team: Vec<usize> = self
                                .state
                                .board
                                .zombies
                                .iter()
                                .enumerate()
                                .filter(|(_, z)| {
                                    z.zombie_type == ZombieType::Bobsled
                                        && z.bobsled_sliding
                                        && z.row == sled_row
                                })
                                .map(|(index, _)| index)
                                .collect();
                            for teammate in team {
                                let speed = self.rng.fixed_range(230_000, 320_000);
                                let zombie = &mut self.state.board.zombies[teammate];
                                zombie.bobsled_sliding = false;
                                zombie.bobsled_counter = 0;
                                zombie.speed = speed;
                            }
                        }
                    }
                }
            }
            if self.state.board.zombies[zombie_index].blowing_away {
                let entity = self.state.board.zombies[zombie_index].id;
                self.state.board.zombies[zombie_index].position_x += BLOWN_AWAY_SPEED;
                if self.state.board.zombies[zombie_index].position_x > BLOWN_AWAY_EDGE {
                    self.emit_zombie_died_with_loot(entity, events);
                    self.state.board.zombies[zombie_index].departed = true;
                }
                continue;
            }
            {
                let zombie = &mut self.state.board.zombies[zombie_index];
                if zombie.imp_flight_ticks > 0 {
                    zombie.imp_flight_ticks -= 1;
                    zombie.position_x -= IMP_THROW_SPEED_X;
                    continue;
                }
                if zombie.bungee_held {
                    continue;
                }
                // PARTICLE_ICE_TRAP_RELEASE fires the tick the freeze expires.
                if zombie.frozen_counter == 1 {
                    events.push(GameEvent::ZombieThawed { entity: zombie.id });
                }
                // DropHelm / DropShield anchors: armor loss is observed at the
                // tick boundary so every damage source routes through one site.
                if zombie.armor_intact {
                    let helm = matches!(
                        zombie.zombie_type,
                        ZombieType::Buckethead | ZombieType::Football | ZombieType::Conehead
                    );
                    let lost = if helm {
                        zombie.health <= 270
                    } else {
                        zombie.shield_health == 0
                    };
                    if lost {
                        zombie.armor_intact = false;
                        let entity = zombie.id;
                        if helm {
                            events.push(GameEvent::ZombieArmorLost { entity });
                        } else {
                            events.push(GameEvent::ZombieShieldLost { entity });
                        }
                    }
                }
            }
            {
                let (delivering, phase, counter, held, entity, altitude) = {
                    let zombie = &self.state.board.zombies[zombie_index];
                    (
                        zombie.zombie_type == ZombieType::Bungee && zombie.special_phase > 0,
                        zombie.special_phase,
                        zombie.special_counter,
                        zombie.special_target,
                        zombie.id,
                        zombie.bungee_altitude,
                    )
                };
                if delivering {
                    let counter = counter.saturating_sub(1);
                    self.state.board.zombies[zombie_index].special_counter = counter;
                    let grassstep_entity = if phase == 1 {
                        let zombie = &mut self.state.board.zombies[zombie_index];
                        zombie.bungee_altitude =
                            zombie.bungee_altitude.saturating_sub(BUNGEE_DROP_SPEED);
                        if held.is_none()
                            && altitude > BUNGEE_LANDING_GRASS_ALTITUDE
                            && zombie.bungee_altitude <= BUNGEE_LANDING_GRASS_ALTITUDE
                        {
                            Some(entity)
                        } else {
                            None
                        }
                    } else {
                        None
                    };
                    let scream_entity = if phase == 1 {
                        let zombie = &mut self.state.board.zombies[zombie_index];
                        if zombie.bungee_altitude > 0
                            && !zombie.bungee_scream_played
                            && zombie.bungee_altitude < BUNGEE_SCREAM_ALTITUDE
                            && self.state.challenge.kind != ChallengeKind::FinalBoss
                        {
                            zombie.bungee_scream_played = true;
                            Some(zombie.id)
                        } else {
                            None
                        }
                    } else {
                        None
                    };
                    if let Some(entity) = grassstep_entity {
                        events.push(GameEvent::BungeeGrassStep { entity });
                    }
                    if let Some(entity) = scream_entity {
                        events.push(GameEvent::BungeeScream {
                            entity,
                            variant: self.rng.range(3) as u8,
                        });
                    }
                    if counter == 0 {
                        if phase == 1 {
                            if let Some(zombie) = held.and_then(|held_id| {
                                self.state
                                    .board
                                    .zombies
                                    .iter_mut()
                                    .find(|z| z.id == held_id)
                            }) {
                                zombie.bungee_held = false;
                            }
                            let zombie = &mut self.state.board.zombies[zombie_index];
                            if held.is_some() {
                                zombie.special_phase = 2;
                                zombie.special_counter = BUNGEE_RISE_DEPART_TICKS;
                                zombie.special_target = None;
                            } else {
                                zombie.special_phase = 0;
                                zombie.special_counter = 0;
                                zombie.bungee_altitude = 0;
                                zombie.bungee_counter = BUNGEE_STEAL_TICKS;
                            }
                        } else {
                            let lifted_plant = self.state.board.zombies[zombie_index]
                                .bungee_target_plant
                                .take();
                            if let Some(plant_id) = lifted_plant
                                && let Some(plant_index) = self
                                    .state
                                    .board
                                    .plants
                                    .iter()
                                    .position(|plant| plant.id == plant_id)
                            {
                                self.state.board.plants.remove(plant_index);
                                events.push(GameEvent::PlantDied { entity: plant_id });
                            }
                            let entity = self.state.board.zombies[zombie_index].id;
                            self.emit_zombie_died(entity, events);
                            self.state.board.zombies[zombie_index].departed = true;
                        }
                    }
                    continue;
                }
            }
            let gargantuar_throwing = self.update_gargantuar_throw(zombie_index, events);
            let pole_vaulting = self.update_pole_vault(zombie_index, events);
            let mut entered_pool = None;
            {
                let scene = self.state.scene;
                let zombie = &mut self.state.board.zombies[zombie_index];
                if scene == SceneKind::Pool
                    && matches!(zombie.row, 2 | 3)
                    && zombie.position_x < 680 * POSITION_SCALE
                    && !zombie.in_pool
                    && zombie.zombie_type != ZombieType::Snorkel
                    && zombie.zombie_type != ZombieType::DolphinRider
                    && (zombie_type_can_go_in_pool(zombie.zombie_type)
                        || zombie.zombie_type == ZombieType::DuckyTube)
                {
                    zombie.in_pool = true;
                    entered_pool = Some(zombie.id);
                }
            }
            if let Some(entity) = entered_pool {
                events.push(GameEvent::ZombieEnteredPool {
                    entity,
                    variant: self.rng.range(2) as u8,
                });
            }
            // Source UpdatePlaying decrements the ice/butter counter before
            // dispatching phase actions, so a still-immobilized Dolphin or
            // Snorkel must not advance entry, splash, eating, descent, or exit
            // progress. The pre-decrement value decides: counters 0..=1 are
            // running or on the exact thaw tick, counters above 1 are paused.
            let immobilized = self.state.board.zombies[zombie_index].frozen_counter > 1;
            let dolphin_suppress_attack = if immobilized {
                false
            } else {
                self.update_dolphin_state(zombie_index, events)
            };
            if !immobilized {
                self.update_snorkel_state(zombie_index, events);
            }
            self.update_zamboni_state(zombie_index);
            let garlic_active = self.advance_garlic_state(zombie_index, events);
            if self.update_special_zombie_state(zombie_index, events) {
                continue;
            }
            {
                let zombie = &mut self.state.board.zombies[zombie_index];
                if zombie.zombie_type == ZombieType::Yeti && !zombie.yeti_running {
                    // Phase countdown precedes thaw; UpdateYeti checks after thaw.
                    if zombie.frozen_counter == 0 {
                        zombie.yeti_counter = zombie.yeti_counter.saturating_sub(1);
                    }
                    if zombie.yeti_counter == 0 && !zombie.hypnotized && zombie.frozen_counter <= 1
                    {
                        zombie.yeti_running = true;
                    }
                }
            }
            self.update_dancer_state(zombie_index, events);
            let dancer_group_blocked = self.dancer_group_blocked(zombie_index);
            {
                let mode = self.state.mode;
                let zombie = &mut self.state.board.zombies[zombie_index];
                if zombie.zombie_type == ZombieType::Digger {
                    if zombie.digger_underground && zombie.position_x <= 10 * POSITION_SCALE {
                        zombie.digger_underground = false;
                        zombie.digger_counter = DIGGER_RISE_TICKS;
                        // PARTICLE_DIGGER_RISE anchor.
                        events.push(GameEvent::DiggerSurfaced { entity: zombie.id });
                        // Zombie_ResetSpeed: the surfaced walk is 0.12, or
                        // 0.23 on I, Zombie levels.
                        zombie.speed = if mode == ModeKind::IZombie {
                            DIGGER_IZOMBIE_WALK_SPEED
                        } else {
                            DIGGER_WALK_SPEED
                        };
                    } else if zombie.digger_counter > 0 {
                        zombie.digger_counter = zombie.digger_counter.saturating_sub(1);
                    }
                }
            }
            let bungee_steals = {
                let zombie = &mut self.state.board.zombies[zombie_index];
                if zombie.zombie_type == ZombieType::Bungee && !zombie.bungee_stolen {
                    zombie.bungee_counter = zombie.bungee_counter.saturating_sub(1);
                    if zombie.bungee_counter == 0 {
                        zombie.bungee_stolen = true;
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            };
            if bungee_steals {
                let zombie_id = self.state.board.zombies[zombie_index].id;
                let target = {
                    let zombie = &self.state.board.zombies[zombie_index];
                    zombie.bungee_target_row.zip(zombie.bungee_target_column)
                };
                let mut deflected = false;
                let mut lifted_plant = None;
                if let Some((target_row, target_column)) = target
                    && let Some(plant_index) = self.find_bungee_top_plant(target_row, target_column)
                {
                    let umbrella = self
                        .find_umbrella_plant(target_row, target_column)
                        .map(|index| self.state.board.plants[index].id);
                    if let Some(umbrella_id) = umbrella {
                        events.push(GameEvent::UmbrellaDeflected {
                            plant: umbrella_id,
                            zombie: zombie_id,
                        });
                        deflected = true;
                    } else {
                        lifted_plant = Some(self.state.board.plants[plant_index].id);
                    }
                }
                if target.is_some() && !deflected {
                    if let Some(plant_id) = lifted_plant {
                        self.state
                            .board
                            .plants
                            .iter_mut()
                            .find(|plant| plant.id == plant_id)
                            .expect("Bungee lift target remains on the board until rise completion")
                            .bungee_lifted = true;
                        self.state.board.zombies[zombie_index].bungee_target_plant = Some(plant_id);
                        events.push(GameEvent::BungeePlantLifted {
                            zombie: zombie_id,
                            plant: plant_id,
                        });
                    }
                    let zombie = &mut self.state.board.zombies[zombie_index];
                    zombie.special_phase = 2;
                    zombie.special_counter = BUNGEE_RISE_DEPART_TICKS;
                    continue;
                }
                self.state.board.zombies[zombie_index].health = 0;
                self.emit_zombie_died(zombie_id, events);
                continue;
            }
            self.update_pogo_state(zombie_index, events);
            // Zombie_UpdateJack plays the surprise Foley at remaining counter 80,
            // then detonates at zero. Frozen Jacks keep both boundaries paused.
            let (jackbox_boing, jackbox_surprise, jackbox_explosion, jackbox_entity) = {
                let zombie = &mut self.state.board.zombies[zombie_index];
                if zombie.zombie_type == ZombieType::Jackbox
                    && zombie.jackbox_timer > 0
                    && zombie.frozen_counter == 0
                {
                    zombie.jackbox_timer = zombie.jackbox_timer.saturating_sub(1);
                    (
                        zombie.jackbox_timer == JACKBOX_POP_TICKS,
                        zombie.jackbox_timer == JACKBOX_SURPRISE_REMAINING_TICKS,
                        zombie.jackbox_timer == 0,
                        zombie.id,
                    )
                } else {
                    (false, false, false, zombie.id)
                }
            };
            if jackbox_boing {
                events.push(GameEvent::JackboxBoing {
                    entity: jackbox_entity,
                });
            }
            if jackbox_surprise {
                events.push(GameEvent::JackboxSurprise {
                    entity: jackbox_entity,
                    variant: self.rng.range(3) as u8,
                });
            }
            if jackbox_explosion {
                self.state.board.zombies[zombie_index].health = 0;
                self.apply_jackbox_explosion(zombie_index, events);
            }
            let (
                entity,
                row,
                position_x,
                age,
                was_eating,
                frozen,
                dancer_dancing,
                digger_hidden,
                balloon_airborne,
                bobsled_sliding,
                newspaper_mad_transition,
                newspaper_mad_has_head,
            ) = {
                let zombie = &mut self.state.board.zombies[zombie_index];
                zombie.age = zombie.age.saturating_add(1);
                zombie.groan_counter -= 1;
                zombie.frozen_counter = zombie.frozen_counter.saturating_sub(1);
                zombie.chilled_counter = zombie.chilled_counter.saturating_sub(1);
                // Source UpdateZombieRiseFromGrave advances only when the
                // ice/butter counter has cleared; a frozen riser pauses.
                if zombie.rise_counter > 0 && zombie.frozen_counter == 0 {
                    zombie.rise_counter -= 1;
                }
                if zombie.zombie_type == ZombieType::PeaHead {
                    zombie.pea_head_counter = zombie.pea_head_counter.saturating_sub(1);
                }
                if zombie.groan_counter == 0 && self.rng.range(zombie_count) == 0 {
                    let (family, variants) = if is_gargantuar(zombie.zombie_type) {
                        (ZombieGroanFamily::Low, 2)
                    } else if zombie.variant != 0 {
                        (ZombieGroanFamily::Brains, 9)
                    } else if sukhbir_mode {
                        (ZombieGroanFamily::Sukhbir, 9)
                    } else {
                        (ZombieGroanFamily::Normal, 6)
                    };
                    events.push(GameEvent::ZombieGroaned {
                        entity: zombie.id,
                        zombie_type: zombie.zombie_type,
                        family,
                        variant: self.rng.range(variants) as u8,
                    });
                    zombie.groan_counter = (self.rng.range(1_000) + 500) as i32;
                }
                let frozen = zombie.frozen_counter != 0;
                let newspaper_mad_transition = zombie.zombie_type == ZombieType::Newspaper
                    && zombie.newspaper_mad_pending
                    && zombie.frozen_counter == 0
                    && zombie.health > 0;
                if newspaper_mad_transition {
                    zombie.newspaper_mad_pending = false;
                }
                if !(frozen
                    || zombie.eating
                    || gargantuar_throwing
                    || pole_vaulting
                    || garlic_active
                    || (zombie.zombie_type == ZombieType::Catapult && zombie.catapult_armed)
                    || (zombie.zombie_type == ZombieType::Pogo && zombie.pogo_counter > 0)
                    || dancer_group_blocked
                    || ((zombie.zombie_type == ZombieType::Dancer
                        && !matches!(
                            zombie.dancer_phase,
                            DANCER_ENTRANCE_PHASE | DANCER_DANCE_PHASE
                        ))
                        || (zombie.zombie_type == ZombieType::BackupDancer
                            && zombie.dancer_phase != DANCER_DANCE_PHASE))
                    || (zombie.zombie_type == ZombieType::Digger
                        && (zombie.digger_underground || zombie.digger_counter > 0))
                    || snorkel_blocks_movement(zombie)
                    || zombie.rise_counter > 0
                    || (zombie.zombie_type == ZombieType::Balloon
                        && zombie.balloon_phase == BALLOON_POPPING_PHASE)
                    || zombie.zombie_type == ZombieType::Bungee)
                {
                    let sledding =
                        zombie.zombie_type == ZombieType::Bobsled && zombie.bobsled_sliding;
                    let base_speed = if sledding {
                        BOBSLED_SPEED
                    } else if zombie.yeti_running {
                        YETI_RUNNING_SPEED
                    } else if zombie.zombie_type == ZombieType::Newspaper
                        && zombie.shield_health == 0
                    {
                        // Zombie_ResetSpeed gives PHASE_NEWSPAPER_MAD 0.89-0.91.
                        NEWSPAPER_MAD_SPEED
                    } else {
                        zombie.speed
                    };
                    let speed = if zombie.chilled_counter == 0 || sledding {
                        base_speed
                    } else {
                        base_speed * 2 / 5
                    };
                    if zombie.hypnotized
                        || zombie.yeti_running
                        || (zombie.zombie_type == ZombieType::Dancer
                            && zombie.dancer_phase == DANCER_ENTRANCE_PHASE)
                    {
                        zombie.position_x = zombie.position_x.saturating_add(speed);
                    } else {
                        zombie.position_x = zombie.position_x.saturating_sub(speed);
                    }
                }
                (
                    zombie.id,
                    zombie.row,
                    zombie.position_x,
                    zombie.age,
                    zombie.eating,
                    frozen,
                    (zombie.zombie_type == ZombieType::Dancer
                        || zombie.zombie_type == ZombieType::BackupDancer)
                        && zombie.dancer_phase != DANCER_DANCE_PHASE,
                    zombie.zombie_type == ZombieType::Digger
                        && (zombie.digger_underground || zombie.digger_counter > 0),
                    balloon_is_airborne(zombie),
                    zombie.zombie_type == ZombieType::Bobsled && zombie.bobsled_sliding,
                    newspaper_mad_transition,
                    zombie.has_head,
                )
            };

            if newspaper_mad_transition {
                let zombie_count_on_screen = self
                    .state
                    .board
                    .zombies
                    .iter()
                    .filter(|zombie| {
                        zombie.health > 0
                            && !zombie.departed
                            && zombie.has_head
                            && !zombie.hypnotized
                    })
                    .count();
                if newspaper_mad_has_head && zombie_count_on_screen <= 10 {
                    events.push(GameEvent::ZombieNewspaperRarrgh {
                        entity,
                        variant: self.rng.range(3) as u8,
                    });
                }
            }

            if frozen {
                self.state.board.zombies[zombie_index].eating = false;
            } else if garlic_active {
                self.state.board.zombies[zombie_index].eating = true;
            } else if age % 4 == 0
                && !gargantuar_throwing
                && !pole_vaulting
                && !dancer_dancing
                && !digger_hidden
                && !snorkel_blocks_attack(&self.state.board.zombies[zombie_index])
                && !dolphin_suppress_attack
                && !dolphin_blocks_attack(&self.state.board.zombies[zombie_index])
                && !(self.state.board.zombies[zombie_index].zombie_type == ZombieType::DolphinRider
                    && self.dolphin_is_tangle_target(entity))
                && !balloon_airborne
                && !bobsled_sliding
                && self.state.board.zombies[zombie_index].zombie_type != ZombieType::Bungee
            {
                let is_hypnotized = self.state.board.zombies[zombie_index].hypnotized;
                if is_hypnotized {
                    self.attack_zombie_target(entity, row, events);
                } else {
                    let ztype = self.state.board.zombies[zombie_index].zombie_type;
                    let target = if ztype == ZombieType::DolphinRider
                        && self.state.board.zombies[zombie_index].dolphin_phase
                            == DOLPHIN_RIDING_PHASE
                    {
                        self.find_plant_for_dolphin(row, position_x, false)
                    } else {
                        self.find_plant_for_zombie(row, position_x, ztype)
                    };
                    let pogo_has_stick = ztype == ZombieType::Pogo
                        && self.state.board.zombies[zombie_index].special_phase == 0;
                    self.state.board.zombies[zombie_index].eating =
                        target.is_some() && !pogo_has_stick;
                    if let Some(plant_index) = target {
                        let plant_id = self.state.board.plants[plant_index].id;
                        if ztype == ZombieType::SquashHead
                            && self.state.board.zombies[zombie_index].special_phase == 0
                        {
                            let zombie = &mut self.state.board.zombies[zombie_index];
                            zombie.eating = false;
                            zombie.special_phase = 1;
                            zombie.special_counter = ZOMBOTANY_SQUASH_RISE_TICKS;
                            zombie.special_target = Some(plant_id);
                        } else if ztype == ZombieType::Ladder
                            && is_ladder_target(self.state.board.plants[plant_index].plant_type)
                            && !self.state.board.ladders.iter().any(|ladder| {
                                ladder.row == self.state.board.plants[plant_index].row
                                    && ladder.column == self.state.board.plants[plant_index].column
                            })
                        {
                            let (row, column) = {
                                let plant = &self.state.board.plants[plant_index];
                                (plant.row, plant.column)
                            };
                            self.state.board.ladders.push(LadderState { row, column });
                            events.push(GameEvent::LadderPlaced {
                                zombie: entity,
                                row,
                                column,
                            });
                            // Leaving PHASE_LADDER_CARRYING re-picks the plain
                            // 0.23-0.32 walk (Zombie_ResetSpeed).
                            let walk_speed = self.rng.fixed_range(230_000, 320_000);
                            self.state.board.zombies[zombie_index].ladder_placed = true;
                            self.state.board.zombies[zombie_index].shield_health = 0;
                            self.state.board.zombies[zombie_index].eating = false;
                            self.state.board.zombies[zombie_index].speed = walk_speed;
                        } else if ztype == ZombieType::Pogo
                            && self.state.board.zombies[zombie_index].special_phase == 0
                        {
                            // UpdateZombiePogo starts the next jump only at a bounce boundary.
                            self.state.board.zombies[zombie_index].eating = false;
                        } else if ztype == ZombieType::Zamboni
                            && self.state.board.plants[plant_index]
                                .plant_type
                                .is_spikeweed()
                        {
                            // Let Spikeweed/Spikerock resolve its vehicle hit before
                            // the Zamboni's normal plant-clearing behavior.
                            self.state.board.zombies[zombie_index].eating = false;
                        } else if ztype == ZombieType::Zamboni {
                            self.state.board.plants.remove(plant_index);
                            self.state.board.zombies[zombie_index].eating = false;
                            events.push(GameEvent::PlantDied { entity: plant_id });
                        } else if is_gargantuar(ztype) {
                            let plant_type = self.state.board.plants[plant_index].plant_type;
                            if plant_type.slot() == 46 {
                                self.state.board.plants[plant_index].health -=
                                    GARGANTUAR_SPIKEROCK_DAMAGE;
                                let health_remaining = self.state.board.plants[plant_index].health;
                                events.push(GameEvent::PlantDamaged {
                                    entity: plant_id,
                                    damage: GARGANTUAR_SPIKEROCK_DAMAGE,
                                    health_remaining,
                                });
                                if health_remaining <= 0 {
                                    self.state.board.plants.remove(plant_index);
                                    events.push(GameEvent::PlantDied { entity: plant_id });
                                }
                            } else {
                                self.state.board.plants.remove(plant_index);
                                events.push(GameEvent::PlantDied { entity: plant_id });
                            }
                            self.state.board.zombies[zombie_index].eating = false;
                        } else if self.state.board.plants[plant_index]
                            .plant_type
                            .is_hypno_shroom()
                        {
                            self.state.board.plants.remove(plant_index);
                            self.state.board.zombies[zombie_index].hypnotized = true;
                            self.state.board.zombies[zombie_index].eating = false;
                            events.push(GameEvent::ZombieHypnotized { entity });
                            events.push(GameEvent::PlantDied { entity: plant_id });
                        } else if self.state.board.plants[plant_index].plant_type.is_garlic() {
                            self.state.board.zombies[zombie_index].eating = true;
                            self.state.board.zombies[zombie_index].garlic_counter = 1;
                            self.state.board.zombies[zombie_index].garlic_target = Some(plant_id);
                        } else {
                            let plant_type = self.state.board.plants[plant_index].plant_type;
                            let soft = matches!(plant_type.slot(), 3 | 23 | 30);
                            events.push(GameEvent::ZombieChew {
                                entity,
                                target: Some(plant_id),
                                soft,
                                variant: self.state.board.zombies[zombie_index].variant,
                            });
                            self.state.board.plants[plant_index].health -= ZOMBIE_BITE_DAMAGE;
                            self.state.board.plants[plant_index].recently_eaten_counter =
                                RECENTLY_EATEN_TICKS;
                            let health_remaining = self.state.board.plants[plant_index].health;
                            events.push(GameEvent::PlantDamaged {
                                entity: plant_id,
                                damage: ZOMBIE_BITE_DAMAGE,
                                health_remaining,
                            });
                            if health_remaining <= 0 {
                                if plant_type.is_explode_o_nut() {
                                    let column = self.state.board.plants[plant_index].column;
                                    let center_x = grid_x(column);
                                    let explode_targets = self
                                        .state
                                        .board
                                        .zombies
                                        .iter()
                                        .filter(|z| {
                                            plant_damage_can_hit_zombie(z)
                                                && z.row.abs_diff(row) <= 1
                                                && (z.position_x - center_x).abs()
                                                    <= 115 * POSITION_SCALE
                                        })
                                        .map(|z| z.id)
                                        .collect::<Vec<_>>();
                                    if !explode_targets.is_empty() {
                                        events.push(GameEvent::PlantSpecialTriggered {
                                            entity: plant_id,
                                            plant_type,
                                        });
                                    }
                                    for zombie_id in &explode_targets {
                                        // Apply damage without removing — the outer
                                        // zombie loop uses a fixed range, and
                                        // update_mowers retains dead zombies.
                                        let Some(target_idx) = self
                                            .state
                                            .board
                                            .zombies
                                            .iter()
                                            .position(|z| z.id == *zombie_id)
                                        else {
                                            continue;
                                        };
                                        self.damage_zombie(
                                            target_idx,
                                            PLANT_SPECIAL_DAMAGE,
                                            events,
                                        );
                                        let health_remaining =
                                            self.state.board.zombies[target_idx].health;
                                        events.push(GameEvent::PlantSpecialHit {
                                            plant: plant_id,
                                            zombie: *zombie_id,
                                            damage: PLANT_SPECIAL_DAMAGE,
                                            health_remaining,
                                        });
                                        if health_remaining <= 0 {
                                            self.state.board.zombies[target_idx].health = 0;
                                            self.emit_zombie_died_with_loot(*zombie_id, events);
                                        }
                                    }
                                }
                                self.state.board.plants.remove(plant_index);
                                // Find the eating zombie by ID — the explosion may have
                                // shifted indices or removed it entirely.
                                if let Some(pos) =
                                    self.state.board.zombies.iter().position(|z| z.id == entity)
                                {
                                    self.state.board.zombies[pos].eating = false;
                                }
                                events.push(GameEvent::PlantDied { entity: plant_id });
                            }
                        }
                    } else if was_eating {
                        self.state.board.zombies[zombie_index].eating = false;
                    }
                }
            }

            if self.state.board.zombies[zombie_index].zombie_type == ZombieType::PeaHead
                && self.state.board.zombies[zombie_index].pea_head_counter == 0
            {
                self.state.board.zombies[zombie_index].pea_head_counter =
                    ZOMBIE_PEA_HEAD_RELOAD_TICKS;
                self.fire_projectile(
                    entity,
                    ProjectileType::ZombiePea,
                    row,
                    ProjectileTrajectory {
                        motion: ProjectileMotion::Backwards,
                        position_x: position_x + 20 * POSITION_SCALE,
                        position_y: grid_y(row),
                        velocity_x: -3_330_000,
                        velocity_y: 0,
                    },
                    events,
                );
            }
            if self.state.board.zombies[zombie_index].zombie_type == ZombieType::Catapult {
                let target = self.find_catapult_target(row, position_x);
                let zombie = &self.state.board.zombies[zombie_index];
                if zombie.catapult_shots == 0 {
                    self.state.board.zombies[zombie_index].catapult_armed = false;
                } else {
                    if !zombie.catapult_armed
                        && position_x <= 650 * POSITION_SCALE
                        && target.is_some()
                    {
                        let zombie = &mut self.state.board.zombies[zombie_index];
                        zombie.catapult_armed = true;
                        zombie.catapult_counter = CATAPULT_LAUNCH_TICKS;
                        zombie.eating = false;
                    } else if zombie.catapult_armed && zombie.catapult_counter > 0 {
                        let counter = zombie.catapult_counter.saturating_sub(1);
                        self.state.board.zombies[zombie_index].catapult_counter = counter;
                        if counter == 0 {
                            if let Some(plant_index) = target {
                                let target_column = self.state.board.plants[plant_index].column;
                                let target_x = grid_x(target_column);
                                let target_y = scene_plant_y(self.state.scene, row, target_column);
                                self.fire_catapult_projectile(
                                    entity, row, position_x, target_x, target_y, events,
                                );
                                let zombie = &mut self.state.board.zombies[zombie_index];
                                zombie.catapult_shots -= 1;
                                zombie.catapult_counter = CATAPULT_RELOAD_TICKS;
                                zombie.catapult_armed = zombie.catapult_shots > 0;
                            } else {
                                self.state.board.zombies[zombie_index].catapult_armed = false;
                            }
                        }
                    }
                }
            }

            // GridItem portals: a zombie reaching a portal cell teleports to
            // the next portal in the pair cycle.
            {
                let last_portal_column = self.state.board.zombies[zombie_index].last_portal_column;
                if self.state.board.portals.len() >= 2
                    && let Some(index) =
                        self.portal_at(row, position_x, 10 * POSITION_SCALE, last_portal_column)
                {
                    let target = self.portal_target(index);
                    if let Some((target_row, target_column)) = target {
                        let zombie = &mut self.state.board.zombies[zombie_index];
                        zombie.row = target_row;
                        zombie.position_x = grid_x(target_column);
                        zombie.last_portal_column = u32::from(target_column) + 1;
                        events.push(GameEvent::ZombieTeleported {
                            entity,
                            row: target_row,
                            column: target_column,
                        });
                        continue;
                    }
                }
            }
            // GridItem rake: the first zombie that steps on it dies and
            // consumes it.
            if let Some((rake_row, rake_column)) = self.state.board.rake
                && rake_row == row
                && position_x <= grid_x(rake_column) + 30 * POSITION_SCALE
                && self.state.board.zombies[zombie_index].health > 0
            {
                self.state.board.rake = None;
                events.push(GameEvent::RakeTriggered { zombie: entity });
                self.emit_zombie_died_with_loot(entity, events);
                self.state.board.zombies[zombie_index].departed = true;
                continue;
            }
            let mower_covering_row = self
                .state
                .board
                .mowers
                .iter()
                .any(|mower| mower.row == row && mower.active);
            let mower_triggered = position_x <= MOWER_TRIGGER_X
                && (self.trigger_mower(row, events) || mower_covering_row);
            let fled = self
                .state
                .board
                .zombies
                .get(zombie_index)
                .is_some_and(|zombie| zombie.yeti_running && zombie.position_x > YETI_FLEE_EDGE);
            if fled {
                let entity = self.state.board.zombies[zombie_index].id;
                self.state.board.zombies[zombie_index].departed = true;
                events.push(GameEvent::ZombieFled { entity });
                continue;
            }
            if !mower_triggered
                && self.state.board.zombies[zombie_index].health > 0
                && position_x <= -100 * POSITION_SCALE
            {
                if self.state.mode == ModeKind::IZombie {
                    if self.eat_brain(zombie_index, row, events) {
                        continue;
                    }
                    self.state.board.zombies[zombie_index].health = 0;
                    continue;
                }
                self.state.scene = SceneKind::GameOver;
                self.state.game_lost_cutscene_time = Some(0);
                events.push(GameEvent::GameLost { zombie: entity });
                break;
            }
        }
        self.state.board.zombies.retain(|zombie| !zombie.departed);
    }

    fn apply_cob_explosion(
        &mut self,
        projectile: &ProjectileState,
        target_row: u8,
        target_x: i64,
        events: &mut Vec<GameEvent>,
    ) {
        self.push_projectile_impact(
            projectile.id,
            projectile.projectile_type,
            None,
            ProjectileImpactSound::Splat,
            3,
            events,
        );
        let mut targets = self
            .state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                // Cob blasts carry every positional damage flag.
                plant_damage_can_hit_zombie(zombie)
                    && zombie.row.abs_diff(target_row) <= 1
                    && (zombie.position_x - target_x).abs() <= 115 * POSITION_SCALE
            })
            .map(|zombie| (zombie.id, (zombie.position_x - target_x).abs()))
            .collect::<Vec<_>>();
        targets.sort_by_key(|(_, distance)| *distance);
        for (target_index, (zombie_id, _)) in targets.into_iter().enumerate() {
            let Some(zombie_index) = self
                .state
                .board
                .zombies
                .iter()
                .position(|zombie| zombie.id == zombie_id)
            else {
                continue;
            };
            self.damage_zombie_from_projectile(zombie_index, projectile, projectile.damage, events);
            let health_remaining = self.state.board.zombies[zombie_index].health;
            if target_index == 0 {
                events.push(GameEvent::ProjectileHit {
                    projectile: projectile.id,
                    zombie: zombie_id,
                    damage: projectile.damage,
                    health_remaining,
                });
            } else {
                events.push(GameEvent::ProjectileSplashHit {
                    projectile: projectile.id,
                    zombie: zombie_id,
                    damage: projectile.damage,
                    health_remaining,
                });
            }
            if health_remaining <= 0 {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
            }
        }
    }

    fn resolve_projectile_plant_hit(
        &mut self,
        plant_index: usize,
        projectile: &ProjectileState,
        events: &mut Vec<GameEvent>,
    ) -> bool {
        let target = &self.state.board.plants[plant_index];
        if let Some(umbrella_index) = self.find_umbrella_plant(target.row, target.column) {
            let umbrella = &mut self.state.board.plants[umbrella_index];
            if umbrella.special_armed && umbrella.special_counter <= UMBRELLA_REFLECT_TICKS {
                self.push_projectile_impact(
                    projectile.id,
                    projectile.projectile_type,
                    None,
                    ProjectileImpactSound::Splat,
                    3,
                    events,
                );
                return true;
            }
            if !umbrella.special_armed {
                umbrella.special_armed = true;
                umbrella.special_counter = UMBRELLA_BLOCK_TICKS;
                events.push(GameEvent::UmbrellaTriggered {
                    plant: umbrella.id,
                    projectile: projectile.id,
                });
            }
            return false;
        }

        let plant_id = self.state.board.plants[plant_index].id;
        self.state.board.plants[plant_index].health -= projectile.damage;
        let health_remaining = self.state.board.plants[plant_index].health;
        events.push(GameEvent::PlantDamaged {
            entity: plant_id,
            damage: projectile.damage,
            health_remaining,
        });
        if projectile.projectile_type == ProjectileType::ZombiePea {
            self.push_projectile_impact(
                projectile.id,
                projectile.projectile_type,
                None,
                ProjectileImpactSound::Splat,
                3,
                events,
            );
        }
        if health_remaining <= 0 {
            self.state.board.plants.remove(plant_index);
            events.push(GameEvent::PlantDied { entity: plant_id });
        }
        true
    }

    fn update_projectiles(&mut self, events: &mut Vec<GameEvent>) {
        let mut projectile_index = 0;
        while projectile_index < self.state.board.projectiles.len() {
            if self.state.board.projectiles[projectile_index].motion == ProjectileMotion::Homing {
                self.steer_homing_projectile(projectile_index);
            }
            {
                let projectile = &mut self.state.board.projectiles[projectile_index];
                projectile.age = projectile.age.saturating_add(1);
                let previous_x = projectile.position_x;
                projectile.position_x += projectile.velocity_x;
                projectile.position_y += projectile.velocity_y;
                let slope_delta =
                    scene_row_y(self.state.scene, projectile.row, projectile.position_x)
                        - scene_row_y(self.state.scene, projectile.row, previous_x);
                if projectile.projectile_type.is_catapult() {
                    projectile.position_y += slope_delta;
                    projectile.lob_height -= (slope_delta * PULT_LOB_SCALE / POSITION_SCALE) as i32;
                }
                if projectile.motion == ProjectileMotion::Threepeater {
                    projectile.velocity_y = projectile.velocity_y * 97 / 100;
                }
                projectile.shadow_y += slope_delta;
                if matches!(
                    projectile.motion,
                    ProjectileMotion::Threepeater
                        | ProjectileMotion::Star
                        | ProjectileMotion::Homing
                ) {
                    projectile.shadow_y += projectile.velocity_y;
                }
                if projectile.motion == ProjectileMotion::Star && projectile.velocity_y != 0 {
                    projectile.row = projectile_row_for_scene(
                        self.state.scene,
                        projectile.position_x,
                        projectile.position_y,
                        self.state.board.rows,
                    );
                }
                if projectile.motion == ProjectileMotion::Lobbed
                    && projectile.projectile_type.uses_lob_trajectory()
                {
                    projectile.lob_velocity += PULT_LOB_GRAVITY;
                    projectile.lob_height += projectile.lob_velocity;
                }
            }
            if self.state.board.projectiles[projectile_index].projectile_type == ProjectileType::Cob
            {
                {
                    let projectile = &mut self.state.board.projectiles[projectile_index];
                    if projectile.lob_height < -700 {
                        projectile.lob_velocity = 8;
                        projectile.row = projectile.target_row.unwrap_or(projectile.row);
                        projectile.position_x =
                            projectile.target_x.unwrap_or(projectile.position_x);
                        projectile.position_y = grid_y(projectile.row);
                    }
                    projectile.lob_height += projectile.lob_velocity;
                }
                let projectile = self.state.board.projectiles[projectile_index].clone();
                if projectile.lob_velocity > 0 && projectile.lob_height > -40 {
                    self.apply_cob_explosion(
                        &projectile,
                        projectile.target_row.unwrap_or(projectile.row),
                        projectile.target_x.unwrap_or(projectile.position_x),
                        events,
                    );
                    self.state.board.projectiles.remove(projectile_index);
                } else {
                    projectile_index += 1;
                }
                continue;
            }
            if self.state.board.projectiles[projectile_index].motion == ProjectileMotion::Lobbed
                && self.state.board.projectiles[projectile_index]
                    .projectile_type
                    .is_pult()
            {
                let projectile = self.state.board.projectiles[projectile_index].clone();
                if projectile.position_x > i64::from(LOGICAL_WIDTH) * POSITION_SCALE
                    || projectile.position_x < -100 * POSITION_SCALE
                {
                    self.state.board.projectiles.remove(projectile_index);
                    continue;
                }
                let minimum_height = i64::from(
                    projectile
                        .projectile_type
                        .lob_min_collision_height()
                        .expect("lob minimum collision height"),
                ) * PULT_LOB_SCALE
                    + if scene_row_is_water(self.state.scene, projectile.row) {
                        40 * PULT_LOB_SCALE
                    } else {
                        0
                    };
                if projectile.age > PULT_LOB_COLLISION_AGE
                    && (projectile.lob_velocity < 0
                        || i64::from(projectile.lob_height) <= minimum_height)
                {
                    projectile_index += 1;
                    continue;
                }
            }
            if self.state.board.projectiles[projectile_index]
                .projectile_type
                .is_catapult()
            {
                let projectile = self.state.board.projectiles[projectile_index].clone();
                if projectile.position_x > i64::from(LOGICAL_WIDTH) * POSITION_SCALE
                    || projectile.position_x < -100 * POSITION_SCALE
                {
                    self.state.board.projectiles.remove(projectile_index);
                    continue;
                }
                let minimum_height = i64::from(
                    projectile
                        .projectile_type
                        .lob_min_collision_height()
                        .expect("catapult minimum collision height"),
                ) * PULT_LOB_SCALE
                    + if scene_row_is_water(self.state.scene, projectile.row) {
                        40 * PULT_LOB_SCALE
                    } else {
                        0
                    };
                if projectile.lob_velocity < 0
                    || (projectile.age > PULT_LOB_COLLISION_AGE
                        && i64::from(projectile.lob_height) <= minimum_height)
                {
                    projectile_index += 1;
                    continue;
                }
                if let Some(plant_index) = self.find_catapult_collision_target(&projectile) {
                    if self.resolve_projectile_plant_hit(plant_index, &projectile, events) {
                        self.state.board.projectiles.remove(projectile_index);
                    } else {
                        projectile_index += 1;
                    }
                } else if i64::from(projectile.lob_height)
                    > i64::from(CATAPULT_GROUND_HEIGHT) * PULT_LOB_SCALE
                {
                    self.state.board.projectiles.remove(projectile_index);
                } else {
                    projectile_index += 1;
                }
                continue;
            }
            if self.state.board.projectiles[projectile_index].motion == ProjectileMotion::Star {
                let projectile = self.state.board.projectiles[projectile_index].clone();
                if projectile.position_y > i64::from(LOGICAL_HEIGHT) * POSITION_SCALE
                    || projectile.position_y < 0
                {
                    self.state.board.projectiles.remove(projectile_index);
                    continue;
                }
                let shadow_delta = projectile.shadow_y - projectile.position_y;
                if shadow_delta > STAR_SHADOW_COLLISION_DELAY {
                    projectile_index += 1;
                    continue;
                }
                if shadow_delta < STAR_HIGH_GROUND_SHADOW_THRESHOLD {
                    self.state.board.projectiles.remove(projectile_index);
                    continue;
                }
            }
            if self.state.board.projectiles[projectile_index].motion == ProjectileMotion::Puff
                && self.state.board.projectiles[projectile_index].age >= PUFF_PROJECTILE_MAX_AGE
            {
                self.state.board.projectiles.remove(projectile_index);
                continue;
            }
            if matches!(
                self.state.board.projectiles[projectile_index].motion,
                ProjectileMotion::Fume | ProjectileMotion::Gloom
            ) {
                let projectile = self.state.board.projectiles[projectile_index].clone();
                if projectile.motion == ProjectileMotion::Fume {
                    self.apply_fume_damage(&projectile, events);
                } else {
                    self.apply_gloom_damage(&projectile, events);
                }
                self.state.board.projectiles.remove(projectile_index);
                continue;
            }
            if self.state.board.projectiles[projectile_index].projectile_type
                == ProjectileType::ZombiePea
            {
                let projectile = self.state.board.projectiles[projectile_index].clone();
                let projectile_row = projectile_row(projectile.position_y, self.state.board.rows);
                let target = self
                    .state
                    .board
                    .plants
                    .iter()
                    .enumerate()
                    .filter(|(_, plant)| Some(plant.row) == projectile_row && plant.health > 0)
                    .filter(|(_, plant)| {
                        projectile_hits_plant(projectile.position_x, grid_x(plant.column))
                    })
                    .max_by_key(|(_, plant)| grid_x(plant.column))
                    .map(|(index, _)| index);

                if let Some(plant_index) = target {
                    if self.resolve_projectile_plant_hit(plant_index, &projectile, events) {
                        self.state.board.projectiles.remove(projectile_index);
                    } else {
                        projectile_index += 1;
                    }
                } else if projectile.position_x > i64::from(LOGICAL_WIDTH) * POSITION_SCALE
                    || projectile.position_x < -100 * POSITION_SCALE
                    || projectile_row.is_none()
                {
                    self.state.board.projectiles.remove(projectile_index);
                } else {
                    projectile_index += 1;
                }
                continue;
            }
            if self.state.board.projectiles[projectile_index].projectile_type
                == ProjectileType::Other(1)
            {
                let projectile = self.state.board.projectiles[projectile_index].clone();
                let target_reached = projectile.age >= 120
                    || projectile
                        .target_x
                        .is_some_and(|target_x| projectile.position_x <= target_x);
                if target_reached {
                    let projectile_row =
                        projectile_row(projectile.position_y, self.state.board.rows);
                    let target = self
                        .state
                        .board
                        .plants
                        .iter()
                        .enumerate()
                        .filter(|(_, plant)| Some(plant.row) == projectile_row && plant.health > 0)
                        .filter(|(_, plant)| {
                            projectile
                                .target_x
                                .is_some_and(|target_x| grid_x(plant.column) == target_x)
                        })
                        .map(|(index, _)| index)
                        .next();
                    if let Some(plant_index) = target
                        && !self.resolve_projectile_plant_hit(plant_index, &projectile, events)
                    {
                        projectile_index += 1;
                        continue;
                    }
                    self.state.board.projectiles.remove(projectile_index);
                } else {
                    projectile_index += 1;
                }
                continue;
            }
            self.apply_torchwood(projectile_index, events);
            let projectile = self.state.board.projectiles[projectile_index].clone();
            let projectile_row = if projectile.projectile_type.is_pult()
                || matches!(
                    projectile.motion,
                    ProjectileMotion::Threepeater | ProjectileMotion::Star
                ) {
                Some(projectile.row)
            } else {
                projectile_row(projectile.position_y, self.state.board.rows)
            };
            let scene = self.state.scene;
            let target = if projectile.motion == ProjectileMotion::Homing {
                projectile.target_zombie.and_then(|target_id| {
                    self.state.board.zombies.iter().position(|zombie| {
                        zombie.id == target_id
                            && cattail_can_hit_zombie(zombie)
                            && homing_projectile_hits_target(scene, &projectile, zombie)
                    })
                })
            } else {
                self.state
                    .board
                    .zombies
                    .iter()
                    .enumerate()
                    .filter(|(_, zombie)| {
                        (Some(zombie.row) == projectile_row
                            || zombie.zombie_type == ZombieType::Boss)
                            && zombie.health > 0
                            && projectile_can_hit_zombie(zombie, projectile.projectile_type)
                            && !(projectile.projectile_type.is_pult()
                                && zombie.zombie_type == ZombieType::Snorkel
                                && zombie.snorkel_phase == SNORKEL_WALKING_IN_POOL_PHASE
                                && projectile.lob_height >= PULT_LOB_SNORKEL_CLEARANCE)
                    })
                    .filter(|(_, zombie)| projectile_hits_zombie(scene, &projectile, zombie))
                    .min_by_key(|(_, zombie)| zombie.position_x)
                    .map(|(index, _)| index)
            };

            if let Some(zombie_index) = target {
                let zombie_id = self.state.board.zombies[zombie_index].id;
                let target_zombie = self.state.board.zombies[zombie_index].clone();
                self.emit_projectile_impact(&projectile, Some(&target_zombie), events);
                self.damage_zombie_from_projectile(
                    zombie_index,
                    &projectile,
                    projectile.damage,
                    events,
                );
                let health_remaining = self.state.board.zombies[zombie_index].health;
                events.push(GameEvent::ProjectileHit {
                    projectile: projectile.id,
                    zombie: zombie_id,
                    damage: projectile.damage,
                    health_remaining,
                });
                self.apply_projectile_chill(zombie_id, projectile.projectile_type, events);
                if health_remaining <= 0 {
                    // ponytail: remove terminal entities now; add death phases when rendering consumes them.
                    self.emit_zombie_died_with_loot(zombie_id, events);
                    self.state.board.zombies.remove(zombie_index);
                }
                if projectile.projectile_type.is_splash() {
                    self.apply_splash_damage(&projectile, zombie_id, events);
                }
                self.state.board.projectiles.remove(projectile_index);
            } else if projectile.position_x > i64::from(LOGICAL_WIDTH) * POSITION_SCALE
                || projectile.position_x < -100 * POSITION_SCALE
                || (projectile.motion != ProjectileMotion::Homing && projectile_row.is_none())
            {
                self.state.board.projectiles.remove(projectile_index);
            } else {
                projectile_index += 1;
            }
        }
    }

    fn apply_torchwood(&mut self, projectile_index: usize, events: &mut Vec<GameEvent>) {
        let projectile_type = self.state.board.projectiles[projectile_index].projectile_type;
        if !matches!(
            projectile_type,
            ProjectileType::Pea | ProjectileType::SnowPea
        ) {
            return;
        }

        let projectile = &self.state.board.projectiles[projectile_index];
        let projectile_row = projectile.row;
        let projectile_x = projectile.position_x;
        let hit_column = projectile.hit_torchwood_column;
        // Source Projectile::GetProjectileRect gives a Pea a 40x40 rect anchored
        // at mX; UpdateTorchwood converts when the Torchwood attack rect
        // (Rect(mX + 50, mY, 30, mHeight)) overlaps it by >= 10 units, and the
        // mHitTorchwoodGridX guard skips the column that already converted it.
        let projectile_left = projectile_x;
        let projectile_right = projectile_x + 40 * POSITION_SCALE;
        let Some(torchwood_column) = self
            .state
            .board
            .plants
            .iter()
            .find(|plant| {
                if plant.row != projectile_row
                    || !plant.plant_type.is_torchwood()
                    || hit_column == Some(plant.column)
                {
                    return false;
                }
                let torchwood_x = grid_x(plant.column);
                let attack_left = torchwood_x + 50 * POSITION_SCALE;
                let attack_right = torchwood_x + 80 * POSITION_SCALE;
                let overlap =
                    (attack_right.min(projectile_right) - attack_left.max(projectile_left)).max(0);
                overlap >= 10 * POSITION_SCALE
            })
            .map(|plant| plant.column)
        else {
            return;
        };

        let projectile_id = self.state.board.projectiles[projectile_index].id;
        let projectile = &mut self.state.board.projectiles[projectile_index];
        if projectile_type == ProjectileType::Pea {
            projectile.projectile_type = ProjectileType::Fireball;
            projectile.damage = ProjectileType::Fireball.damage();
            projectile.hit_torchwood_column = Some(torchwood_column);
            events.push(GameEvent::ProjectileIgnited {
                projectile: projectile_id,
            });
        } else {
            projectile.projectile_type = ProjectileType::Pea;
            projectile.damage = ProjectileType::Pea.damage();
            projectile.hit_torchwood_column = Some(torchwood_column);
            events.push(GameEvent::ProjectileWarmed {
                projectile: projectile_id,
            });
        }
    }

    fn emit_projectile_impact(
        &mut self,
        projectile: &ProjectileState,
        zombie: Option<&ZombieState>,
        events: &mut Vec<GameEvent>,
    ) {
        let zombie_id = zombie.map(|zombie| zombie.id);
        let mut emit = |kind: ProjectileImpactSound, variants| {
            self.push_projectile_impact(
                projectile.id,
                projectile.projectile_type,
                zombie_id,
                kind,
                variants,
                events,
            );
        };
        let helm = zombie.and_then(|zombie| {
            if !zombie.armor_intact {
                return None;
            }
            Some(match zombie.zombie_type {
                ZombieType::Buckethead => ProjectileImpactSound::Shield,
                ZombieType::Conehead | ZombieType::Digger | ZombieType::Football => {
                    ProjectileImpactSound::Plastic
                }
                _ => return None,
            })
        });
        let fireball_splash = zombie
            .map(|zombie| {
                !matches!(
                    zombie.zombie_type,
                    ZombieType::Catapult
                        | ZombieType::Zamboni
                        | ZombieType::ScreenDoor
                        | ZombieType::Ladder
                )
            })
            .unwrap_or(true);
        match projectile.projectile_type {
            ProjectileType::Kernel => emit(ProjectileImpactSound::Kernel, 2),
            ProjectileType::Butter => {
                emit(ProjectileImpactSound::Butter, 1);
                if let Some(helm) = helm {
                    emit(helm, 2);
                }
            }
            ProjectileType::Fireball if fireball_splash => emit(ProjectileImpactSound::Ignite, 4),
            ProjectileType::Fireball => match helm {
                Some(ProjectileImpactSound::Shield) => emit(ProjectileImpactSound::Shield, 2),
                Some(ProjectileImpactSound::Plastic) => {
                    emit(ProjectileImpactSound::Plastic, 2);
                    emit(ProjectileImpactSound::Splat, 3);
                }
                None => emit(ProjectileImpactSound::Splat, 3),
                Some(kind) => emit(kind, 1),
            },
            ProjectileType::Melon | ProjectileType::WinterMelon => {
                emit(ProjectileImpactSound::Melon, 2);
                if let Some(helm) = helm {
                    emit(helm, 2);
                }
            }
            _ => match helm {
                Some(ProjectileImpactSound::Shield) => emit(ProjectileImpactSound::Shield, 2),
                Some(ProjectileImpactSound::Plastic) => {
                    emit(ProjectileImpactSound::Plastic, 2);
                    emit(ProjectileImpactSound::Splat, 3);
                }
                None => emit(ProjectileImpactSound::Splat, 3),
                Some(kind) => emit(kind, 1),
            },
        }
    }

    fn push_projectile_impact(
        &mut self,
        projectile: EntityId,
        projectile_type: ProjectileType,
        zombie: Option<EntityId>,
        kind: ProjectileImpactSound,
        variants: u32,
        events: &mut Vec<GameEvent>,
    ) {
        events.push(GameEvent::ProjectileImpact {
            projectile,
            projectile_type,
            zombie,
            kind,
            variant: self.rng.range(variants) as u8,
        });
    }

    fn steer_homing_projectile(&mut self, projectile_index: usize) {
        let projectile = self.state.board.projectiles[projectile_index].clone();
        let Some(target_id) = projectile.target_zombie else {
            return;
        };
        let Some(target) = self
            .state
            .board
            .zombies
            .iter()
            .find(|zombie| zombie.id == target_id && cattail_can_hit_zombie(zombie))
        else {
            return;
        };
        let (_, _, top, bottom) = zombie_threat_rect(self.state.scene, target);
        let target_x = zombie_target_lead_x(target, 0);
        let target_y = (top + bottom) / 2;
        let projectile_x = projectile.position_x + 20 * POSITION_SCALE;
        let projectile_y = projectile.position_y + 20 * POSITION_SCALE;
        let dx = (target_x - projectile_x) as f64;
        let dy = (target_y - projectile_y) as f64;
        let distance = (dx * dx + dy * dy).sqrt().max(1.0);
        let acceleration = projectile.age as f64 * 1_000.0;
        let motion_x = projectile.velocity_x as f64 + dx / distance * acceleration;
        let motion_y = projectile.velocity_y as f64 + dy / distance * acceleration;
        let magnitude = (motion_x * motion_x + motion_y * motion_y).sqrt().max(1.0);
        let speed = 2.0 * POSITION_SCALE as f64;
        let projectile = &mut self.state.board.projectiles[projectile_index];
        projectile.velocity_x = (motion_x / magnitude * speed).round() as i64;
        projectile.velocity_y = (motion_y / magnitude * speed).round() as i64;
    }

    fn apply_projectile_chill(
        &mut self,
        zombie_id: EntityId,
        projectile_type: ProjectileType,
        events: &mut Vec<GameEvent>,
    ) {
        if projectile_type == ProjectileType::Butter {
            // Zombie::ApplyButter 0x5326D0: 400-tick immobilize, refused by
            // Zamboni, the Boss, sledded bobsleds, and airborne fliers.
            if let Some(zombie) = self
                .state
                .board
                .zombies
                .iter_mut()
                .find(|zombie| zombie.id == zombie_id)
                && !matches!(zombie.zombie_type, ZombieType::Zamboni | ZombieType::Boss)
                && !(zombie.zombie_type == ZombieType::Bobsled && zombie.bobsled_sliding)
                && !(zombie.zombie_type == ZombieType::PoleVaulter
                    && zombie.special_phase == POLE_VAULT_IN_VAULT_PHASE)
                && !balloon_is_airborne(zombie)
            {
                zombie.frozen_counter = zombie.frozen_counter.max(BUTTER_TICKS);
                events.push(GameEvent::ZombieButtered { entity: zombie_id });
            }
            return;
        }
        let duration = projectile_type.chill_duration();
        if duration == 0 {
            return;
        }
        let Some(zombie) = self
            .state
            .board
            .zombies
            .iter_mut()
            .find(|zombie| zombie.id == zombie_id)
        else {
            return;
        };
        zombie.chilled_counter = zombie.chilled_counter.max(duration);
        events.push(GameEvent::ZombieChilled {
            entity: zombie_id,
            duration,
        });
    }

    fn apply_splash_damage(
        &mut self,
        projectile: &ProjectileState,
        primary_zombie: EntityId,
        events: &mut Vec<GameEvent>,
    ) {
        let Some(row) = projectile_row(projectile.position_y, self.state.board.rows) else {
            return;
        };
        let is_fireball = projectile.projectile_type == ProjectileType::Fireball;
        let target_ids = self
            .state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                if zombie.id == primary_zombie || zombie.health <= 0 {
                    return false;
                }
                if !projectile_can_hit_zombie(zombie, projectile.projectile_type) {
                    return false;
                }
                if is_fireball {
                    // Source IsZombieHitBySplash: Fireball splash is same-row,
                    // rejects fire-resistant zombies, and uses a width-100 rect.
                    !zombie_is_fire_resistant(zombie)
                        && zombie.row == row
                        && projectile_hits_fireball(projectile.position_x, zombie.position_x)
                } else {
                    zombie.row.abs_diff(row) <= 1
                        && projectile_hits(projectile.position_x, zombie.position_x)
                }
            })
            .map(|zombie| zombie.id)
            .collect::<Vec<_>>();

        // Source DoSplashDamage caps Fireball's aggregate splash at the
        // original damage before applying per-target damage.
        let original_damage = projectile.damage;
        let splash_base = projectile.projectile_type.splash_damage();
        let splash_total = splash_base.saturating_mul(target_ids.len() as i32);
        let max_splash = if is_fireball {
            original_damage
        } else {
            splash_base.saturating_mul(7)
        };
        let splash_damage = if splash_total > max_splash {
            (original_damage * max_splash / (splash_total * 3)).max(1)
        } else {
            splash_base
        };

        for zombie_id in target_ids {
            let Some(zombie_index) = self
                .state
                .board
                .zombies
                .iter()
                .position(|zombie| zombie.id == zombie_id)
            else {
                continue;
            };
            self.damage_zombie_from_projectile(zombie_index, projectile, splash_damage, events);
            let health_remaining = self.state.board.zombies[zombie_index].health;
            events.push(GameEvent::ProjectileSplashHit {
                projectile: projectile.id,
                zombie: zombie_id,
                damage: splash_damage,
                health_remaining,
            });
            self.apply_projectile_chill(zombie_id, projectile.projectile_type, events);
            if health_remaining <= 0 {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
            }
        }
    }

    fn apply_gloom_damage(&mut self, projectile: &ProjectileState, events: &mut Vec<GameEvent>) {
        let target_ids = self
            .state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                zombie.health > 0
                    && projectile_can_hit_zombie(zombie, projectile.projectile_type)
                    && zombie.row.abs_diff(projectile.row) <= GLOOM_ROW_RADIUS
                    && zombie.position_x > projectile.position_x
                    && zombie.position_x
                        < projectile.position_x + GLOOM_ATTACK_RANGE * POSITION_SCALE
            })
            .map(|zombie| zombie.id)
            .collect::<Vec<_>>();

        for zombie_id in target_ids {
            let Some(zombie_index) = self
                .state
                .board
                .zombies
                .iter()
                .position(|zombie| zombie.id == zombie_id)
            else {
                continue;
            };
            self.damage_zombie_bypassing_shield(zombie_index, projectile.damage, false, events);
            let health_remaining = self.state.board.zombies[zombie_index].health;
            events.push(GameEvent::ProjectileHit {
                projectile: projectile.id,
                zombie: zombie_id,
                damage: projectile.damage,
                health_remaining,
            });
            if health_remaining <= 0 {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
            }
        }
    }

    fn apply_fume_damage(&mut self, projectile: &ProjectileState, events: &mut Vec<GameEvent>) {
        let target_ids = self
            .state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                zombie.health > 0
                    && projectile_can_hit_zombie(zombie, projectile.projectile_type)
                    && zombie.row == projectile.row
                    && zombie.position_x > projectile.position_x
                    && zombie.position_x
                        < projectile.position_x + FUME_ATTACK_RANGE * POSITION_SCALE
            })
            .map(|zombie| zombie.id)
            .collect::<Vec<_>>();

        for zombie_id in target_ids {
            let Some(zombie_index) = self
                .state
                .board
                .zombies
                .iter()
                .position(|zombie| zombie.id == zombie_id)
            else {
                continue;
            };
            self.damage_zombie_bypassing_shield(zombie_index, projectile.damage, false, events);
            let health_remaining = self.state.board.zombies[zombie_index].health;
            events.push(GameEvent::ProjectileHit {
                projectile: projectile.id,
                zombie: zombie_id,
                damage: projectile.damage,
                health_remaining,
            });
            if health_remaining <= 0 {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
            }
        }
    }

    fn update_seed_packets(&mut self, events: &mut Vec<GameEvent>) {
        for packet in &mut self.state.board.seed_packets {
            let was_refreshing = packet.refresh_remaining > 0;
            packet.refresh_remaining = packet.refresh_remaining.saturating_sub(1);
            if was_refreshing && packet.refresh_remaining == 0 {
                events.push(GameEvent::SeedPacketReady {
                    slot: packet.slot,
                    plant_type: packet.plant_type,
                });
            }
        }
    }

    fn update_craters(&mut self) {
        for crater in &mut self.state.board.craters {
            if !crater.persistent && crater.remaining != u32::MAX {
                crater.remaining = crater.remaining.saturating_sub(1);
            }
        }
        self.state
            .board
            .craters
            .retain(|crater| crater.persistent || crater.remaining != 0);
    }

    fn update_sun_spawning(&mut self, events: &mut Vec<GameEvent>) {
        self.state.board.sun_countdown = self.state.board.sun_countdown.saturating_sub(1);
        if self.state.board.sun_countdown != 0 {
            return;
        }

        self.state.board.suns_fallen = self.state.board.suns_fallen.saturating_add(1);
        self.state.board.sun_countdown = (SUN_COUNTDOWN
            + self.state.board.suns_fallen.saturating_mul(10))
        .min(SUN_COUNTDOWN_MAX)
            + self.rng.range(SUN_COUNTDOWN_RANGE);
        let position_x = i64::from(self.rng.range_inclusive(100, 649)) * POSITION_SCALE;
        self.spawn_sun(SunSource::Sky, position_x, 60 * POSITION_SCALE, events);
        let ground_y = self.rng.range(250);
        if let Some(sun) = self.state.board.suns.last_mut() {
            // COIN_MOTION_FROM_SKY: the sun drifts down at 0.67 per tick to a
            // ground stop in the randomized band.
            sun.target_y = Some((300 + i64::from(ground_y)) * POSITION_SCALE);
        }
    }

    fn update_suns(&mut self, events: &mut Vec<GameEvent>) {
        for sun in &mut self.state.board.suns {
            if let Some(target_y) = sun.target_y {
                if sun.velocity_y != 0 || sun.velocity_x != 0 {
                    sun.position_x += sun.velocity_x;
                    sun.position_y += sun.velocity_y;
                    sun.velocity_y += SUN_GRAVITY;
                    if sun.velocity_y > 0 && sun.position_y >= target_y {
                        sun.position_y = target_y;
                        sun.target_y = None;
                        sun.velocity_x = 0;
                        sun.velocity_y = 0;
                    }
                } else {
                    sun.position_y += SUN_FALL_SPEED;
                    if sun.position_y >= target_y {
                        sun.position_y = target_y;
                        sun.target_y = None;
                    }
                }
            }
        }
        let mut present_coins_to_collect = Vec::new();
        let mut magnet_coins_to_collect = Vec::new();
        let magnet_targets = self.state.board.gold_magnet_targets.clone();
        let existing_coin_ids = self
            .state
            .board
            .coins
            .iter()
            .map(|coin| coin.id)
            .collect::<Vec<_>>();
        let existing_plant_ids = self
            .state
            .board
            .plants
            .iter()
            .map(|plant| plant.id)
            .collect::<Vec<_>>();
        self.state
            .board
            .gold_magnet_targets
            .retain(|(coin_id, plant_id)| {
                existing_coin_ids.contains(coin_id) && existing_plant_ids.contains(plant_id)
            });
        for coin in &mut self.state.board.coins {
            coin.age = coin.age.saturating_add(1);
            if let Some((_, plant_id)) = magnet_targets.iter().find(|(id, _)| *id == coin.id) {
                let Some(plant) = self
                    .state
                    .board
                    .plants
                    .iter()
                    .find(|plant| plant.id == *plant_id)
                else {
                    continue;
                };
                let dx = grid_x(plant.column) + 40 * POSITION_SCALE - coin.position_x;
                let dy = grid_y(plant.row) + 40 * POSITION_SCALE - coin.position_y;
                if dx * dx + dy * dy <= GOLD_MAGNET_ITEM_REACH * GOLD_MAGNET_ITEM_REACH {
                    magnet_coins_to_collect.push((coin.id, *plant_id));
                } else {
                    let move_x = (dx / 20).clamp(-50 * POSITION_SCALE, 50 * POSITION_SCALE);
                    let move_y = (dy / 20).clamp(-50 * POSITION_SCALE, 50 * POSITION_SCALE);
                    coin.position_x += if move_x == 0 { dx.signum() } else { move_x };
                    coin.position_y += if move_y == 0 { dy.signum() } else { move_y };
                }
            } else if coin.from_present {
                coin.position_x += coin.velocity_x;
                coin.position_y += coin.velocity_y;
                coin.velocity_x = coin.velocity_x * PRESENT_COIN_DECAY_PERCENT / 100;
                coin.velocity_y = coin.velocity_y * PRESENT_COIN_DECAY_PERCENT / 100;
                if coin.age >= PRESENT_COIN_TICKS {
                    present_coins_to_collect.push(coin.id);
                }
            } else if let Some(target_y) = coin.target_y {
                if coin.position_y + coin.velocity_y < target_y {
                    coin.position_x += coin.velocity_x;
                    coin.position_y += coin.velocity_y;
                    if coin.coin_type != CoinType::UsableSeedPacket {
                        coin.velocity_y += COIN_GRAVITY;
                    }
                } else {
                    let entity = coin.id;
                    let coin_type = coin.coin_type;
                    coin.position_y = target_y;
                    coin.target_y = None;
                    coin.velocity_x = 0;
                    coin.velocity_y = 0;
                    events.push(GameEvent::CoinLanded { entity, coin_type });
                }
            }
        }
        for entity in present_coins_to_collect {
            self.collect_coin(entity, events);
        }
        for (coin_id, plant_id) in magnet_coins_to_collect {
            self.state
                .board
                .gold_magnet_targets
                .retain(|(target_id, target_plant)| {
                    *target_id != coin_id || *target_plant != plant_id
                });
            self.collect_coin(coin_id, events);
            if !self
                .state
                .board
                .gold_magnet_targets
                .iter()
                .any(|(_, target_plant)| *target_plant == plant_id)
                && let Some(plant) = self
                    .state
                    .board
                    .plants
                    .iter_mut()
                    .find(|plant| plant.id == plant_id)
            {
                plant.special_counter = self
                    .rng
                    .range_inclusive(GOLD_MAGNET_RECHARGE_MIN, GOLD_MAGNET_RECHARGE_MAX);
            }
        }
    }

    fn update_wave_spawning(&mut self, events: &mut Vec<GameEvent>) {
        // Challenge::UpdateZombieSpawning claims spawning on Scary Potter
        // levels, so the board wave clock never runs on adventure 4-5.
        if self.state.mode == ModeKind::Adventure && self.state.level == 35 {
            return;
        }
        self.update_final_wave_sound(events);
        if self.state.challenge.kind == ChallengeKind::WhackAZombie {
            self.update_whack_zombie_spawning(events);
            return;
        }
        if self.state.board.wave.current >= self.state.board.wave.total {
            if self.state.board.wave.endless {
                self.state.board.wave.current = self.state.board.wave.total.saturating_sub(1);
                self.state.board.wave.countdown = FIRST_WAVE_COUNTDOWN;
                self.state.board.wave.countdown_start = FIRST_WAVE_COUNTDOWN;
            } else {
                return;
            }
        }
        if self.state.board.wave.current >= self.state.board.wave.total {
            return;
        }
        let adventure =
            self.state.mode == ModeKind::Adventure && (1..=50).contains(&self.state.level);
        let column = self.state.challenge.kind == ChallengeKind::Column;
        let last_stand = self.state.challenge.kind == ChallengeKind::LastStand;
        // The huge-wave banner freezes the spawn clock for 750 ticks, then
        // the wave releases immediately.
        if (adventure || column) && self.state.board.huge_wave_countdown > 0 {
            self.state.board.huge_wave_countdown -= 1;
            if self.state.board.huge_wave_countdown == 725 {
                events.push(GameEvent::HugeWaveSound {
                    wave: self.state.board.wave.current,
                });
            }
            if self.state.board.huge_wave_countdown > 0 {
                return;
            }
            self.arm_final_wave_sound();
            self.state.board.wave.countdown = 1;
        }
        self.state.board.wave.countdown = self.state.board.wave.countdown.saturating_sub(1);
        if adventure
            && self.state.board.wave.countdown > 200
            && self.state.board.wave.countdown_start > self.state.board.wave.countdown + 400
            && self.state.board.wave_health_threshold >= 0
            && self.current_wave_health() <= self.state.board.wave_health_threshold
        {
            self.state.board.wave.countdown = 200;
        }
        let flag_wave = if adventure {
            adventure_is_flag_wave(self.state.level, false, self.state.board.wave.current)
        } else {
            (column || last_stand) && self.state.board.wave.current % 10 == 9
        };
        if self.state.board.wave.countdown == 5 {
            if !flag_wave {
                self.arm_final_wave_sound();
            }
            if (adventure || column) && flag_wave {
                self.state.board.huge_wave_countdown = 750;
                return;
            }
        }
        if self.state.board.wave.countdown != 0 {
            return;
        }

        let wave = self.state.board.wave.current;
        events.push(GameEvent::WaveStarted { wave });
        // Board::SpawnZombieWave increments mTotalSpawnedWaves once per
        // actually spawned wave (Board.cpp:5020-5050); the ordinary-loot cap
        // compares this, not current_wave.
        self.state.board.wave.total_spawned_waves =
            self.state.board.wave.total_spawned_waves.saturating_add(1);
        if (adventure || column) && flag_wave {
            events.push(GameEvent::FlagWaveSound { wave });
        }
        let row = if column {
            0
        } else {
            self.rng.range(u32::from(self.state.board.rows)) as u8
        };
        match self.state.challenge.kind {
            ChallengeKind::BobsledBonanza => {
                // Bobsleds only spawn on iced rows; the source wave list leads
                // with Zombonis, whose Bonanza trails never expire.
                if let Some(ice_row) = self.pick_bobsled_row() {
                    self.spawn_bobsled_zombie(ice_row, wave, None, events);
                } else {
                    let zamboni_row = self.pick_spawn_row(ZombieType::Zamboni, wave);
                    self.spawn_zamboni_zombie(zamboni_row, wave, None, events);
                }
            }
            ChallengeKind::PogoParty => {
                self.spawn_pogo_zombie(row, wave, None, events);
            }
            ChallengeKind::WarAndPeas => {
                if wave.is_multiple_of(2) {
                    self.spawn_pea_head_zombie(row, wave, None, events);
                } else {
                    self.spawn_wallnut_head_zombie(row, wave, None, events);
                }
            }
            ChallengeKind::WarAndPeas2 => match wave % 6 {
                0 => {
                    self.spawn_pea_head_zombie(row, wave, None, events);
                }
                1 => {
                    self.spawn_wallnut_head_zombie(row, wave, None, events);
                }
                2 => {
                    self.spawn_jalapeno_head_zombie(row, wave, None, events);
                }
                3 => {
                    self.spawn_gatling_head_zombie(row, wave, None, events);
                }
                4 => {
                    self.spawn_squash_head_zombie(row, wave, None, events);
                }
                _ => {
                    self.spawn_tallnut_head_zombie(row, wave, None, events);
                }
            },
            ChallengeKind::Column => {
                let plan = self
                    .state
                    .board
                    .wave_plan
                    .get(wave as usize)
                    .cloned()
                    .unwrap_or_default();
                for zombie_type in plan {
                    self.spawn_adventure_zombie(zombie_type, wave, events);
                }
            }
            ChallengeKind::LastStand => {
                let global_wave = u32::from(self.state.challenge.stage) * LAST_STAND_WAVES + wave;
                let plan = self
                    .state
                    .board
                    .wave_plan
                    .get(wave as usize)
                    .cloned()
                    .unwrap_or_default();
                for zombie_type in plan {
                    self.spawn_last_stand_zombie(zombie_type, wave, global_wave, events);
                }
            }
            _ => {
                if self.state.mode == ModeKind::Adventure && (1..=50).contains(&self.state.level) {
                    if self.state.board.wave_plan.is_empty() {
                        let level = self.state.level;
                        let plan = self.pick_adventure_waves(level, false);
                        self.state.board.wave_plan = plan;
                    }
                    let plan = self
                        .state
                        .board
                        .wave_plan
                        .get(wave as usize)
                        .cloned()
                        .unwrap_or_default();
                    for zombie_type in plan {
                        self.spawn_adventure_zombie(zombie_type, wave, events);
                    }
                } else {
                    let normal_row = if self.state.scene == SceneKind::Pool {
                        self.pick_spawn_row(ZombieType::Normal, wave)
                    } else {
                        row
                    };
                    self.spawn_normal_zombie(normal_row, wave, None, events);
                }
            }
        }
        self.state.board.wave.current += 1;
        self.state.board.wave.countdown_start = 0;
        if self.state.board.wave.current < self.state.board.wave.total
            && (adventure || column || last_stand)
        {
            let countdown = if column {
                COLUMN_WAVE_COUNTDOWN
            } else if last_stand {
                LAST_STAND_NEXT_WAVE_COUNTDOWN
            } else {
                ZOMBIE_NEXT_WAVE_COUNTDOWN + self.rng.range(ZOMBIE_NEXT_WAVE_RANGE)
            };
            self.state.board.wave.countdown = countdown;
            self.state.board.wave.countdown_start = countdown;
            if adventure {
                // Board::UpdateZombieSpawning: the next wave releases early once
                // this wave's health falls to a random 50-65% of its start.
                let start_health = self.current_wave_health();
                let percent = 50 + self.rng.range(16) as i32;
                self.state.board.wave_health_threshold = start_health * percent / 100;
            }
        }
        // The final wave schedules the scene-routed rise 210 ticks later:
        // gravestones on night boards, pool emerges, or the roof sky drop.
        if matches!(
            self.state.scene,
            SceneKind::Roof | SceneKind::Night | SceneKind::Pool
        ) && self.state.board.wave.current >= self.state.board.wave.total
            && !self.state.board.wave.endless
            && !last_stand
        {
            self.state.board.sky_drop_countdown = SKY_DROP_DELAY_TICKS;
        }
    }

    fn arm_final_wave_sound(&mut self) {
        if self.state.board.final_wave_sound_countdown > 0
            || self.state.board.wave.current.saturating_add(1) != self.state.board.wave.total
        {
            return;
        }
        let final_survival_stage = self.state.mode == ModeKind::Survival
            && self.state.challenge.stage.saturating_add(1)
                >= survival_stage_limit(self.state.level);
        let allowed = final_survival_stage
            || (self.state.mode != ModeKind::Survival
                && self.state.challenge.kind != ChallengeKind::LastStand
                && !is_continuous_challenge(self.state.challenge.kind));
        if allowed {
            self.state.board.final_wave_sound_countdown = FINAL_WAVE_SOUND_DELAY;
            self.state.board.final_wave_sound_wave = self.state.board.wave.current;
        }
    }

    fn update_final_wave_sound(&mut self, events: &mut Vec<GameEvent>) {
        if self.state.board.final_wave_sound_countdown == 0
            || self.state.board.huge_wave_countdown > 0
        {
            return;
        }
        self.state.board.final_wave_sound_countdown -= 1;
        if self.state.board.final_wave_sound_countdown == 0 {
            events.push(GameEvent::FinalWaveSound {
                wave: self.state.board.final_wave_sound_wave,
            });
        }
    }

    fn place_whack_graves(&mut self, count: usize, events: &mut Vec<GameEvent>) {
        let cells = pick_whack_grave_cells(&self.state.board, &mut self.rng, count);
        for (row, column) in cells {
            let plant_ids = self
                .state
                .board
                .plants
                .iter()
                .filter(|plant| plant.row == row && plant.column == column)
                .map(|plant| plant.id)
                .collect::<Vec<_>>();
            if !plant_ids.is_empty() {
                self.state
                    .board
                    .plants
                    .retain(|plant| !(plant.row == row && plant.column == column));
                for entity in plant_ids {
                    events.push(GameEvent::PlantDied { entity });
                }
            }
            self.state.board.graves.push(GraveState { row, column });
        }
    }

    fn update_whack_zombie_spawning(&mut self, events: &mut Vec<GameEvent>) {
        let wave_finished = self.state.board.wave.current >= self.state.board.wave.total
            && self.state.board.wave.countdown == 0;
        if wave_finished {
            return;
        }

        self.state.board.wave.countdown = self.state.board.wave.countdown.saturating_sub(1);
        self.state.challenge.countdown = self.state.board.wave.countdown;
        if self.state.board.wave.countdown == 5 {
            self.arm_final_wave_sound();
        }
        if self.state.board.wave.countdown == 100 && self.state.board.wave.current > 0 {
            let count = 5usize.saturating_sub(self.state.board.graves.len()).max(1);
            self.place_whack_graves(count, events);
        }
        if self.state.board.wave.countdown == 0 {
            self.state.board.wave.countdown = WHACK_WAVE_COUNTDOWN;
            self.state.board.wave.countdown_start = WHACK_WAVE_COUNTDOWN;
            self.state.board.wave.current = self.state.board.wave.current.saturating_add(1);
            self.state.challenge.zombie_countdown =
                if self.state.board.wave.current == self.state.board.wave.total {
                    300
                } else {
                    1
                };
            events.push(GameEvent::WaveStarted {
                wave: self.state.board.wave.current.saturating_sub(1),
            });
        } else if self.state.board.wave.countdown < 300 {
            self.state.challenge.countdown = self.state.board.wave.countdown;
            return;
        }

        self.state.challenge.zombie_countdown =
            self.state.challenge.zombie_countdown.saturating_sub(1);
        if self.state.challenge.zombie_countdown != 0 {
            self.state.challenge.countdown = self.state.board.wave.countdown;
            return;
        }

        let current_wave = self.state.board.wave.current;
        let phase = current_wave
            .saturating_sub(1)
            .saturating_mul(6)
            .checked_div(12)
            .unwrap_or(0)
            .min(5) as usize;
        let double_chance = [0, 30, 10, 10, 15, 18][phase];
        let triple_chance = [0, 0, 0, 0, 10, 13][phase];
        let pail_chance = [0, 0, 0, 10, 15, 15][phase];
        let cone_chance = [0, 0, 30, 30, 30, 30][phase];
        let num_hit = self.rng.range(100);
        let type_hit = self.rng.range(100);
        let final_wave = current_wave == self.state.board.wave.total;
        let mut count = if final_wave {
            20
        } else if num_hit < triple_chance {
            3
        } else if num_hit < triple_chance + double_chance {
            2
        } else {
            1
        };
        let zombie_type = if type_hit < pail_chance && count < 3 {
            ZombieType::Buckethead
        } else if type_hit < pail_chance + cone_chance {
            ZombieType::Conehead
        } else {
            ZombieType::Normal
        };
        let mut graves = self
            .state
            .board
            .graves
            .iter()
            .filter(|grave| {
                !self.state.board.plants.iter().any(|plant| {
                    plant.row == grave.row
                        && plant.column == grave.column
                        && plant.plant_type.is_gravebuster()
                })
            })
            .map(|grave| (grave.row, grave.column))
            .collect::<Vec<_>>();
        count = count.min(graves.len());
        for _ in 0..count {
            let index = self.rng.range(graves.len() as u32) as usize;
            let (row, column) = graves.remove(index);
            let selected_type = if final_wave {
                if self.rng.range(2) == 0 {
                    ZombieType::Conehead
                } else {
                    ZombieType::Buckethead
                }
            } else {
                zombie_type
            };
            let zombie_id =
                self.spawn_rising_zombie(selected_type, row, column, current_wave, events);
            let speed = if final_wave {
                self.rng.fixed_range(500_000, 2 * POSITION_SCALE)
            } else {
                self.rng.fixed_range(500_000, whack_max_speed(current_wave))
            };
            if let Some(zombie) = self
                .state
                .board
                .zombies
                .iter_mut()
                .find(|zombie| zombie.id == zombie_id)
            {
                zombie.rise_counter = WHACK_RISE_TICKS;
                zombie.speed = speed;
            }
        }
        let age = current_wave.saturating_sub(1).min(11);
        let minimum = (1_100 - 70 * age + 5) / 11;
        let maximum = (2_200 - 140 * age + 5) / 11;
        self.state.challenge.zombie_countdown = self.rng.range_inclusive(minimum, maximum);
        if final_wave {
            self.state.board.wave.countdown = 0;
            self.state.challenge.zombie_countdown = 0;
        }
        self.state.challenge.countdown = self.state.board.wave.countdown;
    }

    /// Board::PickGraveRisingZombieType: Normal/Conehead at 4000 each, with
    /// the 3000-weight Buckethead only off gravestone stages.
    fn pick_grave_rising_type(&mut self, include_pail: bool) -> ZombieType {
        let total = if include_pail { 11_000 } else { 8_000 };
        let roll = self.rng.range(total);
        if roll < 4_000 {
            ZombieType::Normal
        } else if roll < 8_000 {
            ZombieType::Conehead
        } else {
            ZombieType::Buckethead
        }
    }

    fn spawn_rising_zombie(
        &mut self,
        zombie_type: ZombieType,
        row: u8,
        column: u8,
        wave: u32,
        events: &mut Vec<GameEvent>,
    ) -> EntityId {
        let health = match zombie_type {
            ZombieType::Conehead => 640,
            ZombieType::Buckethead => 1_370,
            _ => 270,
        };
        let position = grid_x(column) - 25 * POSITION_SCALE;
        let zombie_id =
            self._spawn_zombie_inner(zombie_type, health, row, wave, Some(position), events);
        if let Some(zombie) = self
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == zombie_id)
        {
            // Source RiseFromGrave (Zombie.cpp:8130-8160): a 150-tick rise on
            // land, or a 50-tick rise from the pool with mInPool set. The
            // zombie is off-ground and stationary until the rise completes.
            if self.state.scene == SceneKind::Pool {
                zombie.rise_counter = GRAVE_RISE_POOL_TICKS;
                zombie.in_pool = true;
            } else {
                zombie.rise_counter = GRAVE_RISE_LAND_TICKS;
            }
        }
        if self.state.scene == SceneKind::Pool {
            events.push(GameEvent::ZombiePoolRise { entity: zombie_id });
            events.push(GameEvent::ZombieEnteredPool {
                entity: zombie_id,
                variant: 0,
            });
        } else if self.state.challenge.kind == ChallengeKind::WhackAZombie {
            events.push(GameEvent::ZombieWhackRise { entity: zombie_id });
        } else if self.state.scene == SceneKind::Night {
            events.push(GameEvent::ZombieGraveRumble { entity: zombie_id });
        }
        zombie_id
    }

    /// TotalZombiesHealthInWave for the most recently spawned wave: body plus
    /// a fifth of the shield, skipping bungees and the dead.
    fn current_wave_health(&self) -> i32 {
        let wave = self.state.board.wave.current.saturating_sub(1);
        self.state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                zombie.from_wave == wave
                    && zombie.health > 0
                    && !zombie.hypnotized
                    && zombie.zombie_type != ZombieType::Bungee
            })
            .map(|zombie| zombie.health + zombie.shield_health / 5)
            .sum()
    }

    fn update_sky_drop(&mut self, events: &mut Vec<GameEvent>) {
        if self.state.board.sky_drop_countdown == 0 {
            return;
        }
        self.state.board.sky_drop_countdown -= 1;
        if self.state.board.sky_drop_countdown != 0 {
            return;
        }
        let wave = self.state.board.wave.current.saturating_sub(1);
        match self.state.scene {
            SceneKind::Night => {
                // One riser per gravestone; night stages never roll pails.
                let graves: Vec<(u8, u8)> = self
                    .state
                    .board
                    .graves
                    .iter()
                    .map(|grave| (grave.row, grave.column))
                    .collect();
                for (row, column) in graves {
                    let zombie_type = self.pick_grave_rising_type(false);
                    self.spawn_rising_zombie(zombie_type, row, column, wave, events);
                }
                return;
            }
            SceneKind::Pool => {
                let count = if matches!(self.state.level, 21 | 22 | 31 | 32) {
                    2
                } else {
                    3
                };
                let mut cells: Vec<(u8, u8)> = (2u8..=3)
                    .flat_map(|row| (5u8..=8).map(move |column| (row, column)))
                    .collect();
                for _ in 0..count {
                    let pick = self.rng.range(cells.len() as u32) as usize;
                    let (row, column) = cells.remove(pick);
                    let zombie_type = self.pick_grave_rising_type(true);
                    self.spawn_rising_zombie(zombie_type, row, column, wave, events);
                }
                return;
            }
            _ => {}
        }
        for _ in 0..3 {
            let roll = self.rng.range(11_000);
            let zombie_type = if roll < 4_000 {
                ZombieType::Normal
            } else if roll < 8_000 {
                ZombieType::Conehead
            } else {
                ZombieType::Buckethead
            };
            let column = 4 + self.rng.range(5) as u8;
            let row_limit = u32::from(self.state.board.rows.min(5));
            let row = self.rng.range(row_limit) as u8;
            self.spawn_bungee_drop(zombie_type, row, column, wave, events);
        }
    }

    fn apply_spikeweed_damage(
        &mut self,
        plant_id: EntityId,
        row: u8,
        column: u8,
        events: &mut Vec<GameEvent>,
    ) -> bool {
        let mut vehicle_hit = false;
        let mut zombie_index = 0;
        while zombie_index < self.state.board.zombies.len() {
            let zombie = &self.state.board.zombies[zombie_index];
            if !plant_damage_can_hit_zombie(zombie)
                || zombie_rejects_ground_damage(zombie)
                || zombie.row != row
                || balloon_is_airborne(zombie)
                || !spikeweed_hits(zombie.position_x, column)
            {
                zombie_index += 1;
                continue;
            }
            let zombie_id = zombie.id;
            // Spike damage against the Zomboni and Catapult vehicles is raised to
            // 1800 and pops the tires; the spiky plant pays for it below.
            let damage = if matches!(
                zombie.zombie_type,
                ZombieType::Zamboni | ZombieType::Catapult
            ) {
                vehicle_hit = true;
                SPIKE_VEHICLE_DAMAGE
            } else {
                SPIKEWEED_DAMAGE
            };
            self.damage_zombie_bypassing_shield(zombie_index, damage, vehicle_hit, events);
            let health_remaining = self.state.board.zombies[zombie_index].health;
            events.push(GameEvent::PlantSpecialHit {
                plant: plant_id,
                zombie: zombie_id,
                damage,
                health_remaining,
            });
            if health_remaining <= 0 {
                self.emit_zombie_died_with_loot(zombie_id, events);
                self.state.board.zombies.remove(zombie_index);
            } else {
                zombie_index += 1;
            }
        }
        vehicle_hit
    }

    /// Applies the vehicle-pop cost to a spiky plant. Returns true when the
    /// plant was removed so the caller can stop using its plant index.
    fn pop_spiky_plant(&mut self, plant_id: EntityId, events: &mut Vec<GameEvent>) -> bool {
        let Some(plant_index) = self
            .state
            .board
            .plants
            .iter()
            .position(|plant| plant.id == plant_id)
        else {
            return true;
        };
        let is_spikerock = self.state.board.plants[plant_index].plant_type.slot() == 46;
        if is_spikerock {
            self.state.board.plants[plant_index].health -= SPIKEROCK_VEHICLE_SELF_DAMAGE;
            let health_remaining = self.state.board.plants[plant_index].health;
            events.push(GameEvent::PlantDamaged {
                entity: plant_id,
                damage: SPIKEROCK_VEHICLE_SELF_DAMAGE,
                health_remaining,
            });
            if health_remaining <= 0 {
                self.state.board.plants.remove(plant_index);
                events.push(GameEvent::PlantDied { entity: plant_id });
                return true;
            }
            false
        } else {
            self.state.board.plants.remove(plant_index);
            events.push(GameEvent::PlantDied { entity: plant_id });
            true
        }
    }

    fn find_plant_for_zombie(
        &self,
        row: u8,
        zombie_x: i64,
        zombie_type: ZombieType,
    ) -> Option<usize> {
        if zombie_type == ZombieType::Boss {
            return None;
        }
        self.state
            .board
            .plants
            .iter()
            .enumerate()
            .filter(|(_, plant)| plant.row == row && plant.health > 0)
            .filter(|(_, plant)| !plant.plant_type.is_tangle_kelp())
            .filter(|(_, plant)| plant_is_on_ground(plant))
            // Spikeweed is walked over except by Gargantuars, Zamboni, and
            // plants exposed on water or supported by a Flower Pot.
            .filter(|(_, plant)| {
                !plant.plant_type.is_spikeweed()
                    || is_gargantuar(zombie_type)
                    || zombie_type == ZombieType::Zamboni
                    || scene_row_is_water(self.state.scene, plant.row)
                    || self.state.board.plants.iter().any(|support| {
                        support.row == plant.row
                            && support.column == plant.column
                            && support.plant_type.slot() == 33
                    })
            })
            .filter(|(_, plant)| {
                zombie_type == ZombieType::Digger
                    || !self
                        .state
                        .board
                        .ladders
                        .iter()
                        .any(|ladder| ladder.row == plant.row && ladder.column == plant.column)
            })
            .filter(|(_, plant)| {
                let plant_x = grid_x(plant.column);
                zombie_x + 70 * POSITION_SCALE > plant_x
                    && zombie_x + 50 * POSITION_SCALE < plant_x + 80 * POSITION_SCALE
            })
            .max_by_key(|(_, plant)| plant.column)
            .map(|(index, _)| index)
    }

    fn find_plant_for_pole_vault(&self, row: u8, zombie_x: i64, in_vault: bool) -> Option<usize> {
        let (attack_offset, attack_width) = if in_vault {
            (-40, 100)
        } else if self.state.challenge.kind == ChallengeKind::WallnutBowling {
            (-229, 270)
        } else {
            (-29, 70)
        };
        let attack_left = zombie_x + attack_offset * POSITION_SCALE;
        let attack_right = attack_left + attack_width * POSITION_SCALE;

        self.state
            .board
            .plants
            .iter()
            .enumerate()
            .filter(|(_, plant)| plant.row == row && plant.health > 0)
            .filter(|(_, plant)| !plant.plant_type.is_tangle_kelp())
            .filter(|(_, plant)| !plant.plant_type.is_spikeweed())
            .filter(|(_, plant)| {
                let plant_x = grid_x(plant.column);
                let (plant_offset, plant_width) = match plant.plant_type.slot() {
                    23 => (10, 80),
                    30 => (0, 60),
                    47 => (0, 140),
                    _ => (10, 60),
                };
                let plant_left = plant_x + plant_offset * POSITION_SCALE;
                let plant_right = plant_left + plant_width * POSITION_SCALE;
                attack_right.min(plant_right) - attack_left.max(plant_left) >= 20 * POSITION_SCALE
            })
            .max_by_key(|(_, plant)| {
                (
                    plant.column,
                    !matches!(plant.plant_type.slot(), 16 | 30 | 33 | 35),
                )
            })
            .map(|(index, _)| index)
    }

    fn find_plant_for_dolphin(&self, row: u8, zombie_x: i64, in_jump: bool) -> Option<usize> {
        self.find_plant_for_pole_vault(row, zombie_x, in_jump)
            .filter(|&plant_index| {
                !self.state.board.plants[plant_index]
                    .plant_type
                    .is_tangle_kelp()
            })
    }

    fn find_catapult_target(&self, row: u8, zombie_x: i64) -> Option<usize> {
        let column = self
            .state
            .board
            .plants
            .iter()
            .filter(|plant| {
                plant.health > 0
                    && plant.row == row
                    && !catapult_plant_type(plant).is_spikeweed()
                    && plant_is_on_ground(plant)
                    && zombie_x >= grid_x(plant.column) + 100 * POSITION_SCALE
            })
            .map(|plant| plant.column)
            .min()?;
        self.find_catapult_top_plant(row, column)
    }

    fn find_bungee_top_plant(&self, row: u8, column: u8) -> Option<usize> {
        let mut flying = None;
        let mut normal = None;
        let mut pumpkin = None;
        let mut under_plant = None;
        for (index, plant) in self.state.board.plants.iter().enumerate() {
            if plant.health <= 0 || plant.row != row || !plant_is_on_ground(plant) {
                continue;
            }
            let plant_type = catapult_plant_type(plant);
            let in_cell = if plant_type.is_cob_cannon() {
                plant.column == column || plant.column.checked_add(1) == Some(column)
            } else {
                plant.column == column
            };
            if !in_cell {
                continue;
            }
            match plant_type.slot() {
                35 => flying = Some(index),
                30 => pumpkin = Some(index),
                16 | 33 => under_plant = Some(index),
                _ => normal = Some(index),
            }
        }
        flying.or(normal).or(pumpkin).or(under_plant)
    }

    fn find_catapult_top_plant(&self, row: u8, column: u8) -> Option<usize> {
        let mut flying = None;
        let mut normal = None;
        let mut pumpkin = None;
        let mut under_plant = None;
        for (index, plant) in self.state.board.plants.iter().enumerate() {
            if plant.health <= 0 || plant.row != row || plant.column != column {
                continue;
            }
            match catapult_plant_type(plant).slot() {
                35 => flying = Some(index),
                30 => pumpkin = Some(index),
                16 | 33 => under_plant = Some(index),
                _ => normal = Some(index),
            }
        }
        flying.or(normal).or(pumpkin).or(under_plant)
    }

    fn bungee_target_cell_is_occupied(&self, row: u8, column: u8) -> bool {
        self.state.board.zombies.iter().any(|zombie| {
            zombie.zombie_type == ZombieType::Bungee
                && zombie.health > 0
                && !zombie.departed
                && zombie.bungee_target_row == Some(row)
                && zombie.bungee_target_column == Some(column)
        })
    }

    fn pick_bungee_target(&mut self) -> Option<(u8, u8)> {
        let sunflower_count = self
            .state
            .board
            .plants
            .iter()
            .filter(|plant| catapult_plant_type(plant).makes_sun())
            .count();
        let bungees_targeting_sunflowers = self
            .state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                zombie.zombie_type == ZombieType::Bungee
                    && zombie.health > 0
                    && !zombie.departed
                    && zombie
                        .bungee_target_row
                        .zip(zombie.bungee_target_column)
                        .and_then(|(row, column)| self.find_bungee_top_plant(row, column))
                        .is_some_and(|index| {
                            catapult_plant_type(&self.state.board.plants[index]).makes_sun()
                        })
            })
            .count();
        let allow_sunflower_target = bungees_targeting_sunflowers + 1 != sunflower_count;
        let mut candidates = Vec::new();
        for column in 0..self.state.board.columns.min(GRID_COLUMNS) {
            for row in 0..GRID_ROWS {
                if !bungee_cell_terrain_is_valid(
                    self.state.scene,
                    self.state.mode,
                    self.state.level,
                    self.state.adventure_first_time,
                    row,
                ) {
                    continue;
                }
                if self
                    .state
                    .board
                    .graves
                    .iter()
                    .any(|grave| grave.row == row && grave.column == column)
                    || self.bungee_target_cell_is_occupied(row, column)
                {
                    continue;
                }
                let weight = if let Some(index) = self.find_bungee_top_plant(row, column) {
                    let plant_type = catapult_plant_type(&self.state.board.plants[index]);
                    if (!allow_sunflower_target && plant_type.makes_sun())
                        || plant_type.is_gravebuster()
                        || plant_type.is_cob_cannon()
                    {
                        continue;
                    }
                    10_000
                } else {
                    1
                };
                candidates.push((row, column, weight));
            }
        }
        let total_weight = candidates.iter().map(|(_, _, weight)| *weight).sum::<u32>();
        if total_weight == 0 {
            return None;
        }
        let mut roll = self.rng.range(total_weight);
        candidates.into_iter().find_map(|(row, column, weight)| {
            if roll < weight {
                Some((row, column))
            } else {
                roll -= weight;
                None
            }
        })
    }

    fn find_catapult_collision_target(&self, projectile: &ProjectileState) -> Option<usize> {
        self.state
            .board
            .plants
            .iter()
            .filter(|plant| {
                plant.health > 0
                    && plant.row == projectile.row
                    && catapult_projectile_hits_plant(self.state.scene, projectile, plant)
            })
            .find_map(|plant| self.find_catapult_top_plant(plant.row, plant.column))
    }

    fn find_umbrella_plant(&self, row: u8, column: u8) -> Option<usize> {
        self.state.board.plants.iter().position(|plant| {
            plant.health > 0
                && catapult_plant_type(plant).slot() == 37
                && plant_is_on_ground(plant)
                && plant.row.abs_diff(row) <= 1
                && plant.column.abs_diff(column) <= 1
        })
    }

    fn find_chomper_target(&self, row: u8, column: u8) -> Option<EntityId> {
        let center_x = grid_x(column);
        self.state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                plant_damage_can_hit_zombie(zombie)
                    && zombie.row == row
                    && matches!(zombie.zombie_type, ZombieType::Normal)
                    && zombie.position_x >= center_x - 20 * POSITION_SCALE
                    && zombie.position_x <= center_x + 80 * POSITION_SCALE
            })
            .min_by_key(|zombie| zombie.position_x.abs_diff(center_x))
            .map(|zombie| zombie.id)
    }

    // Plant::FindTargetZombie uses damage flags 5 and TangleKelp's own cell rect.
    fn find_tangle_kelp_target(&self, row: u8, column: u8) -> Option<EntityId> {
        let attack_left = grid_x(column);
        let attack_right = attack_left + 80 * POSITION_SCALE;
        self.state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                let (left, right) = zombie_horizontal_rect(zombie);
                plant_damage_can_hit_zombie(zombie)
                    && !zombie_rejects_ground_damage(zombie)
                    && !zombie.departed
                    && zombie.row == row
                    && zombie.in_pool
                    && !balloon_is_airborne(zombie)
                    && zombie.imp_flight_ticks == 0
                    && !(zombie.zombie_type == ZombieType::Bobsled
                        && zombie.bobsled_sliding
                        && !zombie.bobsled_leader)
                    && !(zombie.zombie_type == ZombieType::PoleVaulter
                        && zombie.special_phase == POLE_VAULT_IN_VAULT_PHASE)
                    && !(zombie.zombie_type == ZombieType::Snorkel
                        && zombie.snorkel_phase == SNORKEL_INTO_POOL_PHASE)
                    && !(zombie.zombie_type == ZombieType::DolphinRider
                        && matches!(
                            zombie.dolphin_phase,
                            DOLPHIN_INTO_POOL_PHASE | DOLPHIN_IN_JUMP_PHASE
                        ))
                    && right >= attack_left
                    && left <= attack_right
                    && !self.state.board.plants.iter().any(|plant| {
                        plant.plant_type.is_tangle_kelp() && plant.special_target == Some(zombie.id)
                    })
            })
            .min_by_key(|zombie| zombie_horizontal_rect(zombie).0)
            .map(|zombie| zombie.id)
    }

    fn find_squash_target(&self, row: u8, column: u8) -> Option<EntityId> {
        let center_x = grid_x(column);
        self.state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                let maximum_gap = if zombie.eating {
                    SQUASH_EATING_TARGET_GAP
                } else {
                    SQUASH_TARGET_GAP
                } * POSITION_SCALE;
                plant_damage_can_hit_zombie(zombie)
                    && zombie.row == row
                    && matches!(zombie.zombie_type, ZombieType::Normal)
                    && (zombie.position_x - center_x).abs() <= maximum_gap
            })
            .min_by_key(|zombie| zombie.position_x.abs_diff(center_x))
            .map(|zombie| zombie.id)
    }

    /// A hypnotized zombie attacks a non-hypnotized zombie in the same row.
    /// Returns true when it found and damaged a target zombie.
    fn attack_zombie_target(
        &mut self,
        attacker_id: EntityId,
        row: u8,
        events: &mut Vec<GameEvent>,
    ) -> bool {
        let position_x = self
            .state
            .board
            .zombies
            .iter()
            .find(|z| z.id == attacker_id)
            .map(|z| z.position_x)
            .unwrap_or(i64::MAX);
        let target_id = self
            .state
            .board
            .zombies
            .iter()
            .filter(|z| {
                z.health > 0
                    && !z.hypnotized
                    && z.row == row
                    && (z.position_x - position_x).abs() <= 115 * POSITION_SCALE
            })
            .min_by_key(|z| z.position_x)
            .map(|z| z.id);
        let Some(target_id) = target_id else {
            return false;
        };
        if let Some(target_idx) = self
            .state
            .board
            .zombies
            .iter()
            .position(|z| z.id == target_id)
        {
            self.damage_zombie(target_idx, ZOMBIE_BITE_DAMAGE, events);
            let health_remaining = self.state.board.zombies[target_idx].health;
            events.push(GameEvent::ZombieDamaged {
                entity: target_id,
                damage: ZOMBIE_BITE_DAMAGE,
                health_remaining,
                attacker: Some(attacker_id),
            });
            if health_remaining <= 0 {
                self.state.board.zombies[target_idx].health = 0;
                self.emit_zombie_died_with_loot(target_id, events);
            }
        }
        true
    }

    fn fire_cob_projectile(
        &mut self,
        source: EntityId,
        source_row: u8,
        source_column: u8,
        target_row: u8,
        target_column: u8,
        events: &mut Vec<GameEvent>,
    ) {
        let projectile_type = ProjectileType::Cob;
        let origin_x = grid_x(source_column) - 44 * POSITION_SCALE;
        let target_x = grid_x(target_column);
        let id = self.state.board.allocate_entity();
        self.state.board.projectiles.push(ProjectileState {
            id,
            projectile_type,
            motion: ProjectileMotion::Lobbed,
            row: target_row,
            position_x: origin_x,
            position_y: grid_y(source_row),
            velocity_x: 0,
            velocity_y: 0,
            shadow_y: projectile_shadow_y(
                self.state.scene,
                target_row,
                origin_x,
                ProjectileMotion::Lobbed,
                0,
            ),
            damage: projectile_type.damage(),
            age: 0,
            target_x: Some(target_x),
            target_row: Some(target_row),
            target_zombie: None,
            lob_height: 0,
            lob_velocity: -8,
            hit_torchwood_column: None,
            last_portal_column: 0,
        });
        events.push(GameEvent::ProjectileFired {
            entity: id,
            source,
            projectile_type,
            row: target_row,
        });
    }

    fn find_pult_target(&self, row: u8, column: u8) -> Option<&ZombieState> {
        self.state
            .board
            .zombies
            .iter()
            .filter(|zombie| {
                if !plant_damage_can_hit_zombie(zombie)
                    || zombie_rejects_ground_damage(zombie)
                    || zombie.imp_flight_ticks > 0
                    || balloon_is_airborne(zombie)
                {
                    return false;
                }
                let (left, _) = zombie_horizontal_rect(zombie);
                (zombie.zombie_type == ZombieType::Boss || zombie.row == row)
                    && left > plant_attack_start(column)
            })
            .min_by_key(|zombie| zombie_horizontal_rect(zombie).0)
    }

    fn find_cattail_target(&self, row: u8, column: u8) -> Option<EntityId> {
        let mut best = None;
        for zombie in &self.state.board.zombies {
            if !cattail_can_target_zombie(self.state.scene, zombie) {
                continue;
            }
            let weight = cattail_target_weight(self.state.scene, row, column, zombie);
            if best.is_none_or(|(_, best_weight)| weight > best_weight) {
                best = Some((zombie.id, weight));
            }
        }
        best.map(|(id, _)| id)
    }

    fn pult_origin(
        plant_type: PlantType,
        projectile_type: ProjectileType,
        row: u8,
        column: u8,
    ) -> (i64, i64) {
        let (offset_x, offset_y) = match plant_type.slot() {
            32 => (5, -12),
            34 if projectile_type == ProjectileType::Butter => (12, -56),
            34 => (19, -37),
            39 | 44 => (25, -46),
            _ => (60, 0),
        };
        (
            grid_x(column) + offset_x * POSITION_SCALE,
            grid_y(row) + offset_y * POSITION_SCALE,
        )
    }

    fn pult_aim(
        &self,
        plant_type: PlantType,
        projectile_type: ProjectileType,
        row: u8,
        column: u8,
    ) -> (i64, i64, Option<PultAim>) {
        let (origin_x, origin_y) = Self::pult_origin(plant_type, projectile_type, row, column);
        let aim = self.find_pult_target(row, column).map(|zombie| {
            let mut range_x_adjustment = 0;
            if zombie.zombie_type == ZombieType::DolphinRider
                && zombie.dolphin_phase == DOLPHIN_RIDING_PHASE
            {
                range_x_adjustment -= 60 * POSITION_SCALE;
            }
            if zombie.zombie_type == ZombieType::Pogo && zombie.special_phase == 0 {
                range_x_adjustment -= 60 * POSITION_SCALE;
            }
            if zombie.zombie_type == ZombieType::Snorkel
                && zombie.snorkel_phase == SNORKEL_WALKING_IN_POOL_PHASE
            {
                range_x_adjustment -= 40 * POSITION_SCALE;
            }
            PultAim {
                target_x: zombie_target_lead_x(zombie, 50),
                target_y: if zombie.zombie_type == ZombieType::Boss {
                    grid_y(row)
                } else {
                    zombie_pult_target_y(zombie)
                },
                range_x_adjustment,
            }
        });
        (origin_x, origin_y, aim)
    }

    fn fire_pult_projectile(
        &mut self,
        source: EntityId,
        plant_type: PlantType,
        projectile_type: ProjectileType,
        row: u8,
        column: u8,
        events: &mut Vec<GameEvent>,
    ) {
        let (origin_x, origin_y, aim) = self.pult_aim(plant_type, projectile_type, row, column);
        let (range_x, range_y) = if let Some(aim) = aim {
            (
                (aim.target_x - origin_x - 30 * POSITION_SCALE + aim.range_x_adjustment)
                    .max(40 * POSITION_SCALE),
                aim.target_y - origin_y,
            )
        } else {
            (
                (700 * POSITION_SCALE - origin_x).max(40 * POSITION_SCALE),
                0,
            )
        };
        let id = self.state.board.allocate_entity();
        self.state.board.projectiles.push(ProjectileState {
            id,
            projectile_type,
            motion: ProjectileMotion::Lobbed,
            row,
            position_x: origin_x,
            position_y: origin_y,
            velocity_x: range_x / 120,
            velocity_y: 0,
            shadow_y: projectile_shadow_y(
                self.state.scene,
                row,
                origin_x,
                ProjectileMotion::Lobbed,
                0,
            ),
            damage: projectile_type.damage(),
            age: 0,
            target_x: aim.map(|aim| aim.target_x),
            target_row: aim.map(|_| row),
            target_zombie: None,
            lob_height: 0,
            lob_velocity: ((range_y * PULT_LOB_SCALE) / (120 * POSITION_SCALE) - 7 * PULT_LOB_SCALE)
                as i32,
            hit_torchwood_column: None,
            last_portal_column: 0,
        });
        events.push(GameEvent::ProjectileFired {
            entity: id,
            source,
            projectile_type,
            row,
        });
    }

    fn fire_catapult_projectile(
        &mut self,
        source: EntityId,
        row: u8,
        source_x: i64,
        target_x: i64,
        target_y: i64,
        events: &mut Vec<GameEvent>,
    ) {
        let projectile_type = ProjectileType::Other(1);
        let origin_x = source_x + 113 * POSITION_SCALE;
        let origin_y = scene_row_y(self.state.scene, row, source_x + 40 * POSITION_SCALE)
            - 30 * POSITION_SCALE
            - 44 * POSITION_SCALE;
        let range_x = (origin_x - target_x - 20 * POSITION_SCALE).max(40 * POSITION_SCALE);
        let id = self.state.board.allocate_entity();
        self.state.board.projectiles.push(ProjectileState {
            id,
            projectile_type,
            motion: ProjectileMotion::Lobbed,
            row,
            position_x: origin_x,
            position_y: origin_y,
            velocity_x: -range_x / CATAPULT_LOB_FLIGHT_UPDATES,
            velocity_y: 0,
            shadow_y: projectile_shadow_y(
                self.state.scene,
                row,
                origin_x,
                ProjectileMotion::Lobbed,
                0,
            ),
            damage: projectile_type.damage(),
            age: 0,
            target_x: Some(target_x),
            target_row: Some(row),
            target_zombie: None,
            lob_height: 0,
            lob_velocity: (((target_y - origin_y) * PULT_LOB_SCALE)
                / (CATAPULT_LOB_FLIGHT_UPDATES * POSITION_SCALE)
                - 7 * PULT_LOB_SCALE) as i32,
            hit_torchwood_column: None,
            last_portal_column: 0,
        });
        events.push(GameEvent::ProjectileFired {
            entity: id,
            source,
            projectile_type,
            row,
        });
    }

    fn fire_projectiles(
        &mut self,
        source: EntityId,
        plant_type: PlantType,
        projectile_type: ProjectileType,
        source_cell: (u8, u8),
        firing_directions: u8,
        events: &mut Vec<GameEvent>,
    ) {
        let (row, column) = source_cell;
        let position_x = if plant_type.is_gloom_shroom() {
            grid_x(column) - 80 * POSITION_SCALE
        } else {
            grid_x(column) + 60 * POSITION_SCALE
        };
        let position_y = grid_y(row);
        match plant_type.firing_pattern() {
            FiringPattern::Homing => {
                let Some(target_zombie) = self.find_cattail_target(row, column) else {
                    return;
                };
                self.emit_plant_fired(source, plant_type, events);
                let projectile_index = self.state.board.projectiles.len();
                self.fire_projectile(
                    source,
                    projectile_type,
                    row,
                    ProjectileTrajectory {
                        motion: ProjectileMotion::Homing,
                        position_x: grid_x(column) + 10 * POSITION_SCALE,
                        position_y: scene_plant_y(self.state.scene, row, column)
                            + 5 * POSITION_SCALE,
                        velocity_x: 2 * POSITION_SCALE,
                        velocity_y: 0,
                    },
                    events,
                );
                self.state.board.projectiles[projectile_index].target_zombie = Some(target_zombie);
            }
            FiringPattern::ThreeRow => {
                let threepeater_position_x = grid_x(column) + 45 * POSITION_SCALE;
                let threepeater_position_y =
                    scene_plant_y(self.state.scene, row, column) + 10 * POSITION_SCALE;
                for target_row in [
                    row.checked_sub(1),
                    Some(row),
                    row.checked_add(1)
                        .filter(|target_row| *target_row < self.state.board.rows),
                ]
                .into_iter()
                .flatten()
                {
                    let (motion, velocity_y) = match target_row.cmp(&row) {
                        std::cmp::Ordering::Less => {
                            (ProjectileMotion::Threepeater, -3 * POSITION_SCALE)
                        }
                        std::cmp::Ordering::Greater => {
                            (ProjectileMotion::Threepeater, 3 * POSITION_SCALE)
                        }
                        std::cmp::Ordering::Equal => (ProjectileMotion::Straight, 0),
                    };
                    self.emit_plant_fired(source, plant_type, events);
                    self.fire_projectile(
                        source,
                        projectile_type,
                        target_row,
                        ProjectileTrajectory {
                            motion,
                            position_x: threepeater_position_x,
                            position_y: threepeater_position_y,
                            velocity_x: 3_330_000,
                            velocity_y,
                        },
                        events,
                    );
                }
            }
            FiringPattern::Split => {
                if firing_directions & FIRING_FORWARD != 0 {
                    self.emit_plant_fired(source, plant_type, events);
                    self.fire_projectile(
                        source,
                        projectile_type,
                        row,
                        ProjectileTrajectory {
                            motion: ProjectileMotion::Straight,
                            position_x,
                            position_y,
                            velocity_x: 3_330_000,
                            velocity_y: 0,
                        },
                        events,
                    );
                }
                if firing_directions & FIRING_BACKWARD != 0 {
                    self.emit_plant_fired(source, plant_type, events);
                    self.fire_projectile(
                        source,
                        projectile_type,
                        row,
                        ProjectileTrajectory {
                            motion: ProjectileMotion::Backwards,
                            position_x: grid_x(column) + 20 * POSITION_SCALE,
                            position_y,
                            velocity_x: -3_330_000,
                            velocity_y: 0,
                        },
                        events,
                    );
                }
            }
            FiringPattern::Star => {
                let star_position_x = grid_x(column) + STAR_ORIGIN_OFFSET;
                let star_position_y =
                    scene_plant_y(self.state.scene, row, column) + STAR_ORIGIN_OFFSET;
                self.emit_plant_fired(source, plant_type, events);
                for (velocity_x, velocity_y) in [
                    (-3_330_000, 0),
                    (0, 3_330_000),
                    (0, -3_330_000),
                    (2_883_865, 1_665_000),
                    (2_883_865, -1_665_000),
                ] {
                    self.fire_projectile(
                        source,
                        projectile_type,
                        row,
                        ProjectileTrajectory {
                            motion: ProjectileMotion::Star,
                            position_x: star_position_x,
                            position_y: star_position_y,
                            velocity_x,
                            velocity_y,
                        },
                        events,
                    );
                }
            }
            FiringPattern::Backward => {
                if firing_directions & FIRING_BACKWARD != 0 {
                    self.emit_plant_fired(source, plant_type, events);
                    self.fire_projectile(
                        source,
                        projectile_type,
                        row,
                        ProjectileTrajectory {
                            motion: ProjectileMotion::Backwards,
                            position_x: grid_x(column) + 20 * POSITION_SCALE,
                            position_y,
                            velocity_x: -3_330_000,
                            velocity_y: 0,
                        },
                        events,
                    );
                }
            }
            _ => {
                self.emit_plant_fired(source, plant_type, events);
                if plant_type.is_pult() {
                    self.fire_pult_projectile(
                        source,
                        plant_type,
                        projectile_type,
                        row,
                        column,
                        events,
                    );
                } else {
                    self.fire_projectile(
                        source,
                        projectile_type,
                        row,
                        ProjectileTrajectory {
                            motion: plant_type.projectile_motion(),
                            position_x,
                            position_y,
                            velocity_x: if plant_type.is_fume_shroom()
                                || plant_type.is_gloom_shroom()
                            {
                                0
                            } else {
                                3_330_000
                            },
                            velocity_y: 0,
                        },
                        events,
                    );
                }
            }
        }
    }

    fn emit_plant_fired(
        &mut self,
        entity: EntityId,
        plant_type: PlantType,
        events: &mut Vec<GameEvent>,
    ) {
        let variant = if matches!(plant_type.slot(), 10 | 42) {
            0
        } else {
            self.rng.range(4) as u8
        };
        events.push(GameEvent::PlantFired {
            entity,
            plant_type,
            variant,
        });
    }

    fn fire_projectile(
        &mut self,
        source: EntityId,
        projectile_type: ProjectileType,
        row: u8,
        trajectory: ProjectileTrajectory,
        events: &mut Vec<GameEvent>,
    ) {
        let id = self.state.board.allocate_entity();
        let shadow_y = projectile_shadow_y(
            self.state.scene,
            row,
            trajectory.position_x,
            trajectory.motion,
            trajectory.velocity_y,
        );
        self.state.board.projectiles.push(ProjectileState {
            id,
            projectile_type,
            motion: trajectory.motion,
            row,
            position_x: trajectory.position_x,
            position_y: trajectory.position_y,
            velocity_x: trajectory.velocity_x,
            velocity_y: trajectory.velocity_y,
            shadow_y,
            damage: projectile_type.damage(),
            age: 0,
            target_x: None,
            target_row: None,
            target_zombie: None,
            lob_height: 0,
            lob_velocity: 0,
            hit_torchwood_column: None,
            last_portal_column: 0,
        });
        events.push(GameEvent::ProjectileFired {
            entity: id,
            source,
            projectile_type,
            row,
        });
    }

