    #[test]
    fn peashooter_projectile_damages_a_normal_zombie() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 150;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 0 },
                InputAction::Plant { row: 2, column: 0 },
            ],
        });
        game.state.board.plants[0].launch_counter = 1;
        let mut setup_events = Vec::new();
        let immune = game.spawn_normal_zombie(2, 0, Some(450 * POSITION_SCALE), &mut setup_events);
        let target = game.spawn_normal_zombie(2, 0, Some(500 * POSITION_SCALE), &mut setup_events);
        game.state.board.zombies[0].hypnotized = true;
        game.state.board.zombies[0].frozen_counter = 1_000;
        for zombie in &mut game.state.board.zombies {
            zombie.speed = 0;
        }

        let mut hit = false;
        let mut immune_hit = false;
        let mut impacts = 0;
        for _ in 0..200 {
            for event in game.advance(InputFrame::default()) {
                hit |= matches!(
                    event,
                    GameEvent::ProjectileHit {
                        zombie,
                        damage: 20,
                        ..
                    } if zombie == target
                );
                immune_hit |=
                    matches!(event, GameEvent::ProjectileHit { zombie, .. } if zombie == immune);
                if matches!(
                    event,
                    GameEvent::ProjectileImpact {
                        kind: ProjectileImpactSound::Splat,
                        variant: 0..=2,
                        ..
                    }
                ) {
                    impacts += 1;
                }
            }
        }

        assert!(hit);
        assert!(!immune_hit);
        assert!(impacts > 0);
        assert!(
            game.advance(InputFrame::default())
                .iter()
                .all(|event| !matches!(event, GameEvent::ZombieDied { .. }))
        );
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == immune)
                .unwrap()
                .health,
            270
        );
        assert!(
            game.state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == target)
                .unwrap()
                .health
                < 270
        );
    }

    #[test]
    fn splitpea_fires_forward_and_backward_projectiles() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 250;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 28 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        game.state.board.plants[0].shooting_counter = 2;
        game.state.board.plants[0].firing_directions = FIRING_FORWARD | FIRING_BACKWARD;
        let mut setup_events = Vec::new();
        let forward = game.spawn_normal_zombie(2, 0, Some(250 * POSITION_SCALE), &mut setup_events);
        let backward =
            game.spawn_normal_zombie(2, 0, Some(150 * POSITION_SCALE), &mut setup_events);

        let events = game.advance(InputFrame::default());

        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, GameEvent::ProjectileFired { .. }))
                .count(),
            2
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, GameEvent::ProjectileHit { .. }))
                .count(),
            2
        );
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit {
                zombie,
                damage: 20,
                ..
            } if *zombie == forward
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit {
                zombie,
                damage: 20,
                ..
            } if *zombie == backward
        )));
        assert!(game.state.board.projectiles.is_empty());
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .map(|zombie| (zombie.id, zombie.health))
                .collect::<Vec<_>>(),
            vec![(forward, 250), (backward, 250)]
        );
    }

    #[test]
    fn directional_shooter_rectangles_use_source_overlap_edges() {
        let zombie_at = |position_x| {
            let mut game = Game::new(7, SceneKind::Day);
            let mut events = Vec::new();
            game.spawn_normal_zombie(2, 0, Some(position_x), &mut events);
            game.state.board.zombies.remove(0)
        };
        let plant_x = grid_x(2);
        let splitpea = PlantType::Other(28);
        let leftpeater = PlantType::Other(52);

        let forward_edge = zombie_at(plant_attack_start(2) - 78 * POSITION_SCALE);
        assert_eq!(
            directional_target_directions(splitpea, 2, 2, &forward_edge),
            FIRING_FORWARD
        );
        let forward_gap = zombie_at(plant_attack_start(2) - 79 * POSITION_SCALE);
        assert_eq!(
            directional_target_directions(splitpea, 2, 2, &forward_gap),
            0
        );

        let mut split_back_edge = zombie_at(plant_x + 33 * POSITION_SCALE);
        split_back_edge.zombie_type = ZombieType::Gargantuar;
        assert_eq!(
            directional_target_directions(splitpea, 2, 2, &split_back_edge),
            FIRING_FORWARD | FIRING_BACKWARD
        );
        split_back_edge.position_x += POSITION_SCALE;
        assert_eq!(
            directional_target_directions(splitpea, 2, 2, &split_back_edge),
            FIRING_FORWARD
        );

        let mut left_edge = zombie_at(plant_x + 17 * POSITION_SCALE);
        left_edge.zombie_type = ZombieType::Gargantuar;
        assert_eq!(
            directional_target_directions(leftpeater, 2, 2, &left_edge),
            FIRING_BACKWARD
        );
        left_edge.position_x += POSITION_SCALE;
        assert_eq!(
            directional_target_directions(leftpeater, 2, 2, &left_edge),
            0
        );

        let mut immune = zombie_at(100 * POSITION_SCALE);
        immune.hypnotized = true;
        assert_eq!(directional_target_directions(splitpea, 2, 2, &immune), 0);
    }

    #[test]
    fn splitpea_and_leftpeater_arm_only_matching_directions() {
        let run = |plant_type: PlantType, launch_counter, targets: &[(u8, i64)]| {
            let mut game = Game::new(7, SceneKind::Day);
            game.state
                .board
                .plants
                .push(test_plant(100, plant_type, 2, 2));
            game.state.board.plants[0].launch_counter = launch_counter;
            let mut setup = Vec::new();
            for (row, position_x) in targets {
                game.spawn_normal_zombie(*row, 0, Some(*position_x), &mut setup);
            }
            for zombie in &mut game.state.board.zombies {
                zombie.speed = 0;
            }

            let mut fired = Vec::new();
            for _ in 0..40 {
                let events = game.advance(InputFrame::default());
                let did_fire = events
                    .iter()
                    .any(|event| matches!(event, GameEvent::PlantFired { .. }));
                fired.extend(events);
                if did_fire {
                    break;
                }
            }
            (game, fired)
        };

        for (target_x, expected_motion) in [
            (500 * POSITION_SCALE, ProjectileMotion::Straight),
            (100 * POSITION_SCALE, ProjectileMotion::Backwards),
        ] {
            let launch_counter = if expected_motion == ProjectileMotion::Straight {
                26
            } else {
                1
            };
            let (mut game, events) = run(PlantType::Other(28), launch_counter, &[(2, target_x)]);
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(event, GameEvent::PlantFired { .. }))
                    .count(),
                1
            );
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(event, GameEvent::ProjectileFired { .. }))
                    .count(),
                1
            );
            assert_eq!(game.state.board.projectiles.len(), 1);
            assert_eq!(game.state.board.projectiles[0].motion, expected_motion);

            let target = game.state.board.zombies[0].id;
            let mut hit = false;
            for _ in 0..100 {
                hit |= game
                    .advance(InputFrame::default())
                    .iter()
                    .any(|event| matches!(event, GameEvent::ProjectileHit { zombie, .. } if *zombie == target));
                if hit {
                    break;
                }
            }
            assert!(hit);
            assert_eq!(game.state.board.zombies[0].health, 250);
        }

        let (no_target, events) = run(PlantType::Other(28), 1, &[(1, 500 * POSITION_SCALE)]);
        assert!(
            events
                .iter()
                .all(|event| !matches!(event, GameEvent::PlantFired { .. }))
        );
        assert!(no_target.state.board.projectiles.is_empty());

        let (backward, events) = run(PlantType::Other(52), 1, &[(2, 100 * POSITION_SCALE)]);
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, GameEvent::ProjectileFired { .. }))
                .count(),
            1
        );
        assert_eq!(
            backward.state.board.projectiles[0].motion,
            ProjectileMotion::Backwards
        );
        let (forward, events) = run(PlantType::Other(52), 1, &[(2, 500 * POSITION_SCALE)]);
        assert!(
            events
                .iter()
                .all(|event| !matches!(event, GameEvent::PlantFired { .. }))
        );
        assert!(forward.state.board.projectiles.is_empty());
    }

    #[test]
    fn plant_specific_firing_cadence_matches_source_counters() {
        let run = |plant_type: PlantType, target_x, ticks| {
            let mut game = Game::new(7, SceneKind::Day);
            game.state
                .board
                .plants
                .push(test_plant(100, plant_type, 2, 2));
            game.state.board.plants[0].launch_counter = 1;
            let mut setup = Vec::new();
            game.spawn_normal_zombie(2, 0, Some(target_x), &mut setup);
            game.state.board.zombies[0].speed = 0;

            let mut reset_counter = 0;
            let mut fired = Vec::new();
            for tick in 1..=ticks {
                let events = game.advance(InputFrame::default());
                if tick == 1 {
                    reset_counter = game.state.board.plants[0].launch_counter;
                }
                for event in events {
                    if matches!(event, GameEvent::ProjectileFired { source: 100, .. }) {
                        fired.push(tick);
                    }
                }
            }
            (fired, reset_counter)
        };

        for (plant_type, target_x, ticks, expected) in [
            (PlantType::Peashooter, 500 * POSITION_SCALE, 60, vec![33]),
            (
                PlantType::Other(40),
                500 * POSITION_SCALE,
                100,
                vec![33, 50, 66, 83],
            ),
            (PlantType::Other(32), 500 * POSITION_SCALE, 60, vec![32]),
            (
                PlantType::Other(42),
                250 * POSITION_SCALE,
                180,
                vec![75, 103, 131, 159],
            ),
            (PlantType::Other(10), 500 * POSITION_SCALE, 60, vec![50]),
        ] {
            assert_eq!(run(plant_type, target_x, ticks).0, expected);
        }

        let (repeater, repeater_cycle) = run(PlantType::Other(7), 500 * POSITION_SCALE, 200);
        assert_eq!(repeater, vec![26, repeater_cycle + 1, repeater_cycle + 26]);

        let (cattail, cattail_cycle) = run(PlantType::Other(43), 500 * POSITION_SCALE, 200);
        assert_eq!(cattail, vec![32, cattail_cycle - 18, cattail_cycle + 32]);

        let mut cattail = Game::new(7, SceneKind::Day);
        cattail.state.board.plants = vec![test_plant(100, PlantType::Other(43), 2, 2)];
        cattail.state.board.plants[0].launch_counter = 1;
        let mut setup = Vec::new();
        cattail.spawn_normal_zombie(4, 0, Some(500 * POSITION_SCALE), &mut setup);
        cattail.advance(InputFrame::default());
        cattail.state.board.zombies.clear();
        assert!(
            (0..31)
                .flat_map(|_| cattail.advance(InputFrame::default()))
                .all(|event| !matches!(event, GameEvent::ProjectileFired { source: 100, .. }))
        );
    }

