    #[test]
    fn torchwood_turns_pea_shots_into_fireballs() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 300;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 22 },
                InputAction::Plant { row: 2, column: 1 },
                InputAction::SelectSeed { slot: 0 },
                InputAction::Plant { row: 2, column: 0 },
            ],
        });
        game.state
            .board
            .plants
            .iter_mut()
            .find(|plant| plant.plant_type == PlantType::Peashooter)
            .expect("peashooter")
            .launch_counter = 1;
        let mut setup_events = Vec::new();
        game.spawn_normal_zombie(2, 0, Some(500 * POSITION_SCALE), &mut setup_events);
        game.spawn_normal_zombie(2, 0, Some(540 * POSITION_SCALE), &mut setup_events);
        let off_row = game.spawn_normal_zombie(1, 0, Some(500 * POSITION_SCALE), &mut setup_events);
        let immune = game.spawn_normal_zombie(3, 0, Some(500 * POSITION_SCALE), &mut setup_events);
        game.state
            .board
            .zombies
            .iter_mut()
            .find(|zombie| zombie.id == immune)
            .unwrap()
            .hypnotized = true;
        for zombie in &mut game.state.board.zombies {
            zombie.speed = 0;
        }

        let mut saw_fireball = false;
        let mut saw_firepea = false;
        let mut saw_fireball_hit = false;
        let mut saw_fireball_splash = false;
        let mut immune_hit = false;
        let mut off_row_hit = false;
        for _ in 0..200 {
            let events = game.advance(InputFrame::default());
            saw_firepea |= events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileIgnited { .. }));
            saw_fireball |= game.state.board.projectiles.iter().any(|projectile| {
                projectile.projectile_type == ProjectileType::Fireball && projectile.damage == 40
            });
            saw_fireball_hit |= events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileHit { damage: 40, .. }));
            saw_fireball_splash |= events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileSplashHit { damage: 13, .. }));
            immune_hit |= events.iter().any(|event| {
                matches!(
                    event,
                    GameEvent::ProjectileHit { zombie, .. }
                        | GameEvent::ProjectileSplashHit { zombie, .. }
                        if *zombie == immune
                )
            });
            off_row_hit |= events.iter().any(|event| {
                matches!(
                    event,
                    GameEvent::ProjectileHit { zombie, .. }
                        | GameEvent::ProjectileSplashHit { zombie, .. }
                        if *zombie == off_row
                )
            });
            if saw_fireball && saw_fireball_hit && saw_fireball_splash {
                break;
            }
        }

        assert!(saw_firepea);
        assert!(saw_fireball);
        assert!(saw_fireball_hit);
        assert!(saw_fireball_splash);
        assert!(!immune_hit);
        assert!(!off_row_hit);
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == immune)
                .unwrap()
                .health,
            270
        );
    }

    #[test]
    fn fireball_splash_is_same_row_and_capped() {
        // Primary takes the full 40, a same-row secondary is splashed for 13,
        // and adjacent-row plus fire-resistant zombies take no splash.
        let mut game = Game::new(7, SceneKind::Day);
        let mut setup = Vec::new();
        let primary = game.spawn_normal_zombie(2, 0, Some(500 * POSITION_SCALE), &mut setup);
        let secondary = game.spawn_normal_zombie(2, 0, Some(520 * POSITION_SCALE), &mut setup);
        let off_row = game.spawn_normal_zombie(1, 0, Some(500 * POSITION_SCALE), &mut setup);
        let fire_resistant =
            game.spawn_screen_door_zombie(2, 0, Some(540 * POSITION_SCALE), &mut setup);
        for zombie in &mut game.state.board.zombies {
            zombie.speed = 0;
        }
        game.fire_projectile(
            0,
            ProjectileType::Fireball,
            2,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: 500 * POSITION_SCALE,
                position_y: grid_y(2),
                velocity_x: 0,
                velocity_y: 0,
            },
            &mut setup,
        );
        let mut events = Vec::new();
        for _ in 0..20 {
            events.extend(game.advance(InputFrame::default()));
        }
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit { zombie, damage: 40, .. } if *zombie == primary
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileSplashHit { zombie, damage: 13, .. } if *zombie == secondary
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit { zombie, .. }
                | GameEvent::ProjectileSplashHit { zombie, .. }
                if *zombie == off_row || *zombie == fire_resistant
        )));

        // Four same-row secondaries scale the splash 13 -> 10 so the aggregate
        // splash stays capped at the original 40 damage.
        let mut game = Game::new(7, SceneKind::Day);
        let mut setup = Vec::new();
        let primary = game.spawn_normal_zombie(2, 0, Some(500 * POSITION_SCALE), &mut setup);
        for dx in [10, 20, 30, 40] {
            game.spawn_normal_zombie(2, 0, Some((500 + dx) * POSITION_SCALE), &mut setup);
        }
        for zombie in &mut game.state.board.zombies {
            zombie.speed = 0;
        }
        game.fire_projectile(
            0,
            ProjectileType::Fireball,
            2,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: 500 * POSITION_SCALE,
                position_y: grid_y(2),
                velocity_x: 0,
                velocity_y: 0,
            },
            &mut setup,
        );
        let mut events = Vec::new();
        for _ in 0..20 {
            events.extend(game.advance(InputFrame::default()));
        }
        assert!(
            events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileSplashHit { damage: 10, .. }))
        );
        let splash_total: i32 = events
            .iter()
            .filter_map(|event| match event {
                GameEvent::ProjectileSplashHit { zombie, damage, .. } if *zombie != primary => {
                    Some(*damage)
                }
                _ => None,
            })
            .sum();
        assert!(
            splash_total <= 40,
            "Fireball aggregate splash must not exceed the original damage"
        );
    }

    #[test]
    fn torchwood_warms_snowpeas_without_igniting_them() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 175;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 22 },
                InputAction::Plant { row: 2, column: 1 },
            ],
        });
        let mut setup_events = Vec::new();
        let target = game.spawn_normal_zombie(2, 0, Some(500 * POSITION_SCALE), &mut setup_events);
        let adjacent =
            game.spawn_normal_zombie(1, 0, Some(500 * POSITION_SCALE), &mut setup_events);
        for zombie in &mut game.state.board.zombies {
            zombie.speed = 0;
        }
        game.fire_projectile(
            0,
            ProjectileType::SnowPea,
            2,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: grid_x(1) - POSITION_SCALE,
                position_y: grid_y(2),
                velocity_x: 3_330_000,
                velocity_y: 0,
            },
            &mut setup_events,
        );

        let mut events = Vec::new();
        let mut saw_warmed = false;
        let mut saw_ignited = false;
        for _ in 0..20 {
            let tick_events = game.advance(InputFrame::default());
            saw_warmed |= tick_events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileWarmed { .. }));
            saw_ignited |= tick_events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileIgnited { .. }));
            events.extend(tick_events);
            if saw_warmed {
                break;
            }
        }
        assert!(saw_warmed);
        assert!(!saw_ignited);
        assert_eq!(
            game.state.board.projectiles[0].projectile_type,
            ProjectileType::Pea
        );
        assert_eq!(game.state.board.projectiles[0].damage, 20);

        let events = game.advance(InputFrame::default());
        assert!(events.iter().all(|event| !matches!(
            event,
            GameEvent::ProjectileIgnited { .. } | GameEvent::ProjectileWarmed { .. }
        )));
        assert_eq!(
            game.state.board.projectiles[0].projectile_type,
            ProjectileType::Pea
        );

        let mut hit = false;
        let mut splash = false;
        let mut chilled = false;
        for _ in 0..200 {
            for event in game.advance(InputFrame::default()) {
                hit |= matches!(
                    event,
                    GameEvent::ProjectileHit {
                        zombie,
                        damage: 20,
                        ..
                    } if zombie == target
                );
                splash |= matches!(event, GameEvent::ProjectileSplashHit { .. });
                chilled |= matches!(event, GameEvent::ZombieChilled { .. });
            }
            if hit {
                break;
            }
        }

        assert!(hit);
        assert!(!splash);
        assert!(!chilled);
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == target)
                .expect("target")
                .health,
            250
        );
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == adjacent)
                .expect("adjacent")
                .health,
            270
        );
    }

    #[test]
    fn torchwood_warms_then_ignites_across_two_columns() {
        // A SnowPea converts to a Pea at the first Torchwood, is not
        // reconverted by that column, then converts to a Fireball at a later
        // Torchwood on the same row.
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 350;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 22 },
                InputAction::Plant { row: 2, column: 1 },
            ],
        });
        game.state.board.seed_packets[22].refresh_remaining = 0;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 22 },
                InputAction::Plant { row: 2, column: 3 },
            ],
        });
        let mut setup = Vec::new();
        game.fire_projectile(
            0,
            ProjectileType::SnowPea,
            2,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: grid_x(0) + 20 * POSITION_SCALE,
                position_y: grid_y(2),
                velocity_x: 40_000_000,
                velocity_y: 0,
            },
            &mut setup,
        );
        let mut saw_warmed = false;
        let mut saw_ignited = false;
        let mut warmed_type = None;
        for _ in 0..30 {
            let events = game.advance(InputFrame::default());
            let warmed_this_tick = events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileWarmed { .. }));
            let ignited_this_tick = events
                .iter()
                .any(|event| matches!(event, GameEvent::ProjectileIgnited { .. }));
            saw_warmed |= warmed_this_tick;
            saw_ignited |= ignited_this_tick;
            if warmed_this_tick && !ignited_this_tick {
                warmed_type = game
                    .state
                    .board
                    .projectiles
                    .first()
                    .map(|projectile| projectile.projectile_type);
            }
        }
        assert!(saw_warmed, "the SnowPea must warm at the first Torchwood");
        assert!(
            saw_ignited,
            "the warmed Pea must ignite at the second Torchwood"
        );
        assert_eq!(warmed_type, Some(ProjectileType::Pea));
    }

