    #[test]
    fn ice_shroom_applies_source_chill_freeze_and_damage_classes() {
        let trigger = |game: &mut Game| {
            game.state.sun = 200;
            game.advance(InputFrame {
                actions: vec![
                    InputAction::SelectSeed { slot: 14 },
                    InputAction::Plant { row: 2, column: 2 },
                ],
            });
            game.state.board.plants[0].special_counter = 1;
            game.advance(InputFrame::default())
        };

        // Fresh ordinary zombie: chill + 400..=600 freeze + 20 damage.
        let mut game = Game::new(7, SceneKind::Night);
        let mut setup = Vec::new();
        let fresh = game.spawn_normal_zombie(0, 0, Some(grid_x(2)), &mut setup);
        let events = trigger(&mut game);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieChilled {
                entity,
                duration: ICE_SHROOM_CHILL_TICKS,
            } if *entity == fresh
        )));
        let fresh_frozen = events
            .iter()
            .find_map(|event| match event {
                GameEvent::ZombieFrozen { entity, duration } if *entity == fresh => Some(*duration),
                _ => None,
            })
            .expect("a fresh zombie must be frozen");
        assert!(
            (ICE_SHROOM_FRESH_FREEZE_MIN..=ICE_SHROOM_FRESH_FREEZE_MAX).contains(&fresh_frozen)
        );
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialHit {
                zombie,
                damage: ICE_SHROOM_DAMAGE,
                ..
            } if *zombie == fresh
        )));

        // Already-cold zombie: chill + 300..=400 freeze + 20 damage.
        let mut game = Game::new(7, SceneKind::Night);
        let mut setup = Vec::new();
        let cold = game.spawn_normal_zombie(0, 0, Some(grid_x(2)), &mut setup);
        game.state.board.zombies[0].chilled_counter = 100;
        let events = trigger(&mut game);
        let cold_frozen = events
            .iter()
            .find_map(|event| match event {
                GameEvent::ZombieFrozen { entity, duration } if *entity == cold => Some(*duration),
                _ => None,
            })
            .expect("an already-cold zombie must be frozen");
        assert!((ICE_SHROOM_COLD_FREEZE_MIN..=ICE_SHROOM_COLD_FREEZE_MAX).contains(&cold_frozen));

        // In-pool zombie: chill + exactly 300 freeze + 20 damage.
        let mut game = Game::new(7, SceneKind::Night);
        let mut setup = Vec::new();
        let pool_zombie = game.spawn_normal_zombie(0, 0, Some(grid_x(2)), &mut setup);
        game.state.board.zombies[0].in_pool = true;
        let events = trigger(&mut game);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieFrozen {
                entity,
                duration: ICE_SHROOM_POOL_FREEZE_TICKS,
            } if *entity == pool_zombie
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialHit {
                zombie,
                damage: ICE_SHROOM_DAMAGE,
                ..
            } if *zombie == pool_zombie
        )));

        // Chill-only class: a bouncing Pogo is chilled but not frozen or damaged.
        let mut game = Game::new(7, SceneKind::Night);
        let mut setup = Vec::new();
        let pogo = game.spawn_pogo_zombie(0, 0, Some(grid_x(2)), &mut setup);
        {
            let zombie = game
                .state
                .board
                .zombies
                .iter_mut()
                .find(|candidate| candidate.id == pogo)
                .unwrap();
            zombie.pogo_counter = 10;
            zombie.pogo_phase = 1;
        }
        let events = trigger(&mut game);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieChilled { entity, .. } if *entity == pogo
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieFrozen { entity, .. } if *entity == pogo
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialHit { zombie, .. } if *zombie == pogo
        )));
        let pogo_state = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == pogo)
            .unwrap();
        assert_eq!(pogo_state.health, 500);
        assert_eq!(pogo_state.frozen_counter, 0);

        // Excluded class: a Zamboni receives no chill, freeze, or damage.
        let mut game = Game::new(7, SceneKind::Night);
        let mut setup = Vec::new();
        let zamboni = game.spawn_zamboni_zombie(0, 0, Some(grid_x(2)), &mut setup);
        let zamboni_health = game.state.board.zombies[0].health;
        let events = trigger(&mut game);
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieChilled { entity, .. } if *entity == zamboni
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieFrozen { entity, .. } if *entity == zamboni
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialHit { zombie, .. } if *zombie == zamboni
        )));
        assert_eq!(game.state.board.zombies[0].health, zamboni_health);
        assert_eq!(game.state.board.zombies[0].frozen_counter, 0);

        // Grave risers remain excluded until their source rise timer expires.
        let mut game = Game::new(7, SceneKind::Night);
        let mut setup = Vec::new();
        game.spawn_rising_zombie(ZombieType::Normal, 0, 2, 0, &mut setup);
        let riser = game.state.board.zombies[0].id;
        let riser_health = game.state.board.zombies[0].health;
        let events = trigger(&mut game);
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieChilled { entity, .. } if *entity == riser
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieFrozen { entity, .. } if *entity == riser
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialHit { zombie, .. } if *zombie == riser
        )));
        assert_eq!(game.state.board.zombies[0].health, riser_health);
    }

    #[test]
    fn frozen_zombies_do_not_move_or_eat_until_the_counter_expires() {
        let mut game = Game::new(7, SceneKind::Night);
        game.state.sun = 200;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 14 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        game.state.board.plants[0].special_counter = 1;
        let mut setup_events = Vec::new();
        let zombie = game.spawn_normal_zombie(2, 0, Some(500 * POSITION_SCALE), &mut setup_events);
        let before = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == zombie)
            .expect("spawned zombie")
            .position_x;

        game.advance(InputFrame::default());

        let frozen = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == zombie)
            .expect("frozen zombie")
            .clone();
        assert_eq!(frozen.position_x, before);
        assert!(!frozen.eating);
        assert!(frozen.frozen_counter > 0);
    }

    #[test]
    fn gravebuster_requires_and_clears_a_grave_after_four_hundred_ticks() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 75;

        let rejected = game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 11 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        assert!(rejected.iter().any(|event| matches!(
            event,
            GameEvent::InputRejected {
                reason: InputRejectReason::InvalidTerrain,
                ..
            }
        )));

        game.state
            .board
            .graves
            .push(GraveState { row: 2, column: 2 });
        let placed = game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 11 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        let gravebuster = game.state.board.plants[0].id;
        assert!(placed.iter().any(|event| matches!(
            event,
            GameEvent::PlantPlaced {
                entity,
                plant_type: PlantType::Other(11),
                ..
            } if *entity == gravebuster
        )));
        assert_eq!(
            game.state.board.plants[0].special_counter,
            GRAVEBUSTER_EAT_TICKS - 1
        );

        let mut cleared = false;
        for _ in 0..(GRAVEBUSTER_EAT_TICKS - 1) {
            cleared |= game.advance(InputFrame::default()).iter().any(|event| {
                matches!(
                    event,
                    GameEvent::GraveCleared { entity, row: 2, column: 2 }
                        if *entity == gravebuster
                )
            });
        }

        assert!(cleared);
        assert!(game.state.board.graves.is_empty());
        assert!(game.state.board.plants.is_empty());
    }

    #[test]
    fn doom_shroom_removes_targets_and_leaves_a_replant_blocking_crater() {
        let mut game = Game::new(7, SceneKind::Night);
        game.state.sun = 300;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 15 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        game.state.board.plants[0].special_counter = 1;
        let center = grid_x(2);
        let mut setup_events = Vec::new();
        game.spawn_normal_zombie(2, 0, Some(center + 100 * POSITION_SCALE), &mut setup_events);
        game.spawn_normal_zombie(0, 0, Some(center + 100 * POSITION_SCALE), &mut setup_events);
        let survivor =
            game.spawn_normal_zombie(2, 0, Some(center + 300 * POSITION_SCALE), &mut setup_events);

        let events = game.advance(InputFrame::default());

        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::CraterCreated {
                row: 2,
                column: 2,
                duration: DOOM_CRATER_TICKS,
            }
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieDied { entity } if *entity != survivor
        )));
        assert_eq!(game.state.board.zombies.len(), 1);
        assert_eq!(game.state.board.zombies[0].id, survivor);
        assert_eq!(game.state.board.craters.len(), 1);
        assert_eq!(game.state.board.craters[0].remaining, DOOM_CRATER_TICKS - 1);
        assert!(game.state.board.plants.is_empty());

        let rejected = game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 0 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        assert!(rejected.iter().any(|event| matches!(
            event,
            GameEvent::InputRejected {
                reason: InputRejectReason::Crater,
                ..
            }
        )));
    }

