        let hit_ids = events
            .iter()
            .filter_map(|event| match event {
                GameEvent::PlantSpecialHit { plant, zombie, .. } if *plant == squash => {
                    Some(*zombie)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(hit_ids, vec![football, boss]);
