    #[test]
    fn spikeweed_attacks_on_contact_and_is_not_eaten() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 200;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 21 },
                InputAction::Plant { row: 2, column: 0 },
            ],
        });
        let spikeweed = game.state.board.plants[0].id;
        let mut setup_events = Vec::new();
        let zombie = game.spawn_normal_zombie(
            2,
            0,
            Some(grid_x(0) + 10 * POSITION_SCALE),
            &mut setup_events,
        );
        let immune = game.spawn_normal_zombie(
            2,
            0,
            Some(grid_x(0) + 10 * POSITION_SCALE),
            &mut setup_events,
        );
        game.state.board.zombies[1].hypnotized = true;
        game.state.board.zombies[1].frozen_counter = 1_000;
        let starting_health = game.state.board.zombies[0].health;

        let events = (0..=(SPIKEWEED_ATTACK_TICKS - SPIKEWEED_DAMAGE_COUNTDOWN))
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();

        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialTriggered {
                entity,
                plant_type: PlantType::Other(21),
            } if *entity == spikeweed
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialHit {
                plant,
                zombie: hit_zombie,
                damage: SPIKEWEED_DAMAGE,
                health_remaining,
            } if *plant == spikeweed
                && *hit_zombie == zombie
                && *health_remaining == starting_health - SPIKEWEED_DAMAGE
        )));
        assert_eq!(
            game.state.board.zombies[0].health,
            starting_health - SPIKEWEED_DAMAGE
        );
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialHit { zombie, .. } if *zombie == immune
        )));
        assert_eq!(game.state.board.zombies[1].health, 270);
        // Zombies walk over spikeweed instead of chewing it.
        assert_eq!(
            game.state.board.plants[0].health,
            game.state.board.plants[0].max_health
        );
        assert!(!game.state.board.zombies[0].eating);
    }

    #[test]
    fn spiky_plant_target_eligibility_matches_source() {
        let target = |scene, zombie_type, plant_type| {
            let mut game = Game::new(7, scene);
            game.state
                .board
                .plants
                .push(test_plant(1, plant_type, 2, 2));
            game.find_plant_for_zombie(2, grid_x(2), zombie_type)
        };

        for plant_type in [PlantType::Other(21), PlantType::Other(46)] {
            assert_eq!(target(SceneKind::Day, ZombieType::Normal, plant_type), None);
            for zombie_type in [
                ZombieType::Gargantuar,
                ZombieType::Gigagargantuar,
                ZombieType::Zamboni,
            ] {
                assert_eq!(target(SceneKind::Day, zombie_type, plant_type), Some(0));
            }
            assert_eq!(
                target(SceneKind::Pool, ZombieType::Normal, plant_type),
                Some(0)
            );
            assert_eq!(
                target(SceneKind::Fog, ZombieType::Normal, plant_type),
                Some(0)
            );
        }

        let mut roof = Game::new(7, SceneKind::Roof);
        roof.state.board.plants = vec![
            test_plant(1, PlantType::Other(33), 2, 2),
            test_plant(2, PlantType::Other(21), 2, 2),
        ];
        assert_eq!(
            roof.find_plant_for_zombie(2, grid_x(2), ZombieType::Normal),
            Some(1)
        );
    }

