    #[test]
    fn snorkel_uses_source_spawn_speed_and_hides_in_pool_until_it_eats() {
        let mut game = Game::new(7, SceneKind::Pool);
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 24 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        game.state.board.plants[0].launch_counter = 10_000;
        let mut setup = Vec::new();
        let mut expected_rng = game.rng.clone();
        let _variant = expected_rng.range(5) == 0;
        let _generic_position = expected_rng.range(40);
        expected_rng.range_inclusive(300, 400);
        let expected_speed = expected_rng.fixed_range(660_000, 680_000);
        let snorkel = game.spawn_snorkel_zombie(2, 0, Some(720 * POSITION_SCALE), &mut setup);
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
                .unwrap()
                .speed,
            expected_speed
        );
        assert_eq!(game.rng.snapshot(), expected_rng.snapshot());

        let entry_start = game.advance(InputFrame::default());
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
                .unwrap()
                .snorkel_phase,
            SNORKEL_INTO_POOL_PHASE
        );
        assert!(
            !game
                .state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
                .unwrap()
                .in_pool
        );
        assert!(!entry_start.iter().any(|event| matches!(
            event,
            GameEvent::ZombieEnteredPool { entity, .. } if *entity == snorkel
        )));
        let splash_events = (0..SNORKEL_SPLASH_TICKS)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();
        assert!(splash_events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieEnteredPool { entity, .. } if *entity == snorkel
        )));
        let state = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == snorkel)
            .unwrap();
        assert_eq!(state.snorkel_phase, SNORKEL_INTO_POOL_PHASE);
        assert!(!state.in_pool);

        let entry_events = (SNORKEL_SPLASH_TICKS..SNORKEL_ENTRY_TICKS)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();
        assert!(!entry_events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieEnteredPool { entity, .. } if *entity == snorkel
        )));
        let state = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == snorkel)
            .unwrap();
        assert_eq!(state.snorkel_phase, SNORKEL_WALKING_IN_POOL_PHASE);
        assert!(state.in_pool);
        assert_eq!(state.speed, SNORKEL_ENTRY_SPEED);

        let snorkel_position = {
            let snorkel_state = game
                .state
                .board
                .zombies
                .iter_mut()
                .find(|candidate| candidate.id == snorkel)
                .unwrap();
            snorkel_state.position_x = grid_x(2) + 20 * POSITION_SCALE;
            snorkel_state.speed = 0;
            snorkel_state.age = 0;
            snorkel_state.position_x
        };
        let mut projectile_events = Vec::new();
        game.fire_projectile(
            0,
            ProjectileType::Pea,
            2,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: snorkel_position,
                position_y: grid_y(2),
                velocity_x: 0,
                velocity_y: 0,
            },
            &mut projectile_events,
        );
        let hidden_events = game.advance(InputFrame::default());
        assert!(!hidden_events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit { zombie, .. } if *zombie == snorkel
        )));
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
                .unwrap()
                .health,
            270
        );

        game.state.board.projectiles.clear();
        game.state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == snorkel)
            .unwrap()
            .eating = true;
        game.advance(InputFrame::default());
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
                .unwrap()
                .snorkel_phase,
            SNORKEL_UP_TO_EAT_PHASE
        );
        for _ in 0..SNORKEL_EAT_TRANSITION_TICKS {
            game.advance(InputFrame::default());
        }
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
                .unwrap()
                .snorkel_phase,
            SNORKEL_EATING_IN_POOL_PHASE
        );
        let mut projectile_events = Vec::new();
        game.fire_projectile(
            0,
            ProjectileType::Pea,
            2,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: snorkel_position,
                position_y: grid_y(2),
                velocity_x: 0,
                velocity_y: 0,
            },
            &mut projectile_events,
        );
        let exposed_events = game.advance(InputFrame::default());
        assert!(exposed_events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit {
                zombie,
                damage: 20,
                health_remaining: 250,
                ..
            } if *zombie == snorkel
        )));

        game.state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == snorkel)
            .unwrap()
            .eating = false;
        game.advance(InputFrame::default());
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
                .unwrap()
                .snorkel_phase,
            SNORKEL_DOWN_FROM_EAT_PHASE
        );
        for _ in 0..SNORKEL_EAT_TRANSITION_TICKS {
            game.advance(InputFrame::default());
        }
        let snorkel_state = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == snorkel)
            .unwrap();
        assert_eq!(snorkel_state.snorkel_phase, SNORKEL_WALKING_IN_POOL_PHASE);
        assert!(snorkel_state.in_pool);
        assert!((660_000..=680_000).contains(&snorkel_state.speed));

        let snorkel_index = game
            .state
            .board
            .zombies
            .iter()
            .position(|candidate| candidate.id == snorkel)
            .unwrap();
        {
            let snorkel_state = &mut game.state.board.zombies[snorkel_index];
            snorkel_state.position_x = 25 * POSITION_SCALE;
            snorkel_state.speed = 0;
        }
        let mut exit_events = Vec::new();
        game.update_snorkel_state(snorkel_index, &mut exit_events);
        assert_eq!(
            game.state.board.zombies[snorkel_index].snorkel_phase,
            SNORKEL_OUT_OF_POOL_PHASE
        );
        assert!(game.state.board.zombies[snorkel_index].in_pool);
        assert_eq!(
            game.state.board.zombies[snorkel_index].position_x,
            10 * POSITION_SCALE
        );
        for _ in 0..SNORKEL_EXIT_TICKS {
            game.update_snorkel_state(snorkel_index, &mut exit_events);
        }
        assert_eq!(
            game.state.board.zombies[snorkel_index].snorkel_phase,
            SNORKEL_WALKING_PHASE
        );
        assert!(!game.state.board.zombies[snorkel_index].in_pool);

        let mut backwards = Game::new(7, SceneKind::Pool);
        let mut setup = Vec::new();
        let backwards_id =
            backwards.spawn_snorkel_zombie(2, 0, Some(641 * POSITION_SCALE), &mut setup);
        let backwards_index = backwards
            .state
            .board
            .zombies
            .iter()
            .position(|candidate| candidate.id == backwards_id)
            .unwrap();
        {
            let state = &mut backwards.state.board.zombies[backwards_index];
            state.snorkel_phase = SNORKEL_WALKING_IN_POOL_PHASE;
            state.in_pool = true;
            state.hypnotized = true;
            state.speed = 0;
        }
        let mut backwards_events = Vec::new();
        backwards.update_snorkel_state(backwards_index, &mut backwards_events);
        assert_eq!(
            backwards.state.board.zombies[backwards_index].snorkel_phase,
            SNORKEL_OUT_OF_POOL_PHASE
        );
        assert_eq!(
            backwards.state.board.zombies[backwards_index].position_x,
            656 * POSITION_SCALE
        );
        for _ in 0..SNORKEL_EXIT_TICKS {
            backwards.update_snorkel_state(backwards_index, &mut backwards_events);
        }
        assert_eq!(
            backwards.state.board.zombies[backwards_index].snorkel_phase,
            SNORKEL_WALKING_PHASE
        );
        assert!(!backwards.state.board.zombies[backwards_index].in_pool);
    }

    #[test]
    fn snorkel_keeps_walking_while_surfacing_from_the_pool() {
        let mut game = Game::new(7, SceneKind::Pool);
        let mut setup = Vec::new();
        let snorkel =
            game.spawn_snorkel_zombie(2, 0, Some(grid_x(2) + 20 * POSITION_SCALE), &mut setup);
        let exit_x = 25 * POSITION_SCALE;
        {
            let state = game
                .state
                .board
                .zombies
                .iter_mut()
                .find(|candidate| candidate.id == snorkel)
                .unwrap();
            state.snorkel_phase = SNORKEL_WALKING_IN_POOL_PHASE;
            state.snorkel_counter = 0;
            state.position_x = exit_x;
            state.in_pool = true;
            state.age = 3;
        }
        let mut saw_rise_movement = false;
        let mut last_rise_x = None;
        for _ in 0..SNORKEL_EXIT_TICKS {
            game.advance(InputFrame::default());
            let Some(state) = game
                .state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == snorkel)
            else {
                // A surfacing Snorkel can walk into the pool cleaner; the
                // movement-during-rise check is already proven by then.
                break;
            };
            if state.snorkel_phase == SNORKEL_OUT_OF_POOL_PHASE {
                assert!((660_000..=680_000).contains(&state.speed));
                assert!(state.in_pool);
                match last_rise_x {
                    Some(previous) => assert!(
                        state.position_x < previous,
                        "a surfacing snorkel must keep walking during the rise"
                    ),
                    None => assert!(state.position_x < exit_x),
                }
                last_rise_x = Some(state.position_x);
                saw_rise_movement = true;
            }
        }
        assert!(saw_rise_movement);
    }

    #[test]
    fn submerged_snorkel_takes_pult_but_not_pea_damage() {
        for phase in [SNORKEL_DOWN_FROM_EAT_PHASE, SNORKEL_OUT_OF_POOL_PHASE] {
            let mut game = Game::new(7, SceneKind::Pool);
            let mut setup = Vec::new();
            let snorkel =
                game.spawn_snorkel_zombie(2, 0, Some(grid_x(2) + 20 * POSITION_SCALE), &mut setup);
            let snorkel_x = {
                let state = game
                    .state
                    .board
                    .zombies
                    .iter_mut()
                    .find(|candidate| candidate.id == snorkel)
                    .unwrap();
                state.snorkel_phase = phase;
                state.snorkel_counter = SNORKEL_EAT_TRANSITION_TICKS / 2;
                state.in_pool = true;
                state.eating = false;
                state.speed = 0;
                state.age = 3;
                state.position_x
            };
            let mut pea_events = Vec::new();
            game.fire_projectile(
                0,
                ProjectileType::Pea,
                2,
                ProjectileTrajectory {
                    motion: ProjectileMotion::Straight,
                    position_x: snorkel_x,
                    position_y: grid_y(2),
                    velocity_x: 0,
                    velocity_y: 0,
                },
                &mut pea_events,
            );
            let events = game.advance(InputFrame::default());
            assert!(
                !events.iter().any(|event| matches!(
                    event,
                    GameEvent::ProjectileHit { zombie, .. } if *zombie == snorkel
                )),
                "a pea must pass over a submerged snorkel in phase {phase}"
            );

            game.state.board.projectiles.clear();
            let mut melon_events = Vec::new();
            game.fire_projectile(
                0,
                ProjectileType::Melon,
                2,
                ProjectileTrajectory {
                    motion: ProjectileMotion::Straight,
                    position_x: snorkel_x,
                    position_y: grid_y(2),
                    velocity_x: 0,
                    velocity_y: 0,
                },
                &mut melon_events,
            );
            let events = game.advance(InputFrame::default());
            assert!(
                events.iter().any(|event| matches!(
                    event,
                    GameEvent::ProjectileHit { zombie, .. } if *zombie == snorkel
                )),
                "a pult lob must hit a submerged snorkel in phase {phase}"
            );
        }
    }

    #[test]
    fn dolphin_phases_pause_while_immobilized_and_resume_on_thaw() {
        let mut game = Game::new(7, SceneKind::Pool);
        let mut setup = Vec::new();
        let dolphin = game.spawn_dolphin_rider_zombie(2, 0, Some(720 * POSITION_SCALE), &mut setup);
        {
            let state = game
                .state
                .board
                .zombies
                .iter_mut()
                .find(|candidate| candidate.id == dolphin)
                .unwrap();
            state.dolphin_phase = DOLPHIN_INTO_POOL_PHASE;
            state.dolphin_counter = DOLPHIN_ENTRY_TICKS;
            state.frozen_counter = 5;
            state.age = 3;
        }
        let events = game.advance(InputFrame::default());
        let state = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dolphin)
            .unwrap();
        assert_eq!(state.dolphin_counter, DOLPHIN_ENTRY_TICKS);
        assert_eq!(state.frozen_counter, 4);
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieEnteredPool { entity, .. } if *entity == dolphin
        )));
        for _ in 0..3 {
            game.advance(InputFrame::default());
        }
        let state = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dolphin)
            .unwrap();
        assert_eq!(state.dolphin_counter, DOLPHIN_ENTRY_TICKS);
        assert_eq!(state.frozen_counter, 1);
        game.advance(InputFrame::default());
        let state = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dolphin)
            .unwrap();
        assert_eq!(state.frozen_counter, 0);
        assert_eq!(state.dolphin_counter, DOLPHIN_ENTRY_TICKS - 1);
    }

