        let state = game
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == zombie)
            .unwrap();
        state.jackbox_timer = 1;
        state.speed = 0;

        let events = game.advance(InputFrame::default());
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::JackboxExploded { entity, .. } if *entity == zombie
        )));
