    #[test]
    fn night_gravestone_rise_emits_source_rumble_event() {
        let mut game = Game::new(0, SceneKind::Night);
        let events = game.debug_prepare_gravestone_rumble();
        let entity = events
            .iter()
            .find_map(|event| match event {
                GameEvent::ZombieGraveRumble { entity } => Some(*entity),
                _ => None,
            })
            .expect("night rise grave rumble event");
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, GameEvent::ZombieGraveRumble { .. }))
                .count(),
            1
        );
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieSpawned {
                entity: spawned,
                row: 2,
                ..
            } if *spawned == entity
        )));
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == entity)
                .expect("rising night zombie")
                .rise_counter,
            GRAVE_RISE_LAND_TICKS
        );

        let mut whack = Game::new_mode(0, ModeKind::MiniGame, 14);
        let events = whack.debug_prepare_whack_zombie_rise();
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, GameEvent::ZombieWhackRise { .. }))
                .count(),
            1
        );
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, GameEvent::ZombieGraveRumble { .. }))
        );
    }

