    #[test]
    fn tangle_kelp_grabs_a_nearby_zombie_then_dies() {
        let mut game = Game::new(7, SceneKind::Pool);
        game.state.sun = 500;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 19 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        let tangle_kelp = game.state.board.plants[0].id;
        let mut setup_events = Vec::new();
        let zombie_x = grid_x(2) + 20 * POSITION_SCALE;
        let zombie = game.spawn_normal_zombie(2, 0, Some(zombie_x), &mut setup_events);
        game.state.board.zombies[0].in_pool = true;
        assert_eq!(
            game.find_plant_for_zombie(2, zombie_x, ZombieType::Normal),
            None
        );
        assert_eq!(game.find_plant_for_pole_vault(2, zombie_x, false), None);

        let events = (0..=TANGLE_KELP_GRAB_TICKS)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();

        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantSpecialTriggered {
                entity,
                plant_type: PlantType::Other(19),
            } if *entity == tangle_kelp
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::TangleKelpWaterEntry { entity } if *entity == tangle_kelp
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieDied { entity } if *entity == zombie
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantDied { entity } if *entity == tangle_kelp
        )));
        assert!(game.state.board.zombies.is_empty());
        assert!(game.state.board.plants.is_empty());
    }

    #[test]
    fn tangle_kelp_targets_only_eligible_pool_zombies() {
        for (zombie_type, snorkel_phase, dolphin_phase) in [
            (ZombieType::Normal, 0, 0),
            (ZombieType::Snorkel, SNORKEL_WALKING_IN_POOL_PHASE, 0),
            (ZombieType::DolphinRider, 0, DOLPHIN_RIDING_PHASE),
            (ZombieType::Conehead, 0, 0),
        ] {
            let mut game = Game::new(7, SceneKind::Pool);
            game.place_izombie_plant(PlantType::Other(19), 2, 2);
            let mut setup = Vec::new();
            let target =
                game.spawn_normal_zombie(2, 0, Some(grid_x(2) + 20 * POSITION_SCALE), &mut setup);
            let state = game
                .state
                .board
                .zombies
                .iter_mut()
                .find(|zombie| zombie.id == target)
                .unwrap();
            state.zombie_type = zombie_type;
            state.in_pool = true;
            state.snorkel_phase = snorkel_phase;
            state.dolphin_phase = dolphin_phase;
            state.speed = 0;

            let events = game.advance(InputFrame::default());
            assert_eq!(game.state.board.plants[0].special_target, Some(target));
            assert!(events.iter().any(|event| matches!(
                event,
                GameEvent::TangleKelpGrabStarted { entity }
                    if *entity == game.state.board.plants[0].id
            )));
        }

        let mut game = Game::new(7, SceneKind::Pool);
        game.place_izombie_plant(PlantType::Other(19), 2, 2);
        let mut setup = Vec::new();
        let target =
            game.spawn_normal_zombie(2, 0, Some(grid_x(2) + 20 * POSITION_SCALE), &mut setup);
        assert_eq!(game.find_tangle_kelp_target(2, 2), None);

        {
            let state = game
                .state
                .board
                .zombies
                .iter_mut()
                .find(|zombie| zombie.id == target)
                .unwrap();
            state.in_pool = true;
            state.position_x = grid_x(2) + 80 * POSITION_SCALE;
        }
        assert_eq!(game.find_tangle_kelp_target(2, 2), None);

        game.state.board.zombies[0].position_x = grid_x(2) + 20 * POSITION_SCALE;
        game.state.board.zombies[0].zombie_type = ZombieType::Snorkel;
        game.state.board.zombies[0].snorkel_phase = SNORKEL_INTO_POOL_PHASE;
        assert_eq!(game.find_tangle_kelp_target(2, 2), None);

        game.state.board.zombies[0].snorkel_phase = SNORKEL_WALKING_IN_POOL_PHASE;
        assert_eq!(game.find_tangle_kelp_target(2, 2), Some(target));

        game.state.board.zombies[0].zombie_type = ZombieType::Bobsled;
        game.state.board.zombies[0].bobsled_sliding = true;
        game.state.board.zombies[0].bobsled_leader = false;
        assert_eq!(game.find_tangle_kelp_target(2, 2), None);

        game.state.board.zombies[0].bobsled_leader = true;
        assert_eq!(game.find_tangle_kelp_target(2, 2), Some(target));

        let mut other_tangle_kelp = game.state.board.plants[0].clone();
        other_tangle_kelp.id = game.state.board.allocate_entity();
        other_tangle_kelp.column = 3;
        other_tangle_kelp.special_armed = true;
        other_tangle_kelp.special_target = Some(target);
        game.state.board.plants.push(other_tangle_kelp);
        assert_eq!(game.find_tangle_kelp_target(2, 2), None);
    }

    #[test]
    fn spikerock_attacks_twice_per_cycle_and_has_extra_health() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 500;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 46 },
                InputAction::Plant { row: 2, column: 0 },
            ],
        });
        let spikerock = game.state.board.plants[0].id;
        assert_eq!(game.state.board.plants[0].max_health, 450);

        let mut setup_events = Vec::new();
        let zombie = game.spawn_normal_zombie(
            2,
            0,
            Some(grid_x(0) + 40 * POSITION_SCALE),
            &mut setup_events,
        );
        let starting_health = game.state.board.zombies[0].health;
        let events = (0..70)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();

        let hits = events
            .iter()
            .filter(|event| {
                matches!(
                    event,
                    GameEvent::PlantSpecialHit {
                        plant,
                        zombie: hit_zombie,
                        damage: SPIKEWEED_DAMAGE,
                        ..
                    } if *plant == spikerock && *hit_zombie == zombie
                )
            })
            .count();
        assert_eq!(hits, 2);
        assert_eq!(
            game.state.board.zombies[0].health,
            starting_health - 2 * SPIKEWEED_DAMAGE
        );
    }

    #[test]
    fn source_coin_type_catalog_preserves_money_sun_and_award_groups() {
        let types = [
            CoinType::Silver,
            CoinType::Gold,
            CoinType::Diamond,
            CoinType::Sun,
            CoinType::SmallSun,
            CoinType::LargeSun,
            CoinType::FinalSeedPacket,
            CoinType::Trophy,
            CoinType::Shovel,
            CoinType::Almanac,
            CoinType::CarKeys,
            CoinType::Vase,
            CoinType::WateringCan,
            CoinType::Taco,
            CoinType::Note,
            CoinType::UsableSeedPacket,
            CoinType::PresentPlant,
            CoinType::AwardMoneyBag,
            CoinType::AwardPresent,
            CoinType::AwardBagDiamond,
            CoinType::AwardSilverSunflower,
            CoinType::AwardGoldSunflower,
            CoinType::Chocolate,
            CoinType::AwardChocolate,
            CoinType::PresentMinigames,
            CoinType::PresentPuzzleMode,
            CoinType::PresentSurvivalMode,
        ];
        assert_eq!(types.len(), 27);
        assert_eq!(
            types
                .iter()
                .copied()
                .filter(|coin_type| coin_type.is_money())
                .count(),
            3
        );
        assert_eq!(CoinType::Silver.value(), 1);
        assert_eq!(CoinType::Gold.value(), 5);
        assert_eq!(CoinType::Diamond.value(), 100);
        assert_eq!(CoinType::SmallSun.sun_value(), 15);
        assert_eq!(CoinType::Sun.sun_value(), 25);
        assert_eq!(CoinType::LargeSun.sun_value(), 50);
        assert!(CoinType::FinalSeedPacket.is_level_award());
        assert!(CoinType::AwardChocolate.is_level_award());
        assert_eq!(CoinType::PresentMinigames.unlock_mask(), 1);
        assert_eq!(CoinType::PresentPuzzleMode.unlock_mask(), 2);
        assert_eq!(CoinType::PresentSurvivalMode.unlock_mask(), 4);
    }

    #[test]
    fn prize_pickups_update_unlocks_garden_inventory_and_currency() {
        let mut game = Game::new(7, SceneKind::Day);
        let collect = |game: &mut Game, coin_type, plant_type, usable_seed_type| {
            let mut produced = Vec::new();
            game.spawn_pickup_with_payload(
                coin_type,
                grid_x(2),
                grid_y(2),
                plant_type,
                usable_seed_type,
                &mut produced,
            );
            let entity = game.state.board.coins.last().unwrap().id;
            let events = game.advance(InputFrame {
                actions: vec![InputAction::CollectCoin { entity }],
            });
            assert!(events.iter().any(|event| matches!(
                event,
                GameEvent::PickupCollected { entity: found, .. } if *found == entity
            )));
        };

        collect(&mut game, CoinType::PresentMinigames, None, None);
        collect(&mut game, CoinType::PresentPuzzleMode, None, None);
        collect(&mut game, CoinType::PresentSurvivalMode, None, None);
        assert_eq!(game.state.unlocked_modes, 7);

        collect(
            &mut game,
            CoinType::PresentPlant,
            Some(PlantType::Other(31)),
            None,
        );
        assert_eq!(game.state.garden.plants[0].plant_type, PlantType::Other(31));

        collect(
            &mut game,
            CoinType::UsableSeedPacket,
            None,
            Some(PlantType::Other(5)),
        );
        assert_eq!(game.state.board.selected_seed, Some(5));

        collect(&mut game, CoinType::Chocolate, None, None);
        collect(&mut game, CoinType::AwardChocolate, None, None);
        collect(&mut game, CoinType::AwardMoneyBag, None, None);
        collect(&mut game, CoinType::AwardBagDiamond, None, None);
        assert_eq!(game.state.chocolates, 2);
        assert_eq!(game.state.coins, 0);

        let mut profile = SaveProfile::new("chocolate");
        game.update_profile(&mut profile);
        assert_eq!(profile.inventory.chocolates, 2);
        let json = profile.to_json_pretty().unwrap();
        let restored = SaveProfile::from_json(&json).unwrap();
        assert_eq!(restored.inventory.chocolates, 2);

        let mut next = Game::new(7, SceneKind::Day);
        next.apply_profile(&restored);
        assert_eq!(next.state.chocolates, 2);
    }

    #[test]
    fn award_money_bag_fans_out_present_coins_and_auto_collects() {
        let mut game = Game::new(7, SceneKind::Day);
        let mut produced = Vec::new();
        game.spawn_pickup(CoinType::AwardMoneyBag, grid_x(4), grid_y(2), &mut produced);
        let award_id = game.state.board.coins[0].id;
        game.state.scene = SceneKind::Complete;
        let collected = game.advance(InputFrame {
            actions: vec![InputAction::CollectCoin { entity: award_id }],
        });
        assert!(collected.iter().any(|event| matches!(
            event,
            GameEvent::PickupCollected {
                entity,
                coin_type: CoinType::AwardMoneyBag,
                value: 1,
                ..
            } if *entity == award_id
        )));
        assert_eq!(game.state.coins, 0);
        assert_eq!(game.state.board.coins.len(), 5);
        assert!(game.state.board.coins.iter().all(|coin| {
            coin.coin_type == CoinType::Gold && coin.from_present && coin.age == 1
        }));

        let mut auto_collected = Vec::new();
        for _ in 1..PRESENT_COIN_TICKS {
            auto_collected = game.advance(InputFrame::default());
        }
        assert_eq!(game.state.coins, 25);
        assert!(game.state.board.coins.is_empty());
        assert_eq!(
            auto_collected
                .iter()
                .filter(|event| matches!(event, GameEvent::CoinCollected { .. }))
                .count(),
            5
        );
    }

