    #[test]
    fn source_defined_minigame_inputs_use_deterministic_targets() {
        let mut slot_machine = Game::new_mode(7, ModeKind::MiniGame, 2);
        assert_eq!(
            slot_machine.state().challenge.kind,
            ChallengeKind::SlotMachine
        );
        let events = slot_machine.advance(InputFrame {
            actions: vec![InputAction::ChallengeSpin],
        });
        assert_eq!(slot_machine.state().sun, 25);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ChallengeAction {
                kind: ChallengeKind::SlotMachine,
                value: 1
            }
        )));

        let mut beghouled = Game::new_mode(7, ModeKind::MiniGame, 4);
        assert_eq!(beghouled.state().board.rows, 5);
        assert_eq!(beghouled.state().board.columns, 8);
        assert_eq!(beghouled.state().board.plants.len(), 40);
        assert_eq!(beghouled.state().sun, 0);
        assert!(beghouled.state().board.mowers.is_empty());
        beghouled.state.challenge.score = 74;
        let events = beghouled.advance(InputFrame {
            actions: vec![InputAction::ChallengeSwap {
                from_column: 2,
                from_row: 1,
                to_column: 2,
                to_row: 2,
            }],
        });
        assert_eq!(
            beghouled.state().challenge.twist_state,
            BeghouledTwistState::Moving
        );
        let mut settling_events = Vec::new();
        for _ in 0..99 {
            settling_events.extend(beghouled.advance(InputFrame::default()));
        }
        assert_eq!(beghouled.state().challenge.score, 75);
        assert_eq!(beghouled.state().scene, SceneKind::Complete);
        assert!(
            events
                .iter()
                .chain(&settling_events)
                .any(|event| matches!(event, GameEvent::GameWon))
        );

        let mut aquarium = Game::new_mode(7, ModeKind::MiniGame, 7);
        let before = aquarium.state().board.zombies.len();
        let events = aquarium.advance(InputFrame {
            actions: vec![InputAction::ChallengeFeed { x: 400, y: 250 }],
        });
        assert_eq!(aquarium.state().sun, 45);
        assert_eq!(aquarium.state().board.zombies.len(), before);
        assert_eq!(
            aquarium
                .state()
                .board
                .brains
                .iter()
                .filter(|brain| !brain.squished)
                .count(),
            1
        );
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ChallengeAction {
                kind: ChallengeKind::Zombiquarium,
                value: 5
            }
        )));

        let mut whack = Game::new_mode(7, ModeKind::MiniGame, 14);
        let mut setup = Vec::new();
        whack.spawn_normal_zombie(2, 0, Some(grid_x(2)), &mut setup);
        let events = whack.advance(InputFrame {
            actions: vec![InputAction::ChallengeWhack {
                row: 2,
                column: 2,
                x: 200,
                y: 300,
            }],
        });
        assert!(whack.state().board.zombies.is_empty());
        assert!(
            events
                .iter()
                .any(|event| matches!(event, GameEvent::ZombieDied { .. }))
        );
        assert!(
            events
                .iter()
                .any(|event| matches!(event, GameEvent::WhackHammerSwung))
        );
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::WhackHit {
                x: 200,
                y: 300,
                sound: WhackHitSound::Bonk,
                variant: 0
            }
        )));
    }

    #[test]
    fn whack_helm_damage_precedes_the_source_bonk_kill() {
        let hit = |game: &mut Game| {
            game.advance(InputFrame {
                actions: vec![InputAction::ChallengeWhack {
                    row: 2,
                    column: 2,
                    x: 200,
                    y: 300,
                }],
            })
        };

        let mut cone = Game::new_mode(7, ModeKind::MiniGame, 14);
        cone.state.board.zombies.clear();
        let mut setup = Vec::new();
        cone.spawn_conehead_zombie(2, 0, Some(grid_x(2)), &mut setup);
        let cone_events = hit(&mut cone);
        assert_eq!(cone.state.board.zombies[0].health, WHACK_BODY_HEALTH);
        assert!(!cone.state.board.zombies[0].armor_intact);
        assert!(cone_events.iter().any(|event| matches!(
            event,
            GameEvent::WhackHit {
                sound: WhackHitSound::Plastic,
                variant: 0 | 1,
                ..
            }
        )));

        let mut bucket = Game::new_mode(7, ModeKind::MiniGame, 14);
        bucket.state.board.zombies.clear();
        let bucket_id = bucket.spawn_buckethead_zombie(2, 0, Some(grid_x(2)), &mut setup);
        let first = hit(&mut bucket);
        assert_eq!(bucket.state.board.zombies[0].health, 470);
        assert!(bucket.state.board.zombies[0].armor_intact);
        assert!(
            !first
                .iter()
                .any(|event| matches!(event, GameEvent::ZombieDied { .. }))
        );

        let second = hit(&mut bucket);
        assert_eq!(bucket.state.board.zombies[0].health, WHACK_BODY_HEALTH);
        assert!(!bucket.state.board.zombies[0].armor_intact);
        assert!(second.iter().any(
            |event| matches!(event, GameEvent::ZombieArmorLost { entity } if *entity == bucket_id)
        ));

        let third = hit(&mut bucket);
        assert!(bucket.state.board.zombies.is_empty());
        assert!(third.iter().any(|event| matches!(
            event,
            GameEvent::WhackHit {
                x: 200,
                y: 300,
                sound: WhackHitSound::Bonk,
                variant: 0
            }
        )));
        assert!(third.iter().any(
            |event| matches!(event, GameEvent::ZombieDied { entity } if *entity == bucket_id)
        ));
    }

    #[test]
    fn zombiquarium_uses_snorkels_and_brain_bait() {
        let mut game = Game::new_mode(7, ModeKind::MiniGame, 7);
        assert_eq!(game.state().board.zombies.len(), 2);
        assert!(game.state().board.zombies.iter().all(|zombie| {
            zombie.zombie_type == ZombieType::Snorkel
                && zombie.health == ZOMBIQUARIUM_START_HEALTH
                && zombie.max_health == ZOMBIQUARIUM_MAX_HEALTH
                && (50 * POSITION_SCALE..=650 * POSITION_SCALE).contains(&zombie.position_x)
                && (100 * POSITION_SCALE..=400 * POSITION_SCALE).contains(&zombie.position_y)
        }));
        assert!(game.state().board.brains.is_empty());

        game.state.sun = ZOMBIQUARIUM_BRAIN_COST * 3;
        for (x, y) in [(200, 160), (400, 250), (600, 340)] {
            game.advance(InputFrame {
                actions: vec![InputAction::ChallengeFeed { x, y }],
            });
        }
        assert_eq!(game.state().sun, 0);
        assert_eq!(
            game.state()
                .board
                .brains
                .iter()
                .filter(|brain| !brain.squished)
                .count(),
            ZOMBIQUARIUM_MAX_BRAINS
        );

        game.state.sun = ZOMBIQUARIUM_BRAIN_COST;
        let rejected = game.advance(InputFrame {
            actions: vec![InputAction::ChallengeFeed { x: 300, y: 220 }],
        });
        assert!(rejected.iter().any(|event| matches!(
            event,
            GameEvent::InputRejected {
                action: InputAction::ChallengeFeed { x: 300, y: 220 },
                reason: InputRejectReason::ChallengeUnavailable
            }
        )));
        assert_eq!(
            game.state()
                .board
                .brains
                .iter()
                .filter(|brain| !brain.squished)
                .count(),
            ZOMBIQUARIUM_MAX_BRAINS
        );

        for brain in &mut game.state.board.brains {
            brain.squished = true;
        }
        let zombie = &mut game.state.board.zombies[0];
        zombie.health = 150;
        zombie.position_x = 200 * POSITION_SCALE;
        zombie.position_y = 200 * POSITION_SCALE;
        zombie.aquarium_speed = 0;
        zombie.aquarium_phase_counter = 100;
        let brain = &mut game.state.board.brains[0];
        brain.squished = false;
        brain.age = ZOMBIQUARIUM_BRAIN_ARM_TICKS;
        brain.position_x = zombie.position_x + 50 * POSITION_SCALE;
        brain.position_y = zombie.position_y + 40 * POSITION_SCALE;

        let events = game.advance(InputFrame::default());
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::BrainEaten { zombie: entity, .. }
                if *entity == game.state().board.zombies[0].id
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombiquariumBrainSlurped { zombie: entity, row: 0 }
                if *entity == game.state().board.zombies[0].id
        )));
        assert!(game.state().board.brains[0].squished);
        assert_eq!(
            game.state().board.zombies[0].health,
            ZOMBIQUARIUM_MAX_HEALTH
        );

        game.state.sun = ZOMBIQUARIUM_SNORKEL_COST;
        let events = game.advance(InputFrame {
            actions: vec![InputAction::SelectSeed { slot: 0 }],
        });
        assert_eq!(game.state().board.zombies.len(), 3);
        assert_eq!(game.state().sun, 0);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombieSpawned {
                zombie_type: ZombieType::Snorkel,
                ..
            }
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ChallengeAction {
                kind: ChallengeKind::Zombiquarium,
                value: ZOMBIQUARIUM_SNORKEL_COST
            }
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ZombiquariumSnorkelPurchased { variant } if *variant < 2
        )));
    }

    #[test]
    fn whack_a_zombie_uses_graves_for_the_first_and_final_waves() {
        let mut game = Game::new_mode(7, ModeKind::MiniGame, 14);
        assert_eq!(game.state.board.graves.len(), WHACK_INITIAL_GRAVES);
        assert!(
            game.state
                .board
                .graves
                .iter()
                .all(|grave| grave.column >= 3)
        );
        assert_eq!(game.state.board.wave.countdown, WHACK_INITIAL_COUNTDOWN);
        assert_eq!(game.state.challenge.countdown, WHACK_INITIAL_COUNTDOWN);

        for _ in 0..WHACK_INITIAL_COUNTDOWN - 1 {
            game.advance(InputFrame::default());
        }
        assert_eq!(game.state.board.wave.current, 0);
        assert!(game.state.board.zombies.is_empty());
        game.advance(InputFrame::default());
        assert_eq!(game.state.board.wave.current, 1);
        assert_eq!(game.state.board.zombies.len(), 1);
        assert_eq!(game.state.board.zombies[0].rise_counter, WHACK_RISE_TICKS);
        assert_eq!(game.state.challenge.countdown, WHACK_WAVE_COUNTDOWN);

        game.state.board.zombies.clear();
        game.state.board.graves = (0..DAY_ROWS)
            .flat_map(|row| (3..GRID_COLUMNS).map(move |column| (row, column)))
            .take(20)
            .map(|(row, column)| GraveState { row, column })
            .collect();
        game.state.board.wave.current = game.state.board.wave.total;
        game.state.board.wave.countdown = WHACK_WAVE_COUNTDOWN;
        game.state.challenge.zombie_countdown = 1;
        game.advance(InputFrame::default());
        assert_eq!(game.state.board.zombies.len(), 20);
        assert!(game.state.board.zombies.iter().all(|zombie| {
            matches!(
                zombie.zombie_type,
                ZombieType::Conehead | ZombieType::Buckethead
            ) && zombie.rise_counter == WHACK_RISE_TICKS
        }));
        assert_eq!(game.state.board.wave.countdown, 0);
        assert_eq!(game.state.challenge.zombie_countdown, 0);
    }

