    #[test]
    fn wallnut_bowling_rolls_into_a_zombie_and_emits_impact() {
        let mut game = Game::new_mode(7, ModeKind::MiniGame, 1);
        let setup = game.debug_prepare_wallnut_bowling_impact();
        assert!(setup.iter().any(|event| matches!(
            event,
            GameEvent::PlantPlaced {
                plant_type: PlantType::Other(3),
                ..
            }
        )));

        let mut impact = false;
        for _ in 0..100 {
            let events = game.advance(InputFrame::default());
            if events
                .iter()
                .any(|event| matches!(event, GameEvent::BowlingImpact { .. }))
            {
                let spawn_sun = events
                    .iter()
                    .position(|event| {
                        matches!(
                            event,
                            GameEvent::LootDropSound {
                                sound: LootDropSound::SpawnSun
                            }
                        )
                    })
                    .expect("Bowling reward plays SpawnSun");
                let coin = events
                    .iter()
                    .position(|event| matches!(event, GameEvent::CoinProduced { .. }))
                    .expect("Bowling reward produces a coin");
                assert!(spawn_sun < coin);
                impact = true;
                break;
            }
        }

        assert!(impact);
        assert!(game.state.board.zombies.is_empty());
        assert!(game.state.board.plants[0].position_x > grid_x(0));
    }

    #[test]
    fn remaining_minigame_profiles_match_source_scenes_and_wave_counts() {
        let profiles = [
            (2, ChallengeKind::SlotMachine, SceneKind::Day, 0),
            (3, ChallengeKind::RainingSeeds, SceneKind::Fog, 40),
            (4, ChallengeKind::Beghouled, SceneKind::Night, 0),
            (5, ChallengeKind::Invisighoul, SceneKind::Fog, 20),
            (6, ChallengeKind::SeeingStars, SceneKind::Day, 40),
            (7, ChallengeKind::Zombiquarium, SceneKind::Pool, 0),
            (8, ChallengeKind::BeghouledTwist, SceneKind::Night, 0),
            (9, ChallengeKind::LittleTrouble, SceneKind::Pool, 30),
            (10, ChallengeKind::PortalCombat, SceneKind::Night, 20),
            (11, ChallengeKind::Column, SceneKind::Roof, 30),
            (13, ChallengeKind::ZombiesOnSpeed, SceneKind::Pool, 40),
            (14, ChallengeKind::WhackAZombie, SceneKind::Night, 12),
            (19, ChallengeKind::FinalBoss, SceneKind::Boss, 40),
        ];
        for (level, kind, scene, total_waves) in profiles {
            let game = Game::new_mode(7, ModeKind::MiniGame, level);
            assert_eq!(game.state().challenge.kind, kind, "level {level}");
            assert_eq!(game.state().scene, scene, "level {level}");
            assert_eq!(game.state().board.wave.total, total_waves, "level {level}");
        }

        let mut regular = Game::new(7, SceneKind::Pool);
        let mut setup = Vec::new();
        regular.spawn_normal_zombie(2, 0, Some(grid_x(4)), &mut setup);
        let regular_speed = regular.state().board.zombies[0].speed;
        let mut fast = Game::new_mode(7, ModeKind::MiniGame, 13);
        fast.spawn_normal_zombie(2, 0, Some(grid_x(4)), &mut setup);
        assert_eq!(fast.state().board.zombies[0].speed, regular_speed * 2);

        let boss = Game::new_mode(7, ModeKind::MiniGame, 19);
        assert_eq!(boss.state().board.zombies.len(), 1);
        assert_eq!(boss.state().board.zombies[0].zombie_type, ZombieType::Boss);
        assert_eq!(boss.state().board.zombies[0].health, BOSS_CHALLENGE_HEALTH);
    }

    #[test]
    fn raining_seeds_spawn_on_source_cadence_with_filtered_payloads() {
        let mut game = Game::new_mode(7, ModeKind::MiniGame, 3);
        game.state.unlocked_plants = vec![
            PlantType::Peashooter,
            PlantType::Sunflower,
            PlantType::Other(9),
            PlantType::Other(35),
            PlantType::Other(37),
            PlantType::Other(40),
            PlantType::Other(48),
            PlantType::Other(16),
        ];

        assert_eq!(game.state.challenge.kind, ChallengeKind::RainingSeeds);
        assert_eq!(game.state.challenge.countdown, 100);
        assert!(game.raining_seed_allowed(PlantType::Peashooter));
        for plant_type in [
            PlantType::Sunflower,
            PlantType::Other(9),
            PlantType::Other(35),
            PlantType::Other(37),
            PlantType::Other(40),
            PlantType::Other(48),
        ] {
            assert!(!game.raining_seed_allowed(plant_type));
        }

        for _ in 0..99 {
            let events = game.advance(InputFrame::default());
            assert!(game.state.board.coins.is_empty());
            assert!(!events.iter().any(|event| matches!(
                event,
                GameEvent::CoinProduced {
                    coin_type: CoinType::UsableSeedPacket,
                    ..
                }
            )));
        }

        let events = game.advance(InputFrame::default());
        let first = game
            .state
            .board
            .coins
            .first()
            .expect("first Raining Seeds packet");
        assert_eq!(first.coin_type, CoinType::UsableSeedPacket);
        assert!(matches!(
            first.usable_seed_type,
            Some(PlantType::Peashooter | PlantType::Other(16))
        ));
        assert!((100 * POSITION_SCALE..=649 * POSITION_SCALE).contains(&first.position_x));
        assert_eq!(first.position_y, 60 * POSITION_SCALE + 330_000);
        assert!(
            (300 * POSITION_SCALE..=549 * POSITION_SCALE)
                .contains(&first.target_y.expect("seed packet landing target"))
        );
        assert_eq!(first.velocity_y, 330_000);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::CoinProduced {
                coin_type: CoinType::UsableSeedPacket,
                ..
            }
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ChallengeAction {
                kind: ChallengeKind::RainingSeeds,
                ..
            }
        )));

        let next_countdown = game.state.challenge.countdown;
        assert!((500..=999).contains(&next_countdown));
        game.advance(InputFrame::default());
        assert_eq!(game.state.board.coins[0].velocity_y, 330_000);
        let mut repeated_events = Vec::new();
        for _ in 1..next_countdown {
            repeated_events = game.advance(InputFrame::default());
        }
        assert_eq!(game.state.board.coins.len(), 2);
        assert!((500..=999).contains(&game.state.challenge.countdown));
        assert_eq!(
            repeated_events
                .iter()
                .filter(|event| matches!(
                    event,
                    GameEvent::CoinProduced {
                        coin_type: CoinType::UsableSeedPacket,
                        ..
                    }
                ))
                .count(),
            1
        );
    }

    #[test]
    fn weather_checkpoints_follow_source_rain_and_thunder_boundaries() {
        let mut raining = Game::new_mode(7, ModeKind::MiniGame, 3);
        let first = raining.advance(InputFrame::default());
        assert!(first.iter().any(|event| matches!(
            event,
            GameEvent::WeatherSound {
                sound: WeatherSound::Rain
            }
        )));
        let second = raining.advance(InputFrame::default());
        assert!(
            !second
                .iter()
                .any(|event| matches!(event, GameEvent::WeatherSound { .. }))
        );

        let mut storm = Game::new_adventure(7, 40, false, 0, false);
        storm.debug_prepare_weather_audio();
        let first = storm.advance(InputFrame::default());
        assert!(first.iter().any(|event| matches!(
            event,
            GameEvent::WeatherSound {
                sound: WeatherSound::Rain
            }
        )));
        let mut thunder = false;
        for _ in 0..99 {
            thunder |= storm.advance(InputFrame::default()).iter().any(|event| {
                matches!(
                    event,
                    GameEvent::WeatherSound {
                        sound: WeatherSound::Thunder
                    }
                )
            });
        }
        assert!(thunder, "Stormy Night thunder boundary did not fire");
    }

    #[test]
    fn raining_seed_collection_preserves_payload_for_free_planting() {
        let mut game = Game::new_mode(7, ModeKind::MiniGame, 3);
        game.state.unlocked_plants = vec![
            PlantType::Peashooter,
            PlantType::Sunflower,
            PlantType::Other(16),
        ];
        game.state.sun = 0;
        game.state.challenge.countdown = 1;
        game.advance(InputFrame::default());

        let coin = game
            .state
            .board
            .coins
            .first()
            .expect("Raining Seeds packet")
            .clone();
        let payload = coin.usable_seed_type.expect("seed payload");
        let row = u8::from(payload == PlantType::Other(16)) * 2;
        let events = game.advance(InputFrame {
            actions: vec![
                InputAction::CollectCoin { entity: coin.id },
                InputAction::Plant { row, column: 0 },
            ],
        });

        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PickupCollected {
                entity,
                coin_type: CoinType::UsableSeedPacket,
                ..
            } if *entity == coin.id
        )));
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantPlaced {
                plant_type,
                row: placed_row,
                column: 0,
                ..
            } if *plant_type == payload && *placed_row == row
        )));
        assert!(game.state.board.coins.is_empty());
        assert!(game.state.board.selected_seed.is_none());
        assert!(game.state.board.selected_usable_seed.is_none());
        assert_eq!(game.state.sun, 0);
        assert!(game.state.board.seed_packets.is_empty());
    }

