    #[test]
    fn pogo_zombie_bounces_over_a_plant_without_biting_it() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 50;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 1 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        let plant_id = game.state.board.plants[0].id;
        let mut setup_events = Vec::new();
        let zombie = game.spawn_pogo_zombie(
            2,
            0,
            Some(grid_x(2) + 20 * POSITION_SCALE),
            &mut setup_events,
        );
        let pogo = game
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == zombie)
            .unwrap();
        pogo.speed = 0;
        pogo.pogo_counter = 1;

        game.advance(InputFrame::default());
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == zombie)
                .unwrap()
                .pogo_counter,
            POGO_BOUNCE_TICKS
        );
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == zombie)
                .unwrap()
                .pogo_phase,
            POGO_HIGH_BOUNCE_PHASE
        );
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == zombie)
                .unwrap()
                .pogo_target_x,
            None
        );
        assert_eq!(game.state.board.plants[0].health, 300);

        let events = (0..POGO_BOUNCE_TICKS * 2)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, GameEvent::PogoBounceSound { entity } if *entity == zombie))
                .count(),
            2
        );
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::PlantDamaged { entity, .. } if *entity == plant_id
        )));
        assert_eq!(game.state.board.plants[0].health, 300);
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == zombie)
                .unwrap()
                .position_x,
            grid_x(2) - 60 * POSITION_SCALE
        );
    }

    #[test]
    fn pogo_unopposed_bounces_repeat_and_move_at_walk_speed() {
        let mut game = Game::new(7, SceneKind::Day);
        let mut setup_events = Vec::new();
        let start = grid_x(5);
        let zombie = game.spawn_pogo_zombie(2, 0, Some(start), &mut setup_events);
        let pogo = game
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == zombie)
            .unwrap();
        pogo.pogo_counter = 1;
        pogo.speed = 450_000;

        game.advance(InputFrame::default());
        let events = (0..POGO_BOUNCE_TICKS * 2)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();
        let pogo = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == zombie)
            .unwrap();
        assert_eq!(pogo.pogo_counter, POGO_BOUNCE_TICKS);
        assert_eq!(pogo.pogo_phase, 0);
        assert_eq!(pogo.position_x, start - 161 * 450_000);
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, GameEvent::PogoBounceSound { entity } if *entity == zombie))
                .count(),
            2
        );
    }

