    #[test]
    fn gargantuar_squishes_a_plant_and_damages_spikerock() {
        let mut game = Game::new(7, SceneKind::Day);
        game.state.sun = 50;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 1 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        let plant_id = game.state.board.plants[0].id;
        let mut setup_events = Vec::new();
        let zombie = game.spawn_gargantuar_zombie(
            2,
            0,
            Some(grid_x(2) + 20 * POSITION_SCALE),
            &mut setup_events,
        );
        game.state.board.zombies[0].speed = 0;
        let events = (0..4)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantDied { entity } if *entity == plant_id
        )));
        assert!(game.state.board.plants.is_empty());
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == zombie)
                .unwrap()
                .health,
            3_000
        );

        game.state.sun = 125;
        game.advance(InputFrame {
            actions: vec![
                InputAction::SelectSeed { slot: 46 },
                InputAction::Plant { row: 2, column: 2 },
            ],
        });
        let spikerock = game.state.board.plants[0].id;
        let gargantuar = game
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == zombie)
            .unwrap();
        gargantuar.position_x = grid_x(2) + 20 * POSITION_SCALE;
        gargantuar.age = 0;
        let events = (0..4)
            .flat_map(|_| game.advance(InputFrame::default()))
            .collect::<Vec<_>>();
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::PlantDamaged {
                entity,
                damage: GARGANTUAR_SPIKEROCK_DAMAGE,
                health_remaining: 430,
            } if *entity == spikerock
        )));
        assert_eq!(game.state.board.plants[0].health, 430);
    }

    #[test]
    fn dancer_summons_four_backup_dancers_after_snap_and_links_them() {
        let mut game = Game::new(7, SceneKind::Day);
        let mut setup_events = Vec::new();
        let dancer = game.spawn_dancer_zombie(2, 0, Some(grid_x(2)), &mut setup_events);
        let leader = game
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        leader.speed = 0;
        leader.hypnotized = true;
        leader.dancer_phase = DANCER_SNAP_PHASE;
        leader.dancer_counter = 1;
        let events = game.advance(InputFrame::default());
        let backups = game
            .state
            .board
            .zombies
            .iter()
            .filter(|candidate| candidate.zombie_type == ZombieType::BackupDancer)
            .collect::<Vec<_>>();
        assert_eq!(backups.len(), BACKUP_DANCER_COUNT);
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(
                    event,
                    GameEvent::ZombieSpawned {
                        zombie_type: ZombieType::BackupDancer,
                        ..
                    }
                ))
                .count(),
            BACKUP_DANCER_COUNT
        );
        assert_eq!(backups[0].row, 1);
        assert_eq!(backups[1].row, 3);
        assert_eq!(backups[2].position_x, grid_x(2) - 100 * POSITION_SCALE);
        assert_eq!(backups[3].position_x, grid_x(2) + 100 * POSITION_SCALE);
        for (slot, backup) in backups.iter().enumerate() {
            assert_eq!(backup.dancer_leader, Some(dancer));
            assert_eq!(backup.dancer_slot, slot as u8);
            assert_eq!(backup.dancer_phase, DANCER_RISE_PHASE);
            assert_eq!(backup.dancer_counter, DANCER_RISE_TICKS);
            assert!(backup.hypnotized);
        }
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == dancer)
                .unwrap()
                .health,
            500
        );
    }

    #[test]
    fn backup_dancer_rise_rejects_ground_damage_until_landing() {
        let backup_x = grid_x(4);
        let mut game = Game::new(7, SceneKind::Day);
        let mut setup = Vec::new();
        let backup = game.spawn_backup_dancer(1, 0, Some(backup_x), &mut setup);
        game.state.board.zombies[0].speed = 0;
        let starting_health = game.state.board.zombies[0].health;
        let rising = &game.state.board.zombies[0];
        assert_eq!(rising.dancer_phase, DANCER_RISE_PHASE);
        assert!(!projectile_can_hit_zombie(rising, ProjectileType::Pea));
        assert!(!projectile_can_hit_zombie(rising, ProjectileType::Fireball));
        assert!(!squash_hits_zombie(rising, 1, backup_x));

        let mut events = Vec::new();
        game.fire_projectile(
            0,
            ProjectileType::Pea,
            1,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: backup_x,
                position_y: grid_y(1),
                velocity_x: 0,
                velocity_y: 0,
            },
            &mut events,
        );
        game.update_projectiles(&mut events);
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit { zombie, .. } if *zombie == backup
        )));
        assert_eq!(game.state.board.zombies[0].health, starting_health);
        game.state.board.projectiles.clear();

        let normal = game.spawn_normal_zombie(2, 0, Some(backup_x), &mut setup);
        game.state.board.zombies[1].speed = 0;
        events.clear();
        game.fire_projectile(
            0,
            ProjectileType::Fireball,
            2,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: backup_x,
                position_y: grid_y(2),
                velocity_x: 0,
                velocity_y: 0,
            },
            &mut events,
        );
        game.update_projectiles(&mut events);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit { zombie, damage: 40, .. } if *zombie == normal
        )));
        assert!(!events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileSplashHit { zombie, .. } if *zombie == backup
        )));
        assert_eq!(game.state.board.zombies[0].health, starting_health);

        for _ in 0..DANCER_RISE_TICKS {
            game.advance(InputFrame::default());
        }
        let landed = game
            .state
            .board
            .zombies
            .iter()
            .find(|zombie| zombie.id == backup)
            .unwrap();
        assert_eq!(landed.dancer_phase, DANCER_DANCE_PHASE);
        assert!(projectile_can_hit_zombie(landed, ProjectileType::Pea));
        assert!(squash_hits_zombie(landed, 1, landed.position_x));
        let landed_x = landed.position_x;

        events.clear();
        game.fire_projectile(
            0,
            ProjectileType::Pea,
            1,
            ProjectileTrajectory {
                motion: ProjectileMotion::Straight,
                position_x: landed_x,
                position_y: grid_y(1),
                velocity_x: 0,
                velocity_y: 0,
            },
            &mut events,
        );
        game.update_projectiles(&mut events);
        assert!(events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit { zombie, damage: 20, .. } if *zombie == backup
        )));
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|zombie| zombie.id == backup)
                .unwrap()
                .health,
            starting_health - 20
        );

        let mut cob_game = Game::new(7, SceneKind::Day);
        let mut cob_events = Vec::new();
        let cob_target = cob_game.spawn_backup_dancer(1, 0, Some(grid_x(4)), &mut cob_events);
        cob_game.fire_cob_projectile(0, 1, 0, 1, 4, &mut cob_events);
        let cob = cob_game.state.board.projectiles.pop().unwrap();
        cob_game.apply_cob_explosion(&cob, 1, grid_x(4), &mut cob_events);
        assert!(cob_events.iter().any(|event| matches!(
            event,
            GameEvent::ProjectileHit {
                zombie,
                damage: 1_800,
                ..
            } if *zombie == cob_target
        )));
        assert!(cob_game.state.board.zombies.is_empty());
    }

    #[test]
    fn dancer_entrance_moves_right_and_pauses_until_thaw() {
        let mut game = Game::new(7, SceneKind::Day);
        let mut setup_events = Vec::new();
        let dancer = game.spawn_dancer_zombie(2, 0, Some(grid_x(5)), &mut setup_events);
        let leader = game
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        assert!(
            (DANCER_ENTRANCE_TICKS..DANCER_ENTRANCE_TICKS + 12).contains(&leader.dancer_counter)
        );
        assert_eq!(leader.dancer_phase, DANCER_ENTRANCE_PHASE);
        leader.dancer_counter = 2;
        leader.speed = 500_000;
        leader.frozen_counter = 2;
        let start = leader.position_x;

        game.advance(InputFrame::default());
        let leader = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        assert_eq!(leader.dancer_counter, 2);
        assert_eq!(leader.position_x, start);

        let thaw_events = game.advance(InputFrame::default());
        let leader = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        assert_eq!(leader.dancer_counter, 2);
        assert_eq!(leader.position_x, start);
        assert!(
            thaw_events.iter().any(
                |event| matches!(event, GameEvent::ZombieThawed { entity } if *entity == dancer)
            )
        );

        game.advance(InputFrame::default());
        let leader = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        assert_eq!(leader.dancer_counter, 1);
        assert_eq!(leader.position_x, start + 500_000);

        game.advance(InputFrame::default());
        let leader = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        assert_eq!(leader.dancer_phase, DANCER_SNAP_PHASE);
        assert_eq!(leader.dancer_counter, DANCER_SNAP_TICKS);
        assert_eq!(leader.position_x, start + 500_000);
    }

    #[test]
    fn dancer_hold_and_backup_rise_finish_before_group_dance() {
        let mut game = Game::new(7, SceneKind::Day);
        let mut setup_events = Vec::new();
        let dancer = game.spawn_dancer_zombie(2, 0, Some(grid_x(2)), &mut setup_events);
        let leader = game
            .state
            .board
            .zombies
            .iter_mut()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        leader.speed = 0;
        leader.dancer_phase = DANCER_SNAP_PHASE;
        leader.dancer_counter = 1;
        game.advance(InputFrame::default());

        for _ in 0..DANCER_RISE_TICKS {
            game.advance(InputFrame::default());
        }
        let leader = game
            .state
            .board
            .zombies
            .iter()
            .find(|candidate| candidate.id == dancer)
            .unwrap();
        assert_eq!(leader.dancer_phase, DANCER_HOLD_PHASE);
        assert_eq!(leader.dancer_counter, DANCER_HOLD_TICKS - DANCER_RISE_TICKS);
        assert!(
            game.state
                .board
                .zombies
                .iter()
                .filter(|candidate| candidate.zombie_type == ZombieType::BackupDancer)
                .all(|backup| {
                    backup.dancer_phase == DANCER_DANCE_PHASE && backup.dancer_counter == 0
                })
        );

        for _ in 0..(DANCER_HOLD_TICKS - DANCER_RISE_TICKS) {
            game.advance(InputFrame::default());
        }
        assert_eq!(
            game.state
                .board
                .zombies
                .iter()
                .find(|candidate| candidate.id == dancer)
                .unwrap()
                .dancer_phase,
            DANCER_DANCE_PHASE
        );
    }

